# 裝飾器

def thGetSysMessageF(func=None, *, uiName='ThUiMain'):
    if func is None:
        return partial(thGetSysMessageF, uiName=uiName)

    @wraps(func)
    def wrapperF(*args, **kwargs):
        outStdout = io.StringIO()
        htmlText = None
        ret = None
        try:
            with redirect_stdout(outStdout), redirect_stderr(outStdout):
                ret = func(*args, **kwargs)
        except Exception:
            errTrace = traceback.format_exc()
            htmlText = f'<span style="color: rgb(255,70,70); white-space: pre-wrap;">{errTrace}</span>'
            # raise  # 若需要對外拋出錯誤可以取消註解這行
        else:
            stdoutMessage = outStdout.getvalue().rstrip('\n')
            if stdoutMessage:
                htmlText = f'<span style="color: rgb(140,200,110); white-space: pre-wrap;">{stdoutMessage}</span>'
        #
        if not htmlText:
            successText = f'{func.__name__} -> 執行完成！'
            htmlText = f'<span style="color: rgb(140,200,110);">{successText}</span>'
        #
        currentTime = datetime.datetime.now().strftime("%H:%M:%S")
        htmlText = f'<span style="color: rgb(200,200,200);">[{currentTime}]: </span>{htmlText}'
        #
        try:
            # 優先從函數所在的 globals 中尋找 UI 類別 (這對於在不同環境中執行動態腳本最可靠)
            targetUi = func.__globals__.get(uiName)
            # 如果 globals 找不到，再嘗試從 sys.modules 中尋找 (處理跨模組調用)
            if not targetUi:
                targetModule = sys.modules.get(func.__module__)
                if targetModule and hasattr(targetModule, uiName):
                    targetUi = getattr(targetModule, uiName)
            #
            if targetUi and hasattr(targetUi, 'instanceCls') and targetUi.instanceCls:
                targetUi.instanceCls.log.appendHtml(htmlText)
                scrollBar = targetUi.instanceCls.log.verticalScrollBar()
                scrollBar.setValue(scrollBar.maximum())
            else:
                if not targetUi:
                    print(f"[Log 輸出錯誤]: 在模組中找不到指定的 UI 名稱 -> {uiName}")
                # else: UI 未開啟，不輸出錯誤
        except Exception as exceptionErr:
            print(f"[Log 輸出錯誤]: {exceptionErr}")
        #
        return ret

    return wrapperF


def thDoUndoF(func):
    """裝飾器: 設置函數執行的開始與結束"""
    def wrapperF(*args, **kwargs):
        cmds.undoInfo(openChunk=True)
        ret = func(*args, **kwargs)
        cmds.undoInfo(closeChunk=True)
        return ret
    return wrapperF


def thNoUndoF(func):
    """裝飾器: 關閉 undo"""
    def wrapperF(*args, **kwargs):
        cmds.flushUndo()
        cmds.undoInfo(stateWithoutFlush=False)
        try:
            ret = func(*args, **kwargs)
        finally:
            cmds.undoInfo(stateWithoutFlush=True)  # 無論如何都會恢復
        return ret
    return wrapperF


