# Language

class ThLanguage:
    """
    語言類別。
    包含語言設定的功能。
    """

    _translator = None
    lang = 'zh_TW'

    @classmethod
    def setLanguageF(cls, lang):
        """設置並載入語言檔"""
        cls.lang = lang
        # 如果已經有安裝過翻譯器，先移除
        if cls._translator:
            QtWidgets.QApplication.removeTranslator(cls._translator)
        # 如果是中文(預設語言)，就不需要載入翻譯檔，直接返回
        if lang == 'zh_TW':
            print("[Language] 使用預設中文介面")
            return
        #
        cls._translator = QtCore.QTranslator()
        #
        langPath = thGetResourcePathF('files', 'languages', f'{lang}.qm')
        #
        if cls._translator.load(langPath):
            QtWidgets.QApplication.installTranslator(cls._translator)
            print(f"[Language] 成功載入語言: {langPath}")
        else:
            print(f"[Language] 載入失敗或找不到語言檔: {langPath}")

    @classmethod
    def tr(cls, tx, context="ThLanguage"):
        """調用 Qt 標準翻譯介面"""
        return QtCore.QCoreApplication.translate(context, tx)


