def thUnlockDefaultNodesF():
    nodes = ['defaultTextureList1', 'renderPartition', 'defaultShaderList1', 'defaultLightList1']
    for node in nodes:
        try:
            cmds.lockNode(node, l=False, lockUnpublished=False)
            print(f"[解鎖] {node}")
        except Exception as e:
            print(f"[跳過] {node}: {e}")


def thSwapPositionsF(sourceObj, targetObj):
    """交換位置"""
    sourceObjData = cmds.xform(sourceObj, q=True, ws=True, m=True)
    targetObjData = cmds.xform(targetObj, q=True, ws=True, m=True)
    cmds.xform(sourceObj, ws=True, m=targetObjData)
    cmds.xform(targetObj, ws=True, m=sourceObjData)


def thCopyAndConnectAttributesF(sourceObj, attrList, targetObj):
    """
    將來源物件的屬性列表添加到目標物件，並用新增的屬性連接來源屬性。
    """
    for attr in attrList:
        sourceAttr = f"{sourceObj}.{attr}"
        targetAttr = f"{targetObj}.{attr}"
        # 確保來源屬性存在
        if not cmds.objExists(sourceAttr):
            print(f"[警告] 屬性不存在: {sourceAttr}")
            continue
        # 支援類型: 常見數值與布林
        attrType = cmds.getAttr(sourceAttr, type=True)
        if attrType not in ['double', 'float', 'long', 'short', 'byte', 'bool']:
            print(f"[跳過] 不支援的屬性類型: {sourceAttr} ({attrType})")
            continue
        # 嘗試取得 min, max, defaultValue
        minVal = None
        maxVal = None
        defaultVal = 0.0 if attrType != 'bool' else False
        #
        if cmds.attributeQuery(attr, node=sourceObj, minExists=True):
            minVal = cmds.attributeQuery(attr, node=sourceObj, min=True)[0]
        if cmds.attributeQuery(attr, node=sourceObj, maxExists=True):
            maxVal = cmds.attributeQuery(attr, node=sourceObj, max=True)[0]
        #
        try:
            defaultVal = cmds.getAttr(sourceAttr)
        except:
            defaultVal = 0.0 if attrType != 'bool' else False
        # 若 target 沒有此屬性，建立新屬性
        if not cmds.objExists(targetAttr):
            addKwargs = {
                'longName': attr,
                'keyable': True
            }
            if attrType == 'bool':
                addKwargs['attributeType'] = 'bool'
                addKwargs['defaultValue'] = defaultVal
            else:
                addKwargs['attributeType'] = attrType
                addKwargs['defaultValue'] = defaultVal
                if minVal is not None:
                    addKwargs['min'] = minVal
                if maxVal is not None:
                    addKwargs['max'] = maxVal
            #
            try:
                cmds.addAttr(targetObj, **addKwargs)
            except Exception as e:
                print(f"[錯誤] 新增屬性失敗: {targetAttr} ({str(e)})")
                continue
        # 建立連接
        try:
            if not cmds.isConnected(targetAttr, sourceAttr):
                cmds.connectAttr(targetAttr, sourceAttr, force=True)
                cmds.setAttr(sourceAttr, lock=True)
        except Exception as e:
            print(f"[錯誤] 無法連接 {targetAttr} 到 {sourceAttr}：{e}")


def thGetSoftSelectWeightDataF():
    """獲取軟選擇權重"""
    richSel = om2.MGlobal.getRichSelection()
    richSelList = richSel.getSelection()
    path, component = richSelList.getComponent(0)
    componentFn = om2.MFnSingleIndexedComponent(component)
    # 獲取值
    idList = []
    idListData = []
    size = componentFn.getCompleteData()
    for i in range(0, size):
        weight = componentFn.weight(i)
        idList.append(componentFn.element(i))
        idListData.append(weight.influence)
    return [idList, idListData]


def thSortByHierarchyF(objs=None, autoSelect=True):
    """
    根據父層級對物件重新排序，層級越淺（越外層）越優先排列。
    參數：
    - objs: 要排序的物件列表（若為 None 則使用當前選取項目）。
    - autoSelect: 是否在排序後自動選取這些物件。
    回傳：
    - 排序後的物件列表。
    """
    # 若未指定物件，則使用當前選取
    if objs is None:
        objs = cmds.ls(selection=True, long=True)
    else:
        objs = cmds.ls(objs, long=True)  # 轉為完整路徑以避免同名物件混淆
    #
    if not objs:
        cmds.warning("請先選取控制器或指定物件列表。")
        return []

    # 計算每個物件的層級深度（由 root 至當前的階層數）
    def getDepthF(obj):
        parents = cmds.listRelatives(obj, fullPath=True, parent=True)
        depth = 0
        while parents:
            depth += 1
            parents = cmds.listRelatives(parents[0], fullPath=True, parent=True)
        return depth

    # 根據層級深度排序
    sortedObjs = sorted(objs, key=getDepthF)
    # 是否重新選取排序後的物件
    if autoSelect:
        cmds.select(sortedObjs, replace=True)
    #
    return sortedObjs


def thGetFullNamespaceF(objName):
    """分析命名空間"""
    if ':' not in objName:
        return ''
    namespaceParts = objName.split(':')[:-1]  # 移除最末端名稱（通常是物件名稱）
    return ':'.join(namespaceParts)


