def thGetObjAnimRangeF__old(objectList=None):
    """讀取場景或指定物件的動畫長度"""
    # 查找動畫節點
    keyNodeList = []
    animCurveTypes = ['animCurveTA', 'animCurveTU', 'animCurveTL']
    if objectList:
        historyNodes = cmds.listHistory(objectList, leaf=False) or []
        keyNodeList = [node for node in set(historyNodes) if cmds.nodeType(node) in animCurveTypes]
    else:
        keyNodeList = cmds.ls(type=animCurveTypes)
    #
    if not keyNodeList:
        return [0, 1]  # 如果沒有找到動畫節點，返回預設範圍
    # 查詢所有關鍵幀的最小和最大時間
    minTime, maxTime = float('inf'), float('-inf')
    for keyNode in keyNodeList:
        keyTimes = cmds.keyframe(keyNode, q=True, timeChange=True)
        if keyTimes:  # 避免空的 keyframe 查詢
            minTime = min(minTime, keyTimes[0])
            maxTime = max(maxTime, keyTimes[-1])
    # 如果沒有有效範圍，設置為最小長度 1
    if minTime == maxTime:
        maxTime = minTime + 1
    #
    return [int(minTime), int(maxTime)]


def thGetObjAnimRangeF(objectList=None):
    """讀取場景或指定物件的動畫 key 時間範圍"""
    #
    animCurveTypes = [
        'animCurveTA',
        'animCurveTL',
        'animCurveTU',
        'animCurveTT',
        'animCurveUA'
    ]
    #
    keyNodeSet = set()
    # 收集 animCurve 節點
    if objectList:
        for obj in objectList:
            # 找出該物件所有被 animCurve 驅動的屬性
            connections = cmds.listConnections(
                obj, s=True, d=False, type='animCurve') or []
            #
            for node in connections:
                if cmds.nodeType(node) in animCurveTypes:
                    keyNodeSet.add(node)
    else:
        keyNodeSet = set(cmds.ls(type=animCurveTypes) or [])
    #
    if not keyNodeSet:
        # 沒有任何動畫 key，回傳最小安全範圍
        return [0, 1]
    #
    minTime = float('inf')
    maxTime = float('-inf')
    # 計算所有 key 的時間範圍
    for keyNode in keyNodeSet:
        keyTimes = cmds.keyframe(
            keyNode,
            q=True,
            timeChange=True
        )
        #
        if not keyTimes:
            continue
        #
        minTime = min(minTime, min(keyTimes))
        maxTime = max(maxTime, max(keyTimes))
    #
    if minTime == float('inf') or maxTime == float('-inf'):
        return [0, 1]
    #
    if minTime == maxTime:
        maxTime = minTime + 1
    #
    return [int(minTime), int(maxTime)]


def thListToMelF(list_):
    """Python list to mel list"""
    listStr = str(list_)
    listStr = listStr.replace('u\'', '"')
    listStr = listStr.replace('\'', '"')
    listStr = listStr.replace('[', '{')
    listStr = listStr.replace(']', '}')
    return listStr


