def thGetVtxDataF(mesh, doRound=0, space='object'):
    """獲取頂點位置"""
    appSpace = {'object': om2.MSpace.kObject, 'world': om2.MSpace.kWorld}
    meshList = om2.MSelectionList().add(mesh)
    meshDagPath = meshList.getDagPath(0)
    fnMesh = om2.MFnMesh(meshDagPath)
    pointList = fnMesh.getPoints(appSpace[space])
    weightList = [list(n)[:3] for n in pointList]
    # 四捨五入
    if doRound:
        doRoundF = lambda x: [round(n, doRound) for n in x]
        weightList = [doRoundF(n) for n in weightList]
    return weightList


