def thTimeToFrameF(hour=0, minute=0, second=0, frame=0, fps=30, addFrame=0):
    """時間換算影格"""
    minute = (hour * 60) + minute
    second = (minute * 60) + second
    frame = (second * fps) + frame
    frame += addFrame
    sys.stdout.write(frame)


def thBatchSetKeyToFrameF(selectList=None, attrList=None, startTime=0):
    selectList = selectList if selectList else cmds.ls(sl=True)
    attrList = attrList if attrList else thGetMainChannelBoxF()
    for n in selectList:
        for ii, nn in enumerate(attrList):
            try:
                cmds.setKeyframe('{}.{}'.format(n, nn), time=(ii - 1) + startTime, value=0)
                cmds.setKeyframe('{}.{}'.format(n, nn), time=ii + startTime, value=1)
                cmds.setKeyframe('{}.{}'.format(n, nn), time=(ii + 1) + startTime, value=0)
            except:
                pass


def thAdsorptionAndConstrainF(list_, mode='parent', isScale=True):
    """吸附並約束"""
    thEditPivotF(list_[:-1], list_[-1])
    if mode == 'parent':
        for n in list_[:-1]:
            cmds.parentConstraint([list_[-1], n], mo=True, weight=1)
    elif mode == 'point':
        for n in list_[:-1]:
            cmds.pointConstraint([list_[-1], n], offset=[0, 0, 0], weight=1)
    if isScale:
        for n in list_[:-1]:
            cmds.scaleConstraint([list_[-1], n], offset=[1, 1, 1], weight=1)


def thDuplicateWithoutChildrenF(nodes, label='', keepShapes=True):
    """複製不帶子層級之物件"""
    if not nodes:
        return []
    duplicates = []
    for obj in nodes:
        dup = cmds.duplicate(obj, n='{}{}'.format(label, obj), rc=True)[0]
        children = cmds.listRelatives(dup, fullPath=True)
        if children:
            if keepShapes:
                children = list(set(children) - set(cmds.ls(children, shapes=True, long=True)))
            if children:
                cmds.delete(children)
        duplicates.append(dup)
    if duplicates:
        cmds.select(duplicates, r=True)
    return duplicates


def thFollowObjAnimF(inObjList, outObj, mode=1, ifT=True, ifR=True, start=None, end=None):
    """對位並 KEY"""
    # 獲取時間範圍
    if not start is None and not end is None:
        range_ = (end - start)
        #
        doRange = abs(range_)
        doMode = 1 if range_ > 1 else -1
        doStart = start
        #
        cmds.currentTime(start)
    else:
        doRange = 1
        doMode = mode
        doStart = cmds.currentTime(q=True)
    # 複製控制器
    mainGrp = cmds.group(em=True)
    locList = cmds.duplicate(inObjList, rr=True, po=True, rc=True)
    thLockHiddenAttrF(locList, lock=False)
    locGrpList = [cmds.group(x, r=True) for x in locList]
    cmds.parent(locGrpList, mainGrp)
    for n in locList:
        cmds.parentConstraint(outObj, n, mo=True, weight=1, dr=True)
    #
    for i in range(doRange):
        cmds.currentTime(doStart + ((i + 1) * doMode))
        for ii, loc in enumerate(locList):
            if ifT:
                cmds.xform(inObjList[ii], wd=True, t=cmds.xform(loc, q=True, wd=True, t=True))
            if ifR:
                cmds.xform(inObjList[ii], wd=True, ro=cmds.xform(loc, q=True, wd=True, ro=True))
        cmds.setKeyframe(inObjList, breakdown=0, hierarchy='none', controlPoints=0, shape=0)
    # 刪除
    cmds.delete(mainGrp)
    cmds.select(inObjList + [outObj], r=True)


def thFaceToCamF(obj):
    """選擇面向攝影機的面"""
    # 得到最小角度的餘弦值
    minAngle = 180
    angleScalar = mel.eval('sind({})'.format(minAngle))
    # 獲取對象的面孔列表
    faces = cmds.polyInfo(obj, fn=True)
    # 激活相機和視圖軸
    cameraName = cmds.lookThru(cmds.paneLayout('viewPanes', q=True, activePane=True), q=True)
    cameraMatrix = cmds.xform(cameraName, q=True, m=True, ws=True)
    camAx = [0, 0, 1]
    camAxis = mel.eval(
        'pointMatrixMult({{{}}}, {{{}}})'.format(str(camAx)[1:-1], str(cameraMatrix)[1:-1]))
    facesSelected = []
    index = 0
    #
    for face in faces:
        # 獲取面部編號
        buffer = [n for n in face[:-1].split(' ') if n]
        faceNum = int(buffer[1][:-1])
        # 獲取每張臉的局部法線向量
        axis = [float(buffer[2]), float(buffer[3]), float(buffer[4])]
        # 將局部法線與對象矩陣結合起來得到，在世界空間中正常
        transform = cmds.xform(obj, q=True, m=True, ws=True)
        worldAxis = mel.eval(
            'pointMatrixMult({{{}}}, {{{}}})'.format(str(axis)[1:-1], str(transform)[1:-1]))
        # 查找具有相機Z軸的點積的最大值的法線
        dotProd = mel.eval(
            'dotProduct({{{}}}, {{{}}}, 1)'.format(str(worldAxis)[1:-1], str(camAxis)[1:-1]))
        #
        if dotProd > angleScalar:
            facesSelected.append(faceNum)
    doSelect = ['{}.f[{}]'.format(obj, n) for n in facesSelected]
    cmds.select(doSelect, r=True)


