def thIntegrationListF(list1, list2, quantity):
    """隨機抽樣並整合兩個列表"""
    if not len(list1) == len(list2):
        return
    indexList = range(len(list1))
    indexRand = random.sample(indexList, quantity)
    indexOther = list(set(indexList) - set(indexRand))
    #
    newList1 = [list1[i] for i in indexRand]
    newList2 = [list2[i] for i in indexOther]
    combineList = newList1 + newList2
    cmds.select(combineList, r=True)


def thDeleteRepeatMaterialF(print_=True):
    """刪除重複的材質球.
    - 本功能適用於 reference or import
    - 執行會套用最新材質，刪除舊材質
    - 場景中不要存在多個 namespase
    - 執行完成後，請自行刪除 namespase
    """
    materials = cmds.ls(type=['phong', 'lambert', 'blinn', 'phongE'])
    deleteList = []
    splitNamespaseList = []
    namespaseList = []
    noNamespaseList = []
    for n in materials:
        if ':' in n:
            splitNamespaseList.append(n.split(':')[1])
            namespaseList.append(n)
        else:
            noNamespaseList.append(n)
    for n in noNamespaseList:
        if n in splitNamespaseList:
            index = splitNamespaseList.index(n)
            # 指定材質
            cmds.hyperShade(o=n)
            sel = cmds.ls(sl=True)
            sg = cmds.listConnections(namespaseList[index], type='shadingEngine')[0]
            cmds.sets(sel, e=True, fe=sg)
            #
            deleteList.append(n)
            cmds.delete(n)
    if print_:
        sys.stdout.write('delete: {}'.format(str(deleteList)))
    return deleteList


def thSelectAnimLayerF(select):
    """選擇動畫層"""
