def thCreateTxtF(
    txt, objs, size=1, font='Noto Sans TC', isCenterPivot=False, rotate=(0, 0, 0),
    isOverrideDisplayType=True):
    """創建說明文字"""
    list_ = []
    for obj in objs:
        # 創建
        node = cmds.textCurves(f=font, t=txt, n=obj, ch=False)
        # 命名 grp
        newName = cmds.rename(node[0], f'{obj}_txt_grp#')
        list_.append(newName)
        # 刪除子 grp
        children = cmds.listRelatives(newName, c=True, typ='transform')
        cmds.ungroup(children)
        # 命名 curve
        children = cmds.listRelatives(newName, c=True, typ='transform')
        for c in children:
            cmds.rename(c, f'{obj}_txt#')
        # template
        cmds.setAttr(f'{newName}.overrideEnabled', 1)
        if isOverrideDisplayType:
            cmds.setAttr(f'{newName}.overrideDisplayType', 2)
        else:
            cmds.setAttr(f'{newName}.overrideDisplayType', 1)
        # center pivot
        if isCenterPivot:
            cmds.xform(newName, cp=True)
        # rotate
        cmds.rotate(rotate[0], rotate[1], rotate[2], newName, r=False, os=True, fo=True)
        # 對位
        ThAdsorptionObj([newName], obj, 't')
        # scale
        cmds.setAttr(f'{newName}.s', size, size, size)
        # parent
        cmds.parent(newName, obj)
    cmds.select(list_, r=True)
    return list_


def thSetShapeAttrF(objs, attr, data=None):
    """設定 shape attr"""
    try:
        shapeList = cmds.listRelatives(objs, f=True, s=True)
        #
        if not data is None:
            doData = data
        else:
            doData = 0 if cmds.getAttr(f'{shapeList[0]}.{attr}') else 1
        #
        for shape in shapeList:
            cmds.setAttr(f'{shape}.{attr}', doData)
    except:
        pass


def thDataTransferF(
    refList, newList, clear=True, addUp=False, addUpScale=False, scaleList=None,
    scaleValue=None):
    """數值傳遞"""
    attrs = ['tx', 'ty', 'tz', 'rx', 'ry', 'rz', 'sx', 'sy', 'sz']
    # get
    data0 = []
    for n in refList:
        data1 = []
        for attr in attrs:
            data1.append(cmds.getAttr('{}.{}'.format(n, attr)))
        data0.append(data1)
    # scale
    if scaleList:
        defData = [0, 0, 0, 0, 0, 0, 1, 1, 1]
        for i, n in enumerate(refList):
            if not n in scaleList:
                continue
            for ii, attr in enumerate(attrs):
                data0[i][ii] = ((data0[i][ii] - defData[ii]) * scaleValue) + defData[ii]
    # add
    if addUp:
        addAttr = attrs if addUpScale else attrs[:6]
        for i, n in enumerate(newList):
            for ii, attr in enumerate(addAttr):
                data = cmds.getAttr('{}.{}'.format(n, attr))
                data0[i][ii] += data
    # set
    for i, n in enumerate(newList):
        for ii, attr in enumerate(attrs):
            cmds.setAttr('{}.{}'.format(n, attr), data0[i][ii])  # clear
    if clear:
        stratData = [0, 0, 0, 0, 0, 0, 1, 1, 1]
        for n in refList:
            for ii, attr in enumerate(attrs):
                cmds.setAttr('{}.{}'.format(n, attr), stratData[ii])


def thDeleteDrivenKeyF(objs):
    """刪除 driven key"""
    type = ['animCurveUA', 'animCurveUL', 'animCurveUU']
    for obj in objs:
        list_ = cmds.listConnections(obj)
        for n in list_:
            for t in type:
                if cmds.nodeType(n) == t:
                    cmds.delete(n)
                    break


def thDynOutlinerF(objs, main, rename=True):
    """歸納力學物件"""
    if main:
        # 獲取標籤名
        label = main.replace('_dyn_grp', '')
        # 獲取物件類別列表
        objTypes = thTypeF(objs)
        # 定義列表
        types = [['hairSystem'], ['nCloth'], ['nucleus'], ['nRigid'], ['mesh'],
            ['airField', 'dragField', 'gravityField', 'newtonField', 'radialField',
                'turbulenceField', 'uniformField', 'vortexField']]
        tx = ['hairSystem', 'nCloth', 'nucleus', 'nRigid', 'mesh', 'field']
        # 創建基本 grp
        if not cmds.objExists('dyn'):
            cmds.group(em=True, n='dyn')
        if not cmds.objExists(label + '_dyn_grp'):
            cmds.group(em=True, n=label + '_dyn_grp')
            cmds.parent(label + '_dyn_grp', 'dyn')
        # 進入物件循環
        for i, obj in enumerate(objs):
            # 物件屬於 types 列表中的多少索引直
            inbex = None
            for ii, type0 in enumerate(types):
                for type1 in type0:
                    if objTypes[i] == type1:
                        inbex = ii
                        break
            # 如果找不到索引值就定義為 'other' 類別
            typ = 'other' if inbex is None else tx[inbex]
            grp = '{}_dyn_{}_grp'.format(label, typ)
            # 創建 grp
            if not cmds.objExists(grp):
                cmds.group(em=True, n=grp)
                cmds.parent(grp, label + '_dyn_grp')
            # rename and parent
            nName = obj
            if rename:
                nName = cmds.rename(
                    obj, '{}_dyn_{}#'.format(label, objTypes[i]))
            cmds.parent(nName, grp)


def thFieldTurbulenceF(meshList, ctrl, dynNode, name='object'):
    """假風場"""
    if not meshList:
        return
    # 創建假風場
    field = cmds.turbulence(
        n=name + '_turbulenceField#', pos=[0, 0, 0], m=5, att=1, f=1, phaseX=0, phaseY=0, phaseZ=0,
        noiseLevel=0, noiseRatio=0.707, mxd=1, vsh='none', vex=0, vof=[0, 0, 0], vsw=360, tsr=0.5)[
        0]
    dynNodeShape = cmds.listRelatives(dynNode, s=True)[0]
    cmds.connectDynamic(dynNodeShape, f=field)
    cmds.setAttr(field + '.attenuation', 0)
    cmds.setAttr(field + '.useMaxDistance', 0)
    # 添加屬性
    cmds.addAttr(ctrl, k=True, ln='field', at='enum', en='------:------:')
    cmds.setAttr(ctrl + '.field', e=True, channelBox=True)
    cmds.addAttr(ctrl, k=True, ln='magnitude_', at='double', dv=5)
    cmds.addAttr(ctrl, k=True, ln='frequency_', at='double', dv=1)
    cmds.addAttr(ctrl, k=True, ln='field_wind_X', at='double', dv=1)
    cmds.addAttr(ctrl, k=True, ln='field_wind_Y', at='double', dv=0)
    cmds.addAttr(ctrl, k=True, ln='field_wind_Z', at='double', dv=0)
    # ex
    ex = ''
    ex += '{0}.magnitude = {1}.magnitude_;\n'
    ex += '{0}.frequency = {1}.frequency_;\n'
    ex += '{0}.tx = frame * {1}.field_wind_X;\n'
    ex += '{0}.ty = frame * {1}.field_wind_Y;\n'
    ex += '{0}.tz = frame * {1}.field_wind_Z;'
    ex = ex.format(field, ctrl)
    cmds.expression(n='{}_dynField_EX#'.format(name), s=ex)


def thGrpParentF(objs, reverse=False, layout_=0, select=True, ret=False, isFreeParent=False):
    """物件 parent to group.
    :return: str
        頂級父物件
    """
    if reverse:
        objs = objs[::-1]
    grp = objs[:-1]
    obj = objs[1:]
    #
    for i, g in enumerate(grp):
        # 找父層級
        father = g
        for ii in range(layout_):
            father = cmds.listRelatives(father, ap=True)[0]
        #
        if isFreeParent:
            ThFreeParent(obj[i], [father])
        else:
            cmds.parent([father, obj[i]])
    #
    if select:
        cmds.select(objs, r=True)
    #
    if ret:
        father = objs[-1]
        for i in range(layout_):
            father = cmds.listRelatives(father, ap=True)[0]
        return father


def thCvToFollowLocF(cvList, quantity, name='obj'):
    """曲線上創建跟隨 locator"""
    locList = []

    def app(cv, quantity, name):
        locList = []
        # 判斷是否為閉合曲線
        shape = cmds.listRelatives(cv, f=True, s=True)[0]
        open = cmds.getAttr(shape + '.form')
        openClose = 0 if open else 1
        maxVertex = cmds.getAttr(shape + '.maxValue')
        addTime = maxVertex / (quantity - openClose)
        #
        add = 0
        for i in range(quantity):
            # 創建曲線測量結點
            poci = cmds.createNode(
                'pointOnCurveInfo', n='{}_pointOnCurveInfo{}'.format(name, i + 1))
            # 設置位置
            cmds.setAttr(poci + '.parameter', add)
            # 關聯 curve
            cmds.connectAttr(shape + '.worldSpace[0]', poci + '.inputCurve')
            # 創建 locator
            loc = cmds.spaceLocator(n='{}_locator{}'.format(name, i + 1))[0]
            locList.append(loc)
            # 關聯 locator
            cmds.connectAttr(poci + '.position', loc + '.translate')
            #
            add += addTime
            if add > maxVertex:
                add = maxVertex
        return locList

    #
    for i, n in enumerate(cvList, 1):
        locList.extend(app(n, quantity, '{}{}'.format(name, i)))
    cmds.select(locList, r=True)
    return locList


def thSetNoAniF(objs):
    """設置不動"""
    if not cmds.objExists('def'):
        cmds.group(em=True, n='def')
    grpList = thLocatorGrpF(objs, 'nAnim')
    sys_ = cmds.group(em=True, n='thNoAnimObjSys#')
    cmds.parent(sys_, 'def')
    for i, n in enumerate(objs):
        cGrp1 = cmds.group(em=True, n='nLoc_{}1'.format(grpList[i]))
        cGrp2 = cmds.group(cGrp1, n='nLoc_{}2'.format(grpList[i]))
        cmds.parent(cGrp2, sys_)
        cmds.parentConstraint([sys_, cGrp1], mo=True, weight=1)
        cmds.connectAttr('{}.t'.format(n), '{}.t'.format(cGrp2))
        cmds.connectAttr('{}.r'.format(n), '{}.r'.format(cGrp2))
        cmds.connectAttr('{}.t'.format(cGrp1), '{}.t'.format(grpList[i]))
        cmds.connectAttr('{}.r'.format(cGrp1), '{}.r'.format(grpList[i]))


def thDelNamespaceF():
    # 取得所有命名空間（包含巢狀）
    allNamespaces = cmds.namespaceInfo(recurse=True, listOnlyNamespaces=True) or []
    # Maya 的預設命名空間，這些不能移除
    defaultNamespaces = ['UI', 'shared']
    # 過濾出自訂命名空間
    customNamespaces = [ns for ns in allNamespaces if ns not in defaultNamespaces]
    # 反向排序，從最深層的命名空間開始處理
    for namespace in sorted(customNamespaces, reverse=True):
        try:
            print(f"Merging and removing namespace: {namespace}")
            cmds.namespace(removeNamespace=namespace, mergeNamespaceWithRoot=True)
        except Exception as error:
            print(f"Failed to remove namespace {namespace}: {error}")


def thDelUnknownF():
    """刪除未知節點"""
    nodes = cmds.ls(typ='unknown')
    for n in nodes:
        if cmds.lockNode(n, q=True, l=True):
            cmds.lockNode(n, l=False)
    if nodes:
        cmds.delete(nodes)


def thRandDataF(objs, attrList, min_, max_):
    """隨機數值"""
    for obj in objs:
        for attr in attrList:
            data = random.uniform(min_, max_)
            cmds.setAttr(obj + '.' + attr, data)


def thSoftToClusterF():
    selection = cmds.ls(sl=True)
    sel = selection[0].split('.')
    richSel = om2.MGlobal.getRichSelection()
    richSelList = richSel.getSelection()
    path, component = richSelList.getComponent(0)
    componentFn = om2.MFnSingleIndexedComponent(component)
    cluster = cmds.cluster(rel=True)
    clusterSet = cmds.listConnections(cluster, type='objectSet')
    cmds.select(selection[0], r=True)
    for i in range(0, componentFn.getCompleteData()):
        weight = componentFn.weight(i)
        v = componentFn.element(i)
        w = weight.influence
        vtx = (sel[0] + '.vtx[%d]') % v
        cmds.sets(vtx, add=clusterSet[0])
        cmds.percent(cluster[0], vtx, v=w)
    cmds.select(cluster)


def thTypeF(objs):
    """回傳物件 type"""
    typeList = []
    for obj in objs:
        # 尋找子層級中的 dag
        shapes = cmds.listRelatives(obj, s=True, f=True)
        # 如果沒有 dag，就判斷物件類別
        if shapes:
            typeList.append(cmds.nodeType(shapes[0]))
        else:
            typeList.append(cmds.nodeType(obj))
    return typeList


def thClearStrF(list_, str_):
    """清除指定字符"""
    newNameList = []
    for n in list_:
        newName = n.replace(str_, '')
        newNameList.append(newName)
        if newName != n:
            cmds.rename(n, newName)
    cmds.select(newNameList, r=True)
    # 清除重複名稱
    ThRemoveDuplicateNames(newNameList).doRenameF()


def thJointDrawStyleF(joints):
    """joint 的 displat style"""
    appDict = {0: 2, 2: 0}
