def thSelectJointVtxF(joints, mesh):
    """選擇與骨骼連接的 vertex"""
    # get joints skin node
    skinNode = thFindSkinNodeF([mesh])[0]
    #
    vtxList = []
    for j in joints:
        cmds.select(cl=True)
        cmds.skinCluster(skinNode, e=True, siv=j)
        vtxList.extend(cmds.ls(sl=True, fl=True))
    cmds.select(list(set(vtxList)), r=True)


def thGetMaterialF(objs):
    """
    讀取指定物件的材質球名稱（支援多物件與防呆）
    :param objs: 物件或物件清單
    :return: 去重後的材質球名稱 list
    """
    if not objs:
        return []
    # 確保是 list（支援單一物件傳入）
    if isinstance(objs, str):
        objs = [objs]
    #
    materials = []
    #
    for obj in objs:
        # 取得 shape 節點
        shapes = cmds.listRelatives(obj, shapes=True, fullPath=True) or []
        for shape in shapes:
            # 檢查 intermediateObject 屬性是否為 0 (非中繼物件)
            isIntermediate = cmds.getAttr(shape + ".intermediateObject")
            if isIntermediate:
                continue
            # 取得 shadingEngine
            sgList = cmds.listConnections(shape, type='shadingEngine') or []
            for sg in sgList:
                # 取得材質球
                shader = cmds.connectionInfo(f'{sg}.surfaceShader', sourceFromDestination=True)
                if shader:
                    mat = shader.split('.')[0]
                    if cmds.objExists(mat):
                        materials.append(mat)
    # 去重後回傳
    return list(set(materials))


def thUseSelMaterialF(objs):
    """套用最後選擇模型之材質"""
    shape = cmds.listRelatives(objs[-1], s=True)
    sg = cmds.listConnections(shape, type='shadingEngine')[0]
    for obj in objs[:-1]:
        cmds.sets(obj, e=True, forceElement=sg)


def thBatchEnableF(objFollow, objOffset, objList, conAttr, segmentation=None):
    """控制物件屬性依序以 0 至 1 數值啟動.
    :type objFollow: str 控制跟隨的屬性
    :type objOffset: str 控制偏移的屬性
    :type objList: list 物件列表
    :type conAttr: str 被控制的屬性
    :type segmentation: int
    """
    # 計算累加值
    add = 10.0 / segmentation if segmentation else 10.0 / len(objList)
    max = add
    min = 0
    for i, obj in enumerate(objList):
        # max offset 加減節點
        maxPma = cmds.createNode('plusMinusAverage', n=obj + '_follow_max_PMA#')
        cmds.setAttr(maxPma + '.operation', 1)
        cmds.setAttr(maxPma + '.input1D[0]', max)
        cmds.connectAttr(objOffset, maxPma + '.input1D[1]')
        # min offset 加減節點
        minPma = cmds.createNode('plusMinusAverage', n=obj + '_follow_min_PMA#')
        cmds.setAttr(minPma + '.operation', 2)
        cmds.setAttr(minPma + '.input1D[0]', min)
        cmds.connectAttr(objOffset, minPma + '.input1D[1]')
        # 限制 offset max
        maxSr = cmds.createNode('setRange', n=obj + '_follow_max_SR#')
        cmds.connectAttr(maxPma + '.output1D', maxSr + '.valueX')
        cmds.setAttr(maxSr + '.oldMaxX', 10)
        cmds.setAttr(maxSr + '.oldMinX', 0)
        cmds.setAttr(maxSr + '.maxX', 10)
        cmds.setAttr(maxSr + '.minX', 0)
        # 限制 offset min
        minSr = cmds.createNode('setRange', n=obj + '_follow_min_SR#')
        cmds.connectAttr(minPma + '.output1D', minSr + '.valueX')
        cmds.setAttr(minSr + '.oldMaxX', 10)
        cmds.setAttr(minSr + '.oldMinX', 0)
        cmds.setAttr(minSr + '.maxX', 10)
        cmds.setAttr(minSr + '.minX', 0)
        # 將輸出結果限制在 0 ~ 1
        sr = cmds.createNode('setRange', n=obj + '_follow_SR#')
        cmds.connectAttr(objFollow, sr + '.valueX')
        cmds.connectAttr(maxSr + '.outValueX', sr + '.oldMaxX')
        cmds.connectAttr(minSr + '.outValueX', sr + '.oldMinX')
        cmds.setAttr(sr + '.maxX', 1)
        cmds.setAttr(sr + '.minX', 0)
        cmds.connectAttr(sr + '.outValueX', obj + '.' + conAttr)
        #
        min += add
        max += add


def thOpenPathF(mode):
    """打開該檔資料夾.
    :type mode: str
        'file' | 'temp' | 'default'
    """
    path = None
    if mode == 'file':
        path = os.path.dirname(cmds.file(q=True, sn=True))
    elif mode == 'temp':
        path = mel.eval('getenv TMPDIR')
    elif mode == 'default':
        path = cmds.workspace(q=True, rd=True)
    os.startfile(path)


def thBatchRenameF(objs, name, changeChildren=False):
    """批量重新命名
    :type objs: list
    :type name: str
    :type changeChildren: bool
    """
    newName = []
    if not changeChildren:
        for obj in objs:
            newName.append(cmds.rename(obj, name + '#'))
    else:
        # 取得新列表
        newList = []
        for obj in objs:
            allChildList = []
            childList = cmds.listRelatives(obj, ad=True)
            if childList:
                allChildList = childList
            allChildList.append(obj)
            newList.append(allChildList[::-1])
        # rename
        index1 = 1
        for list_ in newList:
            for n in list_:
                newName.append(
                    cmds.rename(n, '{}{}_#'.format(name, index1)))
            index1 += 1
    return newName


def thSelCreateJointF(objs):
    """依據選擇物件中心創建 joint"""
    cl = cmds.cluster(objs)[1]
    cmds.select(cl=True)
    jo = cmds.joint()
    ThAdsorptionObj([jo], cl, 't')
    cmds.delete(cl)
    return jo


def thMirrorJointF(joints, axial, renameName=None, automaticRe=True):
    """鏡像 joint"""
    newJoint = []
    lLift = ['left', 'left_', '_left', 'L_', '_L', 'Left', 'Left_', '_Left']
    rList = ['right', 'right_', '_right', 'R_', '_R', 'Right', 'Right_', '_Right']
    axialData = {'x': [1, 0, 0], 'y': [0, 1, 0], 'z': [0, 0, 1]}
    #
    combineLrList = [lLift, rList]

    #
    def getRenameNameF(joint):
        """自動替換名稱"""
        if not automaticRe:
            return renameName if renameName else ['', '']
        #
        for lrListId, lrList in enumerate(combineLrList):
            for lrId, lr in enumerate(lrList):
                if lr in joint:
                    return [lr, combineLrList[1 - lrListId][lrId]]
        return renameName if renameName else ['', '']

    #
    for joint in joints:
        doRenameName = getRenameNameF(joint)
        mirroredJoint = cmds.mirrorJoint(
            joint, mb=True,
            myz=axialData[axial][0], mxz=axialData[axial][1],
            mxy=axialData[axial][2], sr=doRenameName)[0]
        newJoint.append(mirroredJoint)
    #
    cmds.select(newJoint, r=True)
    return newJoint


def thWeightToCtrlF(mainObj, obj, vlSize=1):
    """以少數控制多數.
    :type mainObj: list
    :type obj: list
    :type vlSize: float
    """
    # 創建 vl
    vlCls = ThVtxLocator(
        objs=obj, name='WTC', ifVl=True, vlSize=vlSize)
    vlCls.createVlAndFollicleF()
    # constrain obj
    for i, follicle in enumerate(vlCls.follicleList):
        cmds.parentConstraint([follicle, obj[i]], mo=True, weight=1)
    # 在 mainObj 底下創建 joint
    jointList = []
    for n in mainObj:
        cmds.select(cl=True)
        joint_ = cmds.joint(n=n + '_WTC_joint#')
        # 對位
        ThAdsorptionObj([joint_], n, 'tr')
        #
        jointList.append(joint_)
        cmds.parent(joint_, n)
    # skin
    cmds.skinCluster(jointList, vlCls.vl, mi=5, dr=4.0, tsb=True)
    cmds.hide(jointList)
    # 統一 weight
    vlCls.uniteWightF([vlCls.vl])
    return jointList


def thRemoveStrNumF(str_, isClearHyphen=True):
    """去掉字符字尾數字.
    :return: list
        [新的字串, 去掉的字符]
    """
    # 去掉數字
    tx = str_
    index = re.search(r'\d*$', tx).start()
    tx = tx[:index]
    if isClearHyphen:
        # 去掉 '_'
        index = re.search(r'_*$', tx).start()
        tx = tx[:index]
    return [tx, str_[index:]]


def thLocatorGrpF(objs, name=None):
    """創建與物件相同軸向的 grp"""
    newGrpList = []
    for obj in objs:
        # 取得新名稱
        # 獲取去掉尾數的字串
        removeNum = thRemoveStrNumF(obj)
        # 新名稱
        newName = None
        # 字尾是否名為 '_grp'
        if re.search(r'_*[Gg]rp$', removeNum[0]):
            newName = removeNum[0] + '#'
        else:
            newName = removeNum[0] + removeNum[1] + '_grp#'
        # 是否增加前綴
        if name:
            if not re.search(r'^' + name, newName):
                newName = '{}_{}'.format(name, newName)
        # 取得物件父層級名稱
        father = cmds.listRelatives(obj, p=True, f=True)
        # 創建空 grp
        newGrp = cmds.group(em=True, n=newName)
        # grp 對位
        ThAdsorptionObj([newGrp], obj)
        # parent
        if father:
            cmds.parent(newGrp, father[0])
            # freeze
            cmds.makeIdentity(
                newGrp, apply=True, t=True, r=True, s=True, n=False, pn=True)
        cmds.parent(obj, newGrp)
        newGrpList.append(newGrp)
    return newGrpList


def thObjForObjSkinF(obj1, obj2):
    """依據物件 skin 物件"""
    # 物件1 的 joint
    joints = thGetSkinJointF([obj1])
    #
    cmds.skinCluster(joints, obj2, mi=5, dr=4.0, tsb=True)


def thDefSineSwirlRigF(obj):
    """Sine 變形器設定漩渦 rig effects.
    :type obj: str
    """
    # create def
    sineNode1 = cmds.nonLinear(obj, type='sine', n='def_swirl_sine#')
    sineNode2 = cmds.nonLinear(obj, type='sine', n='def_swirl_sine#')
    # set attr
    cmds.setAttr(sineNode1[0] + '.dropoff', 1)
    cmds.setAttr(sineNode1[0] + '.amplitude', .6)
    cmds.setAttr(sineNode1[0] + '.wavelength', .5)
    cmds.setAttr(sineNode2[0] + '.offset', .13)
    mainGrp = cmds.group([sineNode1[1], sineNode2[1]], n='def_swirl_sine_grp#')
    cmds.group([sineNode1[1], sineNode2[1]], n='def_swirl_sine_grp#')
    cmds.rotate(0, 0, 0, sineNode1[1])
    cmds.rotate(0, 90, 0, sineNode2[1])
    cmds.rotate(90, 0, 0, mainGrp)
    # connect
    cmds.connectAttr(
        sineNode1[0] + '.amplitude', sineNode2[0] + '.amplitude')
    cmds.connectAttr(
        sineNode1[0] + '.wavelength', sineNode2[0] + '.wavelength')
    cmds.connectAttr(
        sineNode1[0] + '.dropoff', sineNode2[0] + '.dropoff')
    cmds.select(mainGrp, r=True)


def thCtrlDefaultPoseF(objs, setAttrList=None):
    """物件回到初始值"""
    data = {'tx': 0, 'ty': 0, 'tz': 0, 'rx': 0, 'ry': 0, 'rz': 0, 'sx': 1, 'sy': 1, 'sz': 1}
    setAttrList = setAttrList if setAttrList else list(data.keys())
    for obj in objs:
        for attr in setAttrList:
            if not attr in data:
                continue
            try:
                cmds.setAttr(obj + '.' + attr, data[attr])
            except:
                pass


def thDeleteConstrainNodeF(objs):
    """刪除 constrain node"""
    typeList = [
        'pointConstraint', 'aimConstraint', 'orientConstraint', 'scaleConstraint',
        'parentConstraint', 'pointOnPolyConstraint', 'tangentConstraint',
        'normalConstraint']
    # 刪除連接到該物件的 constrain
    for obj in objs:
        for type in typeList:
            node = eval('cmds.' + type + '(obj, q=True)')
            if node:
                cmds.delete(node)
    # 刪除層級底下的 constrain node
    node = cmds.listRelatives(objs, typ=typeList, c=True, f=True)
    if node:
        cmds.delete(node)


def thReplaceCurveShapeF(objs):
    """替換 curve shape.
    :type objs: list
        [被替換的, 主要的 shape]
    """
    # 最後選擇物件的 shape
    for obj in objs[:-1]:
        # 複製基礎 curve
        new = cmds.duplicate(objs[-1], n='th_copy_shape#', rr=True)
        # 獲取基礎 curve shape
        newShape = cmds.listRelatives(new, s=True)
        # 獲取被取代 curve shape
        inShape = cmds.listRelatives(obj, s=True, f=True)
        cmds.parent(newShape, obj, r=True, s=True)
        # 刪除
        cmds.delete(new, inShape)
        cmds.rename(newShape, obj + 'Shape')
    cmds.select(objs[:-1])


def thReverseConnectF(sel, ctrlAttr, conAttr):
    """一對多控制 0 與 1 切換數值.
    :type sel: list
    :type ctrlAttr: list (ctrl, attr)
    :type conAttr: str
    """
    # 創建 node
    pma = cmds.createNode('plusMinusAverage', n=ctrlAttr[0] + '_' + ctrlAttr[1] + '_conPMA#')
    cmds.setAttr(pma + '.operation', 2)
    cmds.setAttr(pma + '.input1D[0]', 1)
    # 關聯
    cmds.connectAttr(ctrlAttr[0] + '.' + ctrlAttr[1], pma + '.input1D[1]')
    for n in sel:
        cmds.connectAttr(pma + '.output1D', n + '.' + conAttr)


def thGetSkinJointF(mesh):
    """讀取 skin 的 joint.
    :type mesh: list
    """
    jointList = []
    for n in mesh:
        pass
        skin = thFindSkinNodeF([n])[0]
        joint = cmds.skinCluster(skin, q=True, wi=True)
        jointList.extend(joint)
    return jointList


def thSetCtrlColorF(objs, color):
    """設定控制器 color.
    :type objs: list
    :type color: int
    """
    # 找物件的 shape nnode
    shape = cmds.listRelatives(objs, f=True, s=True)
    if color:
        for n in shape:
            cmds.setAttr(n + '.overrideEnabled', 1)
            cmds.setAttr(n + '.overrideColor', color)
    else:
        for n in shape:
            cmds.setAttr(n + '.overrideEnabled', 0)


