# Class

class ThEditNormals:

    @staticmethod
    def hasLockedNormals(obj):
        # 取得所有 vertexFace
        vtxFaceList = cmds.ls(obj + ".vtxFace[*][*]", fl=True)
        if not vtxFaceList:
            return False
        #
        result = cmds.polyNormalPerVertex(vtxFaceList, q=True, fn=True)
        #
        return any(result)

    @staticmethod
    def unLockNormals(obj):
        isLockNm = __class__.hasLockedNormals(obj)
        if isLockNm:
            cmds.polyNormalPerVertex(obj, ufn=True)
            cmds.polySoftEdge(obj, a=180, ch=True)


class ThFreeParent:
    def __init__(self, father, objectList):
        """子物件不受父物件縮放影響"""
        self.father = father
        # 確保 objectList 永遠是 list 格式
        self.objectList = objectList if isinstance(objectList, list) else [objectList]
        #
        self.fpJoint = None
        # 使用 fullPath=True 避免同名物件衝突
        jointList = cmds.listRelatives(self.father, ad=False, type='joint', fullPath=True)
        #
        if jointList:
            for j in jointList:
                # 取得短名稱進行比對
                shortName = j.split('|')[-1]
                if '_FP_' in shortName:
                    self.fpJoint = j
                    break
            else:
                self.createJointF()
        else:
            self.createJointF()
        # 執行 parent 前過濾，避免重複 parent 導致警告
        currentChildren = cmds.listRelatives(self.fpJoint, children=True, fullPath=True) or []
        targetsToParent = [obj for obj in self.objectList if cmds.ls(obj, l=True)[0] not in currentChildren]
        #
        if targetsToParent:
            cmds.parent(targetsToParent, self.fpJoint)

    def createJointF(self):
        """創建用於抵消縮放的 joint"""
        # 紀錄原始選取狀態
        originalSelection = cmds.ls(sl=True)
        # 取得不帶路徑的名稱作為命名基礎
        baseName = self.father.split('|')[-1]
        cmds.select(cl=True)
        # 創建 Joint 並設定屬性
        self.fpJoint = cmds.joint(n=f'{baseName}_FP_joint#')
        # 複製位姿
        fatherMatrix = cmds.xform(self.father, q=True, ws=True, m=True)
        cmds.xform(self.fpJoint, ws=True, m=fatherMatrix)
        # 層級歸屬
        cmds.parent(self.fpJoint, self.father)
        # 凍結變換但保留位姿，pn=True 確保子層級不被影響
        cmds.makeIdentity(self.fpJoint, apply=True, t=True, r=True, s=True, n=False, pn=True)
        # 關鍵：連結 inverseScale 抵消縮放
        if not cmds.isConnected(f'{self.father}.scale', f'{self.fpJoint}.inverseScale'):
            cmds.connectAttr(f'{self.father}.scale', f'{self.fpJoint}.inverseScale', f=True)
        # 設置繪製樣式為 None (隱藏 Joint 骨頭外觀)
        cmds.setAttr(f'{self.fpJoint}.drawStyle', 2)
        # 恢復原始選取
        if originalSelection:
            cmds.select(originalSelection)


class ThTexturePathSwitcher:
    def __init__(self, sysName='ThTexturePathSwitcher_data'):
        self.sysName = sysName
        #
        self.oldPrefix = None
        self.newPrefix = None
        self.data = {}  # {fileNode: originalFullPath}

    def switchF(self, oldPrefix, newPrefix, fileNodes=None):
        if cmds.objExists(self.sysName):
            cmds.select(self.sysName, r=True)
            print('object exists, skipped execution.')
            return
        #
        self.oldPrefix = os.path.normpath(oldPrefix)
        self.newPrefix = os.path.normpath(newPrefix)
        #
        fileNodes = fileNodes if fileNodes else cmds.ls(type='file')
        #
        for fileNode in fileNodes:
            attr = f"{fileNode}.fileTextureName"
            texturePath = cmds.getAttr(attr)
            if not texturePath:
                continue
            #
            normalizedPath = os.path.normpath(texturePath)
            if normalizedPath.startswith(self.oldPrefix):
                # 替換
                newPath = normalizedPath.replace(oldPrefix, newPrefix, 1)
                if not os.path.exists(newPath):
                    continue
                # 儲存歷史以便還原
                self.data[fileNode] = {'old': normalizedPath, 'new': newPath}
                #
                cmds.setAttr(attr, newPath, type="string")
                print(f"{fileNode} → {newPath}")
        #
        if self.data:
            gsd = ThGrpSaveData(self.sysName)
            gsd.setF(self.data)

    @staticmethod
    def undoF(sysNameList, mode='old'):
        """還原原本貼圖路徑"""
        for sysName in sysNameList:
            if not cmds.objExists(sysName):
                return
            #
            data = ThGrpSaveData(sysName).getF()
            #
            for fileNode, originalPathData in data.items():
                attr = f"{fileNode}.fileTextureName"
                if cmds.objExists(attr):
                    texturePath = cmds.getAttr(attr)
                    if texturePath == originalPathData[mode]:
                        continue
                    #
                    cmds.setAttr(attr, originalPathData[mode], type="string")
                    print(f"{fileNode} ← {originalPathData[mode]}")


class ThMatrixSetPose:
    objList = []
    dataDict = {}

    @classmethod
    def getF(cls, objList, worldSpace=True):
        """
        儲存物件的 transform 矩陣
        :param objList: 要儲存的物件清單
        :param worldSpace: 是否使用世界空間（預設 True）
        """
        cls.objList = thSortByHierarchyF(objList)
        cls.dataDict = {}  # 清除舊資料

        for obj in cls.objList:
            if not cmds.objExists(obj):
                print(f"⚠️ 物件不存在，跳過: {obj}")
                continue
            try:
                matrix = cmds.xform(obj, q=True, m=True, ws=worldSpace)
                cls.dataDict[obj] = matrix
            except Exception as e:
                print(f"❌ 無法取得矩陣：{obj}，錯誤：{e}")

    @classmethod
    def setF(cls, worldSpace=True):
        """
        套用先前儲存的 transform 矩陣
        :param worldSpace: 是否使用世界空間（預設 True）
        """
        if not cls.dataDict:
            print("⚠️ 尚未儲存任何矩陣")
            return

        for obj, matrix in cls.dataDict.items():
            if not cmds.objExists(obj):
                print(f"⚠️ 物件不存在，跳過: {obj}")
                continue
            try:
                cmds.xform(obj, m=matrix, ws=worldSpace)
            except Exception as e:
                print(f"❌ 套用矩陣失敗：{obj}，錯誤：{e}")


class ThDeformEdit:
    @staticmethod
    def getFfdF(latticeTransform):
        """取得 FFD Deformer 節點"""
        latticeShape = cmds.listRelatives(latticeTransform, s=True)
        if not latticeShape:
            return None
        connections = cmds.listConnections(latticeShape[0], type='ffd')
        if connections:
            return connections[0]
        return None

    @staticmethod
    def connFfdGeoF(latticeTransformList, geometryList, mode='add'):
        """添加 Geometry 到 FFD"""
        for la in latticeTransformList:
            ffd = __class__.getFfdF(la)
            if not ffd:
                continue
            for g in geometryList:
                if mode == 'add':
                    cmds.deformer(ffd, e=True, g=g)
                else:
                    cmds.deformer(ffd, e=True, rm=True, g=g)

    @staticmethod
    def selConnFfdGeoF(selectList, mode='add'):
        selTypeList = thTypeF(selectList)
        meshLisst = [s for s, st in zip(selectList, selTypeList) if st == 'mesh']
        latticeList = [s for s, st in zip(selectList, selTypeList) if st == 'lattice']
        #
        __class__.connFfdGeoF(latticeList, meshLisst, mode)


class ThAttrTypeConverter:
    @staticmethod
    def convertAttributesF(objList, attrList, toType='int'):
        """
        將指定屬性轉換類型。支援 float <-> int 轉換。
        - objName: 物件名稱
        - attrList: 屬性名稱列表 (list of str)
        - toType: 'int' or 'float'
        """
        for obj in objList:
            for attr in attrList:
                ThAttrTypeConverter._convertSingleAttributeF(obj, attr, toType)

    @staticmethod
    def _convertSingleAttributeF(obj, attrName, toType):
        fullAttr = f"{obj}.{attrName}"
        #
        if not cmds.objExists(fullAttr):
            print(f"[錯誤] 屬性不存在: {fullAttr}")
            return
        #
        currentType = cmds.getAttr(fullAttr, type=True)
        if toType == 'int' and currentType not in ['float', 'double']:
            print(f"[跳過] {fullAttr} 不是 float/double，無需轉換為 int")
            return
        if toType == 'float' and currentType not in ['long', 'short', 'byte', 'int']:
            print(f"[跳過] {fullAttr} 不是整數型別，無需轉換為 float")
            return
        # 儲存值與限制
        try:
            currentVal = cmds.getAttr(fullAttr)
        except:
            currentVal = 0
        #
        minVal = maxVal = None
        if cmds.attributeQuery(attrName, node=obj, minExists=True):
            minVal = cmds.attributeQuery(attrName, node=obj, min=True)[0]
        if cmds.attributeQuery(attrName, node=obj, maxExists=True):
            maxVal = cmds.attributeQuery(attrName, node=obj, max=True)[0]
        # 儲存連接
        sourceConn = cmds.listConnections(fullAttr, s=True, d=False, p=True) or []
        destConn = cmds.listConnections(fullAttr, s=False, d=True, p=True) or []
        # 刪除原屬性
        try:
            cmds.deleteAttr(fullAttr)
        except Exception as e:
            print(f"[錯誤] 刪除屬性失敗: {e}")
            return
        # 設定目標類型
        if toType == 'int':
            newAttrType = 'long'
            newValue = int(currentVal)
        else:
            newAttrType = 'float'
            newValue = float(currentVal)
        # 建立新屬性
        addKwargs = {
            'longName': attrName,
            'attributeType': newAttrType,
            'keyable': True,
            'defaultValue': newValue
        }
        if minVal is not None:
            addKwargs['min'] = minVal
        if maxVal is not None:
            addKwargs['max'] = maxVal
        #
        try:
            cmds.addAttr(obj, **addKwargs)
            cmds.setAttr(fullAttr, newValue)
        except Exception as e:
            print(f"[錯誤] 建立新屬性失敗: {e}")
            return
        # 還原連接
        for src in sourceConn:
            try:
                cmds.connectAttr(src, fullAttr, force=True)
            except Exception as e:
                print(f"[警告] 無法從 {src} 連接到 {fullAttr}: {e}")
        #
        for dst in destConn:
            try:
                cmds.connectAttr(fullAttr, dst, force=True)
            except Exception as e:
                print(f"[警告] 無法從 {fullAttr} 連接到 {dst}: {e}")
        #
        print(f"[完成] 已將 {fullAttr} 轉為 {newAttrType}")


class ThVlSysSkinDrivenConstraint:
    def __init__(self, mesh, objList, conMode='scale'):
        self.mesh = mesh
        self.objList = objList
        self.conMode = conMode
        #
        self.skinCluster = self.getSkinClusterF(mesh)
        #
        if not self.skinCluster:
            raise RuntimeError(f"找不到 skinCluster，請確認 mesh 是否已綁定權重: {mesh}")
        #
        self.influenceJoints = cmds.skinCluster(self.skinCluster, q=True, inf=True)
        self.constraintData = {}

    def getSkinClusterF(self, mesh):
        """取得指定 mesh 的 skinCluster"""
        history = cmds.listHistory(mesh)
        skinClusters = cmds.ls(history, type='skinCluster')
        return skinClusters[0] if skinClusters else None

    def getVertexWeightsF(self, vertexIndex):
        """取得指定頂點的 skin weights 資訊"""
        weightDict = {}
        for joint in self.influenceJoints:
            weight = cmds.skinPercent(
                self.skinCluster,
                f'{self.mesh}.vtx[{vertexIndex}]',
                transform=joint,
                q=True
            )
            if weight > 0.0:
                weightDict[joint] = weight
        return weightDict

    def applyConstraintsF(self):
        """建立 constraint 並使用 expression 控制其權重"""
        vertexIdList = [(i * 3) + 2 for i in range(len(self.objList))]
        #
        for vertexId, obj in zip(vertexIdList, self.objList):
            weightData = self.getVertexWeightsF(vertexId)
            if not weightData:
                continue
            # 建立 parentConstraint
            jointList = list(weightData.keys())
            constraintDrivers = jointList + [obj]
            if self.conMode == 'scale':
                constraintNode = cmds.scaleConstraint(constraintDrivers, mo=True)[0]
            elif self.conMode == 'parent':
                constraintNode = cmds.parentConstraint(constraintDrivers, mo=True)[0]
            elif self.conMode == 'point':
                constraintNode = cmds.pointConstraint(constraintDrivers, mo=True)[0]
            elif self.conMode == 'rotate':
                constraintNode = cmds.orientConstraint(constraintDrivers, mo=True)[0]
            #
            self.constraintData[constraintNode] = jointList
            # 建立 expression 控制 constraint 權重
            expressionStr = f"// 自動生成權重表達式 for {constraintNode}\n"
            sumWeight = 0
            for i, joint in enumerate(jointList[:-1]):
                attr = f'{constraintNode}.{joint}W{i}'
                weight = round(weightData[joint], 3)
                expressionStr += f'{attr} = {weight};\n'
                sumWeight += weight
            else:
                attr = f'{constraintNode}.{jointList[-1]}W{i + 1}'
                expressionStr += f'{attr} = {1 - sumWeight};\n'
            # 建立 Maya expression
            cmds.expression(
                name=f'exp_{obj}_{vertexId}#',
                s=expressionStr
            )


class ThAttrLockManager:
    """解鎖指定物件所有 keyable 屬性，並可還原原始 lock 狀態"""

    def __init__(self, objectList, isUnlockAllAttrs=True):
        self.objectList = objectList
        self.isUnlockAllAttrs = isUnlockAllAttrs
        #
        self.lockState = {}
        #
        self._unlockAllKeyableAttrsF()

    def _unlockAllKeyableAttrsF(self):
        for obj in self.objectList:
            keyableAttrs = cmds.listAttr(obj, keyable=True) or []
            if cmds.nodeType(obj) == 'blendShape':
                keyableAttrs.extend(cmds.listAttr(obj + '.w', m=True) or [])
            #
            for attr in keyableAttrs:
                fullAttr = f"{obj}.{attr}"
                if cmds.objExists(fullAttr):
                    isLocked = cmds.getAttr(fullAttr, lock=True)
                    if isLocked:
                        self.lockState[fullAttr] = cmds.getAttr(fullAttr)
                        if self.isUnlockAllAttrs:
                            cmds.setAttr(fullAttr, lock=False)

    def restoreLocksF(self):
        """還原所有原本被鎖住的屬性狀態"""
        for fullAttr, value in self.lockState.items():
            if cmds.objExists(fullAttr):
                cmds.setAttr(fullAttr, value)
                cmds.setAttr(fullAttr, lock=True)

    @staticmethod
    def transferF(main, objList):
        alm = __class__([main], isUnlockAllAttrs=False)
        for obj in objList:
            for fullAttr, value in alm.lockState.items():
                if cmds.getAttr(fullAttr, lock=True):
                    continue
                #
                attr = fullAttr.split('.')[1]
                objAttr = f"{obj}.{attr}"
                if cmds.objExists(objAttr):
                    cmds.setAttr(objAttr, value)
                    cmds.setAttr(objAttr, lock=True)


class ThSetDeltaMushWeight:

    def setWeightF(self):
        """依據軟選擇設定 DeltaMush 權重"""
        sels = cmds.ls(sl=True)
        if not sels:
            return
        # 獲取 deltaMush 列表
        selMdl = sels[0].split('.')[0]
        historyNodes = cmds.listHistory(selMdl) or []
        deltaMushList = [x for x in historyNodes if cmds.nodeType(x) == "deltaMush"]
        if not deltaMushList:
            return
        # 獲取軟選擇權重
        softIdList, softWeightList = thGetSoftSelectWeightDataF()
        softWeightList = [1 - x for x in softWeightList]
        # 設定權重
        for dm in deltaMushList:
            for id, w in zip(softIdList, softWeightList):
                attr = f"{dm}.weightList[0].weights[{id}]"
                cmds.setAttr(attr, w)
        #
        cmds.select(selMdl, r=True)

    def backF(self):
        sels = cmds.ls(sl=True)
        if not sels:
            return
        #
        for s in sels:
            historyNodes = cmds.listHistory(sels) or []
            deltaMushList = [x for x in historyNodes if cmds.nodeType(x) == "deltaMush"]
            # 獲取 poly 頂點數量
            vertexCount = cmds.polyEvaluate(s, vertex=True)
            # 設定權重
            for dm in deltaMushList:
                for i in range(vertexCount):
                    attr = f"{dm}.weightList[0].weights[{i}]"
                    cmds.setAttr(attr, 1)


class ThGetObjLayoutVis:
    def __init__(self, groupNameList):
        """
        初始化類別，可接受單一 group 或 group 名稱列表
        :param groupNameList: str 或 list，群組名稱或群組名稱列表
        """
        self.groupNameList = groupNameList
        self.visibleModels = []
        self.rootJoints = set()

    def getAllParentsF(self, nodeName):
        """回傳指定物件所有父層級 (由最近到最上層)"""
        parentsList = []
        #
        current = nodeName
        while True:
            parent = cmds.listRelatives(current, fullPath=True, parent=True)
            if not parent:
                break
            #
            parentNode = parent[0]
            parentsList.append(parentNode)
            current = parentNode
        #
        return parentsList

    def getRangeTimeeVisModeListF(self, range_=None):
        # 判斷時間
        if range_ is None:
            staet = int(cmds.playbackOptions(q=True, min=True))
            end = int(cmds.playbackOptions(q=True, max=True))
            range_ = [staet, end]
        rangeLen = abs(range_[1] - range_[0])
        # 獲取物件與父物件
        meshDict = {}
        meshList = self.getActiveMeshTransformsF(self.groupNameList)
        for _m in meshList:
            meshDict[_m] = self.getAllParentsF(_m)
        # 循環時間判斷物件是否顯示
        doMeshSet = set()
        for _i in range(rangeLen + 1):
            cmds.currentTime(range_[0] + _i)
            for _m, _fs in meshDict.items():
                isVis = all([cmds.getAttr(f'{x}.v') for x in _fs] + [cmds.getAttr(f'{_m}.v')])
                if isVis:
                    doMeshSet.add(_m)
        return list(doMeshSet)

    def getVisibleModelsAndRootJointsF(self):
        """
        執行主邏輯，回傳可見模型與根骨骼列表
        :return: [模型列表, 根骨骼列表]
        """
        for group in self.groupNameList:
            allDescendants = cmds.listRelatives(group, allDescendents=True, fullPath=True) or []
            allTransforms = [node for node in allDescendants if cmds.nodeType(node) == "transform"]
            #
            for transform in allTransforms:
                # 檢查是否顯示於場景中
                if not cmds.getAttr(transform + ".visibility"):
                    continue
                if not self.isVisibleInHierarchyF(transform):
                    continue
                # 檢查是否為可渲染模型
                shapes = cmds.listRelatives(transform, shapes=True, fullPath=True) or []
                if not shapes:
                    continue
                #
                validShape = any(cmds.nodeType(shape) in ["mesh", "nurbsSurface"] for shape in shapes)
                if not validShape:
                    continue
                #
                self.visibleModels.append(transform)
                # 檢查 skinCluster 並找出骨骼
                for shape in shapes:
                    historyNodes = cmds.listHistory(shape) or []
                    skinClusters = [node for node in historyNodes if cmds.nodeType(node) == "skinCluster"]
                    for skinCluster in skinClusters:
                        joints = cmds.skinCluster(skinCluster, query=True, influence=True) or []
                        for joint in joints:
                            parent = cmds.listRelatives(joint, parent=True, fullPath=True)
                            if not parent or cmds.nodeType(parent[0]) != "joint":
                                self.rootJoints.add(joint)
        #
        return [cmds.ls(self.visibleModels), list(self.rootJoints)]

    def isVisibleInHierarchyF(self, nodeName):
        """
        檢查節點與其所有父層是否皆為可見
        :param nodeName: str, 要檢查的節點名稱
        :return: bool
        """
        current = nodeName
        while current:
            if not cmds.getAttr(current + ".visibility"):
                return False
            current = cmds.listRelatives(current, parent=True, fullPath=True)
            current = current[0] if current else None
        return True

    def getActiveMeshTransformsF(self, rootNodeList=None):
        """獲取層級下所以有顯示的模型"""
        rootNodeList = rootNodeList or self.groupNameList
        # 檢查輸入是否為列表，如果不是則轉換為列表以方便統一處理
        if not isinstance(rootNodeList, list):
            rootNodeList = [rootNodeList]
        #
        activeTransforms = []
        #
        for rootNode in rootNodeList:
            # 獲取該節點層級下所有的 mesh 節點
            allMeshShapes = cmds.listRelatives(rootNode, allDescendents=True, type="mesh", fullPath=True)
            #
            if not allMeshShapes:
                continue
            #
            for shape in allMeshShapes:
                # 檢查 intermediateObject 屬性是否為 0 (非中繼物件)
                isIntermediate = cmds.getAttr(shape + ".intermediateObject")
                #
                if not isIntermediate:
                    # 獲取該 shape 的父位階 (Transform 節點)
                    parentTransform = cmds.listRelatives(shape, parent=True, fullPath=True)
                    #
                    if parentTransform:
                        activeTransforms.append(parentTransform[0])
        # 使用 set 移除重複項並回傳列表
        return list(set(activeTransforms))


class ThObjAverager:
    def __init__(self, objList, axisList=['x', 'y', 'z']):
        self.objList = objList
        self.axisList = axisList

    def averageF(self):
        if not self.objList:
            return
        self.objListLen = len(self.objList)
        if self.objListLen < 3:
            return
        data = self.getPositionF()
        newData = self.updateF(data)
        for _o, _d in zip(self.objList, newData):
            cmds.xform(_o, ws=True, t=_d)

    def getPositionF(self):
        """取得世界位置"""
        positionList = []
        for _obj in self.objList:
            pos = cmds.xform(_obj, q=True, ws=True, t=True)
            positionList.append(pos)
        return positionList

    def updateF(self, data):
        newData = copy.deepcopy(data)
        axisDict = {'x': 0, 'y': 1, 'z': 2}
        for _axis in self.axisList:
            axisIdx = axisDict[_axis]
            startPos = data[0][axisIdx]
            endPos = data[-1][axisIdx]
            totalDistance = endPos - startPos
            average = totalDistance / (self.objListLen - 1)
            for i in range(1, self.objListLen - 1):
                newData[i][axisIdx] = startPos + average * i
        return newData


class ThUVComparer:
    def __init__(self, meshNameList):
        """初始化，儲存多個 Mesh 名稱"""
        self.meshNameList = meshNameList

    def getUVsF(self, meshName):
        """取得單一 Mesh 的 UV 資訊（依照面頂點順序）"""
        sel = om2.MSelectionList()
        sel.add(meshName)
        dagPath = sel.getDagPath(0)
        mfnMesh = om2.MFnMesh(dagPath)
        uArray, vArray = mfnMesh.getUVs()
        uvCounts, uvIds = mfnMesh.getAssignedUVs()
        uvPerVertex = []
        # 逐面取得每個頂點對應的 UV
        for faceId in range(mfnMesh.numPolygons):
            verts = mfnMesh.getPolygonVertices(faceId)
            for localVertId in range(len(verts)):
                uvIndex = mfnMesh.getPolygonUVid(faceId, localVertId)
                uv = (round(uArray[uvIndex], 6), round(vArray[uvIndex], 6))
                uvPerVertex.append(uv)
        return uvPerVertex

    def comparePairF(self, meshA, meshB):
        """比較兩個單一 Mesh 的 UV 是否一致"""
        uvsA = self.getUVsF(meshA)
        uvsB = self.getUVsF(meshB)
        if len(uvsA) != len(uvsB):
            print(f"UV 數量不一致: {meshA} vs {meshB}")
            return False
        for i, (uv1, uv2) in enumerate(zip(uvsA, uvsB)):
            if uv1 != uv2:
                print(f"第 {i} 個 UV 不一致: {meshA} vs {meshB} → {uv1} vs {uv2}")
                return False
        print(f"UV 完全一致: {meshA} vs {meshB}")
        return True

    def compareMeshListsF(self, otherMeshList):
        """逐一比較兩個 Mesh 列表的 UV"""
        errorList = []
        if len(self.meshNameList) != len(otherMeshList):
            print("Mesh 列表長度不一致")
            return False
        allMatch = True
        for meshA, meshB in zip(self.meshNameList, otherMeshList):
            result = self.comparePairF(meshA, meshB)
            if not result:
                errorList.append(meshB)
                allMatch = False
        if allMatch:
            cmds.select(cl=True)
            print("所有 Mesh UV 完全一致")
        else:
            cmds.select(errorList, r=True)
            print("有些 Mesh UV 不一致")
        return allMatch


class ThObjectSorter:
    """
    一個用於根據參考物件順序來重新排序另一組物件的工具類。
    """

    def __init__(self, referenceList, targetList, tolerance=0.01):
        """
        初始化排序器，並獲取物件座標。
        """
        self.referenceList = referenceList
        self.targetList = targetList
        self.tolerance = tolerance
        # 取得物件的世界座標
        self.referencePositions = {obj: self.getWorldPositionF(obj) for obj in referenceList}
        self.targetPositions = {obj: self.getWorldPositionF(obj) for obj in targetList}

    def getWorldPositionF(self, obj):
        """獲取物件的世界座標"""
        return cmds.xform(obj, query=True, worldSpace=True, rotatePivot=True)

    def calculateDistanceF(self, posA, posB):
        """計算兩個座標點之間的尤拉距離平方（省去開根號提高效能）"""
        return sum((a - b) ** 2 for a, b in zip(posA, posB))

    def findClosestMatchF(self, referencePos, currentTargetPool):
        """在剩餘的目標池中找到距離最近且在誤差範圍內的物件"""
        bestMatch = None
        minDistance = self.tolerance ** 2
        #
        for obj, pos in currentTargetPool.items():
            dist = self.calculateDistanceF(referencePos, pos)
            if dist <= minDistance:
                minDistance = dist
                bestMatch = obj
        #
        return bestMatch

    def sortObjectsF(self):
        """根據 referenceList 的順序來重新排序 targetList"""
        sortedTargetList = []
        # 建立一個動態的目標池複本，避免重複匹配
        tempTargetPool = self.targetPositions.copy()
        #
        for refObj in self.referenceList:
            refPos = self.referencePositions[refObj]
            matchedObj = self.findClosestMatchF(refPos, tempTargetPool)
            #
            if matchedObj:
                sortedTargetList.append(matchedObj)
                # 找到後立即從池中移除，確保一對一對應
                del tempTargetPool[matchedObj]
            else:
                # 若找不到，則放入 None 以保持列表長度一致，並打印詳細警告
                sortedTargetList.append(None)
                print(f"警告：找不到與 {refObj} 匹配的物件！座標: {refPos}")
        #
        return sortedTargetList

    def applySelectionF(self):
        """執行排序並選取排序後的物件"""
        sortedTargetList = self.sortObjectsF()
        # 過濾掉 None 值的物件以便執行選取
        validList = [obj for obj in sortedTargetList if obj is not None]
        #
        if validList:
            cmds.select(validList, replace=True)
        #
        if len(validList) != len(self.referenceList):
            print(f"排序完成，但數量不符！預期: {len(self.referenceList)}, 實際: {len(validList)}")
        else:
            print("排序完成，物件數量完全一致！")
        #
        return sortedTargetList


class ThBlendShapeCleaner:
    def __init__(self, meshName, blendShapeName):
        self.meshName = meshName
        self.blendShapeName = blendShapeName
        # 斷開連接
        self.dc = ThDisconnectConnect('ThBlendShapeCleaner__init__')
        self.dc.switchF([blendShapeName])

    def roundSmallMorphChangesF(self, round_=2):
        # 獲取基礎網格形狀
        shapes = cmds.listRelatives(self.meshName, shapes=True)
        if not shapes:
            print(f'no shape found for {self.meshName}')
            return
        # 獲取所有 Blend Shape 目標
        targetAttrs = cmds.listAttr(self.blendShapeName + ".w", multi=True)
        if not targetAttrs:
            print(f'no blend shapes found on {self.blendShapeName}')
            return
        # 獲取基礎網格的 MObject
        baseShape = shapes[0]
        sel = om.MSelectionList()
        sel.add(baseShape)
        dagPath = sel.getDagPath(0)
        baseMesh = om.MFnMesh(dagPath)
        # 關閉所有屬性
        for target in targetAttrs: cmds.setAttr(f'{self.blendShapeName}.{target}', 0)
        # 關閉編輯狀態
        cmds.sculptTarget(self.blendShapeName, e=True, target=-1)
        # 循環屬性
        for target in targetAttrs:
            # 設置目標權重為 1.0 以獲取變化後的頂點
            bsAttr = f'{self.blendShapeName}.{target}'
            cmds.setAttr(bsAttr, 1.0)
            targetPoints = baseMesh.getPoints(om.MSpace.kObject)
            newTargetPoints = []
            # 四捨五入
            for _point in targetPoints:
                newTargetPoints.append(
                    om.MPoint(round(_point.x, round_), round(_point.y, round_), round(_point.z, round_), _point.w))
            # 啟用編輯
            targetId = ThEditBlendShape.findIdAttrF(self.blendShapeName, target)
            cmds.sculptTarget(self.blendShapeName, e=True, target=int(targetId[7:-1]))
            # 設置座標
            baseMesh.setPoints(newTargetPoints, om.MSpace.kObject)
            # 關閉編輯
            cmds.sculptTarget(self.blendShapeName, e=True, target=int(targetId[7:-1]))
            #
            cmds.setAttr(bsAttr, 0)
        # 還原連接
        self.dc.switchF()

    def cleanSmallMorphChangesF(self, threshold=0.01):
        # 獲取基礎網格形狀
        shapes = cmds.listRelatives(self.meshName, shapes=True)
        if not shapes:
            print(f'no shape found for {self.meshName}')
            return
        # 獲取所有 Blend Shape 目標
        targetAttrs = cmds.listAttr(self.blendShapeName + ".w", multi=True)
        if not targetAttrs:
            print(f'no blend shapes found on {self.blendShapeName}')
            return
        # 獲取基礎網格的 MObject
        baseShape = shapes[0]
        sel = om.MSelectionList()
        sel.add(baseShape)
        dagPath = sel.getDagPath(0)
        baseMesh = om.MFnMesh(dagPath)
        basePoints = baseMesh.getPoints(om.MSpace.kObject)
        # 關閉所有屬性
        for target in targetAttrs: cmds.setAttr(f'{self.blendShapeName}.{target}', 0)
        # 關閉編輯狀態
        cmds.sculptTarget(self.blendShapeName, e=True, target=-1)
        # 循環屬性
        for target in targetAttrs:
            # 設置目標權重為 1.0 以獲取變化後的頂點
            bsAttr = f'{self.blendShapeName}.{target}'
            cmds.setAttr(bsAttr, 1.0)
            targetPoints = baseMesh.getPoints(om.MSpace.kObject)
            for i in range(len(basePoints)):
                # 修正: 只在變化幅度大於閾值時才保留變形
                if abs(targetPoints[i].x - basePoints[i].x) < threshold:
                    targetPoints[i].x = basePoints[i].x
                if abs(targetPoints[i].y - basePoints[i].y) < threshold:
                    targetPoints[i].y = basePoints[i].y
                if abs(targetPoints[i].z - basePoints[i].z) < threshold:
                    targetPoints[i].z = basePoints[i].z
            # 啟用編輯
            targetId = ThEditBlendShape.findIdAttrF(self.blendShapeName, target)
            targetIndex = int(targetId[7:-1])  # 解析 ID
            cmds.sculptTarget(self.blendShapeName, e=True, target=targetIndex)
            # 設置新頂點數據
            baseMesh.setPoints(targetPoints, om.MSpace.kObject)
            # 關閉編輯
            cmds.sculptTarget(self.blendShapeName, e=True, target=targetIndex)
            #
            cmds.setAttr(bsAttr, 0)
        # 還原連接
        self.dc.switchF()

    @staticmethod
    def appSelCleanSmallMorphChangesF(threshold=0.015):
        selectList = cmds.ls(sl=True)
        if not selectList:
            return
        typeList = thTypeF(selectList)
        for _sel, _type in zip(selectList, typeList):
            if _type != 'mesh':
                continue
            bsNodeList = thFindBlendShapeNodeF([_sel])
            if not bsNodeList:
                continue
            cleaner = ThBlendShapeCleaner(_sel, bsNodeList[0])
            cleaner.cleanSmallMorphChangesF(threshold=threshold)


class ThSelectCustomizeObj:

    @staticmethod
    def filterApplyF(list_, str_, yesNo, isSelect=True):
        """篩選"""
        if not str_:
            return
        selectList = list_
        if not selectList:
            return
        newList = thFilterNameListF(selectList, str_, yesNo)
        if isSelect:
            cmds.select(newList, r=True)
        return newList

    @staticmethod
    def modifyStrF(list_, clearStr='', addStartText='', addEndStr='', repList=None, isSelect=True):
        newList = list_
        if clearStr:
            newList = [x.replace(clearStr, '') for x in newList]
        if addStartText or addEndStr:
            newList = [f'{addStartText}{x}{addEndStr}' for x in newList]
        if repList:
            newList = [x.replace(repList[0], repList[1]) for x in newList]
        #
        if isSelect:
            selectList = []
            noList = []
            for n in newList:
                if cmds.objExists(n):
                    selectList.append(n)
                else:
                    noList.append(n)
            cmds.select(selectList, r=True)
            if noList:
                cmds.warning(ThLanguage.tr('找不到: {}').format(', '.join(noList)))
        return newList


class ThSetToMaterial:
    def __init__(self, inpList, outList):
        self.inpList = inpList
        self.outList = outList
        self.data = {}
        # 獲取物件與材質對應數據
        self.getMatDataF()
        cmds.select(cl=True)

    def setF(self):
        errorList = []
        for _inp, _out in zip(self.inpList, self.outList):
            inpFaceCount = cmds.polyEvaluate(_inp, face=True)
            outFaceCount = cmds.polyEvaluate(_out, face=True)
            if inpFaceCount != outFaceCount:
                errorList.append(_out)
                continue
            for _mat, _face in self.data[_inp].items():
                sgNode = self.getShadingEngineF(_mat)
                if sgNode:
                    faceList = [f'{_out}.f{x}' for x in _face]
                    cmds.sets(faceList, e=True, fe=sgNode)
        if errorList:
            cmds.select(errorList, r=True)
            print(f'error objs: {errorList}')

    def getMatDataF(self):
        """獲取物件與材質對應數據"""
        for _inp in self.inpList:
            matList = thGetMaterialF([_inp])
            for _mat in matList:
                objList = self.getFacesByMaterialF(_mat)
                if not objList:
                    continue
                for item in objList:
                    if '.f' in item:
                        self.addFaceToDataF(item, _mat)
                    else:
                        self.addAllFacesToDataF(item, _mat)

    def getShadingEngineF(self, material):
        """獲取材質的 shading engine"""
        connections = cmds.listConnections(material, type='shadingEngine')
        return connections[0] if connections else None

    def getFacesByMaterialF(self, material):
        """獲取材質對應的面"""
        cmds.hyperShade(objects=material)
        return cmds.ls(sl=True)

    def addFaceToDataF(self, faceItem, material):
        """添加單個面的數據"""
        objName, faceRange = faceItem.split('.f')
        if objName in self.inpList:
            if objName not in self.data:
                self.data[objName] = {}
            if material not in self.data[objName]:
                self.data[objName][material] = []
            self.data[objName][material].append(faceRange)

    def addAllFacesToDataF(self, objName, material):
        """添加所有面的數據"""
        transform = cmds.listRelatives(objName, parent=True)[0]
        if transform in self.inpList:
            faceCount = cmds.polyEvaluate(transform, face=True)
            faces = ['[0:{}]'.format(faceCount - 1)]
            if transform not in self.data:
                self.data[transform] = {}
            self.data[transform][material] = faces


class ThSnapVerticesToNearest:
    targetPositions = None
    step_ = False

    @classmethod
    def stepSnapVerticesToNearestF(cls):
        if cls.step_ == False:
            cls.getSelectedVertexPositionsF()
            cls.step_ = True
            print('step1: Get selected vertex positions!')
        else:
            cls.snapVerticesToNearestF()
            cls.step_ = False
            print('step2: Snap vertices to nearest!')

    @classmethod
    def getSelectedVertexPositionsF(cls):
        # 將當前選擇的物件轉換為頂點選擇
        cmds.select(cmds.polyListComponentConversion(tv=True))  # 將當前選擇轉換為頂點
        # 獲取當前選擇的頂點物件
        sel = om2.MGlobal.getActiveSelectionList()
        iterSel = om2.MItSelectionList(sel, om2.MFn.kMeshVertComponent)  # 遍歷頂點選擇
        vertexPositions = []
        while not iterSel.isDone():
            # 取得 DAG 路徑與頂點的 component
            dagPath, component = iterSel.getComponent()
            # 取得 MFnMesh 物件
            vertexIter = om2.MItMeshVertex(dagPath, component)
            while not vertexIter.isDone():
                # 獲取頂點座標
                vertexPosition = vertexIter.position(om2.MSpace.kWorld)  # 世界座標系統下的頂點座標
                vertexCoord = [vertexPosition.x, vertexPosition.y, vertexPosition.z]
                # 保存頂點座標
                vertexPositions.append(vertexCoord)
                vertexIter.next()
            iterSel.next()
        cls.targetPositions = vertexPositions
        return vertexPositions

    @classmethod
    def snapVerticesToNearestF(cls):
        if cls.targetPositions is None:
            return
        # 將當前選擇的物件轉換為頂點選擇
        cmds.select(cmds.polyListComponentConversion(tv=True))  # 將當前選擇轉換為頂點
        # 獲取當前選擇的頂點物件
        sel = om2.MGlobal.getActiveSelectionList()
        iterSel = om2.MItSelectionList(sel, om2.MFn.kMeshVertComponent)  # 遍歷頂點選擇
        while not iterSel.isDone():
            # 取得 DAG 路徑與頂點的 component
            dagPath, component = iterSel.getComponent()
            # 取得 MFnMesh 物件
            meshFn = om2.MFnMesh(dagPath)
            # 迭代每個選中的頂點
            vertexIter = om2.MItMeshVertex(dagPath, component)
            while not vertexIter.isDone():
                # 獲取當前頂點的世界座標
                vertexPosition = vertexIter.position(om2.MSpace.kWorld)
                vertexCoord = [vertexPosition.x, vertexPosition.y, vertexPosition.z]
                # 計算與每個目標座標的距離，並找到最近的目標座標
                closestPosition = None
                minDistance = float('inf')
                for target_pos in cls.targetPositions:
                    dist = math.sqrt(
                        (vertexCoord[0] - target_pos[0]) ** 2 +
                        (vertexCoord[1] - target_pos[1]) ** 2 +
                        (vertexCoord[2] - target_pos[2]) ** 2)
                    if dist < minDistance:
                        minDistance = dist
                        closestPosition = target_pos
                # 如果找到了最近的座標，將頂點移動到該位置
                if closestPosition:
                    meshFn.setPoint(vertexIter.index(), om2.MPoint(closestPosition), om2.MSpace.kWorld)
                vertexIter.next()
            iterSel.next()


class ThCopyPointNormal:
    vertexInfo = None
    _step = False

    @classmethod
    def copySelectedVertexInfoF(cls):
        if cls._step == False:
            cls.getSelectedVertexInfoF()
            cls._step = True
            print('step1: Get selected vertex info!')
        else:
            cls.setSelectedVertexNormalsF()
            cls._step = False
            print('step2: Set selected vertex normals!')

    @classmethod
    def getSelectedVertexInfoF(cls):
        # 先將當前選擇的物件轉換為頂點選擇
        cmds.select(cmds.polyListComponentConversion(tv=True))  # 將當前選擇轉換為頂點
        # 獲取當前頂點選擇的物件
        sel = om2.MGlobal.getActiveSelectionList()
        iterSel = om2.MItSelectionList(sel, om2.MFn.kMeshVertComponent)  # 遍歷頂點選擇
        vertexInfo = []
        while not iterSel.isDone():
            # 取得 DAG 路徑與頂點的 component
            dagPath, component = iterSel.getComponent()
            # 取得 MFnMesh 物件
            meshFn = om2.MFnMesh(dagPath)
            # 迭代每個頂點
            vertexIter = om2.MItMeshVertex(dagPath, component)
            while not vertexIter.isDone():
                # 獲取頂點座標
                vertexPosition = vertexIter.position(om2.MSpace.kWorld)  # 世界座標系統下的頂點座標
                vertexCoord = [vertexPosition.x, vertexPosition.y, vertexPosition.z]
                # 獲取頂點法線
                vertexNormal = vertexIter.getNormal(om2.MSpace.kWorld)  # 世界座標系統下的法線
                normalCoord = [vertexNormal.x, vertexNormal.y, vertexNormal.z]
                # 添加頂點的座標與法線到結果列表中
                vertexInfo.append([vertexCoord, normalCoord])
                vertexIter.next()
            iterSel.next()
        cls.vertexInfo = vertexInfo
        return vertexInfo

    @classmethod
    def setSelectedVertexNormalsF(cls, round_=3):
        # 先將當前選擇的物件轉換為頂點選擇
        cmds.select(cmds.polyListComponentConversion(tv=True))  # 將當前選擇轉換為頂點
        # 獲取當前選擇的頂點物件
        sel = om2.MGlobal.getActiveSelectionList()
        iterSel = om2.MItSelectionList(sel, om2.MFn.kMeshVertComponent)  # 遍歷頂點選擇
        while not iterSel.isDone():
            # 取得 DAG 路徑與頂點的 component
            dagPath, component = iterSel.getComponent()
            # 取得 MFnMesh 物件
            meshFn = om2.MFnMesh(dagPath)
            # 保存需要更新的頂點索引與法線數據
            vertexIndices = []
            vertexNormals = []
            # 遍歷選中的頂點
            vertexIter = om2.MItMeshVertex(dagPath, component)
            while not vertexIter.isDone():
                # 獲取當前頂點的世界座標
                vertexPosition = vertexIter.position(om2.MSpace.kWorld)
                vertexCoord = [vertexPosition.x, vertexPosition.y, vertexPosition.z]
                # 在資料中尋找匹配的座標
                for coord, normal in cls.vertexInfo:
                    if (round(vertexCoord[0], round_) == round(coord[0], round_) and
                            round(vertexCoord[1], round_) == round(coord[1], round_) and
                            round(vertexCoord[2], round_) == round(coord[2], round_)):
                        # 如果找到匹配的座標，則準備更新該頂點的法線
                        normalVector = om2.MVector(normal)
                        vertexIndices.append(vertexIter.index())
                        vertexNormals.append(normalVector)
                        break  # 找到匹配後，停止對該頂點的進一步比較
                vertexIter.next()
            # 使用 MFnMesh 設置頂點法線
            if vertexIndices:
                meshFn.setVertexNormals(vertexNormals, vertexIndices, om2.MSpace.kWorld)
            iterSel.next()

    def copyMeshVertexInfoF(self):
        selectList = cmds.ls(selection=True, dag=True, type='mesh')  # 獲取當前選中的 mesh
        if not selectList:
            return
        self.getMeshVertexInfoF([selectList[-1]])
        self.setMeshVertexNormalsF(selectList[:-1])

    def getMeshVertexInfoF(self, meshList=None):
        meshList = meshList if meshList else cmds.ls(selection=True, dag=True, type='mesh')  # 獲取當前選中的 mesh
        if not meshList:
            raise ValueError("No mesh selected!")
        vertexInfo = []
        for _mesh in meshList:
            # 獲取選中的物件的 MObject
            selectionList = om2.MSelectionList()
            selectionList.add(_mesh)
            dagPath = selectionList.getDagPath(0)
            # 取得 MFnMesh 物件
            meshFn = om2.MFnMesh(dagPath)
            # 獲取頂點位置與法線
            for i in range(meshFn.numVertices):
                # 取得頂點座標
                vertexPosition = meshFn.getPoint(i, om2.MSpace.kWorld)  # 世界座標系統下的頂點座標
                vertexCoord = [vertexPosition.x, vertexPosition.y, vertexPosition.z]
                # 取得頂點法線
                vertexNormal = meshFn.getVertexNormal(i, om2.MSpace.kWorld)  # 世界座標系統下的法線
                normalCoord = [vertexNormal.x, vertexNormal.y, vertexNormal.z]
                # 將座標和法線資訊加入列表
                vertexInfo.append([vertexCoord, normalCoord])
        self.vertexInfo = vertexInfo
        return vertexInfo

    def setMeshVertexNormalsF(self, meshList=None, vertexData=None, round_=3):
        meshList = meshList if meshList else cmds.ls(selection=True, dag=True, type='mesh')  # 獲取當前選中的 mesh
        vertexData = vertexData if vertexData else self.vertexInfo
        # 確認模型存在
        for _mesh in meshList:
            if not cmds.objExists(_mesh):
                raise ValueError(f"Mesh {_mesh} does not exist.")
            # 獲取選中的 mesh 的 MObject
            selectionList = om2.MSelectionList()
            selectionList.add(_mesh)
            dagPath = selectionList.getDagPath(0)
            # 取得 MFnMesh 物件
            meshFn = om2.MFnMesh(dagPath)
            # 獲取 mesh 的所有頂點座標
            allVertexPositions = meshFn.getPoints(om2.MSpace.kWorld)
            # 需要設置的頂點索引與對應的法線列表
            vertexIndices = []
            vertexNormals = []
            # 比對每個頂點的座標
            for i, vertexPosition in enumerate(allVertexPositions):
                for coord, normal in vertexData:
                    # 如果座標匹配
                    if (round(vertexPosition.x, round_) == round(coord[0], round_) and
                            round(vertexPosition.y, round_) == round(coord[1], round_) and
                            round(vertexPosition.z, round_) == round(coord[2], round_)):
                        # 記錄頂點索引與對應的法線
                        vertexIndices.append(i)
                        vertexNormals.append(om2.MVector(normal))
            # 如果找到匹配的頂點，設置法線
            if vertexIndices:
                # 設置頂點法線
                meshFn.setVertexNormals(vertexNormals, vertexIndices, om2.MSpace.kWorld)


class ThOffsetConnect:
    def __init__(self, inpList, outList, attrList=['tx', 'ty', 'tz'], mode='inp'):
        ex = ''
        if mode == 'inp':
            for inp_, out_ in zip(inpList, outList):
                for attr in attrList:
                    value = cmds.getAttr('{}.{}'.format(out_, attr))
                    ex += '{0}.{1} = {2}.{1} + {3};\n'.format(out_, attr, inp_, value)
        else:
            for inp_, out_ in zip(inpList, outList):
                for attr in attrList:
                    value = cmds.getAttr('{}.{}'.format(inp_, attr))
                    ex += '{0}.{1} = {2}.{1} - {3};\n'.format(out_, attr, inp_, value)
        self.exNode = cmds.expression(n='ThOffsetConnect_EX#', s=ex)


class ThReSkinAndBs:
    """重建模型的 BS 與 skin 權重"""

    def __init__(self, meshList, isCopy=False, deleteHisTypeList=['polySmoothFace', 'deleteComponent']):
        self.meshList = meshList
        self.isCopy = isCopy
        self.deleteHisTypeList = deleteHisTypeList
        #
        self.newMeshList = []
        #
        for mesh in self.meshList:
            skinNodeList = thFindSkinNodeF([mesh])
            if not skinNodeList:
                continue
            #
            newMesh = self.reSkinF(mesh)  # 產生新模型與權重
            #
            bsNodeList = thFindBlendShapeNodeF([mesh])
            if bsNodeList:
                self.reBsF(mesh, newMesh, bsNodeList[0])  # 傳遞 BS
            # 傳遞連接
            ThDisconnectConnect().transferF(mesh, [newMesh])
            # 整理
            newSkinNodeList = thFindSkinNodeF([newMesh])
            newBsNodeList = thFindBlendShapeNodeF([newMesh])
            if isCopy:
                # 重命名 skin
                cmds.rename(newSkinNodeList[0], skinNodeList[0] + '#')
                # 重命名 bs
                if newBsNodeList:
                    cmds.rename(newBsNodeList[0], bsNodeList[0] + '#')
                #
                self.deleteComponentF(mesh)
                #
                self.newMeshList.append(newMesh)
            else:
                # 刪除舊模型
                cmds.delete(mesh)
                # 重命名 skin
                cmds.rename(newSkinNodeList[0], skinNodeList[0])
                # 重命名 bs
                if newBsNodeList:
                    cmds.rename(newBsNodeList[0], bsNodeList[0])
                # 重命名新模型
                cmds.rename(newMesh, mesh)
                self.newMeshList.append(mesh)
            # 選擇到新模型
        cmds.select(self.newMeshList, r=True)

    def deleteComponentF(self, mesh):
        if not self.deleteHisTypeList:
            return
        #
        hisList = cmds.listHistory(mesh)
        if not hisList:
            return
        #
        nodeList = []
        for n in hisList:
            for t in self.deleteHisTypeList:
                if cmds.nodeType(n) == t:
                    nodeList.append(n)
        #
        cmds.delete(nodeList)
        return nodeList

    def reBsF(self, mesh, newMesh, bsNode):
        ebsw = ThEditBlendShapeWrap(
            oldObj=mesh,
            newObjList=[newMesh],
            oldObjBs=bsNode,
            mode='blendShape',
            isCorrectionBaseShape=False)
        ebsw.createControlF()
        ebsw.bakeBsF()

    def reSkinF(self, mesh):
        meshParent = cmds.listRelatives(mesh, parent=True)
        jointList = thFindSkinJointF([mesh])
        #
        dts = ThDefToSkin('ThUiToolBoxCommonSkinTools__reSkinF')
        dts.applyF([mesh], jointList, 50, True, False, False, False, 'y')
        # 解除屬性鎖定
        attrList = ['tx', 'ty', 'tz', 'rx', 'ry', 'rz', 'sx', 'sy', 'sz']
        for a in attrList:
            cmds.setAttr(f'{dts.newMeshList[0]}.{a}', lock=False)
        # parent
        if meshParent:
            cmds.parent(dts.newMeshList, meshParent[0])
        else:
            cmds.parent(dts.newMeshList, w=True)
        # 鎖定屬性
        for a in attrList:
            cmds.setAttr(f'{dts.newMeshList[0]}.{a}', lock=True)
        #
        cmds.delete(dts.systemName)
        newMesh = cmds.rename(dts.newMeshList[0], f'{mesh}#')
        cmds.hide(mesh)
        #
        return newMesh


