class ThLiveLinkFace:
    _bsDict = {
        'browDownLeft': 41,
        'browDownRight': 42,
        'browInnerUp': 43,
        'browOuterUpLeft': 44,
        'browOuterUpRight': 45,
        'cheekPuff': 46,
        'cheekSquintLeft': 47,
        'cheekSquintRight': 48,
        'eyeBlinkLeft': 0,
        'eyeBlinkRight': 7,
        'eyeLookDownLeft': 1,
        'eyeLookDownRight': 8,
        'eyeLookInLeft': 2,
        'eyeLookInRight': 9,
        'eyeLookOutLeft': 3,
        'eyeLookOutRight': 10,
        'eyeLookUpLeft': 4,
        'eyeLookUpRight': 11,
        'eyeSquintLeft': 5,
        'eyeSquintRight': 12,
        'eyeWideLeft': 6,
        'eyeWideRight': 13,
        'headPitch': 53,
        'headRoll': 54,
        'headYaw': 52,
        'jawForward': 14,
        'jawLeft': 15,
        'jawOpen': 17,
        'jawRight': 16,
        'leftEyePitch': 56,
        'leftEyeRoll': 57,
        'leftEyeYaw': 55,
        'mouthClose': 18,
        'mouthDimpleLeft': 27,
        'mouthDimpleRight': 28,
        'mouthFrownLeft': 25,
        'mouthFrownRight': 26,
        'mouthFunnel': 19,
        'mouthLeft': 21,
        'mouthLowerDownLeft': 37,
        'mouthLowerDownRight': 38,
        'mouthPressLeft': 35,
        'mouthPressRight': 36,
        'mouthPucker': 20,
        'mouthRight': 22,
        'mouthRollLower': 31,
        'mouthRollUpper': 32,
        'mouthShrugLower': 33,
        'mouthShrugUpper': 34,
        'mouthSmileLeft': 23,
        'mouthSmileRight': 24,
        'mouthStretchLeft': 29,
        'mouthStretchRight': 30,
        'mouthUpperUpLeft': 39,
        'mouthUpperUpRight': 40,
        'noseSneerLeft': 49,
        'noseSneerRight': 50,
        'rightEyePitch': 59,
        'rightEyeRoll': 60,
        'rightEyeYaw': 58,
        'tongueOut': 51}
    namespace = ''
    isApp = False
    port = 22222
    th = None
    serverSocket = None
    callbackId = None
    #
    ignoreExpressionValue = .05
    startExpression = None
    endExpression = None
    arkitData = [0.0] * 61
    expression = copy.copy(ThLiveLinkFaceData.expression)  # 修改動作(前/ 後)數據
    doExpression = []  # 編譯後的表達式數據
    animData = {}  # 保存動畫時間與修改後數據
    #
    ctrlHead = None
    headPitchAxis = 'x'
    headYawAxis = 'y'
    headRollAxis = 'z'
    headPitchDir = -45
    headYawDir = -45
    headRollDir = -45
    headScale = 1.2
    #
    isTongue = False
    appAttrList = []

    @classmethod
    def delExpressionF(cls, index):
        cls.expression.pop(index)

    @classmethod
    def defExpressionF(cls):
        cls.expression = copy.copy(ThLiveLinkFaceData.expression)

    @classmethod
    def doExpressionF(cls):
        """產生表達式資料"""
        cls.doExpression = []
        eye = ThEditArkit.eyeAttrList
        mouth = ThEditArkit.mouthAttrList + ['tongueOut']
        for n in cls.expression:  # 循環表達式
            # 獲取主要設定值(將改變的值提取出來)
            mainList = []
            for nn in ThEditArkit.attrTongueList:
                if n['start'][nn] != n['end'][nn]:
                    value = n['end'][nn] - n['start'][nn]
                    mainList.append([nn, value])
            # 獲取驅動值列表(將大於指定值的屬性提取出來)
            eyeList = [[x, n['start'][x]] for x in eye if n['start'][x] > cls.ignoreExpressionValue]
            mouthList = [[x, n['start'][x]] for x in mouth if n['start'][x] > cls.ignoreExpressionValue]
            for nn in mainList:
                otherList = eyeList if nn[0] in eye else mouthList  # 判斷要使用的列表
                otherList = [x for x in otherList if x[0] != nn[0]]  # 排除自己
                # 如果沒有資料就跳過
                if not otherList:
                    continue
                # 獲取權重(屬性, 當值到達, 影響的權重)
                averageList = [x[1] for x in otherList]
                averageList = thAverageDataF(averageList)
                otherList = [[x[0], x[1], averageList[i]] for i, x in enumerate(otherList)]
                # 整合資料(當 otherList 到達這些值後 nn[0] 要加上 nn[1])
                cls.doExpression.append([nn, otherList])

    @classmethod
    def addExpressionF(cls, annotation='', ignoreValue=.05):
        cls.ignoreExpressionValue = ignoreValue
        cls.doExpression = []
        if cls.startExpression != cls.endExpression:
            cls.expression.append(
                {'annotation': annotation, 'start': cls.startExpression, 'end': cls.endExpression})

    @classmethod
    def toExpressionListF(cls, mode, index):
        if not cls.expression:
            return
        for k, v in cls.expression[index][mode].items():
            cmds.setAttr(f'{cls.namespace}{k}_ARKIT_ctrl.tx', v)

    @classmethod
    def toExpressionF(cls, mode):
        doData = cls.startExpression if mode == 'start' else cls.endExpression
        if doData:
            for k, v in doData.items():
                cmds.setAttr(f'{cls.namespace}{k}_ARKIT_ctrl.tx', v)

    @classmethod
    def getExpressionF(cls, mode, namespace=None):
        cls.namespace = namespace if namespace else cls.namespace
        #
        if not cmds.objExists(f'{cls.namespace}ARKIT_ctrl_grp'):
            cmds.warning(
                ThLanguage.tr('場景中找不到控制器，請確認 "命名空間" 輸入是否正確!'))
            return
        #
        if not cmds.play(q=True, st=True):
            cmds.play(st=False)
        #
        data = {x: cmds.getAttr(f'{cls.namespace}{x}_ARKIT_ctrl.tx') for x in ThEditArkit.attrTongueList}
        if mode == 'start':
            cls.startExpression = data
        else:
            cls.endExpression = data

    @classmethod
    def appExpressionF(cls, bsData):
        for funcData in cls.doExpression:
            mainName = funcData[0][0]  # 要操作的 bs
            mainValue = bsData[mainName]  # 獲取 bs 值
            # clamp(當前值 / 定義值) * 加權最大值
            weight = sum(cls.clampF(bsData[x[0]] / x[1]) * x[2] for x in funcData[1])
            mainValue = mainValue + (funcData[0][1] * weight)  # 獲取設定值
            mainValue = cls.clampF(mainValue)  # 限制最大最小值
            bsData[mainName] = mainValue
        return bsData

    @classmethod
    def modifyValueF(cls, bsData, isScaleEyeBlink=0):
        """優化 BS 值"""
        eyeBlinkRange = cmds.getAttr(f'{cls.namespace}ARKIT_ctrl.eyeBlinkRange')
        if eyeBlinkRange:
            for n in lr:
                mainName = f'eyeBlink{n}'
                mainValue = bsData[mainName]
                mainValue = cls._getRangeValueF(mainValue, isScaleEyeBlink, eyeBlinkRange)
                mainValue = cls.clampF(mainValue)
                bsData[mainName] = mainValue
        return bsData

    @classmethod
    def appF(cls, port=None, namespace=None, startFrame=1, isTongue=True):
        cls.isTongue = isTongue
        cls.port = port if port else cls.port
        cls.namespace = namespace if namespace else cls.namespace
        cls.animData = {}  # 初始化保存數據
        cls.doExpressionF()  # 產生表達式資料
        cls.appAttrList = ThEditArkit.attrTongueList if cls.isTongue else ThEditArkit.attrList  # 設置動畫要使用哪個列表
        #
        if not cmds.objExists(f'{cls.namespace}ARKIT_ctrl_grp'):
            cmds.warning(
                ThLanguage.tr('場景中找不到控制器，請確認 "命名空間" 輸入是否正確!'))
            return
        # 使用 DG 評估模式
        if cmds.evaluationManager(q=True, mode=True)[0] != 'off':
            cmds.evaluationManager(mode='off')
        # 創建控制器
        if not cmds.objExists(f'{cls.namespace}ARKIT_ctrl_grp'):
            ThEditArkitAnimation().ctrlF()
        cls.endF()  # 結束
        cls._disconnectAnimF()  # 斷開控制, 頭部控制, 表情控制器動畫
        # 連線
        try:
            serverSocket = socket.socket(socket.AF_INET, socket.SOCK_DGRAM)
            serverSocket.bind(('', cls.port))
            serverSocket.settimeout(5)  # 設置超時時間為5秒
        except OSError:
            cls.serverSocket.setsockopt(socket.SOL_SOCKET, socket.SO_REUSEADDR, 1)
        else:
            cls.serverSocket = serverSocket
        # 多線程、解碼
        cls.isApp = True
        cls.th = threading.Thread(target=cls.connectF)
        cls.th.start()
        # 創建一個時間軸改變的回調
        cls.addEventCallbackF()
        #
        cmds.currentTime(startFrame)
        if not cmds.play(q=True, st=True):
            cmds.play(st=True)

    @classmethod
    def _disconnectAnimF(cls):
        """斷開控制, 頭部控制, 表情控制器動畫"""
        # 斷開控制器動畫
        ctrlList = [f'{cls.namespace}{x}_ARKIT_ctrl' for x in ThEditArkit.attrTongueList]
        ThDisconnectConnect('ThLiveLinkFace_data').switchF(ctrlList, ['tx'])
        # 斷開頭部控制器動畫
        if cls.ctrlHead:
            ThDisconnectConnect('ThLiveLinkFaceHead_data').switchF(ctrlList, ['rx', 'ry', 'rz'])
        # 斷開表情控制器動畫
        ThArkitCustomFace(cls.namespace).disconnectAnimCtrlF('disconnect')

    @classmethod
    def connectF(cls):
        """解碼"""
        try:
            while cls.isApp:
                bytesData, _ = cls.serverSocket.recvfrom(1024)
                nameLength = struct.unpack('!i', bytesData[41:45])[0]
                nameEndPos = 45 + nameLength
                if len(bytesData) > nameEndPos + 16:
                    cls.arkitData = struct.unpack('!61f', bytesData[nameEndPos + 17:])
        except:
            cmds.warning(ThLanguage.tr('超時內未收到數據!'))
        finally:
            cls.serverSocket.close()

    @classmethod
    def setAnimF(cls):
        """設置控制器"""
        if not cls.arkitData:
            return
        animData = {}
        # 表情動畫
        bsDataDict = {x: cls.arkitData[cls._bsDict[x]] for x in cls._bsDict.keys()}  # 轉為 dict
        bsDataDict = cls.appExpressionF(bsDataDict)  # 表達式
        for n in cls.appAttrList:
            cmds.setAttr(f'{cls.namespace}{n}_ARKIT_ctrl.tx', bsDataDict[n])
        animData['face'] = bsDataDict
        # 頭部動畫
        if cls.ctrlHead:
            rotateValueList = {
                f'{cls.ctrlHead}.r{cls.headPitchAxis}':
                    cls.arkitData[cls._bsDict['headPitch']] * (cls.headPitchDir * cls.headScale),
                f'{cls.ctrlHead}.r{cls.headYawAxis}':
                    cls.arkitData[cls._bsDict['headYaw']] * (cls.headYawDir * cls.headScale),
                f'{cls.ctrlHead}.r{cls.headRollAxis}':
                    cls.arkitData[cls._bsDict['headRoll']] * (cls.headRollDir * cls.headScale)}
            for k, v in rotateValueList.items():
                cmds.setAttr(k, v)
            animData['head'] = rotateValueList
        cls.animData[cmds.currentTime(q=True)] = animData

    @classmethod
    def keyF(cls, namespace):
        """設置 KEY"""
        cls.namespace = namespace
        if not cmds.objExists(f'{cls.namespace}ARKIT_ctrl_grp'):
            cmds.warning(
                ThLanguage.tr('場景中找不到控制器，請確認 "命名空間" 輸入是否正確!'))
            return
        if not cls.animData:
            return
        # key iphone ctrl
        for k, v in cls.animData.items():
            for attr in ThEditArkit.attrTongueList:
                cmds.setKeyframe(
                    f'{cls.namespace}{attr}_ARKIT_ctrl',
                    time=k, at='tx', value=v['face'][attr])
            if 'head' in v:
                for kk, vv in v['head'].items():
                    ctrl, ctrlAttr = kk.split('.')
                    cmds.setKeyframe(ctrl, time=k, at=ctrlAttr, value=vv)

    @classmethod
    def bakeToCtrlKeyF(cls, namespace):
        """烘焙到控制器"""
        cls.namespace = namespace
        if not cmds.objExists(f'{cls.namespace}ARKIT_ctrl_grp'):
            cmds.warning(
                ThLanguage.tr('場景中找不到控制器，請確認 "命名空間" 輸入是否正確!'))
            return
        gsd = ThGrpSaveData(f'{cls.namespace}ARKIT_ctrl_grp')
        data = gsd.getF()
        if not data:
            return
        if not 'exFormat' in data:
            return
        timeMin = int(cmds.playbackOptions(q=True, min=True))
        timeMax = int(cmds.playbackOptions(q=True, max=True))
        acf = ThArkitCustomFace(cls.namespace)
        acf.disconnectAnimCtrlF('disconnect')  # 斷開表情控制器動畫
        acf.modifyConnectModeExF('on')  # 創建 EX
        # 獲取有建立 EX 的 ctrl.attr 列表
        ctrlAttrList = data['exFormat'].split('\n')
        ctrlAttrList = [x.split(' = ')[0] for x in ctrlAttrList if x]
        ctrlAttrList = [x.format(cls.namespace) for x in ctrlAttrList]
        # 獲取動畫數據
        animData = {}
        for i in range(timeMax - timeMin):
            time = timeMin + i
            cmds.currentTime(time)
            animData1 = {}
            for nn in ctrlAttrList:
                animData1[nn] = cmds.getAttr(nn)
            animData[time] = animData1
        acf.modifyConnectModeExF('off')  # 刪除 EX
        ThDisconnectConnect('ThLiveLinkFaceCtrl_data').switchF()  # 連接表情控制器動畫
        # 刪除 iphone 控制器動畫並回到預設值
        ipCtrlList = [f'{cls.namespace}{x}_ARKIT_ctrl' for x in ThEditArkit.attrTongueList]
        cmds.delete(ipCtrlList, channels=True, unitlessAnimationCurves=False, hierarchy=0, controlPoints=0, shape=0)
        for n in ipCtrlList:
            cmds.setAttr(f'{n}.tx', 0)
        # KEY
        cmds.setKeyframe(
            [f'{cls.namespace}{x}' for x in data['ctrlAttr'].keys()],
            time=timeMin, breakdown=0, preserveCurveShape=0, hierarchy='none', controlPoints=0, shape=0)
        for k, v in animData.items():  # time, {ctrlAttr: value}
            for kk, vv in v.items():
                ctrl, attr = kk.split('.')
                cmds.setKeyframe(ctrl, time=k, at=attr, value=vv)

    @classmethod
    def timeChangedCallbackF(cls, *args, **kwargs):
        """註冊回調函數"""
        cls.setAnimF()

    @classmethod
    def addEventCallbackF(cls):
        """創建一個時間軸改變的回調"""
        cls.callbackId = om2.MEventMessage.addEventCallback('timeChanged', cls.timeChangedCallbackF)

    @classmethod
    def endF(cls):
        """結束"""
        if not cmds.objExists(f'{cls.namespace}ARKIT_ctrl_grp'):
            cmds.warning(
                ThLanguage.tr('場景中找不到控制器，請確認 "命名空間" 輸入是否正確!'))
            return
        #
        if cmds.play(q=True, st=True):
            cmds.play(st=False)
        # 移除回调
        if cls.callbackId:
            om2.MMessage.removeCallback(cls.callbackId)
            cls.callbackId = None
        # 停止循環
        cls.isApp = False
        if cls.th:
            cls.th.join()
            cls.th = None
        # 恢復連線
        ThDisconnectConnect('ThLiveLinkFace_data').switchF()
        ThDisconnectConnect('ThLiveLinkFaceHead_data').switchF()
        ThArkitCustomFace(cls.namespace).disconnectAnimCtrlF('connect')  # 連接表情控制器動畫
        # 保存表達式起始姿勢
        cls.getExpressionF('start')

    @classmethod
    def _getRangeValueF(cls, value, minus, scale=1.0):
        """減慢啟動時間"""
        return (value - minus) * (1 / (1 - (minus * scale)))

    @classmethod
    def _getCurveBendF(cls, value, valueRange=1.0, scale=1.0):
        """形成曲線"""
        return ((math.sin((value / valueRange) * 3.14159) * scale) + 1) * value

    @classmethod
    def clampF(cls, value, minValue=0, maxValue=1):
        """限制值區間"""
        return max(min(value, maxValue), minValue)


class ThSetTestPoseAnim:
    def __init__(self, objList, attrDataList=None, sleep=10):
        attrDataList = attrDataList if attrDataList else [['rx', 90], ['ry', 90], ['rz', 90]]
        frame = cmds.currentTime(q=True)
        for obj in objList:
            for attrData in attrDataList:
                cmds.setKeyframe(
                    obj, time=frame, at=attrData[0], value=0, itt='linear', ott='linear')
                frame += sleep
                cmds.setKeyframe(
                    obj, time=frame, at=attrData[0], value=attrData[1], itt='linear', ott='linear')
                frame += sleep
                cmds.setKeyframe(
                    obj, time=frame, at=attrData[0], value=0, itt='linear', ott='linear')
                frame += sleep
                cmds.setKeyframe(
                    obj, time=frame, at=attrData[0], value=attrData[1] * -1, itt='linear',
                    ott='linear')
                frame += sleep
                cmds.setKeyframe(
                    obj, time=frame, at=attrData[0], value=0, itt='linear', ott='linear')


