class ThEditArkitAnimation(ThEditArkit):
    mainCtrl = None
    ctrlList = []

    def mirrorAttrF(self, direction, namespace=''):
        """鏡像屬性"""
        # 統一左右數值
        setDict = {'left': [self.r, self.l], 'right': [self.l, self.r]}
        for i in range(len(self.l)):
            data = cmds.getAttr(f'{namespace}{setDict[direction][0][i]}_ARKIT_ctrl.translateX')
            cmds.setAttr(f'{namespace}{setDict[direction][1][i]}_ARKIT_ctrl.translateX', data)

    def connectShapeF(self, useSelectList=None):
        """關聯 blend shape"""
        blendShapeList = []
        if useSelectList:
            blendShapeList = useSelectList
        else:
            blendShapeList = cmds.ls(type='blendShape')
        if not blendShapeList:
            return
        # 刪除 key
        cmds.delete(blendShapeList, sc=True, c=True, uac=False)
        # 連接 shape
        for blendShape in blendShapeList:
            for attr in self.attrTongueList:
                if not cmds.attributeQuery(attr, node=blendShape, exists=True):
                    continue
                '''
                if cmds.listConnections(f'{blendShape}.{attr}'):
                    continue
                '''
                try:
                    cmds.connectAttr(f'{attr}_ARKIT_ctrl.export_data', f'{blendShape}.{attr}', f=True)
                except:
                    pass

    def ctrlF(self, font='Noto Sans TC', isCreateDetailAttr=False):
        """創建控制器"""
        if cmds.objExists('ARKIT_ctrl_grp'):
            return
        if not cmds.objExists('face_ctrl_main_grp'):
            cmds.group(em=True, n='face_ctrl_main_grp')
        cmds.group(em=True, n='ARKIT_ctrl_grp')
        cmds.parent('ARKIT_ctrl_grp', 'face_ctrl_main_grp')
        # 創建主要控制器
        self.mainCtrl = cmds.curve(
            n='ARKIT_ctrl',
            d=1, p=[(-1, 1, 0), (18, 1, 0), (18, -30, 0), (-1, -30, 0), (-1, 1, 0)], k=[0, 1, 2, 3, 4])
        for n in ['tx', 'ty', 'tz', 'rx', 'ry', 'rz', 'sx', 'sy', 'sz', 'v']:
            cmds.setAttr(f'{self.mainCtrl}.{n}', e=True, channelBox=True)
        txtList = thCreateTxtF('ARKIT', [self.mainCtrl], 1, font=font)
        cmds.move(-0.9, 1.2, 0, r=True)
        cmds.parent(self.mainCtrl, 'ARKIT_ctrl_grp')
        # 創建屬性控制器
        add = 1
        moveY = 0
        moveX = 0
        for n in self.attrTongueList:
            if n == 'jawForward':
                moveY = 0
                moveX = 8
            rccCls = ThRigCreateCtrl(n + '_ARKIT', 'right', scale=1)
            grp = rccCls.mainGrp
            cmds.parent(grp, self.mainCtrl)
            cmds.move(moveX, moveY, 0, grp)
            txtList = thCreateTxtF(n, [grp], .7, font)
            cmds.move(1.456396, -0.150942, 0, txtList, r=True)
            #
            ctrl = rccCls.ctrlName
            self.ctrlList.append(ctrl)
            cmds.addAttr(ctrl, ln='scale_data', at='double', dv=1, k=True)
            cmds.addAttr(ctrl, ln='export_data', at='double', k=True)
            moveY -= add
            #
            cmds.setAttr(ctrl + '.scale_data', keyable=False, channelBox=True)
        # 創建 EX
        self.generallyExF()
        # 關聯 blend shape
        self.connectShapeF()
        # 創建細節控制屬性
        if isCreateDetailAttr:
            self._createDetailAttrF()
        cmds.select('ARKIT_ctrl_grp', r=True)

    def _createDetailAttrF(self):
        """創建細節控制屬性"""
        # 添加屬性
        cmds.addAttr(self.mainCtrl, ln='eyeBlinkLeft_in', at='double', dv=0, k=True)
        cmds.addAttr(self.mainCtrl, ln='eyeBlinkRight_in', at='double', dv=0, k=True)
        cmds.addAttr(self.mainCtrl, ln='browDown_eyeBlink_left', at='double', dv=0, k=True)
        cmds.addAttr(self.mainCtrl, ln='browDown_eyeBlink_right', at='double', dv=0, k=True)
        cmds.addAttr(self.mainCtrl, ln='cheekSquint_eyeBlink_left', at='double', dv=0, k=True)
        cmds.addAttr(self.mainCtrl, ln='cheekSquint_eyeBlink_right', at='double', dv=0, k=True)
        cmds.addAttr(self.mainCtrl, ln='eyeSquint_eyeBlink_left', at='double', dv=0, k=True)
        cmds.addAttr(self.mainCtrl, ln='eyeSquint_eyeBlink_right', at='double', dv=0, k=True)
        cmds.addAttr(self.mainCtrl, ln='mTeethJawOpenValue', at='double', dv=0, k=True)
        cmds.addAttr(self.mainCtrl, ln='mTeethJawOpen', at='double', dv=0, k=True)
        cmds.addAttr(self.mainCtrl, ln='mTeethBackValue', at='double', dv=0, k=True)
        cmds.addAttr(self.mainCtrl, ln='mTeethBack', at='double', dv=0, k=True)
        cmds.addAttr(self.mainCtrl, ln='mTeethUpDn', at='double', dv=0, k=True)
        # 創建公式
        ex = ''
        ex += f'{self.mainCtrl}.eyeBlinkLeft_in = sin(eyeBlinkLeft_ARKIT_ctrl.export_data * 3.14);\n'
        ex += f'{self.mainCtrl}.eyeBlinkRight_in = sin(eyeBlinkRight_ARKIT_ctrl.export_data * 3.14);\n'
        ex += f'{self.mainCtrl}.browDown_eyeBlink_left = browDownLeft_ARKIT_ctrl.export_data * eyeBlinkLeft_ARKIT_ctrl.export_data;\n'
        ex += f'{self.mainCtrl}.browDown_eyeBlink_right = browDownRight_ARKIT_ctrl.export_data * eyeBlinkRight_ARKIT_ctrl.export_data;\n'
        ex += f'{self.mainCtrl}.cheekSquint_eyeBlink_left = cheekSquintLeft_ARKIT_ctrl.export_data * eyeBlinkLeft_ARKIT_ctrl.export_data;\n'
        ex += f'{self.mainCtrl}.cheekSquint_eyeBlink_right = cheekSquintRight_ARKIT_ctrl.export_data * eyeBlinkRight_ARKIT_ctrl.export_data;\n'
        ex += f'{self.mainCtrl}.eyeSquint_eyeBlink_left = eyeSquintLeft_ARKIT_ctrl.export_data * eyeBlinkLeft_ARKIT_ctrl.export_data;\n'
        ex += f'{self.mainCtrl}.eyeSquint_eyeBlink_right = eyeSquintRight_ARKIT_ctrl.export_data * eyeBlinkRight_ARKIT_ctrl.export_data;\n'
        ex += f'{self.mainCtrl}.mTeethJawOpen = jawOpen_ARKIT_ctrl.export_data * {self.mainCtrl}.mTeethJawOpenValue;\n'
        ex += f'{self.mainCtrl}.mTeethBack = ((mouthSmileLeft_ARKIT_ctrl.export_data + mouthSmileRight_ARKIT_ctrl.export_data) / 2) * {self.mainCtrl}.mTeethBackValue;\n'
        self.exNode = cmds.expression(n=f'{self.mainCtrl}_detailAttr_EX#', s=ex)

    def _doLockF(self, objList, mode):
        """lock"""
        for obj in objList:
            cmds.setAttr('{}_ARKIT_ctrl.export_data'.format(obj), lock=mode)

    def generallyExF(self):
        """創建 EX"""
        self._doLockF(self.attrTongueList, False)  # unlock
        if cmds.objExists('ARKIT_ATTR_CTRL_EX'):
            cmds.delete('ARKIT_ATTR_CTRL_EX')
        ctrlList = [attr + '_ARKIT_ctrl' for attr in self.attrTongueList]
        ex = ''
        for i, attr in enumerate(self.attrTongueList):
            ex += '{0}.export_data = {0}.translateX * {0}.scale_data;\n'.format(ctrlList[i])
        cmds.expression(n='ARKIT_ATTR_CTRL_EX', s=ex)
        self._doLockF(self.attrTongueList, True)  # lock

    def ctrlConnectF(self, refAttrObj='Base', ctrlNamespase=''):
        for attr in self.attrList:
            cmds.connectAttr(f'{refAttrObj}.{attr}', f'{ctrlNamespase}{attr}_ARKIT_ctrl.tx', f=True)

    def styleCtrlConnectF(self, refAttrObj='Base', ctrlNamespase=''):
        ex = '''\
{ctrl}L_eye_ctrl.translateX = {base}.eyeLookOutLeft - {base}.eyeLookInLeft;
{ctrl}L_eye_ctrl.translateY = {base}.eyeLookUpLeft - {base}.eyeLookDownLeft;
{ctrl}R_eye_ctrl.translateX = {base}.eyeLookInRight - {base}.eyeLookOutRight;
{ctrl}R_eye_ctrl.translateY = {base}.eyeLookUpRight - {base}.eyeLookDownRight;
{ctrl}mouth_ctrl.translateY = (({base}.mouthShrugLower + {base}.mouthShrugUpper) / 2) - {base}.jawOpen;
{ctrl}mouth_ctrl.translateX = {base}.mouthLeft - {base}.mouthRight;
{ctrl}cheekPuff_ctrl.translateY = {base}.cheekPuff;
{ctrl}mouthRollUpper_ctrl.translateX = {base}.mouthRollUpper - {base}.mouthPucker;
{ctrl}mouthRollUpper_ctrl.translateY = {base}.mouthFunnel - {base}.mouthRollLower;
{ctrl}mouthClose_ctrl.translateX = clamp(0,{base}.jawOpen,{base}.mouthClose);
{ctrl}L_mouth_ctrl.translateX = {base}.mouthDimpleLeft;
{ctrl}L_mouth_ctrl.translateY = {base}.mouthSmileLeft - {base}.mouthFrownLeft;
{ctrl}R_mouth_ctrl.translateX = - {base}.mouthDimpleRight;
{ctrl}R_mouth_ctrl.translateY = {base}.mouthSmileRight - {base}.mouthFrownRight;
{ctrl}L_mouth_mouthPress_ctrl.translateY = {base}.mouthPressLeft - {base}.mouthStretchLeft;
{ctrl}R_mouth_mouthPress_ctrl.translateY = {base}.mouthPressRight - {base}.mouthStretchRight;
{ctrl}mouthLowerDown_ctrl.translateY = - max({base}.mouthLowerDownLeft, {base}.mouthLowerDownRight);
{ctrl}mouthLowerDown_ctrl.translateX = {base}.mouthLowerDownLeft - {base}.mouthLowerDownRight;
{ctrl}mouthUpperUp_ctrl.translateY = max({base}.mouthUpperUpLeft, {base}.mouthUpperUpRight);
{ctrl}mouthUpperUp_ctrl.translateX = {base}.mouthUpperUpLeft - {base}.mouthUpperUpRight;
{ctrl}noseSneer_ctrl.translateY = max({base}.noseSneerLeft, {base}.noseSneerRight);
{ctrl}noseSneer_ctrl.translateX = {base}.noseSneerLeft - {base}.noseSneerRight;
{ctrl}mouth1_ctrl.translateY = {base}.jawForward;
{ctrl}mouth1_ctrl.translateX = {base}.jawLeft - {base}.jawRight;
{ctrl}L_eyeBlink_ctrl.translateX = {base}.eyeWideLeft - {base}.cheekSquintLeft;
{ctrl}L_eyeBlink_ctrl.translateY = {base}.eyeSquintLeft - {base}.eyeBlinkLeft;
{ctrl}R_eyeBlink_ctrl.translateX = {base}.eyeWideRight - {base}.cheekSquintRight;
{ctrl}R_eyeBlink_ctrl.translateY = {base}.eyeSquintRight - {base}.eyeBlinkRight;
{ctrl}browInnerUp_ctrl.translateY = {base}.browInnerUp;
{ctrl}browDown_ctrl.translateY = - max({base}.browDownLeft, {base}.browDownRight);
{ctrl}browDown_ctrl.translateX = {base}.browDownLeft - {base}.browDownRight;
{ctrl}browOuterUp_ctrl.translateY = max({base}.browOuterUpLeft, {base}.browOuterUpRight);
{ctrl}browOuterUp_ctrl.translateX = {base}.browOuterUpLeft - {base}.browOuterUpRight;
'''
        ex = ex.format(ctrl=ctrlNamespase, base=refAttrObj)
        if cmds.objExists('ARKIT_ANIM_CONNECT_CTRL_EX'):
            cmds.delete('ARKIT_ANIM_CONNECT_CTRL_EX')
        cmds.expression(n='ARKIT_ANIM_CONNECT_CTRL_EX', s=ex)


class ThArkitCustomFace(ThEditArkit):
    iphoneSys = 'ARKIT_ctrl_grp'

    def __init__(self, namespace=''):
        """
        data = {
            'ctrlAttr': {控制器: [屬性,]},
            'mesh': [模型,],
            'exFormat': EX f'{命名空間}公式',
            'exNode: EX 節點,
            'face': 動畫,
        """
        self.namespace = namespace
        #
        ThEditArkitAnimation().ctrlF()  # 創建控制器
        self.gsd = ThGrpSaveData(f'{self.namespace}{self.iphoneSys}', defData={})
        self.data = self.gsd.getF()

    def saveMeshF(self, meshList):
        """保存模型數據"""
        # 創建 or 讀取資料
        self.data['mesh'] = meshList
        self.gsd.setF(self.data)

    def saveCtrlF(self, ctrlList=None):
        """保存控制器數據"""
        if not cmds.objExists(f'{self.namespace}{self.iphoneSys}'):
            cmds.warning(
                ThLanguage.tr(
                    '1.場景中找不到控制器; 2.該功能無法在 reference 下使用'))
            return
        # 調整時間軸
        cmds.currentUnit(time='ntsc')
        cmds.currentTime(0)
        cmds.playbackOptions(min=0)
        cmds.playbackOptions(max=52)
        self.modifyConnectModeBsF('off')  # 斷開 BS
        # 如果已存在 data 判斷是否表情 ctrl 回到 frame
        if 'exFormat' in self.data:
            # key to ctrl
            for i, n in enumerate(['base'] + self.attrTongueList):  # 時間
                for kk, vv in self.data['ctrlAttr'].items():  # 控制器
                    for iii, nnn in enumerate(vv):  # 屬性
                        try:
                            cmds.setKeyframe(f'{kk}.{nnn}', time=i, value=self.data['face'][n][kk][iii], breakdown=0)
                        except:
                            pass
            # 刪除 EX 公式
            self.data.pop('exFormat')
            self.gsd.setF(self.data)
        # 如果有輸入新控制器
        if ctrlList:
            # 連接 iphone shapes
            bsList = cmds.ls(type='blendShape')
            if 'mesh' in self.data:
                if self.data['mesh']:
                    bsList = list(set(bsList) - set(thFindBlendShapeNodeF(self.data['mesh'])))
            if bsList:
                ThEditArkitAnimation().connectShapeF(bsList)
            #
            cmds.bakeResults(
                ctrlList,
                sm=True, t=(0, 52), sb=1, osr=1, dic=True, pok=True, sac=False,
                ral=False, rba=False, bol=False, mr=True, cp=False, s=True)
            # 獲取 attr list
            attrDict = {}
            for n in ctrlList:
                attrList = cmds.listAttr(n, m=True, k=True, r=True, se=True, v=True, w=True, c=True, u=True)
                if attrList:
                    attrDict[n] = attrList
            # save
            self.data['ctrlAttr'] = attrDict
            self.gsd.setF(self.data)
        # KEY ip ctrl
        for n in ThEditArkit.attrTongueList:  # 第 0 格設置 key
            cmds.setKeyframe(f'{n}_ARKIT_ctrl', time=0, at='tx', value=0)
        thBatchSetKeyF([f'{x}_ARKIT_ctrl' for x in ThEditArkit.attrTongueList], 'tx', 1, 1, 0)  # 逐步啟動
        cmds.select(f'{self.namespace}{self.iphoneSys}', r=True)

    def frameToCtrlF(self):
        """表情 frame 到 ctrl"""
        if not cmds.objExists(f'{self.namespace}{self.iphoneSys}'):
            cmds.warning(
                ThLanguage.tr(
                    '1.場景中找不到控制器; 2.該功能無法在 reference 下使用'))
            return
        self.modifyConnectModeBsF('off')  # 斷開 BS
        # 使用 DG 評估模式
        if cmds.evaluationManager(q=True, mode=True)[0] != 'off':
            cmds.evaluationManager(mode='off')
        # 如果已經創建連接就不執行
        if 'exFormat' in self.data:
            return
        # 定義 base 並初始化數據
        cmds.currentTime(0)
        baseData = {k: [cmds.getAttr(f'{k}.{x}') for x in v] for k, v in self.data['ctrlAttr'].items()}
        self.data['face'] = {'base': baseData}
        # 獲取動畫表情數據
        for i, nn in enumerate(self.attrTongueList):
            cmds.currentTime(i + 1)
            data = {}
            for k, v in self.data['ctrlAttr'].items():
                data[k] = [cmds.getAttr(f'{k}.{x}') for x in v]
            self.data['face'][nn] = data
        # 刪除控制器 key
        cmds.currentTime(0)
        cmds.delete(
            list(self.data['ctrlAttr'].keys()), channels=True, unitlessAnimationCurves=False,
            hierarchy=0, controlPoints=0, shape=0)
        # 創建 BS
        if 'mesh' in self.data:
            if self.data['mesh']:
                ThEditBlendShape.offEditF()  # 關閉編輯狀態
                # 使用進度條
                progressBar = ThUiProgressBar(2)
                progressBar.show()
                progressBar.setStratF(0, 'Face', len(ThEditArkit.attrTongueList))
                for n in ThEditArkit.attrTongueList:  # 循環表情
                    progressBar.setFrameF(0)
                    # 設定 pose
                    for kk, vv in self.data['face'][n].items():  # 控制器, 屬性值列表
                        for iii, vvv in enumerate(vv):  # id, 屬性值
                            cmds.setAttr(f"{kk}.{self.data['ctrlAttr'][kk][iii]}", vvv)
                    # 複製模型
                    copyMeshList = [cmds.duplicate(x, rr=True)[0] for x in self.data['mesh']]
                    # 設定 pose 回預設
                    for kk, vv in self.data['face']['base'].items():  # 控制器, 屬性值列表
                        for iii, vvv in enumerate(vv):  # id, 屬性值
                            cmds.setAttr(f"{kk}.{self.data['ctrlAttr'][kk][iii]}", vvv)
                    progressBar.setStratF(1, 'Mesh', len(self.data['mesh']))
                    # 創建或修改 BS
                    for ii, nn in enumerate(self.data['mesh']):
                        progressBar.setFrameF(1)
                        bsNodeList = thFindBlendShapeNodeF(nn)  # 找 BS 節點
                        if bsNodeList:
                            bsNode = bsNodeList[0]
                        else:
                            bsNode = cmds.blendShape(nn, n=f'{nn}BsNode#', automatic=True)[0]  # 創建 BS 節點
                        #
                        if cmds.attributeQuery(n, node=bsNode, exists=True):  # 如果屬性已存在
                            cmds.setAttr(f'{bsNode}.{n}', 1)  # 開啟設定值
                            bsAttrId = ThEditBlendShape.findIdAttrF(bsNode, n)  # 找屬性對應 ID
                            cmds.sculptTarget(bsNode, e=True, target=int(bsAttrId[7:-1]))  # 開啟編輯狀態
                            ThSetMeshPoint().applyF(copyMeshList[ii], nn)  # 頂點數值傳遞
                            cmds.setAttr(f'{bsNode}.{n}', 0)  # 關閉設定值
                        else:
                            ThEditBlendShape.addShapeF([bsNode], 1, 0, n)  # 創建一個新的並開啟編輯狀態
                            ThSetMeshPoint().applyF(copyMeshList[ii], nn)  # 頂點數值傳遞
                            cmds.setAttr(f'{bsNode}.{n}', 0)  # 關閉設定值
                    cmds.delete(copyMeshList)
                ThEditBlendShape.offEditF()  # 關閉編輯狀態
                progressBar.close()
        # 獲取 EX 公式
        exFormat = ''
        for k, v in self.data['ctrlAttr'].items():  # 控制器, [屬性列表]
            ex = ''
            for ii, nn in enumerate(v):
                valueList = [self.data['face'][nnn][k][ii] - self.data['face']['base'][k][ii] for
                    nnn in self.attrTongueList]
                exList = [f'({valueList[i]} * {{0}}{x}_ARKIT_ctrl.export_data)' for i, x in
                    enumerate(self.attrTongueList) if valueList[i] != 0]
                if exList:
                    ex1 = ' + '.join(exList)
                    ex1 = f"{{0}}{k}.{nn} = ({ex1}) + {self.data['face']['base'][k][ii]};\n"
                    ex += ex1
            if ex:
                exFormat += ex
        self.data['exFormat'] = exFormat  # 保存 EX 公式
        self.modifyConnectModeBsF('on')  # 連接 BS
        self.gsd.setF(self.data)  # 存檔

    def deleteCtrlKeyF(self):
        """刪除 key"""
        if not cmds.objExists(f'{self.namespace}{self.iphoneSys}'):
            cmds.warning(
                ThLanguage.tr(
                    '1.場景中找不到控制器; 2.該功能無法在 reference 下使用'))
            return
        if not self.data:
            return
        # 如果沒有 EX 就創建
        if not 'exFormat' in self.data:
            self.frameToCtrlF()
        # 刪除控制器 key
        cmds.currentTime(0)
        faceCtrlList = list(self.data['ctrlAttr'].keys())
        iphoneCtrlList = [f'{x}_ARKIT_ctrl' for x in ThEditArkit.attrTongueList]
        cmds.delete(
            faceCtrlList + iphoneCtrlList,
            channels=True, unitlessAnimationCurves=False, hierarchy=0, controlPoints=0, shape=0)
        # iphone ctrl 回到預設值
        for n in iphoneCtrlList:
            cmds.setAttr(f'{n}.tx', 0)
        # 連接 BS
        self.modifyConnectModeBsF('on')

    def modifyConnectModeExDefF(self):
        """表情控制器回到預設值"""
        for k, v in self.data['ctrlAttr'].items():
            for ii, nn in enumerate(v):
                cmds.setAttr(f'{self.namespace}{k}.{nn}', self.data['face']['base'][k][ii])

    def disconnectAnimCtrlF(self, mode='disconnect'):
        """斷開表情控制器動畫"""
        if not self.data:
            return
        # 斷開動畫連接
        if mode == 'disconnect':
            if not 'ctrlAttr' in self.data:
                return
            ThDisconnectConnect('ThArkitCustomFace_disconnectAnimCtrlF_data').switchF(
                doList=[f'{self.namespace}{x}' for x in self.data['ctrlAttr'].keys()],
                typeList=[
                    'animBlendNodeAdditiveRotation',
                    'animBlendNodeAdditiveDL',
                    'animBlendNodeAdditiveScale',
                    'animBlendNodeBoolean',
                    'animCurveTL', 'animCurveTA', 'animCurveTU'])
            self.modifyConnectModeExDefF()  # 表情控制器回到預設值
        elif mode == 'connect':
            ThDisconnectConnect('ThArkitCustomFace_disconnectAnimCtrlF_data').switchF()

    def modifyConnectModeExF(self, mode):
        """創建或刪除 EX"""
        # 修改 EX
        if not 'exFormat' in self.data:
            return
        if mode == 'on':
            # 創建
            if 'exNode' in self.data:
                return
            self.modifyConnectModeExDefF()  # 表情控制器回到預設值
            exNode = cmds.expression(
                n=f'ThArkitCustomFace_modifyConnectModeF_EX#', s=self.data['exFormat'].format(self.namespace))
            self.data['exNode'] = exNode  # 保存數據
            self.modifyConnectModeBsF('off')  # 斷開 BS
        elif mode == 'off':
            # 刪除 EX
            if not 'exNode' in self.data:
                return
            cmds.delete(self.data['exNode'])
            self.data.pop('exNode')  # 刪除數據
            self.modifyConnectModeBsF('on')  # 連接 BS
            self.modifyConnectModeExDefF()  # 表情控制器回到預設值
        self.gsd.setF(self.data)

    def modifyConnectModeBsF(self, mode):
        """斷開或連接 BS"""
        if not 'mesh' in self.data:
            return
        for n in [f'{self.namespace}{x}' for x in self.data['mesh']]:
            bsNodeList = thFindBlendShapeNodeF(n)  # 找 BS 節點
            if not bsNodeList:
                continue
            for nn in ThEditArkit.attrTongueList:
                if not cmds.attributeQuery(nn, node=bsNodeList[0], exists=True):  # 如果屬性不存在就跳過
                    continue
                connectNode = cmds.listConnections(f'{bsNodeList[0]}.{nn}')
                if mode == 'on':
                    if connectNode:  # 如果已經連接就跳過
                        continue
                    cmds.connectAttr(f'{self.namespace}{nn}_ARKIT_ctrl.export_data', f'{bsNodeList[0]}.{nn}')
                elif mode == 'off':
                    if not connectNode:  # 如果沒有連接就跳過
                        continue
                    cmds.disconnectAttr(f'{self.namespace}{nn}_ARKIT_ctrl.export_data', f'{bsNodeList[0]}.{nn}')
                    cmds.setAttr(f'{bsNodeList[0]}.{nn}', 0)

    def openArkitFileF(self):
        if not cmds.objExists(f'{self.namespace}{self.iphoneSys}'):
            cmds.warning(
                ThLanguage.tr(
                    '1.場景中找不到控制器; 2.該功能無法在 reference 下使用'))
            return
        # 開啟 CSV 檔案
        path = cmds.file(q=True, sn=True) or 'D:/'
        fileList = cmds.fileDialog2(
            startingDirectory=path, fileFilter=('ARKIT File (*.csv)'), fm=1)
        if not fileList:
            return
        with open(fileList[0]) as csvfile:
            # 讀取 CSV 檔案內容
            data = csv.reader(csvfile)
            dataList = list(data)
            # 獲取 frame list
            time = [float(x[0][9:-4]) / 2.0 for x in dataList[1:]]  # 取出格數
            time = [(x - time[0]) % 30 for x in time]  # 初始化起始值
            # 獲取疊加值
            start = 0
            add = 0
            addList = []
            for n in time:
                if n < start:
                    add += 30
                addList.append(add)
                start = n
            # 加上疊加值
            time = [x + addList[i] for i, x in enumerate(time)]
            # 獲取屬性對應 id
            arkitIdDict = {x: dataList[0].index('{}{}'.format(x[0].upper(), x[1:])) for x in
                self.attrTongueList}
            # 使用進度條
            progressBar = ThUiProgressBar(1)
            progressBar.show()
            progressBar.setStratF(0, '時間', len(time[::2]))
            for i, n in enumerate(time[::2]):  # 時間
                progressBar.setFrameF(0)
                for nn in self.attrTongueList:
                    attr = '{}_ARKIT_ctrl.translateX'.format(nn)
                    cmds.setKeyframe(
                        attr, time=n, value=float(dataList[1:][i * 2][arkitIdDict[nn]]),
                        breakdown=0)
            progressBar.close()


class ThSmoothIkAnim:
    def __init__(self):
        self.clsName = type(self).__name__
        self.sysName = self.clsName + '_data'

    def _keyFrameF(self):
        """key"""
        for i, animValueList in enumerate(self.data['animValueList']):
            for ii, animValues in enumerate(animValueList):
                cmds.setKeyframe(
                    self.data['locJointList'][ii] + '.tx', t=self.timeRange[0] + i, v=animValues)
        # 創建動畫層
        animLayerName = self.clsName + '_animLayer'
        if cmds.objExists(animLayerName):
            cmds.delete(animLayerName)
        cmds.animLayer(animLayerName)
        cmds.select(self.mainCtrl, r=True)
        cmds.animLayer(animLayerName, e=True, addSelectedObjects=True)
        # key to ctrl
        valueList = []
        for time in range(self.timeRange[0], self.timeRange[1] + 1):
            cmds.currentTime(time)
            valueList1 = []
            for attr in ['tx', 'ty', 'tz']:
                valueList1.append(cmds.getAttr('{}.{}'.format(self.data['mainCtrlLoc'], attr)))
            valueList.append(valueList1)
        for i, time in enumerate(range(self.timeRange[0], self.timeRange[1] + 1)):
            for ii, attr in enumerate(['tx', 'ty', 'tz']):
                cmds.setKeyframe(
                    '{}.{}'.format(self.mainCtrl, attr), bd=0, hi='none', cp=0, s=0,
                    al=animLayerName, t=time, itt='spline', ott='spline', v=valueList[i][ii])

    def _smoothAnimF(self):
        """smooth"""
        matrix = ThConversionMatrix.transposeMatrixF(self.data['animValueList'])
        for i in range(self.smoothLoop):
            newMatrix = []
            for ii, m in enumerate(matrix):
                newMatrix1 = [m[0]]  # 加上開頭
                for iii in range(1, len(m) - 1):  # 去掉頭尾
                    now = m[iii]
                    if now != self.data['sumDisValueList'][ii] or self.ifSmoothMaxValue:
                        past = m[iii - 1]
                        future = m[iii + 1]
                        # 計算新值
                        average = (now + past + future) / 3
                        deviation = average - now
                        newValue = now + (deviation * 1)
                        newMatrix1.append(newValue)
                    else:
                        newMatrix1.append(now)
                newMatrix1.append(m[-1])  # 加上結尾
                newMatrix.append(newMatrix1)
            matrix = newMatrix
        self.data['animValueList'] = ThConversionMatrix.transposeMatrixF(matrix)
        self.gsd.setF(self.data)

    def _disF(self, objs):
        disLocGrp = cmds.group(em=True, n=self.clsName + '_disLoc_grp#')
        disLoc1 = cmds.group(em=True, n=self.clsName + '_disLoc1_#')
        disLoc2 = cmds.group(em=True, n=self.clsName + '_disLoc2_#')
        dis = cmds.createNode('distanceBetween', n=self.clsName + '_dis#')
        cmds.connectAttr(disLoc1 + '.worldMatrix', dis + '.inMatrix1', f=True)
        cmds.connectAttr(disLoc2 + '.worldMatrix', dis + '.inMatrix2', f=True)
        cmds.pointConstraint([objs[0], disLoc1], offset=[0, 0, 0], w=1)
        cmds.pointConstraint([objs[1], disLoc2], offset=[0, 0, 0], w=1)
        cmds.parent(disLoc1, disLoc2, disLocGrp)
        cmds.parent(disLocGrp, self.disLocGrp)
        self.data['deleteList'].append(dis)
        return dis

    def _createLocF(self):
        # 創建 sys
        self.gsd = ThGrpSaveData(self.sysName)
        self.data = {}
        self.data['refList'] = self.refList
        self.data['timeRange'] = self.timeRange
        self.data['deleteList'] = [self.sysName]
        self.data['sumDisValueScale'] = self.sumDisValueScale
        # 分析列表
        doRefList = ThConversionMatrix.reshapeListToRowsF(self.refList, 4)
        # 創建 loc
        self.disLocGrp = cmds.group(em=True, n=self.clsName + '_main_disLoc_grp')
        cmds.parent(self.disLocGrp, self.sysName)
        locJointList = []
        locJointGrpList = []
        disNodeList = []
        sumDisValueList = []
        for doRef in doRefList:
            # loc
            cmds.select(cl=True)
            joint1 = cmds.joint(n=self.clsName + '_locJoint1_#')
            cmds.select(cl=True)
            joint2 = cmds.joint(n=self.clsName + '_locJoint2_#')
            ThAdsorptionObj([joint1], doRef[3], 't', ifFreeze=True)
            ThAdsorptionObj([joint2], doRef[0], 't', ifFreeze=True)
            cmds.parent(joint2, joint1)
            cmds.joint(joint1, e=True, oj='xyz', secondaryAxisOrient='zup', ch=True, zso=True)
            cmds.joint(joint2, e=True, oj='none', ch=True, zso=True)
            jointGrp = thLocatorGrpF([joint1])[0]
            cmds.parent(jointGrp, self.sysName)
            locJointList.append(joint2)
            locJointGrpList.append(jointGrp)
            # 約束
            cmds.pointConstraint([doRef[3], jointGrp], offset=[0, 0, 0], w=1)
            cmds.aimConstraint(
                [doRef[0], jointGrp], o=[0, 0, 0], w=1, aim=[1, 0, 0], u=[0, 1, 0], wut='vector',
                wu=[0, 1, 0])
            # 測量距離
            disNodeList1 = [self._disF([x, doRef[i % 3]]) for i, x in enumerate(doRef[:3], 1)]
            disNodeList.append(disNodeList1)
            sumDisValueList.append(
                sum([cmds.getAttr(x + '.distance') for x in disNodeList1[:2]]) * self.sumDisValueScale)
        cmds.hide(locJointGrpList)
        # 複製主控制器
        mainCtrlLoc = cmds.duplicate(self.mainCtrl, rr=True, po=True, rc=True)[0]
        thLockHiddenAttrF([mainCtrlLoc], lock=False)
        cmds.pointConstraint(locJointList + [mainCtrlLoc], mo=True, w=1)
        # 產生動畫曲線數據
        animValueList = []
        for time in range(self.timeRange[0], self.timeRange[1] + 1):
            animValueList1 = []
            for ii, doRef in enumerate(doRefList):
                cmds.currentTime(time)
                disValue = cmds.getAttr(disNodeList[ii][2] + '.distance')
                animValue = sumDisValueList[ii] if disValue > sumDisValueList[ii] else disValue
                animValueList1.append(animValue)
            animValueList.append(animValueList1)
        # 保存資料
        self.data['locJointList'] = locJointList
        self.data['animValueList'] = animValueList
        self.data['sumDisValueList'] = sumDisValueList
        self.data['mainCtrlLoc'] = mainCtrlLoc
        self.data['deleteList'].append(mainCtrlLoc)
        self.gsd.setF(self.data)

    def deleteF(self):
        if cmds.objExists(self.sysName):
            self.gsd = ThGrpSaveData(self.sysName)
            self.data = self.gsd.getF()
            cmds.delete(self.data['deleteList'])

    def applyF(
        self, refList, mainCtrl, timeRange, ifSmoothMaxValue=True, smoothLoop=1,
        sumDisValueScale=1):
        self.refList = refList
        self.mainCtrl = mainCtrl
        self.timeRange = timeRange
        self.ifSmoothMaxValue = ifSmoothMaxValue
        self.smoothLoop = smoothLoop
        self.sumDisValueScale = sumDisValueScale
        if len(self.refList) % 4 != 0:
            cmds.warning(ThLanguage.tr('選擇物件數量錯誤!'))
            return
        #
        if cmds.objExists(self.sysName):
            self.gsd = ThGrpSaveData(self.sysName)
            self.data = self.gsd.getF()
            if (self.data['timeRange'] != self.timeRange or
                    self.data['refList'] != self.refList or
                    self.data['sumDisValueScale'] != self.sumDisValueScale):
                #
                cmds.delete(self.data['deleteList'])
                if cmds.objExists('ThSmoothIkAnim_animLayer'):
                    cmds.delete('ThSmoothIkAnim_animLayer')
                self._createLocF()
            self._smoothAnimF()
            self._keyFrameF()
        else:
            self._createLocF()
            self._smoothAnimF()
            self._keyFrameF()


class ThModifyPivotBoundingBox:
    def __init__(self, objList, dir='-x'):
        """軸心移動到邊界"""
        dirDict = {'-x': [0, 0], 'x': [3, 0], '-y': [1, 1], 'y': [4, 1], '-z': [2, 2], 'z': [5, 2]}
        for obj in objList:
            boundingBox = cmds.xform(obj, q=True, bb=True, ws=True)
            pivot = cmds.xform(obj, q=True, ws=True, rp=True)
            pivot[dirDict[dir][1]] = boundingBox[dirDict[dir][0]]
            cmds.xform(obj, ws=True, a=True, rp=pivot)
            cmds.xform(obj, ws=True, a=True, sp=pivot)


class ThBsToSkinWeight:
    """BS 轉 Skin 權重"""

    def __init__(self, mesh, bsAttrList, mainJoint=None, jointName=None, bsNode=None):
        self.mesh = mesh
        self.bsAttrList = bsAttrList
        self.mainJoint = mainJoint
        self.jointName = jointName if jointName else mesh
        self.bsNode = bsNode if bsNode else thFindBlendShapeNodeF(mesh)[0]
        # 獲取數據
        self._getDataF()
        # 創建綁定
        self._createSkinF()
        # 設定權重
        self._setWeightF()
        # 設定骨骼位置
        self._moveJointF()
        cmds.select(cl=True)

    def _moveJointF(self):
        """設定骨骼位置"""
        # 獲取每根骨骼最大值
        scaleAverageMax = 1 / self.averageMax
        dirList = [1, -1] * 3
        maxList = [(max(n) * scaleAverageMax) * dirList[i] for i, n in enumerate(self.xyzData)]
        xyzLabelList = [n for n in self.xyzLabelList for nn in range(2)]
        for i, n in enumerate(self.newJointList):
            cmds.setAttr('{}.t{}'.format(n, xyzLabelList[i]), maxList[i])

    def _setWeightF(self):
        """設定權重"""
        for i, n in enumerate(self.doIdList):
            self.cwa.dataDict[self.mainJoint][n] = self.otherWeightList[i]
            for ii, nn in enumerate(self.newJointList):
                self.cwa.dataDict[nn][n] = self.xyzDataAverage[ii][i]
        self.cwa.setWeightDataF()

    def _createSkinF(self):
        """創建綁定"""
        # 複製模型
        if not cmds.objExists('thBsToSkinMesh_grp'):
            cmds.group(em=True, n='thBsToSkinMesh_grp')
        self.newMesh = ThEditBlendShape.baseShapeF([self.mesh])[0]
        self.newMesh = cmds.rename(self.newMesh, 'jbs_{}_mesh'.format(self.jointName))
        cmds.parent(self.newMesh, 'thBsToSkinMesh_grp')
        # 創建主要權重骨骼
        cmds.select(cl=True)
        if not self.mainJoint:
            self.mainJoint = cmds.joint(n='jbs_{}_main_joint'.format(self.jointName))
        # 創建主要父骨骼
        cmds.select(cl=True)
        fatherJoint = cmds.joint(n='jbs_{}_joint'.format(self.jointName))
        # 創建次要骨骼
        self.newJointList = []
        for n in self.xyzLabelList:
            for ii in range(2):
                cmds.select(cl=True)
                self.newJointList.append(
                    cmds.joint(n='jbs_{}_{}{}_joint'.format(self.jointName, n, ii)))
        # 修改層級關係
        cmds.parent(self.newJointList, fatherJoint)
        ThAdsorptionObj([fatherJoint], self.mainJoint, 't')
        cmds.parent(fatherJoint, self.mainJoint)
        # skin
        self.skinNode = cmds.skinCluster(
            [self.mainJoint] + self.newJointList, self.newMesh, mi=1, dr=4.0, tsb=True)
        # 獲取權重
        self.cwa = ThCopyWeightApi()
        self.cwa.getWeightDataF(self.newMesh)

    def _getDataF(self):
        """獲取數據"""
        # 斷開連接
        dc = ThDisconnectConnect('ThBsToSkinWeight_ThDisconnectConnect_data')
        dc.switchF([self.bsNode], self.bsAttrList)
        # 獲取起始與結束座標
        for bsAttr in self.bsAttrList:
            cmds.setAttr('{}.{}'.format(self.bsNode, bsAttr), 0)
        startData = thGetVtxDataF(mesh=self.mesh, space='world')
        for bsAttr in self.bsAttrList:
            cmds.setAttr('{}.{}'.format(self.bsNode, bsAttr), 1)
        endData = thGetVtxDataF(mesh=self.mesh, space='world')
        # 恢復連接
        dc.switchF()
        # 獲取有變化的 id
        self.xyzLabelList = ['x', 'y', 'z']
        self.doIdList = []
        changeDataList = []
        for i, n in enumerate(startData):
            if n != endData[i]:
                self.doIdList.append(i)
                changeDataList1 = []
                for ii, nn in enumerate(self.xyzLabelList):
                    dataRange = endData[i][ii] - n[ii]
                    changeDataList1.append(dataRange)
                changeDataList.append(changeDataList1)
        # 獲取設定數據
        self.xyzData = [[0] * len(self.doIdList) for i in range(6)]
        for i, n in enumerate(changeDataList):
            for ii, nn in enumerate(self.xyzLabelList):
                if n[ii] != 0:
                    dirId = 0 if n[ii] > 0 else 1
                    self.xyzData[(ii * 2) + dirId][i] = abs(n[ii])
        # 獲取權重設定值
        self.averageMax = 1 / 3.0
        self.xyzDataAverage = [thScaleValueRangeF(i, self.averageMax) if sum(i) > 0 else i for i in
            self.xyzData]  # 平均移動值 1/3
        xyzData = ThConversionMatrix.transposeMatrixF(self.xyzDataAverage)  # 轉換矩陣格式
        self.otherWeightList = [1 - sum(i) for i in xyzData]  # 加總取得剩下的權種值


class ThResetBlendShape:
    """匯出與匯入 blend shape"""

    def resetF(self, meshList):
        # 匯出 BS
        self.exportF(meshList)
        # 匯入 BS
        self.importF()

    def importF(self):
        """匯入 BS"""
        if not cmds.objExists('ThResetBlendShape'):
            return
        # 讀取資料
        rbs = ThGrpSaveData('ThResetBlendShape')
        nodeDict = rbs.getF()
        # 匯入
        for data in nodeDict['data']:
            # 刪除
            if cmds.objExists(data[1]):
                cmds.delete(data[1])
            # 創建
            cmds.blendShape(data[0], automatic=True, n=data[1])
            cmds.blendShape(data[1], e=True, ip=data[2])
        ThDisconnectConnect('ThResetBlendShape_ThDisconnectConnect_data').switchF()
        # 刪除資料夾
        shutil.rmtree(nodeDict['path'])
        # 刪除保存數據
        cmds.delete('ThResetBlendShape')

    def exportF(self, meshList):
        """匯出 BS"""
        if not meshList:
            return
        # debug
        for n in meshList:
            if '|' in n:
                cmds.warning(
                    ThLanguage.tr(
                        '所選物件中有重複名稱，請先重新命名，再執行本功能!'))
                return
        if cmds.objExists('ThResetBlendShape'):
            cmds.delete('ThResetBlendShape')
        # 創建資料夾
        self.path = cmds.file(q=True, sn=True)
        if not self.path:
            cmds.warning(ThLanguage.tr('請先保存當前檔案!'))
            return
        nodeDict = {}
        nodeDictData = []
        self.nameSp = os.path.splitext(self.path)
        nodeDict['path'] = self.nameSp[0] + 'BsFolder'
        if not os.path.isdir(nodeDict['path']):
            os.mkdir(nodeDict['path'])
        # 匯出
        for mesh in meshList:
            nodeList = thFindBlendShapeNodeF(mesh)
            for node in nodeList:
                filePath = '{}/{}.shp'.format(nodeDict['path'], node)
                nodeDictData.append([mesh, node, filePath])
                cmds.blendShape(node, e=True, ep=filePath)
        nodeDict['data'] = nodeDictData
        # 保存資料
        ThDisconnectConnect('ThResetBlendShape_ThDisconnectConnect_data').switchF(
            [n[1] for n in nodeDict['data']])
        rbs = ThGrpSaveData('ThResetBlendShape')
        rbs.setF(nodeDict)
        cmds.select(meshList, r=True)


class ThCreateInBetweenAttr:
    """創建 in between 屬性"""

    def __init__(self, list_=None, attrList=None):
        self.list_ = list_ if list_ else cmds.ls(sl=True)
        self.attrList = attrList if attrList else thGetMainChannelBoxF()

    def softF(self):
        if not self.list_ or not self.attrList:
            return
        ex = ''
        for n in self.list_:
            for attr in self.attrList:
                addAttr = '{}_inb'.format(attr)
                addOffsetAttr1 = '{}_inb_offset1'.format(attr)
                addOffsetAttr2 = '{}_inb_offset2'.format(attr)
                floatValue1 = '{}_inb_floatValue1'.format(attr)
                floatValue2 = '{}_inb_floatValue2'.format(attr)
                cmds.addAttr(n, ln=addAttr, k=True, at='double', dv=0)
                cmds.addAttr(n, ln=addOffsetAttr1, k=True, at='double', min=0, max=10, dv=0)
                cmds.addAttr(n, ln=addOffsetAttr2, k=True, at='double', min=0, max=10, dv=0)
                cmds.addAttr(n, ln=floatValue1, k=True, at='double', min=0, max=1, dv=0)
                cmds.addAttr(n, ln=floatValue2, k=True, at='double', min=0, max=1, dv=0)
                #
                dsl = ThDistanceSoftLocator(
                    objs=[n], name='{}_{}'.format(n, attr), modeSoft='pipe')
                #
                ex += '{soft}.follow = {n}.{attr} * 10;\n'.format(
                    soft=dsl.softNode[0][1], n=n, attr=attr)
                #
                cmds.connectAttr(
                    '{}.{}'.format(n, addOffsetAttr1), '{}.offset1'.format(dsl.softNode[0][1]))
                cmds.connectAttr(
                    '{}.{}'.format(n, addOffsetAttr2), '{}.offset2'.format(dsl.softNode[0][1]))
                cmds.connectAttr(
                    '{}.{}'.format(n, floatValue1), '{}.floatValue1'.format(dsl.softNode[0][1]))
                cmds.connectAttr(
                    '{}.{}'.format(n, floatValue2), '{}.floatValue2'.format(dsl.softNode[0][1]))
                cmds.connectAttr('{}.ty'.format(dsl.locatorList[0]), '{}.{}'.format(n, addAttr))
        cmds.expression(n='InBetweenAttr_EX#', s=ex)
        cmds.select(self.list_, r=True)

    def exF(self):
        if not self.list_ or not self.attrList:
            return
        ex = ''
        exf = '{0}.{1} = clamp(0, 1, sin((({0}.{2} * {0}.{3}) + (1 - {0}.{3}) / 2) * 3.14159));\n'
        for n in self.list_:
            for attr in self.attrList:
                addAttr = '{}_inb'.format(attr)
                addOffsetAttr = '{}_inb_offset'.format(attr)
                cmds.addAttr(n, ln=addAttr, k=True, at='double', dv=0)
                cmds.addAttr(n, ln=addOffsetAttr, k=True, at='double', min=1, dv=1)
                ex += exf.format(n, addAttr, attr, addOffsetAttr)
        cmds.expression(n='InBetweenAttr_EX#', s=ex)
        cmds.select(self.list_, r=True)


class ThGrpSaveData:
    """保存數據"""
    system = 'ThGrpSaveData_data'

    def __init__(self, system=None, data=None, defData='""'):
        self.system = system if system else self.system
        #
        sysNote = f'{self.system}.notes'
        if not cmds.objExists(self.system):
            cmds.group(em=True, n=self.system)
        if not cmds.attributeQuery('nts', node=self.system, exists=True):
            cmds.addAttr(self.system, sn='nts', ln='notes', dt='string')
            cmds.setAttr(sysNote, defData, type='string')
        if not data is None:
            cmds.setAttr(sysNote, data, type='string')

    def setF(self, data):
        self.data = data
        cmds.setAttr(f'{self.system}.notes', self.data, type='string')

    def getF(self):
        if cmds.objExists(self.system):
            data = cmds.getAttr(f'{self.system}.notes')
            if data is None:
                return
            else:
                self.data = eval(data)
                return self.data


class ThEditSelectJointSkinWeight:
    """編輯指定骨骼權重"""

    def editF(self, mesh, jointList, copyWeightMode='copy'):
        if cmds.objExists('ThEditSelectJointSkinWeight_data'):
            return
        # 使用進度條
        progressBar = ThUiProgressBar(1)
        progressBar.show()
        progressBar.setStratF(0, '', 5)
        #
        self.mesh = mesh
        self.jointList = [j for j in jointList if cmds.nodeType(j) == 'joint']
        self.copyWeightMode = copyWeightMode
        self.skinNode = thFindSkinNodeF([self.mesh])[0]
        # 添加骨骼列表
        progressBar.setFrameF(0, ThLanguage.tr('添加骨骼列表'))
        self._reJointListF(self.mesh, self.jointList)
        # 獲取 vtx list
        progressBar.setFrameF(0, ThLanguage.tr('獲取 vtx list'))
        self._getSkinVtxF()
        # 複製權重模型
        progressBar.setFrameF(0, ThLanguage.tr('複製權重模型'))
        self._copySkinMeshF()
        # 複製編輯權重模型
        progressBar.setFrameF(0, ThLanguage.tr('複製編輯權重模型'))
        self._copyEditSkinMeshF()
        # hidden
        try:
            cmds.hide(self.mesh)
            cmds.hide(self.newMesh)
            cmds.showHidden(self.newEditMesh)
        except:
            pass
        # 影藏其他骨骼
        scJointList = [x for x in cmds.ls(type='joint') if cmds.getAttr(f'{x}.drawStyle') == 0]
        scJointDrawStyleData = {x: cmds.getAttr(f'{x}.drawStyle') for x in scJointList}
        doScJointList = list(set(scJointList) - set(self.jointList))
        for j in doScJointList:
            cmds.setAttr(f'{j}.drawStyle', 2)
        # maya 2022 沒辦法設定
        try:
            for j in self.jointList:
                cmds.setAttr(f'{j}.drawStyle', 3)
        except:
            pass
        # save
        progressBar.setFrameF(0, 'Save')
        data = {
            'mesh': self.mesh,
            'jointList': self.jointList,
            'newMesh': self.newMesh,
            'newEditMesh': self.newEditMesh,
            'doScJointList': doScJointList,
            'scJointDrawStyleData': scJointDrawStyleData}
        gsd = ThGrpSaveData('ThEditSelectJointSkinWeight_data')
        gsd.setF(data)
        # parent
        cmds.parent(self.newMesh, self.newEditMesh, 'ThEditSelectJointSkinWeight_data')
        # select
        cmds.select(self.newEditMesh, r=True)
        #
        progressBar.close()

    @staticmethod
    def backF():
        # 讀取數據
        gsd = ThGrpSaveData('ThEditSelectJointSkinWeight_data')
        data = gsd.getF()
        #
        try:
            cmds.showHidden(data['mesh'])
        except:
            pass
        # 顯示其他骨骼
        for j, v in data['scJointDrawStyleData'].items():
            cmds.setAttr(f'{j}.drawStyle', v)
        #
        cmds.delete('ThEditSelectJointSkinWeight_data')

    def copyWeightF(self, ifOm2=False):
        # 讀取數據
        gsd = ThGrpSaveData('ThEditSelectJointSkinWeight_data')
        data = gsd.getF()
        # 導回權重
        if not ifOm2:
            csaw = ThCopySkinAndWeight([data['newMesh']], [data['mesh']])
            csaw.copySkinF()
            csaw.copyWeightF()
        else:
            ThCopyWeightApi().copyWeightF(data['newMesh'], data['mesh'])
        #
        __class__.backF()
        #
        cmds.select(data['mesh'], r=True)

    def modifyF(self):
        # 讀取數據
        gsd = ThGrpSaveData('ThEditSelectJointSkinWeight_data')
        data = gsd.getF()
        # 轉移權重
        ThMoveSkinWeightOm2(
            objs=[data['newMesh']], oldJointList=data['jointList'][:-1],
            newJointList=[data['jointList'][-1]])
        # 添加骨骼列表
        self._reJointListF(data['newEditMesh'], data['jointList'])
        # 拆分權重
        ThTwoObjWeightBlend(
            refObj=data['newEditMesh'], mainObjList=[data['newMesh']],
            refJointList=data['jointList'], mainJointList=[data['jointList'][-1]], om2=True,
            doPruneWeightsArgList=True)
        try:
            cmds.showHidden(data['newMesh'])
            cmds.hide(data['newEditMesh'])
        except:
            pass

    def _reJointListF(self, mesh, jointList):
        """添加骨骼列表"""
        skinJointList = thFindSkinJointF([mesh])
        for j in jointList:
            if not j in skinJointList:
                cmds.skinCluster(self.skinNode, e=True, ai=j, wt=0)

    def _copyEditSkinMeshF(self):
        """複製編輯權重模型"""
        self.newEditMesh = cmds.duplicate(self.newMesh, rr=True)[0]
        self.newEditMesh = cmds.rename(self.newEditMesh, 'ThEditSelectJointSkinWeight_newEditMesh#')
        newEditMeshVtxList = ['{}.{}'.format(self.newEditMesh, n) for n in self.skinVtxList]
        newEditMeshFaceList = cmds.polyListComponentConversion(newEditMeshVtxList, tf=True)
        cmds.select(newEditMeshFaceList, r=True)
        # mel.eval('PolySelectTraverse 2;')  # 減少選擇範圍
        cmds.select('{}.f[*]'.format(self.newEditMesh), tgl=True)
        if cmds.ls(sl=True):
            cmds.delete()
        # 複製權重
        skinObjList = self.jointList + [self.newEditMesh]
        if self.copyWeightMode == 'myFunc':
            cmds.skinCluster(skinObjList, tsb=True, obeyMaxInfluences=False)
            ThCopyWeightApi().copyNameWeightF(self.mesh, self.newEditMesh)
        elif self.copyWeightMode == 'name':
            cmds.skinCluster(skinObjList, tsb=True, obeyMaxInfluences=False)
            ThCopySkinAndWeight([self.mesh], [self.newEditMesh]).copyWeightF('name')
        elif self.copyWeightMode == 'skin':
            cmds.skinCluster(skinObjList, mi=1, dr=4, tsb=True)
        # 解鎖變換
        for attr in ['tx', 'ty', 'tz', 'rx', 'ry', 'rz', 'sx', 'sy', 'sz']:
            cmds.setAttr('{}.{}'.format(self.newEditMesh, attr), lock=False, keyable=True)

    def _copySkinMeshF(self):
        """複製權重模型"""
        self.newMesh = cmds.duplicate(self.mesh, rr=True)[0]
        self.newMesh = cmds.rename(self.newMesh, 'ThEditSelectJointSkinWeight_newMesh')
        ThClearChShapeNode([self.newMesh])
        ThCopyWeightApi().copyWeightF(self.mesh, self.newMesh)
        # 解鎖變換
        for attr in ['tx', 'ty', 'tz', 'rx', 'ry', 'rz', 'sx', 'sy', 'sz']:
            cmds.setAttr('{}.{}'.format(self.newMesh, attr), lock=False, keyable=True)

    def _getSkinVtxF(self):
        """獲取 vtx list"""
        self.skinVtxList = []
        for joint in self.jointList:
            cmds.select(cl=True)
            cmds.skinCluster(self.skinNode, siv=joint, e=True)
            selVtx = cmds.ls(sl=True, fl=True)
            if '.' in selVtx[0]:
                self.skinVtxList.extend([n.split('.')[1] for n in selVtx])
        self.skinVtxList = list(set(self.skinVtxList))


class ThSmoothAnimCv:
    def __init__(self, timeSlider=None):
        self.timeSlider = timeSlider
        # 獲取曲線屬性列表
        self._getCvF()

    def _getCvF(self):
        """獲取曲線屬性列表"""
        self.selCvList = cmds.keyframe(q=True, name=True, sl=True)
        if self.selCvList == None:
            cmds.warning(ThLanguage.tr('請選擇動畫曲線後再執行本功能!'))
            return
        # 範圍
        if self.timeSlider == 'play':
            self.staet = int(cmds.playbackOptions(q=True, min=True))
            self.end = int(cmds.playbackOptions(q=True, max=True))
        else:
            cvData = cmds.keyframe(self.selCvList[0], q=True, timeChange=True, sl=True)
            self.staet = cvData[0]
            self.end = cvData[-1]

    def smoothF(self, strongValue=1, keepValue=1):
        """
        :type strongValue: int 循環次數
        :type keepValue: float 設定值乘數
        """
        for cv in self.selCvList:
            for k in range(int(strongValue)):
                # 時間滑塊中鍵的值
                cvValueList = cmds.keyframe(
                    cv, q=True, time=(self.staet, self.end), valueChange=True)
                # 時間滑塊中鍵的時間值
                cvTimeList = cmds.keyframe(cv, q=True, time=(self.staet, self.end), timeChange=True)
                # 排除開頭及結尾
                newCvValueList = [cvValueList[0]]
                # 循還值
                for i in range(1, len(cvValueList) - 1):
                    now = cvValueList[i]
                    past = cvValueList[i - 1]
                    future = cvValueList[i + 1]
                    # 計算新值
                    average = (now + past + future) / 3
                    deviation = average - now
                    newValue = now + (deviation * keepValue)
                    newCvValueList.append(newValue)
                newCvValueList.append(cvValueList[-1])
                # 設定 key
                for i in range(len(newCvValueList) - 1):
                    try:
                        cmds.keyframe(
                            cv, e=True, time=(cvTimeList[i],), valueChange=newCvValueList[i])
                    except:
                        pass

    def filterCurveF(self, timeTolerance=.06):
        selectList = cmds.ls(sl=True)
        for cv in self.selCvList:
            cmds.filterCurve(cv, s=self.staet, e=self.end, filter='simplify', tto=timeTolerance)
            cmds.bakeResults(cv, sb=1, osr=1, t=(self.staet, self.end), pok=1, sac=0)
        cmds.select(selectList, r=True)


class ThBackMocapRotate:
    def __init__(self, objectList, timeRange=None):
        # 讀取時間範圍
        if timeRange is None:
            timeRange = thGetObjAnimRangeF(objectList)
            if timeRange is None:
                sys.stdout.write('not find key node!')
                return
        # 控制器移出動畫層
        animLayerList = cmds.ls(type='animLayer')
        mel.eval(
            'layerEditorRemoveObjectsAnimLayer({}, {})'.format(
                thListToMelF(objectList), thListToMelF(animLayerList)))
        #
        range_ = (timeRange[1] - timeRange[0])
        cmds.currentTime(timeRange[0])
        data = {}
        for i in range(range_ + 1):
            time = timeRange[0] + i
            data[time] = {x: cmds.xform(x, q=True, ws=True, m=True) for x in objectList}
            cmds.currentTime(time)
        # 關閉自動 key
        cmds.autoKeyframe(state=0)
        for time, d in data.items():
            for obj, value in d.items():
                cmds.xform(obj, ws=True, m=value)
            cmds.setKeyframe(objectList, t=time)
        cmds.select(objectList, r=True)


class ThLoopValueRangeLimit:
    """列表屬性值 0 到 1 循環"""

    def __init__(self, list_, ctrlAttr, attr, range_=1, speed=.1):
        self.list_ = list_
        self.ctrlAttr = ctrlAttr
        self.attr = attr
        self.range_ = range_
        self.speed = speed
        self.system = 'ThLoopValueRangeLimit_EX#'
        #
        exStart = 'if ({} < 0)'.format(ctrlAttr)
        ex1 = ''
        ex2 = ''
        for n in self.list_:
            value = cmds.getAttr('{}.{}'.format(n, self.attr))
            ex1 += '    {}.{} = 1 - (((abs({}) * {}) + (1 - {})) % {});\n'.format(
                n, self.attr, ctrlAttr, self.speed, value, self.range_)
            ex2 += '    {}.{} = (({} * {}) + {}) % {};\n'.format(
                n, self.attr, ctrlAttr, self.speed, value, self.range_)
        ex = exStart + '{\n' + ex1 + '} else {\n' + ex2 + '}'
        cmds.expression(n=self.system, s=ex)


class ThConversionMatrix:
    """列表與矩陣轉換"""

    @staticmethod
    def reshapeListToRowsF(list_, len_):
        """
        依固定長度轉為 row 矩陣
        [1,2,3,4,5,6] + len_=3 → [[1,2,3], [4,5,6]]
        """
        list0 = []
        list1 = []
        for i, n in enumerate(list_, 1):
            list1.append(n)
            if i % len_ == 0:
                list0.append(list1)
                list1 = []
        return list0

    @staticmethod
    def reshapeListToColumnsF(list_, horizontal):
        """
        依 column 數轉為 column 矩陣
        list_[i::horizontal]
        """
        rusList_ = []
        for i in range(horizontal):
            rusList_.append(list_[i::horizontal])
        return rusList_

    @staticmethod
    def flattenListF(list_):
        """
        攤平成一維 list
        [[1,2],[3,4]] → [1,2,3,4]
        """
        rusList = [nn for n in list_ for nn in n]
        return rusList

    @staticmethod
    def transposeMatrixF(list_):
        """
        矩陣行列轉置
        [[1,2,3],[4,5,6]] → [[1,4],[2,5],[3,6]]
        """
        rusList0 = []
        vertical = len(list_)
        horizontal = len(list_[0])
        for i in range(horizontal):
            rusList1 = []
            for ii in range(vertical):
                rusList1.append(list_[ii][i])
            rusList0.append(rusList1)
        return rusList0


class ThDefToSkin:
    """變形器轉換蒙皮權重"""

    def __init__(self, systemName='ThDefToSkin_data'):
        self.systemName = systemName

    def applyF(
        self, meshList, jointList, offset=1, ifNewMesh=False, ifDelLattice=False,
        ifDelDeltaMush=False, ifDelTension=False, dir='y',
        scaleValueJointList=None, scaleValue=2):
        #
        self.meshList = meshList
        self.jointList = jointList
        self.offset = offset
        self.ifNewMesh = ifNewMesh
        self.ifDelLattice = ifDelLattice
        self.ifDelDeltaMush = ifDelDeltaMush
        self.ifDelTension = ifDelTension
        self.dir = dir
        self.dirId = {'x': 0, 'y': 1, 'z': 2}[self.dir]
        self.scaleValueJointList = scaleValueJointList
        self.scaleValue = scaleValue
        #
        self.dc = None
        self.rp = None
        #
        if cmds.objExists(self.systemName):
            return
        # 斷開連接
        attrList = ['tx', 'ty', 'tz', 'rx', 'ry', 'rz', 'sx', 'sy', 'sz']
        self.dc = ThDisconnectConnect('ThDefToSkin_ThDisconnectConnect_data')
        self.dc.switchF(self.jointList, attrList + ['t', 'r', 'x'])
        # 解除父子關係
        self.rp = ThReconstructionParent(
            list_=self.jointList, system='ThDefToSkin_ThReconstructionParent_data')
        self.rp.applyF()
        #
        rpJointList = self.rp.getJointListF()
        #
        self.newMeshList = []
        for mesh in meshList:
            skinData = self._getWeightF(mesh)  # 獲取權重數據
            newMesh = self._copySkinMeshF(mesh)  # 複製新模型
            self.newMeshList.append(newMesh)
            # skin
            cwa = ThCopyWeightApi()
            cwa.mesh = newMesh
            cwa.data = [rpJointList, skinData]
            cwa.setWeightDataF(False)
        #
        if self.ifNewMesh and hasattr(self, 'gsd'):
            self.gsd.setF(
                {
                    'meshList': self.meshList,
                    'jointList': rpJointList,
                    'newMeshList': self.newMeshList
                })
        #
        self.rp.applyF()  # 恢復父子關係
        self.dc.switchF()  # 恢復連接
        #
        self.delDefF(self.meshList, self.ifDelLattice, self.ifDelDeltaMush, self.ifDelTension)
        #
        if self.newMeshList:
            cmds.select(self.newMeshList, r=True)

    def delDefF(self, meshList, ifDelLattice=True, ifDelDeltaMush=True, ifDelTension=True):
        """刪除指定的變形器及其相關節點"""
        defTypeList = []
        if ifDelLattice:
            # lattice 通常包含 ffd 節點與 lattice 造型節點
            defTypeList += ["ffd", "lattice", "baseLattice"]
        #
        if ifDelDeltaMush:
            defTypeList += ["deltaMush"]
        #
        if ifDelTension:
            defTypeList += ["tension"]
        #
        delList = []
        for meshName in meshList:
            historyNodes = cmds.listHistory(meshName) or []
            for nodeName in historyNodes:
                nodeType = cmds.nodeType(nodeName)
                if nodeType in defTypeList:
                    # 檢查該節點是否為 shape，如果是則抓取其父層 transform
                    if nodeType in ["lattice", "baseLattice"]:
                        parentNodes = cmds.listRelatives(nodeName, parent=True, fullPath=True)
                        if parentNodes:
                            delList.append(parentNodes[0])
                    # 將節點本身加入刪除清單
                    delList.append(nodeName)
        #
        if delList:
            # 使用 set 去除重複節點，避免重複刪除報錯
            finalDelList = list(set(delList))
            cmds.delete(finalDelList)

    def _copySkinMeshF(self, mesh):
        """複製新模型"""
        newMesh = mesh
        if self.ifNewMesh:
            newMesh = cmds.duplicate(mesh, rr=True)[0]
            newMesh = cmds.rename(newMesh, f'ThDefToSkin_{mesh}#')
            thLockHiddenAttrF([newMesh], [1, 1, 1, 1], False)
            # 呼叫清除形狀節點函式
            ThClearChShapeNode(objList=[newMesh])
            #
            if not cmds.objExists(self.systemName):
                self.gsd = ThGrpSaveData(self.systemName)
            #
            cmds.parent(newMesh, self.systemName)
        else:
            skinNode = thFindSkinNodeF([mesh])
            if skinNode:
                cmds.delete(skinNode)
        return newMesh

    def _getWeightF(self, mesh):
        """獲取權重數據"""
        defVtxData = self._getVtxDataF(mesh)  # 獲取初始頂點位置
        skWeightList = []
        #
        for joint in self.rp.getJointListF():
            tData = cmds.getAttr(f'{joint}.t')[0]
            offsetValue = self.offset
            #
            if self.scaleValueJointList:
                if joint in self.scaleValueJointList:
                    offsetValue *= self.scaleValue
                else:
                    offsetValue /= self.scaleValue
            #
            jointMove = [0, 0, 0]
            jointMove[self.dirId] = offsetValue
            #
            cmds.move(*jointMove, joint, ws=True, r=True)
            vtxData = self._getVtxDataF(mesh)
            #
            weightList = [abs(b - a) for a, b in zip(defVtxData, vtxData)]
            skWeightList.extend(weightList)
            #
            cmds.setAttr(f'{joint}.t', *tData)
        # 權重矩陣處理
        skWeightMatrix = ThConversionMatrix.reshapeListToColumnsF(skWeightList, len(defVtxData))
        #
        averageSkWeightMatrix = [thAverageDataF(row) for row in skWeightMatrix]
        skWeightList = ThConversionMatrix.flattenListF(averageSkWeightMatrix)
        return skWeightList

    def _getVtxDataF(self, mesh):
        """獲取頂點位置"""
        sel = om2.MSelectionList()
        sel.add(mesh)
        meshDagPath = sel.getDagPath(0)
        fnMesh = om2.MFnMesh(meshDagPath)
        pointList = fnMesh.getPoints(om2.MSpace.kWorld)
        return [p[self.dirId] for p in pointList]


class ThJointLayoutGrp:
    """依據子骨骼數量創建歸納群組"""

    def __init__(self, type='joint', objList=None):
        self.type = type
        self.objList = objList if objList else cmds.ls(sl=True)
        for n in self.objList:
            objLen = len(cmds.listRelatives(n, ad=True, f=True, type=self.type))
            grpName = '_{}LayGrp_{}'.format(self.type, objLen)
            if not cmds.objExists(grpName):
                cmds.group(n=grpName, em=True)
            cmds.parent(n, grpName)
        cmds.select(cl=True)


class ThMoveSkinWeightToNewJoint:
    """移動權重到新骨骼"""

    def __init__(self, jointList):
        self.jointList = jointList
        self.newJointList = []
        #
        for j in self.jointList:
            # 獲取 skin mesh
            skinMeshList = thFindJointConnectMeshF([j])
            if not skinMeshList:
                continue
            # 創建 joint
            cmds.select(cl=True)
            newJoint = cmds.joint(n='in_{}_#'.format(j))
            self.newJointList.append(newJoint)
            # 對位
            ThAdsorptionObj([newJoint], j, 'tr')
            cmds.parent(newJoint, j)
            cmds.makeIdentity(newJoint, apply=True, t=True, r=True, s=True, n=False, pn=True)
            # 轉移權重
            msw = ThMoveSkinWeightOm2(
                objs=skinMeshList, oldJointList=[j], newJointList=[newJoint], opacity=1,
                ifRemoveInfluence=True)
        cmds.select(self.newJointList, r=True)


class ThSplitAttrData:
    """分割屬性權重"""

    def __init__(self, objList=None, attrList=None, mode='+'):
        self.objList = objList if objList else cmds.ls(sl=True)
        self.attrList = attrList if attrList else thGetMainChannelBoxF()
        self.mode = mode
        #
        ex = ''
        for obj in self.objList:
            for attr in self.attrList:
                defaultVal = cmds.getAttr('{}.{}'.format(obj, attr))
                addAttr1 = attr + '_1'
                addAttr2 = None
                # 嘗試取得 min, max, defaultValue
                minVal = None
                maxVal = None
                #
                if cmds.attributeQuery(attr, node=obj, minExists=True):
                    minVal = cmds.attributeQuery(attr, node=obj, min=True)[0]
                if cmds.attributeQuery(attr, node=obj, maxExists=True):
                    maxVal = cmds.attributeQuery(attr, node=obj, max=True)[0]
                # 若 target 沒有此屬性，建立新屬性
                targetAttr = f'{obj}.{addAttr1}'
                if not cmds.objExists(targetAttr):
                    addKwargs = {
                        'longName': addAttr1,
                        'keyable': True}
                    #
                    addKwargs['attributeType'] = 'double'
                    addKwargs['defaultValue'] = defaultVal
                    if minVal is not None:
                        addKwargs['min'] = minVal
                    if maxVal is not None:
                        addKwargs['max'] = maxVal
                    #
                    try:
                        cmds.addAttr(obj, **addKwargs)
                    except Exception as e:
                        print(f"[錯誤] 新增屬性失敗: {targetAttr} ({str(e)})")
                        continue
                #
                if self.mode == '+':
                    addAttr2 = attr + '_2'
                    cmds.addAttr(obj, ln=addAttr2, k=True, at='double', dv=0)
                else:
                    addAttr2 = '{}_weight'.format(attr)
                    cmds.addAttr(obj, ln=addAttr2, k=True, at='double', min=0, max=1, dv=1)
                ex += '{0}.{1} = {0}.{4} {2} {0}.{3};\n'.format(
                    obj, attr, self.mode, addAttr2, addAttr1)
        cmds.expression(n='splitAttr_EX#', s=ex)
        cmds.select(self.objList, r=True)


class ThDelNoneConGrp:
    """清理層級下無作用的 group"""

    def __init__(self, list_):
        self.list_ = list_
        # 篩選類別
        grpList = cmds.listRelatives(list_, f=0, ad=True)
        grpTypeList = thTypeF(grpList)
        grpList = [grp for i, grp in enumerate(grpList) if grpTypeList[i] == 'transform']
        # 篩選作用
        grpList = [grp for grp in grpList if len(cmds.listHistory(grp, leaf=True)) <= 1]
        # 篩選初始值
        attrList = ['tx', 'ty', 'tz', 'rx', 'ry', 'rz']
        attrDataList = [0, 0, 0, 0, 0, 0, 1, 1, 1]
        ungroupList = []
        for grp in grpList:
            for i, attr in enumerate(attrList):
                if cmds.getAttr('{}.{}'.format(grp, attr)) != attrDataList[i]:
                    break
            else:
                try:
                    cmds.ungroup(grp)
                    ungroupList.append(grp)
                except:
                    continue
        sys.stdout.write(ThLanguage.tr('刪除了: {} 個物件').format(len(ungroupList)))


class ThSelectIsTypeCtrl:
    def __init__(self, list_, base):
        self.list_ = list_
        self.base = base
        #
        maxValue = cmds.getAttr('{}.maxValue'.format(self.base))
        shape = cmds.listRelatives(self.base, f=True, s=True)[0]
        color = cmds.getAttr('{}.overrideColor'.format(shape))
        result = []
        for n in self.list_:
            cMaxValue = cmds.getAttr('{}.maxValue'.format(n))
            cShape = cmds.listRelatives(n, f=True, s=True)[0]
            cColor = cmds.getAttr('{}.overrideColor'.format(cShape))
            if cMaxValue == maxValue and cColor == color:
                result.append(n)
        if result:
            cmds.select(result + [self.base], r=True)
        else:
            cmds.select(cl=True)


