class ThEditBlendShape:
    @staticmethod
    def delAttrF(node, attr):
        """刪除屬性"""
        if cmds.attributeQuery(attr, node=node, exists=True):
            id_ = __class__.findIdAttrF(node, attr)
            mel.eval('blendShapeDeleteTargetGroup("{}", "{}")'.format(node, id_[7:-1]))

    @staticmethod
    def scaleWeightF(mesh, bsNode, scale, attrList):
        """縮放權重"""
        # 斷開 bs 連接
        dcSys = 'ThEditBlendShape_scaleWeightF_ThDisconnectConnect'
        dc = ThDisconnectConnect(dcSys)
        dc.switchF([bsNode], attrList)
        # 關閉 bs 編輯狀態
        __class__.offEditF([bsNode])
        for attr in attrList:
            # 設定值
            nodeAttr = '{}.{}'.format(bsNode, attr)
            value = cmds.getAttr(nodeAttr)
            cmds.setAttr(nodeAttr, scale)
            # 複製模型
            newMesh = cmds.duplicate(mesh, rr=True)[0]
            # 設定值
            cmds.setAttr(nodeAttr, 1)
            # 開啟編輯
            bsAttrId = __class__.findIdAttrF(bsNode, attr)
            cmds.sculptTarget(bsNode, e=True, target=int(bsAttrId[7:-1]))
            # 頂點數值傳遞
            ThSetMeshPoint().applyF(newMesh, mesh)
            # 關閉編輯
            cmds.sculptTarget(bsNode, e=True, target=int(bsAttrId[7:-1]))
            # 回復原數據
            cmds.setAttr(nodeAttr, value)
            # 刪除複製模型
            cmds.delete(newMesh)
        # 還原連接
        dc.switchF()
        cmds.select(cl=True)

    @staticmethod
    def isSkinWeightCreateJointF(node, mesh):
        """依據 skin 權重設定 blend(創建 joint)"""
        attrList = cmds.listAttr('{}.w'.format(node), m=True)
        moveTy = 0
        jointList = []
        for attr in attrList:
            joint = thSelCreateJointF(mesh)
            sysName = 'SW_{}'.format(attr)
            if cmds.objExists(sysName):
                cmds.select(joint, r=True)
                cmds.warning(
                    ThLanguage.tr(
                        '場景中有該規範名稱，請先進行清理後再次執行!'))
                return
            joint = cmds.rename(joint, sysName)
            jointList.append(joint)
            cmds.move(0, moveTy, 0, joint, r=True)
            moveTy += 1
        cmds.skinCluster(jointList + [mesh], mi=5, dr=4.0, tsb=True)

    @staticmethod
    def isSkinWeightF(node, mesh):
        """依據 skin 權重設定 blend 權重(設定權重)"""
        cwa = ThCopyWeightApi()
        cwa.getWeightDataF(mesh, True)
        for joint, weightList in cwa.dataDict.items():
            joint = joint.replace('SW_', '')
            bsId = __class__.findIdAttrF(node, joint)[7:-1]
            for vtx, weight in enumerate(weightList):
                cmds.setAttr(
                    '{}.inputTarget[0].inputTargetGroup[{}].targetWeights[{}]'.format(
                        node, bsId, vtx), weight)

    @staticmethod
    def createBlendShapeF(objects=None, delHis=False, editShape=False, data=1):
        """創建 blend shape node"""
        selectList = objects if objects else cmds.ls(sl=True)
        if not selectList:
            return
        #
        if delHis:
            bsNodeList = thFindBlendShapeNodeF([selectList[-1]])
            if bsNodeList:
                cmds.delete(bsNodeList)
        #
        node = cmds.blendShape(selectList, automatic=True)[0]
        #
        for i in range(len(selectList) - 1):
            cmds.setAttr('{}.w[{}]'.format(node, i), data)
        #
        if editShape:
            cmds.sculptTarget(node, e=True, target=0)
        return node

    @staticmethod
    def baseShapeF(meshList, isClearChShapeNode=True):
        """獲取 base mesh"""
        newMeshList = []
        for mesh in meshList:
            his = cmds.listHistory(mesh)
            typeList = ['blendShape', 'skinCluster']
            defList = cmds.ls(his, type=typeList)
            for n in defList:
                cmds.setAttr(n + '.envelope', 0)
            newMesh = cmds.duplicate(mesh, rr=True, rc=True)[0]
            newMeshList.append(newMesh)
            for n in defList:
                cmds.setAttr(n + '.envelope', 1)
            # unlock
            for attr in ['tx', 'ty', 'tz', 'rx', 'ry', 'rz', 'sx', 'sy', 'sz']:
                cmds.setAttr('{}.{}'.format(newMesh, attr), lock=False, keyable=True)
        # 刪除多餘 shape
        if isClearChShapeNode:
            ThClearChShapeNode(newMeshList)
        return newMeshList

    @staticmethod
    def differenceSkinF(skinMesh, baseMesh, changeMesh):
        """獲取差異"""
        skinNode = thFindSkinNodeF([skinMesh])
        if not skinNode:
            cmds.warning(ThLanguage.tr('需要 skin 節點!'))
        # 創建 blend
        shapeNode = __class__.createBlendShapeF(objects=[baseMesh, skinMesh], editShape=True)
        # 數值傳遞
        ThSetMeshPoint().applyF(changeMesh, skinMesh)
        # 複製
        newShape = cmds.duplicate(baseMesh, rr=True, rc=True)[0]
        # 刪除
        cmds.delete(shapeNode)
        return newShape

    @staticmethod
    def differenceF(baseMesh, stratMesh, endMesh, ifCopy=True):
        """減去"""
        node = cmds.blendShape([endMesh, stratMesh, baseMesh], automatic=True)[0]
        cmds.setAttr(node + '.w[0]', 1)
        cmds.setAttr(node + '.w[1]', -1)
        new = None
        if ifCopy:
            new = cmds.duplicate(baseMesh, rr=True, rc=True)[0]
            cmds.delete(node)
        else:
            new = baseMesh
            cmds.delete(baseMesh, ch=True)
        return new

    @staticmethod
    def findIdF(node):
        """找可用 ID"""
        attrList = cmds.aliasAttr(node, q=True)
        attrList = attrList[1::2] if attrList else None
        idList = [int(n.strip('weight')[1:-1]) for n in attrList] if attrList else []
        #
        index = 0
        for i in idList:
            if not index in idList:
                break
            index += 1
        return index

    @staticmethod
    def findIdAttrF(node, attr):
        """找屬性的 ID.
        :return: str 'weight[...]'
        """
        attrIdList = cmds.aliasAttr(node, q=True)
        if not attrIdList:
            return
        attrList = attrIdList[0::2]
        idList = attrIdList[1::2]
        if not attr in attrList:
            return
        #
        index = attrList.index(attr)
        return idList[index]

    @staticmethod
    def ctrlF(node, base, target, ctrl, mode='up', ctrlMode='addAndCtrl'):
        """連接控制器.
        :type mode: str
            'up' | 'dn' | 'left' | 'right'
            'upLeft' | 'upRight' | 'dnLeft' | 'dnRight'
        :type ctrlMode: str 'addAndCtrl' | 'ctrl'
        """
        # 判斷要用 add 還是從 node 的 attr 控制
        newName = '{}_{}'.format(ctrl, mode)
        if ctrlMode == 'addShape':
            # rename
            newName = cmds.rename(target, newName)
            # add
            __class__.addF(node, base, [newName])
        elif ctrlMode == 'fromAttr':
            if not cmds.attributeQuery(newName, node=node, exists=True):
                id_ = __class__.findIdAttrF(node, target)
                cmds.aliasAttr(newName, '{}.{}'.format(node, id_))
        # ex
        ex = None
        if mode in ['up', 'dn', 'left', 'right']:
            axial = {'up': ['', 'ty'], 'dn': ['-', 'ty'], 'left': ['-', 'tx'], 'right': ['', 'tx']}
            ex = '{}.{} = clamp(0,1,{}{}.{});'
            ex = ex.format(node, newName, axial[mode][0], ctrl, axial[mode][1])
        else:
            axial = {
                'upLeft': ['', '-'], 'upRight': ['', ''], 'dnLeft': ['-', '-'],
                'dnRight': ['-', '']}
            ex = '{0}.{1} = clamp(0,1,{2}{3}.ty) * clamp(0,1,{4}{3}.tx);'
            ex = ex.format(node, newName, axial[mode][0], ctrl, axial[mode][1])
        cmds.expression(n=newName + '_EX#', s=ex)
        cmds.select(ctrl, r=True)

    @staticmethod
    def findSelectListIdF():
        sel = cmds.optionVar(q='blendShapeEditorTreeViewSelection')
        sel = list(set(sel))
        while '' in sel:
            sel.remove('')
        while '0' in sel:
            sel.remove('0')
        sel = sel[0].split('/')
        while '' in sel:
            sel.remove('')
        return sel

    @staticmethod
    def findSelectListIdAttrOneF():
        sel = __class__.findSelectListIdF()[0]
        node, id_ = sel.split('.')
        attrID = 'weight[{}]'.format(id_)
        #
        attrIdList = cmds.aliasAttr(node, q=True)
        attrList = attrIdList[0::2]
        idList = attrIdList[1::2]
        index = idList.index(attrID)
        return attrList[index]

    @staticmethod
    def offEditF(bsNodeList=None):
        """關閉編輯狀態"""
        nodeList = bsNodeList if bsNodeList else cmds.ls(type='blendShape')
        for n in nodeList:
            try:
                cmds.sculptTarget(n, e=True, target=-1)
            except:
                pass

    @staticmethod
    def addF(node, base, inpMeshList, data=0, edit=False, nameList=None):
        """添加 shape"""
        indexList = []
        for i, n in enumerate(inpMeshList):
            index = __class__.findIdF(node)
            indexList.append(index)
            cmds.blendShape(node, e=True, t=[base, index, n, 1], w=[index, data])
            if edit:
                cmds.sculptTarget(node, e=True, target=index)
            if nameList:
                if not nameList[i] == n:
                    cmds.aliasAttr(nameList[i], '{}.w[{}]'.format(node, index))
        return indexList

    @staticmethod
    def addShapeF(nodeList, editOn=0, resetWeight=1, name=None):
        for node in nodeList:
            id_ = mel.eval(
                'doBlendShapeAddTarget("{}", 1, 1, "", {}, {}, {{}});'.format(
                    node, editOn, resetWeight))[0]
            if name:
                mel.eval('blendShapeRenameTargetAlias("{}", {}, "{}");'.format(node, id_, name))
        return id_

    @staticmethod
    def getSelectAttrF(mesh=None, bsNode=None, attrs=None):
        """複製出 shape"""
        if mesh is None:
            selects = cmds.ls(sl=True)
            if len(selects) != 2:
                return
            doMesh = selects[1]
        else:
            doMesh = mesh
        doBsNode = bsNode if bsNode else thFindBlendShapeNodeF([doMesh])[0]
        doAttrs = attrs if attrs else thGetMainChannelBoxF()
        # 斷開屬性連接
        dc = ThDisconnectConnect('ThDisconnectConnectData_getSelectAttrF')
        dc.switchF([doBsNode])
        # 關閉所有 attr
        for attr in doAttrs:
            cmds.setAttr('{}.{}'.format(doBsNode, attr), 0)
        # Copy
        newBsMeshList = []
        for i, attr in enumerate(doAttrs):
            if i:
                cmds.setAttr('{}.{}'.format(doBsNode, doAttrs[i - 1]), 0)
            cmds.setAttr('{}.{}'.format(doBsNode, attr), 1)
            # 複製模型
            copyMesh = cmds.duplicate(doMesh, rr=True, rc=True)[0]
            newBsMeshList.append(cmds.rename(copyMesh, attr))
        else:
            cmds.setAttr('{}.{}'.format(doBsNode, attr), 0)
        # 恢復連接
        dc.switchF()
        #
        cmds.select(newBsMeshList, r=True)

    @staticmethod
    def replaceF(mesh, node, target, attr, mode='connect'):
        """替換造型"""
        if not cmds.attributeQuery(attr, node=node, exists=True):
            return
        id_ = int(__class__.findIdAttrF(node, attr)[7:-1])
        shape = cmds.listRelatives(target, f=True, s=True)[0]
        if mode == 'connect':
            cmds.connectAttr(
                f'{shape}.worldMesh[0]',
                f'{node}.inputTarget[0].inputTargetGroup[{id_}].inputTargetItem[6000].inputGeomTarget')
        else:
            cmds.blendShape(node, e=True, t=[mesh, id_, target, 1])  # 屬姓名會被改變，暫時不使用

    @staticmethod
    def resetBlendShapeF(mesh, bsNode=None, deleteNode=True, newObj=None, attrList=None):
        """重建 BS"""
        # 獲取模型 BS 節點
        if bsNode:
            doBsNode = bsNode
        else:
            doBsNodeList = thFindBlendShapeNodeF([mesh])
            if doBsNodeList:
                doBsNode = doBsNodeList[0]
            else:
                return
        # 斷開屬性連接
        dc = ThDisconnectConnect('ThDisconnectConnectData_resetBlendShapeF')
        dc.switchF([doBsNode])
        # 解開 lock
        alm = ThAttrLockManager([doBsNode])
        # 關閉所有 attr
        doAttrList = attrList if attrList else cmds.listAttr(f'{doBsNode}.w', m=True)
        # 如果要傳給新物件，跳過值不為 0 的 shapes(因應 wrap 工具)
        if newObj:
            doAttrList = [x for x in doAttrList if round(cmds.getAttr(f'{doBsNode}.{x}'), 3) == 0]
        #
        for attr in doAttrList:
            cmds.setAttr(f'{doBsNode}.{attr}', 0)
        # 複製 shapes
        newBsMeshList = []
        for i, attr in enumerate(doAttrList):
            cmds.setAttr(f'{doBsNode}.{attr}', 1)
            newBsMeshList.append(cmds.duplicate(mesh, rr=True, rc=True)[0])  # 複製模型
            cmds.setAttr(f'{doBsNode}.{attr}', 0)
        # 是否刪除 BS node
        doNewObj = newObj if newObj else mesh
        if deleteNode:
            cmds.delete(doBsNode)
            newBsNode = cmds.blendShape(doNewObj, automatic=True, n=doBsNode)[0]  # 創建 BS 節點
            isCreateBsNode = True
        else:
            newBsNodeList = thFindBlendShapeNodeF(doNewObj)  # 找 BS 節點
            if not newBsNodeList:
                newBsNode = cmds.blendShape(doNewObj, automatic=True)[0]  # 創建 BS 節點
                isCreateBsNode = True
            else:
                newBsNode = newBsNodeList[0]
                isCreateBsNode = False
        #
        if isCreateBsNode:  # 是否是新創建的 BS
            # 添加 BS Atte
            __class__.addF(
                node=newBsNode, base=doNewObj, inpMeshList=newBsMeshList,
                nameList=doAttrList)
        else:
            for i, n in enumerate(doAttrList):
                if cmds.attributeQuery(n, node=newBsNode, exists=True):  # 如果屬性存在就替換 BS
                    __class__.replaceF(doNewObj, newBsNode, newBsMeshList[i], n)
                else:  # 否則添加
                    __class__.addF(
                        node=newBsNode, base=doNewObj, inpMeshList=[newBsMeshList[i]],
                        nameList=[n])
        # 恢復連接
        dc.switchF()
        # 恢復 lock
        alm.restoreLocksF()
        # 傳遞連接
        if doBsNode != newBsNode:
            dc.transferF(doBsNode, [newBsNode])
        cmds.delete(newBsMeshList)

    @staticmethod
    def reBsNameF(setObjList=None, isReSkin=True, isSelect=True):
        objList = setObjList if setObjList else cmds.ls(sl=True)
        if not objList:
            cmds.warning('please select object!')
            return
        for obj in objList:
            objBsList = thFindBlendShapeNodeF([obj])
            for bs in objBsList:
                name = cmds.rename(bs, f'{obj}_bs#')
        # 是否重命名 skin node
        if isReSkin:
            for obj in objList:
                objSkinList = thFindSkinNodeF([obj])
                for objSkin in objSkinList:
                    name = cmds.rename(objSkin, f'{obj}_skin#')
        #
        if isSelect:
            cmds.select(objList, r=True)


class ThEditBlendShapeWrap:
    def __init__(
        self,
        oldObj=None, newObjList=None, oldObjBs=None, attrList=None, mode='wrap',
        isCorrectionBaseShape=True):
        """匹配目標並連接屬性"""
        self.oldObj = oldObj
        self.newObjList = newObjList
        self.oldObjBs = oldObjBs
        self.attrList = attrList
        self.mode = mode
        self.isCorrectionBaseShape = isCorrectionBaseShape  # 統一 oldObj shape

    def proximityWrapF(self):
        """創建 wrap 形狀修正"""
        if not self.oldObj or not self.newObjList or not self.oldObjBs:
            return
        gsd = ThGrpSaveData('ThEditBlendShape_wrapF', defData={})
        data = gsd.getF()
        data['oldObj'] = self.oldObj
        data['oldObjBs'] = self.oldObjBs
        data['newObjList'] = self.newObjList
        data['attrList'] = self.attrList
        if 'isAppProximityWrap' in data or 'isAppCreateControl' in data:
            return
        # 複製 oldObjBs
        copyOldObj = cmds.duplicate(self.oldObj, rr=True, rc=True)[0]
        cmds.parent(copyOldObj, 'ThEditBlendShape_wrapF')
        data['copyOldObj'] = copyOldObj
        # 複製 newObjList
        copyNewObjList = [cmds.duplicate(x, rr=True, rc=True)[0] for x in data['newObjList']]
        cmds.parent(copyNewObjList, 'ThEditBlendShape_wrapF')
        data['copyNewObjList'] = copyNewObjList
        # 保存
        data['isAppProximityWrap'] = True
        gsd.setF(data)
        thSetShapeAttrF(data['newObjList'] + [data['oldObj']], 'visibility', 0)  # 影藏

    def createControlF(self):
        """創建控制"""
        # 讀取 data
        gsd = ThGrpSaveData('ThEditBlendShape_wrapF', defData={})
        data = gsd.getF()
        # 如果執行過 wrap 就停止
        if 'isAppCreateControl' in data:
            return
        # 如果沒有創建 wrap 形狀修正
        if not 'isAppProximityWrap' in data:
            # 如果沒有輸入參數
            if not self.oldObj or not self.newObjList or not self.oldObjBs:
                return
            #
            data['oldObj'] = self.oldObj
            data['oldObjBs'] = self.oldObjBs
            data['newObjList'] = self.newObjList
            data['attrList'] = self.attrList
        #
        ThEditBlendShape.offEditF([data['oldObjBs']])  # 關閉 BS 編輯狀態
        # 複製 newObjList
        if not 'isAppProximityWrap' in data:
            copyNewObjList = ThEditBlendShape.baseShapeF(data['newObjList'])
            data['copyNewObjList'] = copyNewObjList
            cmds.parent(copyNewObjList, 'ThEditBlendShape_wrapF')
        # wrap 方法
        if self.mode == 'wrap':
            cmds.select(data['copyNewObjList'] + [data['oldObj']], r=True)
            mel.eval('doWrapArgList "7" {"1","0","1","2","0","1","0"}')
        elif self.mode == 'proximityWrap':
            # 統一 oldObj shape
            if self.isCorrectionBaseShape:
                ThSetMeshPoint().applyF(inMesh=data['oldObj'], isCorrectionBaseShape=self.isCorrectionBaseShape)
            #
            if 'isAppProximityWrap' in data:
                vtxData = ThSetMeshPoint().getCoordinateF(data['copyOldObj'])  # 保存造型
                thSetShapeAttrF(data['oldObj'], 'visibility', 1)  # 顯示
                ThEditBlendShape.createBlendShapeF([data['oldObj'], data['copyOldObj']])  # 創建 BS
                thSetShapeAttrF(data['oldObj'], 'visibility', 0)  # 影藏
                ThSetMeshPoint().setCoordinateF(data['copyOldObj'], vtxData)  # 恢復造型
                thCreateProximityWrapF([data['copyOldObj']], data['copyNewObjList'])  # wrap
            else:
                thCreateProximityWrapF([data['oldObj']], data['copyNewObjList'])  # wrap
        elif self.mode == 'blendShape':
            for i, n in enumerate(data['copyNewObjList']):
                # 創建 BS
                bsNode = cmds.blendShape([data['oldObj'], n], automatic=True)[0]
                cmds.setAttr(f'{bsNode}.w[0]', 1)
                #
                ThEditBlendShape.addShapeF([bsNode], 1, 0, n)  # 創建一個新的並開啟編輯狀態
                ThSetMeshPoint().applyF(data['newObjList'][i], n)  # 頂點數值傳遞
            ThEditBlendShape.offEditF()  # 關閉編輯狀態
        # 保存
        data['isAppCreateControl'] = True
        gsd.setF(data)
        thSetShapeAttrF(data['newObjList'], 'visibility', 0)  # 影藏

    def cancelF(self):
        """撤銷"""
        if not cmds.objExists('ThEditBlendShape_wrapF'):
            return
        data = ThGrpSaveData('ThEditBlendShape_wrapF').getF()
        cmds.delete('ThEditBlendShape_wrapF')  # 刪除
        if data:
            thSetShapeAttrF(data['newObjList'] + [data['oldObj']], 'visibility', 1)  # 顯示

    def bakeBsF(self):
        """烘焙"""
        # 讀取檔案
        if not cmds.objExists('ThEditBlendShape_wrapF'):
            return
        #
        data = ThGrpSaveData('ThEditBlendShape_wrapF').getF()
        # 如果還沒建立 wrap 就停止執行
        if not 'isAppCreateControl' in data:
            return
        thSetShapeAttrF(data['newObjList'] + [data['oldObj']], 'visibility', 1)  # 顯示
        # 重建 BS
        for i, n in enumerate(data['copyNewObjList']):
            if 'isAppProximityWrap' in data:
                vtxData = ThSetMeshPoint().getCoordinateF(data['newObjList'][i])  # 保存造型
                ThSetMeshPoint().applyF(n, data['newObjList'][i])  # 改變造型
            # 重建 BS
            ThEditBlendShape.resetBlendShapeF(
                mesh=n, bsNode=data['oldObjBs'], deleteNode=False,
                newObj=data['newObjList'][i], attrList=data['attrList'])
            # 恢復造型
            if 'isAppProximityWrap' in data:
                ThSetMeshPoint().setCoordinateF(data['newObjList'][i], vtxData)
        cmds.delete('ThEditBlendShape_wrapF')  # 刪除


class ThMirrorScaleData:
    _allAttrList = ["tx", "ty", "tz", "rx", "ry", "rz", "sx", "sy", "sz"]

    def __init__(
        self,
        list1=None,
        list2=None,
        axial="x",
        setAttrList=("tx", "ty", "tz", "rx", "ry", "rz"),
        transferData=True,
        systemName="ThMirrorData__data",
    ):
        """鏡橡數值"""
        self.list1 = list1 or []
        self.list2 = list2 or []
        self.axial = axial
        self.setAttrList = setAttrList
        self.transferData = transferData
        self.systemName = systemName
        #
        self.data = {}
        self.getLocList = {False: [], True: []}
        self.setLocList = {False: [], True: []}
        self.commonList = []
        #
        if cmds.objExists(self.systemName):
            self.data = ThGrpSaveData(self.systemName).getF()
            self._syncFromDataF()
        else:
            if self.list1 and self.list2:
                self.commonList = list(set(self.list2) & set(self.list1))  # 篩選相同物件
                sd = ThGrpSaveData(self.systemName)  # 創建群組
                self._syncToDataF()
                self._createLocF(False)  # 創建定位器
                self._createLocF(True)  # 創建定位器
                sd.setF(self.data)  # 存檔

    def _syncFromDataF(self):
        """將 self.data 的內容同步回 instance 屬性"""
        self.list1 = self.data["list1"]
        self.list2 = self.data["list2"]
        self.axial = self.data["axial"]
        self.setAttrList = self.data["setAttrList"]
        self.transferData = self.data["transferData"]
        self.getLocList = self.data["getLocList"]
        self.setLocList = self.data["setLocList"]
        self.commonList = self.data["commonList"]

    def _syncToDataF(self):
        """將 instance 屬性同步回 self.data"""
        self.data["list1"] = self.list1
        self.data["list2"] = self.list2
        self.data["axial"] = self.axial
        self.data["setAttrList"] = self.setAttrList
        self.data["transferData"] = self.transferData
        self.data["getLocList"] = self.getLocList
        self.data["setLocList"] = self.setLocList
        self.data["commonList"] = self.commonList

    def mirrorF(self, isSwitch=False):
        """執行 mirror"""
        if not self.data:
            return
        # 讀取屬性值
        data = self._getDataF(False)
        if isSwitch:
            data.update(self._getDataF(True))
        # 設置屬性值
        for k, v in data.items():
            try:
                cmds.setAttr(k, v)
            except:
                pass
        # 是否傳遞自訂屬性數據
        if self.transferData:
            self._transferF()

    def _getDataF(self, isSwitch):
        data = {}
        doList = self.list1 if isSwitch else self.list2
        for obj, loc in zip(doList, self.setLocList[isSwitch]):
            if isSwitch and obj in self.commonList:
                continue
            #
            for attr in self.setAttrList:
                data[f"{obj}.{attr}"] = cmds.getAttr(f"{loc}.{attr}")
        return data

    def _setAttrF(self):
        """設置屬性"""
        for obj, loc in zip(self.list2, self.setLocList):
            for attr in self.setAttrList:
                data = cmds.getAttr(f"{loc}.{attr}")
                try:
                    cmds.setAttr(f"{obj}.{attr}", data)
                except:
                    pass

    def _createLocF(self, isSwitch=False):
        """創建左右定位器並建立鏡像連結"""
        if isSwitch:
            list1 = self.list2
            list2 = self.list1
        else:
            list1 = self.list1
            list2 = self.list2
        # 逐一建立每個物件的鏡像定位器與對應關係
        for getObj, setObj in zip(list1, list2):
            # --- 處理參考側 (Reference) 定位器 ---
            getLoc = cmds.duplicate(getObj, n="thMirror_refLoc#", to=True, po=True)[0]
            getLocGrp1 = cmds.group(getLoc, n="thMirror_refLoc_grp#")
            getLocGrp2 = cmds.group(n="thMirror_refLoc_grp#", em=True)
            cmds.parent(getLocGrp1, getLocGrp2)
            cmds.parent(getLocGrp2, self.systemName)
            self.getLocList[isSwitch].append(getLoc)
            # --- 處理目標側 (Object) 定位器 ---
            setLoc = cmds.duplicate(setObj, n="thMirror_obj#", to=True, po=True)[0]
            setLocGrp1 = cmds.group(setLoc, n="thMirror_obj_grp#")
            cmds.parent(setLocGrp1, self.systemName)
            self.setLocList[isSwitch].append(setLoc)
            #
            self._unLockAttrF()
            # --- 執行鏡像翻轉 ---
            if getObj in self.commonList:
                cmds.setAttr(f'{getLocGrp2}.s{self.axial}', 1 if isSwitch else -1)
            else:
                cmds.setAttr(f'{getLocGrp2}.s{self.axial}', -1)
            # --- 建立約束與屬性連接 ---
            # 讓目標側的定位器 (objLoc) 追隨參考側定位器 (refLoc) 的位移與旋轉
            cmds.pointConstraint([getLoc, setLoc], mo=True, w=1)
            cmds.parentConstraint([getLoc, setLoc], mo=True, w=1, st=["x", "y", "z"])
            # 將參考物件的縮放直接連給目標定位器
            cmds.connectAttr(f"{getObj}.s", f"{setLoc}.s")
            # 將參考物件的位移與旋轉直接連給參考定位器 (作為驅動鏡像系統的輸入來源)
            cmds.connectAttr(f"{getObj}.t", f"{getLoc}.t")
            cmds.connectAttr(f"{getObj}.r", f"{getLoc}.r")

    def _unLockAttrF(self):
        allLocList = self.getLocList[False] + self.getLocList[True] + self.setLocList[False] + self.setLocList[True]
        for loc in allLocList:
            for attr in self._allAttrList:
                cmds.setAttr(f'{loc}.{attr}', lock=False, keyable=True, channelBox=True)

    @staticmethod
    def deleteSystemF(systemName="ThMirrorData__data"):
        if cmds.objExists(systemName):
            cmds.delete(systemName)

    def _transferF(self):
        """傳遞自訂屬性的數據"""
        for getObj, setObj in zip(self.list1, self.list2):
            # 讀取自訂屬性
            attrs = cmds.listAttr(getObj, ud=True)
            #
            if not attrs:
                continue
            #
            for attr in attrs:
                try:
                    cmds.setAttr(f"{setObj}.{attr}", cmds.getAttr(f"{getObj}.{attr}"))
                except:
                    pass

    @staticmethod
    def directSwapAttrF(
        leftList,
        rightList,
        attrList=("tx", "ty", "tz", "rx", "ry", "rz"),
        transferData=True,
    ):
        """直接交換兩組控制器的屬性數值（不使用定位器）。
        先將兩邊數值全部讀取完畢後，再統一交換寫入，
        避免先寫入一邊後影響另一邊的讀取結果。

        :param leftList:      list  左側物件名稱列表
        :param rightList:     list  右側物件名稱列表（順序須與 leftList 對應）
        :param attrList:      tuple/list  要交換的屬性列表
        :param transferData:  bool  是否同時交換 user-defined 自訂屬性
        """
        # ── Step 1：先讀取兩邊所有數值 ──────────────────────────────────
        leftData = {}
        rightData = {}
        for leftObj, rightObj in zip(leftList, rightList):
            leftData[leftObj] = {}
            rightData[rightObj] = {}
            for attr in attrList:
                try:
                    leftData[leftObj][attr] = cmds.getAttr(f"{leftObj}.{attr}")
                except:
                    leftData[leftObj][attr] = None
                try:
                    rightData[rightObj][attr] = cmds.getAttr(f"{rightObj}.{attr}")
                except:
                    rightData[rightObj][attr] = None
        # ── Step 2：統一交換寫入 ────────────────────────────────────────
        for leftObj, rightObj in zip(leftList, rightList):
            for attr in attrList:
                if rightData[rightObj][attr] is not None:
                    try:
                        cmds.setAttr(f"{leftObj}.{attr}", rightData[rightObj][attr])
                    except:
                        pass
                if leftData[leftObj][attr] is not None:
                    try:
                        cmds.setAttr(f"{rightObj}.{attr}", leftData[leftObj][attr])
                    except:
                        pass
        # ── Step 3：交換 user-defined 自訂屬性 ─────────────────────────
        if transferData:
            for leftObj, rightObj in zip(leftList, rightList):
                leftUdAttrs = cmds.listAttr(leftObj, ud=True) or []
                rightUdAttrs = cmds.listAttr(rightObj, ud=True) or []
                # 收集
                leftUdData = {}
                rightUdData = {}
                for attr in leftUdAttrs:
                    try:
                        leftUdData[attr] = cmds.getAttr(f"{leftObj}.{attr}")
                    except:
                        pass
                for attr in rightUdAttrs:
                    try:
                        rightUdData[attr] = cmds.getAttr(f"{rightObj}.{attr}")
                    except:
                        pass
                # 寫入
                for attr, value in rightUdData.items():
                    try:
                        cmds.setAttr(f"{leftObj}.{attr}", value)
                    except:
                        pass
                for attr, value in leftUdData.items():
                    try:
                        cmds.setAttr(f"{rightObj}.{attr}", value)
                    except:
                        pass


class ThBatchReference:
    """批量 reference"""

    def __init__(self):
        path = cmds.file(q=True, sn=True) or 'D:/'
        fileList = cmds.fileDialog2(startingDirectory=path, fm=4, okc='Select File List')
        if not fileList:
            return
        for file in fileList:
            refName = os.path.splitext(os.path.split(file)[1])[0]
            cmds.file(file, r=True, iv=True, gl=True, mnc=False, ns=refName)


class ThSplitMeshPlane:
    """拆分模型平面"""

    def __init__(self, defMesh, quantity=4):
        self.defMesh = defMesh
        self.quantity = quantity

    def createPlaneF(self):
        # 創建 grp
        self.mainGrp = cmds.group(em=True, n='splitMeshToBs_grp#')
        self.mainJointGrp = cmds.group(em=True, n='splitMeshToBsJoint_grp#')
        cmds.parent(self.mainJointGrp, self.mainGrp)
        # 創建 plane
        sy = {2: 1, 4: 3, 6: 5}[self.quantity]
        self.plane = cmds.polyPlane(
            w=1, h=1, sx=3, sy=sy, ax=[0, 0, 1], cuv=2, ch=0, n='splitMeshToBs_plane#')
        cmds.parent(self.plane[0], self.mainGrp)
        # 創建 lattice
        lattice = cmds.lattice(
            self.plane[0], divisions=[2, 2, 2], objectCentered=True, ldv=[2, 2, 2],
            n='splitMeshToBs_lattice#')
        cmds.parent([lattice[1], lattice[2]], self.mainGrp)
        cmds.hide(lattice)
        # 設置大小
        self.size = cmds.xform(self.defMesh, q=True, bb=True)  # xmin ymin zmin xmax ymax zmax
        cmds.move(self.size[0], [f'{lattice[1]}.pt[0][0:1][0]', f'{lattice[1]}.pt[0][0:1][1]'], x=True)
        cmds.move(self.size[3], [f'{lattice[1]}.pt[1][0:1][0]', f'{lattice[1]}.pt[1][0:1][1]'], x=True)
        cmds.move(self.size[1], [f'{lattice[1]}.pt[0:1][0][0]', f'{lattice[1]}.pt[0:1][0][1]'], y=True)
        cmds.move(self.size[4], [f'{lattice[1]}.pt[0:1][1][0]', f'{lattice[1]}.pt[0:1][1][1]'], y=True)
        # cluster/ skin
        self.clusterList = []
        self.jointList = []
        if self.quantity == 2:
            cluster = cmds.cluster(
                [f'{self.plane[0]}.vtx[1:2]', f'{self.plane[0]}.vtx[5:6]'],
                rel=True, n='splitMeshToBs_row_cluster#')
            self.clusterList = [cluster[1]]
            #
            jointL = cmds.rename(thSelCreateJointF(f'{self.plane[0]}.f[2]'), 'splitMeshToBs_L_joint#')
            self.jointList.append(jointL)
            jointR = cmds.rename(thSelCreateJointF(f'{self.plane[0]}.f[0]'), 'splitMeshToBs_R_joint#')
            self.jointList.append(jointR)
            cmds.skinCluster(self.jointList, self.plane[0], mi=1, dr=4.0, tsb=True)
            cwa = ThCopyWeightApi()
            cwa.getWeightDataF(self.plane[0])
            cwa.editWeightDataF(idList=[2, 3, 6, 7], idListData=[1] * 4, joint=jointL)
            cwa.editWeightDataF(idList=[0, 1, 4, 5], idListData=[1] * 4, joint=jointR)
            cwa.setWeightDataF()
        #
        elif self.quantity == 4:
            cluster = cmds.cluster(
                [
                    f'{self.plane[0]}.vtx[1:2]', f'{self.plane[0]}.vtx[5:6]',
                    f'{self.plane[0]}.vtx[9:10]', f'{self.plane[0]}.vtx[13:14]'],
                rel=True, n='splitMeshToBs_row_cluster#')
            cluster2 = cmds.cluster([f'{self.plane[0]}.vtx[4:11]'], rel=True, n='splitMeshToBs_column_cluster#')
            self.clusterList = [cluster[1], cluster2[1]]
            #
            jointLUp = cmds.rename(thSelCreateJointF(f'{self.plane[0]}.f[8]'), 'splitMeshToBs_LUp_joint#')
            self.jointList.append(jointLUp)
            jointRUp = cmds.rename(thSelCreateJointF(f'{self.plane[0]}.f[6]'), 'splitMeshToBs_RUp_joint#')
            self.jointList.append(jointRUp)
            jointLDn = cmds.rename(thSelCreateJointF(f'{self.plane[0]}.f[2]'), 'splitMeshToBs_LDn_joint#')
            self.jointList.append(jointLDn)
            jointRDn = cmds.rename(thSelCreateJointF(f'{self.plane[0]}.f[0]'), 'splitMeshToBs_RDn_joint#')
            self.jointList.append(jointRDn)
            cmds.skinCluster(self.jointList, self.plane[0], mi=1, dr=4.0, tsb=True)
            cwa = ThCopyWeightApi()
            cwa.getWeightDataF(self.plane[0])
            cwa.editWeightDataF(idList=[10, 11, 14, 15], idListData=[1] * 4, joint=jointLUp)
            cwa.editWeightDataF(idList=[8, 9, 12, 13], idListData=[1] * 4, joint=jointRUp)
            cwa.editWeightDataF(idList=[2, 3, 6, 7], idListData=[1] * 4, joint=jointLDn)
            cwa.editWeightDataF(idList=[0, 1, 4, 5], idListData=[1] * 4, joint=jointRDn)
            cwa.setWeightDataF()
        #
        elif self.quantity == 6:
            cluster = cmds.cluster(
                [
                    f'{self.plane[0]}.vtx[1:2]', f'{self.plane[0]}.vtx[5:6]',
                    f'{self.plane[0]}.vtx[9:10]', f'{self.plane[0]}.vtx[13:14]',
                    f'{self.plane[0]}.vtx[17:18]', f'{self.plane[0]}.vtx[21:22]'],
                rel=True,
                n='splitMeshToBs_row_cluster#')
            cluster2 = cmds.cluster([f'{self.plane[0]}.vtx[12:19]'], rel=True, n='splitMeshToBs_row_cluster#')
            cluster3 = cmds.cluster([f'{self.plane[0]}.vtx[4:11]'], rel=True, n='splitMeshToBs_row_cluster#')
            self.clusterList = [cluster[1], cluster2[1], cluster3[1]]
            #
            jointLUp = cmds.rename(thSelCreateJointF(f'{self.plane[0]}.f[14]'), 'splitMeshToBs_LUp_joint#')
            self.jointList.append(jointLUp)
            jointRUp = cmds.rename(thSelCreateJointF(f'{self.plane[0]}.f[12]'), 'splitMeshToBs_RUp_joint#')
            self.jointList.append(jointRUp)
            jointLDn = cmds.rename(thSelCreateJointF(f'{self.plane[0]}.f[8]'), 'splitMeshToBs_LDn_joint#')
            self.jointList.append(jointLDn)
            jointRDn = cmds.rename(thSelCreateJointF(f'{self.plane[0]}.f[6]'), 'splitMeshToBs_RDn_joint#')
            self.jointList.append(jointRDn)
            jointLDn1 = cmds.rename(thSelCreateJointF(f'{self.plane[0]}.f[2]'), 'splitMeshToBs_LDn_joint#')
            self.jointList.append(jointLDn1)
            jointRDn1 = cmds.rename(thSelCreateJointF(f'{self.plane[0]}.f[0]'), 'splitMeshToBs_RDn_joint#')
            self.jointList.append(jointRDn1)
            cmds.skinCluster(self.jointList, self.plane[0], mi=1, dr=4.0, tsb=True)
            cwa = ThCopyWeightApi()
            cwa.getWeightDataF(self.plane[0])
            cwa.editWeightDataF(idList=[18, 19, 22, 23], idListData=[1] * 4, joint=jointLUp)
            cwa.editWeightDataF(idList=[16, 17, 20, 21], idListData=[1] * 4, joint=jointRUp)
            cwa.editWeightDataF(idList=[10, 11, 14, 15], idListData=[1] * 4, joint=jointLDn)
            cwa.editWeightDataF(idList=[8, 9, 12, 13], idListData=[1] * 4, joint=jointRDn)
            cwa.editWeightDataF(idList=[2, 3, 6, 7], idListData=[1] * 4, joint=jointLDn1)
            cwa.editWeightDataF(idList=[0, 1, 4, 5], idListData=[1] * 4, joint=jointRDn1)
            cwa.setWeightDataF()
        cmds.xform(self.plane[0], cp=True)
        thEditPivotF([self.mainJointGrp], self.plane[0])
        cmds.parent(self.clusterList, self.mainGrp)
        cmds.parent(self.jointList, self.mainJointGrp)
        cmds.hide(self.clusterList)
        cmds.hide(self.jointList)
        # 創建主要控制器
        ctrlSize = ((self.size[3] - self.size[0]) + (self.size[5] - self.size[2])) / 2
        self.cto = ThCtrlToObject(
            objList=[self.mainJointGrp], name='splitMeshToBs', ctrlStyle='cube',
            ctrlMethod='parent', grpLayout=1, ctrlColor=13, ctrlSize=ctrlSize)
        self.cto.createF()
        cmds.parent(self.cto.mainGrp, self.mainGrp)
        # 縮放控制器
        if self.quantity == 2:
            self._ctrlF([6, 2, 1, 5], 'row', ctrlSize / 2, self.clusterList[0])
        elif self.quantity == 4:
            self._ctrlF([14, 2, 1, 13], 'row', ctrlSize / 2, self.clusterList[0])
            self._ctrlF([11, 7, 4, 8], 'column', ctrlSize / 2, self.clusterList[1])
        elif self.quantity == 6:
            self._ctrlF([1, 2, 22, 21], 'row', ctrlSize / 2, self.clusterList[0])
            self._ctrlF([16, 19, 15, 12], 'column1', ctrlSize / 2, self.clusterList[1])
            self._ctrlF([11, 7, 4, 8], 'column2', ctrlSize / 2, self.clusterList[2])
        cmds.select(self.cto.newCtrlList[0], r=True)

    def _ctrlF(self, idList, label, size, cluster):
        """縮放控制器"""
        xyzList = []
        for point in ['{}.vtx[{}]'.format(self.plane[0], n) for n in idList]:
            xyzList.append(cmds.xform(point, q=True, ws=True, t=True))
        xyzList.append(xyzList[0])
        xyzList = [[n[0], n[1], size] for n in xyzList]
        scaleRowCtrl = cmds.curve(d=1, p=xyzList, n='splitMeshToBs_{}_ctrl#'.format(label))
        thSetCtrlColorF(scaleRowCtrl, 22)
        scaleRowCtrlGrp = cmds.group(scaleRowCtrl, n=f'{scaleRowCtrl}_grp#')
        cmds.parent(scaleRowCtrlGrp, self.cto.newCtrlList[0])
        cmds.xform(scaleRowCtrl, cp=True)
        for attr in ['t', 'r', 's']:
            cmds.connectAttr(f'{scaleRowCtrl}.{attr}', f'{cluster}.{attr}')


class ThShootAttrAnim:
    """動作錄製"""

    def __init__(self):
        self.ifApp = False

    def createCvF(self, degree=2):
        """創建 curve"""
        cv = cmds.curve(d=degree, p=self.data)

    def keyF(self, startFrame=1):
        """key"""
        for i, dataList in enumerate(self.data, 0):
            for ii, data in enumerate(dataList):
                cmds.setKeyframe(self.obj, time=i + startFrame, at=self.attr[ii], value=float(data))

    def endF(self, ifClearData=True):
        """結束"""
        self.ifClearData = ifClearData
        self.ifApp = False
        # clear
        if self.ifClearData:
            self.data = self._reDataF(self.data)

    def startF(self, obj, attr=('tx', 'ty', 'tz'), fps=24):
        """開始"""
        self.obj = obj
        self.attr = attr
        self.fps = fps
        #
        self.data = []
        self.ifApp = True
        #
        th = threading.Thread(target=self._saveF)
        th.start()

    def _saveF(self):
        """紀錄動作"""
        sleep = 1.0 / self.fps
        while self.ifApp:
            time.sleep(sleep)
            data = []
            for n in self.attr:
                data.append(cmds.getAttr('{}.{}'.format(self.obj, n)))
            self.data.append(data)

    def _reDataF(self, data):
        """清理起始與結束多餘數據"""
        start = None
        end = None
        for i, n in enumerate(data):
            if n != data[0]:
                start = i
                break
        for i, n in enumerate(data[::-1]):
            if n != data[-1]:
                end = i
                break
        newData = [data[0]] + data[start:(end * -1)] + [data[-1]]
        return newData


class ThCoordinateCreateMeshLocal:
    """依照物件本地軸向，創建偏移 polygon mesh"""

    def __init__(self, objList, offset=0.1, axis='z', maxInfluences=5, loop=True):
        self.objList = objList
        self.offset = offset
        self.axis = axis.lower()
        self.maxInfluences = maxInfluences
        self.loop = loop
        self.newMesh = None
        # 連接首尾
        self.fullList = self.objList + [self.objList[0]] if self.loop else self.objList
        # 軸向對應字典
        axisIndexDict = {'x': 0, 'y': 1, 'z': 2}
        axisIdx = axisIndexDict.get(self.axis, 2)
        #
        newMeshList = []
        for i in range(len(self.fullList) - 1):
            objA = self.fullList[i]
            objB = self.fullList[i + 1]
            # 取 joint 的世界座標位置
            posA = om2.MVector(*cmds.xform(objA, q=True, ws=True, rp=True))
            posB = om2.MVector(*cmds.xform(objB, q=True, ws=True, rp=True))
            # 計算每個 joint 的 local offset 向量（從其 worldMatrix 中取得方向軸向）
            worldMatrixA = cmds.xform(objA, q=True, ws=True, m=True)
            worldMatrixB = cmds.xform(objB, q=True, ws=True, m=True)
            # 每個 transform 的 local 軸方向
            vecA = om2.MVector(
                worldMatrixA[axisIdx * 4], worldMatrixA[axisIdx * 4 + 1],
                worldMatrixA[axisIdx * 4 + 2]).normalize() * self.offset
            vecB = om2.MVector(
                worldMatrixB[axisIdx * 4], worldMatrixB[axisIdx * 4 + 1],
                worldMatrixB[axisIdx * 4 + 2]).normalize() * self.offset
            # 計算 4 個點：正偏移線段 + 負偏移線段
            p1 = posA + vecA
            p2 = posB + vecB
            p3 = posB - vecB
            p4 = posA - vecA
            #
            coordList = [p1, p2, p3, p4]
            coordList = [(p.x, p.y, p.z) for p in coordList]
            poly = cmds.polyCreateFacet(tx=1, s=1, ch=False, p=coordList)[0]
            newMeshList.append(poly)
        # 合併所有 poly
        if len(newMeshList) == 1:
            self.newMesh = newMeshList[0]
        else:
            self.newMesh = cmds.polyUnite(newMeshList, ch=False, mergeUVSets=True, centerPivot=True)[0]
            cmds.polyMergeVertex(self.newMesh, d=0.0001, am=True, ch=False)
        # skin 綁定
        cmds.skinCluster(self.objList, self.newMesh, mi=self.maxInfluences, dr=4.0, tsb=True)
        cmds.select(self.newMesh, r=True)


class ThModifyJointQuantity:
    """調整骨骼鍊段數"""

    def __init__(self, jointList, quantity):
        self.jointList = jointList
        self.quantity = quantity
        # 若數量少於2，不進行處理
        if self.quantity < 2:
            return
        # 兩點鍊段處理
        if len(self.jointList) == 2:
            self.twoF()
        else:
            self.orderF()

    def orderF(self):
        startLength = len(self.jointList)
        # 依照骨骼產生曲線
        curve = thObjectCurveF(objs=self.jointList)
        # 重建曲線，增加細節
        cmds.rebuildCurve(
            curve, ch=False, rpo=True, rt=False, end=True,
            kr=False, kcp=False, kep=True, kt=False,
            s=len(self.jointList), d=3, tol=0.01
        )
        # 依曲線產生骨骼
        curveToJoint = ThCurveCreateJoint([curve], startLength)
        newJointList = curveToJoint.jointListAll
        # 將原本骨骼對齊到新骨骼位置
        endData = cmds.xform(self.jointList[-1], q=True, ws=True, m=True)
        for originalJoint, newJoint in zip(self.jointList[1:-1], newJointList[1:-1]):
            rotateValue = cmds.getAttr(f'{originalJoint}.rotate')[0]
            cmds.xform(originalJoint, ws=True, m=cmds.xform(newJoint, q=True, ws=True, m=True))
            cmds.setAttr(f'{originalJoint}.rotate', *rotateValue)
        cmds.xform(self.jointList[-1], ws=True, m=endData)
        # 刪除暫時產生的曲線與新骨骼
        cmds.delete(curve)
        cmds.delete(newJointList)
        # 選取原骨骼
        cmds.select(self.jointList, r=True)

    def twoF(self):
        # 解除尾端骨骼的父層關係
        cmds.parent(self.jointList[-1], w=True)
        # 取得頭骨骼以下所有 joint
        internalJointList = cmds.listRelatives(self.jointList[0], ad=True, type='joint') or []
        combinedJointList = [self.jointList[-1]] + internalJointList + [self.jointList[0]]
        startLength = len(combinedJointList)
        #
        if self.quantity == 2:
            # 若目標為2段，直接重新父子關係
            cmds.parent(self.jointList[-1], self.jointList[0])
        else:
            # 依照骨骼產生曲線
            curve = thObjectCurveF(objs=combinedJointList)
            # 重建曲線
            cmds.rebuildCurve(
                curve, ch=False, rpo=True, rt=False, end=True,
                kr=False, kcp=False, kep=True, kt=False,
                s=len(combinedJointList) * 10, d=1, tol=0.01
            )
            # 建立新骨骼
            curveToJoint = ThCurveCreateJoint([curve], self.quantity)
            newJointList = curveToJoint.jointListAll
            # 設定新骨骼的父子關係
            cmds.parent(newJointList[-2], self.jointList[0])
            cmds.parent(self.jointList[-1], newJointList[1])
            # 刪除多餘骨骼與曲線
            cmds.delete(curve)
            cmds.delete([newJointList[0], newJointList[-1]])
        # 刪除原有內部骨骼
        if internalJointList:
            cmds.delete(internalJointList)
        # 若數量一致，則重新命名骨骼
        if startLength == self.quantity:
            for originalJoint, newJoint in zip(internalJointList, newJointList[1:-1]):
                cmds.rename(newJoint, originalJoint)
        # 選取起始與結尾骨骼
        cmds.select([self.jointList[0], self.jointList[-1]], r=True)


class ThFrameToTime:
    def toTimeF(self, frame, fps=30):
        """影格換算時間"""
        # 餘
        key = frame % fps
        # 秒
        second = int(frame / fps)
        # 分
        minute = 0
        if second >= 60:
            minute = int(second / 60)
            second = second % 60
        # 時
        hour = 0
        if minute >= 60:
            hour = int(minute / 60)
            minute = minute % 60
        #
        result = '{}:{}:{}:{}\n'.format(hour, minute, second, key)
        sys.stdout.write(result)

    def toFrameF(self, Time, fps=30):
        """時間換算影格"""
        pass


class ThSetMeshPoint:
    appSpace = {'object': om2.MSpace.kObject, 'world': om2.MSpace.kWorld}
    inPointList = None
    inMesh = None

    def applyF(self, outMesh=None, inMesh=None, space='object', isCorrectionBaseShape=False):
        """頂點數值傳遞(如果未輸入 outMesh 可統一 inMesh shape)"""
        self.outMesh = outMesh if outMesh else inMesh
        self.inMesh = inMesh
        self.space = space
        # 讀取座標
        self.inPointList = self.getCoordinateF(self.inMesh, self.space)
        self.outPointList = self.getCoordinateF(self.outMesh, self.space)
        # 是否規格化
        if isCorrectionBaseShape:
            # 獲取 shape 列表
            inMeshShapeList = cmds.listRelatives(self.inMesh, f=True, s=True)
            # 設置座標
            for n in inMeshShapeList[::-1]:
                self.setCoordinateF(n, self.outPointList)
        else:
            # 設置座標
            self.setCoordinateF(self.inMesh, self.outPointList)
        # 保存數據
        __class__.inPointList = self.inPointList
        __class__.inMesh = self.inMesh

    @classmethod
    def getCoordinateF(cls, mesh, space='object'):
        """讀取座標"""
        meshList = om2.MSelectionList().add(mesh)
        meshDagPath = meshList.getDagPath(0)
        fnMesh = om2.MFnMesh(meshDagPath)
        cls.inPointList = fnMesh.getPoints(cls.appSpace[space])
        cls.inMesh = mesh
        return fnMesh.getPoints(cls.appSpace[space])

    def setCoordinateF(self, mesh=None, data=None):
        """設置座標"""
        doMesh = mesh if mesh else self.inMesh
        doData = data if data else self.inPointList
        meshList = om2.MSelectionList().add(doMesh)
        meshDagPath = meshList.getDagPath(0)
        fnMesh = om2.MFnMesh(meshDagPath)
        fnMesh.setPoints(doData)

    def resetCoordinateF(self):
        if self.inPointList:
            self.setCoordinateF(self.inMesh, self.inPointList)


class ThPrintSetMatrixData:

    def __init__(self):
        selectList = cmds.ls(sl=True)
        if not selectList:
            return
        #
