class ThVertexFollicle:
    """在選擇的 vertexList 上創建 follicle.
    :type vertexList: list
    """

    def __init__(self, vertexList=None, name='obj', rotateObj=None):
        self.vertexList = vertexList
        self.name = name
        self.rotateObj = rotateObj

    def applyF(self):
        follicleNew = []
        # 創建 group
        if not cmds.objExists('def'):
            cmds.group(em=True, n='def')
        if not cmds.objExists('follicle_grp'):
            cmds.group(em=True, n='follicle_grp')
            cmds.parent('follicle_grp', 'def')
        self.mainGrp = cmds.group(em=True, n=self.name + '_follicle_grp#')
        cmds.parent(self.mainGrp, 'follicle_grp')
        # 獲取 uv 座標
        uvPosList = thGetPolyUvPosF(self.vertexList)[1]
        # 模型名稱
        mesh = self.vertexList[0].split('.', 1)[0]
        meshShape = cmds.listRelatives(mesh, c=True, f=True, type='shape')[0]
        for uvPos in uvPosList:
            # 創建 follicle
            follicleShape = cmds.createNode('follicle')
            follicle = cmds.listRelatives(follicleShape, p=True)[0]
            # 屬性連接
            cmds.connectAttr(meshShape + '.outMesh', follicleShape + '.inputMesh', f=True)
            cmds.connectAttr(
                meshShape + '.worldMatrix', follicleShape + '.inputWorldMatrix', f=True)
            cmds.connectAttr(follicleShape + '.outTranslate', follicle + '.translate', f=True)
            if self.rotateObj:
                cmds.orientConstraint([self.rotateObj, follicle], mo=True, weight=1)
            else:
                cmds.connectAttr(follicleShape + '.outRotate', follicle + '.rotate', f=True)
            # 讀取並設置 uv 座標
            cmds.setAttr(follicleShape + '.parameterU', uvPos[0])
            cmds.setAttr(follicleShape + '.parameterV', uvPos[1])
            # parent
            cmds.parent(follicle, self.mainGrp)
            follicleNew.append(cmds.rename(follicle, self.name + '_follicle#'))
        cmds.select(follicleNew, r=True)
        return follicleNew


class ThCoordinateCreateMesh:
    """座標創建 mesh"""

    def __init__(self, list_):
        self.list_ = list_
        # 獲取座標列表
        coordinateList = []
        for n in list_:
            coordinateList.append(cmds.xform(n, q=True, ws=True, rp=True))
        self.newMesh = cmds.polyCreateFacet(tx=1, s=1, ch=False, p=coordinateList)[0]


class ThCreateChPoly:
    """依據骨骼鍊列表創建 mesh"""

    def __init__(self, list_, bake=False, skin=True, inf=5):
        if len(list_) <= 1:
            return
        self.list_ = list_ + [list_[0]] if bake else list_  # 是否成為循環
        newMeshList = []  # 新模型列表
        #
        for i in range(len(self.list_) - 1):
            # 回傳座標列表
            positionList1 = self._getPositionF(self.list_[i])
            positionList2 = self._getPositionF(self.list_[i + 1])
            # 獲取列表長度
            lenList1 = len(positionList1)
            lenList2 = len(positionList2)
            # 判斷最大長度
            maxLen = max([lenList1, lenList2])
            #
            for ii in range(maxLen - 1):
                # 獲取四個座標
                id1 = lenList1 - 1 if ii >= lenList1 else ii
                id2 = lenList2 - 1 if ii >= lenList2 else ii
                id3 = id2 if ii + 1 >= lenList2 else ii + 1
                id4 = id1 if ii + 1 >= lenList1 else ii + 1
                doPosition1 = positionList1[id1]
                doPosition2 = positionList2[id2]
                doPosition3 = positionList2[id3]
                doPosition4 = positionList1[id4]
                # 創建 poly
                newMeshList.append(
                    cmds.polyCreateFacet(
                        tx=1, s=1, ch=False,
                        p=[doPosition1, doPosition2, doPosition3, doPosition4])[0])
        # combine
        newMesh = cmds.polyUnite(newMeshList, ch=False, mergeUVSets=True, centerPivot=True)[0]
        cmds.polyMergeVertex(newMesh, d=0.01, am=True, ch=False)
        # skin
        if skin:
            skinJointList = cmds.listRelatives(list_, ad=True, type='joint')
            skinJointList.extend(list_)
            cmds.skinCluster(skinJointList, newMesh, mi=inf, dr=4.0, tsb=True)
        cmds.select(newMesh, r=True)

    def _getPositionF(self, obj):
        """回傳座標列表"""
        # 獲取層級
        objList = cmds.listRelatives(obj, ad=True, type='joint')
        objList.append(obj)
        # 獲取座標列表
        positionList = [cmds.xform(x, q=True, ws=True, rp=True) for x in objList][::-1]
        return positionList


class ThEditSkinWeightSmooth:
    def __init__(self, list_, quantity=1, jointList=None, value=1, ifRange=False):
        self.list_ = list_
        self.quantity = quantity
        self.jointList = jointList
        self.value = value
        self.ifRange = ifRange
        # 判斷是否 '.' in list_
        if '.' in self.list_[0]:
            mesh = self.list_[0].split('.')[0]
            # 轉換 vtx
            cmds.select(cmds.polyListComponentConversion(self.list_, tv=True), r=True)
            self.doApplyF(mesh)
        else:
            for mesh in self.list_:
                cmds.select(mesh, r=True)
                self.doApplyF(mesh)
        cmds.select(self.list_, r=True)

    def doApplyF(self, mesh):
        # 找 skin node
        nodeList = thFindSkinNodeF([mesh])
        if nodeList:
            # 設定 post 模式
            cmds.skinCluster(nodeList[0], e=True, fnw=True, normalizeWeights=2)
            # 啟動筆刷
            cmds.ArtPaintSkinWeightsToolOptions()
            # 切換到 smooth 模式
            mel.eval('artAttrPaintOperation artAttrSkinPaintCtx Smooth')
            # 設定數值
            mel.eval('artAttrSkinPaintCtx -e -opacity {} `currentCtx`'.format(self.value))
            # 循環骨骼
            jointList = self.jointList if self.jointList else thFindSkinJointF([mesh])
            for joint in jointList:
                mel.eval('setSmoothSkinInfluence {}'.format(joint))
                if self.ifRange:
                    cmds.skinCluster(nodeList[0], e=True, siv=joint)
                for i in range(self.quantity):
                    mel.eval('FloodSurfaces')


class ThJointAxialToWorld:
    """調整末端骨骼軸向到世界"""

    def __init__(self, jointList=None):
        if not jointList:
            jointList = cmds.ls(typ='joint')
        else:
            list_ = cmds.listRelatives(jointList, ad=True, f=True, type='joint') or []
            list_.extend(jointList)
            jointList = list_
        # 找根部 joint
        applyList = []
        for joint in jointList:
            # 判斷有無子物件
            child = cmds.listRelatives(joint, c=True)
            if not child:
                applyList.append(joint)
        # 設定軸向
        len_ = 0
        for joint in applyList:
            # 判斷是否連接 skin node
            ifConSkin = True
            conList = cmds.listConnections(joint) or []
            for n in conList:
                if cmds.nodeType(n) == 'skinCluster':
                    ifConSkin = False
                    break
            if ifConSkin:
                len_ += 1
                cmds.joint(joint, e=True, oj='none', ch=True, zso=True)
        sys.stdout.write('modify joint quantity: {}'.format(len_))


class ThTransformDisplay:
    """變換顯示工具"""

    def __init__(self, selectList, attr='axes', parent=False, type=None):
        applyAttrDict = {'axes': '.displayLocalAxis', 'handles': '.displayHandle'}
        #
        if parent:
            applyFunc = 'cmds.listRelatives(selectList, ad=True, f=True)'
            if type:
                applyFunc = 'cmds.listRelatives(selectList, ad=True, f=True, type=type)'
            parentList = eval(applyFunc) or []
            parentList.extend(selectList)
            selectList = parentList
        #
        applyValue = cmds.getAttr(selectList[0] + applyAttrDict[attr])
        applyValue = False if applyValue else True
        for n in selectList:
            cmds.setAttr(n + applyAttrDict[attr], applyValue)


class ThRenameExchange:
    """交換名稱"""

    def __init__(self, listA, listB):
        """
        將兩個物件清單的名稱交換，若 listB 中某元素為 None 則跳過該項
        :param listA: 第一組物件清單
        :param listB: 第二組物件清單（允許包含 None）
        """
        if len(listA) != len(listB):
            cmds.error("❌ 兩組物件數量不一致")

        tempNames = []

        # 步驟 1：listA 中物件先改暫名（若對應 B 為 None 則不處理）
        for i, (objA, objB) in enumerate(zip(listA, listB)):
            if objB is None:
                tempNames.append(None)
                continue
            tempName = f"__temp_swap_{i}__"
            newTemp = cmds.rename(objA, tempName)
            tempNames.append(newTemp)
        # 步驟 2：將 listB 改成原本 listA 的名稱（跳過 None）
        for objB, oldNameA in zip(listB, listA):
            if objB is None:
                continue
            cmds.rename(objB, oldNameA)
        # 步驟 3：將暫名改為 listB 的原名（跳過 None）
        for temp, oldNameB in zip(tempNames, listB):
            if temp is None or oldNameB is None:
                continue
            cmds.rename(temp, oldNameB)


class ThRenameClearLen:
    """清除長度"""

    def __init__(self, list_, dir):
        dirLen = '[dir:]' if dir > 0 else '[:dir]'
        for n in list_:
            newName = eval('"{}"{}'.format(n, dirLen))
            cmds.rename(n, newName)


class ThSkinSplitBlendShape:
    def __init__(self, mesh, blendNode, attrName=None):
        self.mesh = mesh
        self.blendNode = blendNode
        self.attrName = attrName
        #
        cwa = ThCopyWeightApi()
        cwa.getWeightDataF(mesh)
        self.data = cwa.data
        self.weightList = []
        self.layerLen = len(self.data[0])
        for i in range(self.layerLen):
            self.weightList.append(self.data[1][i::self.layerLen])

    def reWeightF(self):
        for i in range(len(self.weightList[0])):
            cmds.setAttr('{}.inputTarget[0].baseWeights[{}]'.format(self.blendNode, i), 1)

    def setWeightF(self, index):
        for i, weight in enumerate(self.weightList[index], 0):
            cmds.setAttr('{}.inputTarget[0].baseWeights[{}]'.format(self.blendNode, i), weight)

    def splitCopyF(self):
        newMeshList = []
        label = self.attrName if self.attrName else self.mesh
        for i in range(self.layerLen):
            self.setWeightF(i)
            newName = '{}_{}'.format(self.data[0][i], label)
            newName = cmds.duplicate(self.mesh, rr=True, n=newName)[0]
            for attr in ['tx', 'ty', 'tz', 'rx', 'ry', 'rz', 'sx', 'sy', 'sz']:
                cmds.setAttr('{}.{}'.format(newName, attr), lock=False, keyable=True)
            newMeshList.append(newName)
        cmds.select(newMeshList, r=True)
        return newMeshList


class ThSelectTypeObject:
    """選擇列別物件"""

    def __init__(self, objs=None, mode='scenes', type='mesh', transform=False):
        self.objs = objs
        self.mode = mode
        self.type = type
        self.transform = transform
        self.result = None
        #
        appDict = {
            'father': self.fatherF, 'select': self.selectF, 'scenes': self.scenesF,
            'history': self.historyF, 'connect': self.connectF}
        self.result = appDict[mode]()
        if not self.result:
            return
        if transform:
            if self.ifFatherF():
                self.result = list(set(cmds.listRelatives(self.result, ap=True, f=True)))

    def connectF(self):
        result = []
        for obj in self.objs:
            hisList = cmds.listConnections(obj)
            for his in hisList:
                if cmds.nodeType(his) == self.type:
                    result.append(his)
                    break
        return result

    def historyF(self):
        result = []
        for obj in self.objs:
            hisList = cmds.listHistory(obj)
            for his in hisList:
                if cmds.nodeType(his) == self.type:
                    result.append(his)
                    break
        return result

    def selectObjsF(self):
        cmds.select(self.result, r=True)

    def ifFatherF(self):
        father = cmds.listRelatives(self.result[0], ap=True, f=True)
        if father:
            child = cmds.listRelatives(father[0], s=True, f=True)
            if child:
                if cmds.nodeType(child[0]) == self.type:
                    return True
                else:
                    return False
            else:
                return False
        else:
            return False

    def scenesF(self):
        return cmds.ls(type=self.type)

    def fatherF(self):
        objList = []
        for obj in self.objs:
            if cmds.nodeType(obj) == self.type:
                objList.append(obj)
            list_ = cmds.listRelatives(obj, ad=True, typ=self.type, f=True)
            if list_:
                objList.extend(list_[::-1])
        return objList

    def selectF(self):
        typeList = thTypeF(self.objs)
        objList = []
        for i, obj in enumerate(self.objs):
            if typeList[i] == self.type:
                objList.append(obj)
        return objList


class ThCopyWeightApi:
    skinNode = None
    mesh = None
    data = None
    dataDict = None

    def copyNameWeightF(self, refMesh, mesh, doRound=10):
        """仿 copy weight name 模式.
        mesh 的 skin 必須包含 refMesh skin 有的 joint"""
        # 獲取權重
        self.getWeightDataF(refMesh)
        refData = copy.deepcopy(self.data)
        refDataDict = copy.deepcopy(self.dataDict)
        self.getWeightDataF(mesh)
        for n in self.data[0]:
            if not n in refData[0]:
                cmds.error(
                    ThLanguage.tr(
                        'mesh 的 skin 必須包含 "refMesh" skin 有的 joint!'))
                return -1
        # 獲取座標
        refVtxData = thGetVtxDataF(refMesh, doRound)
        vtxData = thGetVtxDataF(mesh, doRound)
        # 獲取相對ID
        vtxIdData = []
        try:
            for n in vtxData:
                vtxIdData.append(refVtxData.index(n))
        except:
            cmds.error(ThLanguage.tr('找不到對應的座標!'))
            return -1
        # 轉換權重
        reIdF = lambda x: [x[i] for i in vtxIdData]
        self.dataDict = {k: reIdF(refDataDict[k]) for k in list(self.dataDict.keys())}
        # 轉為列表
        self._toListF()
        # 權重值轉換0至1區間
        self.reWeightF()
        # 設定權重
        self.setWeightDataF(False)

    def clearMinF(self, meshList, value=.000001):
        """清理權重最小值"""
        for mesh in meshList:
            self.getWeightDataF(mesh)
            weightList = [0 if w < value else w for w in self.data[1]]
            self.data[1] = weightList
        # 重整權重
        self.reWeightF()
        self.setWeightDataF(False)

    def reWeightF(self, toLlist=False):
        """權重值轉換0至1區間"""
        # 轉為列表
        if toLlist:
            self._toListF()
        #
        weightList = ThConversionMatrix.reshapeListToColumnsF(self.data[1], len(self.data[0]))
        weightList = ThConversionMatrix.transposeMatrixF(weightList)
        newWeightList = []
        for n in weightList:
            newWeightList.append(thAverageDataF(n))
        self.data[1] = ThConversionMatrix.flattenListF(newWeightList)

    def copyWeightF(self, inMesh, outMesh):
        """複製權重"""
        skinNode = thFindSkinNodeF([outMesh])
        if skinNode:
            cmds.delete(skinNode)
        self.getWeightDataF(inMesh, False)
        self.setWeightDataF(False, outMesh)

    def findMinF(self, mesh):
        # 讀取權重
        self.getWeightDataF(mesh)
        sortedData = list(sorted(set(self.data[1])))
        return sortedData

    def editWeightDataF(
        self, idList, idListData, joint, otherJointList=None, findUnLockJoint=False):
        """
        需要 self.data 與 self.dataDict
        idList = 要更動的頂點
        idListData = 更動的數值
        joint = 更動的骨骼
        otherJointList = 其他設置骨骼
        findUnLockJoint = 篩選沒鎖定骨骼
        """
        if not self.data and not self.dataDict:
            return
        # 獲取其他設置骨骼
        if otherJointList is None:
            otherJointList = copy.copy(self.data[0])
            otherJointList.remove(joint)
            # 篩選沒鎖定骨骼
            if findUnLockJoint:
                otherJointList = [j for j in otherJointList if cmds.getAttr(j + '.liw') == 0]
        #
        if not otherJointList:
            return
        #
        for i in range(len(idList)):
            # 獲取權重值
            otherJointWeightList = []
            for j in otherJointList:
                otherJointWeightList.append(self.dataDict[j][idList[i]])
            jointWeight = self.dataDict[joint][idList[i]]
            # 判斷可操作最大值
            sum_ = sum(otherJointWeightList + [jointWeight])
            # 獲取其他設置值
            difference = 0 if idListData[i] > sum_ else sum_ - idListData[i]
            otherJointWeightList = thAverageDataF(otherJointWeightList, difference)
            # 設置主要權重
            mainWeight = sum_ if idListData[i] > sum_ else idListData[i]
            self.dataDict[joint][idList[i]] = mainWeight
            # 設定其他值
            for ii, j in enumerate(otherJointList):
                self.dataDict[j][idList[i]] = otherJointWeightList[ii]

    def setWeightDataF(self, toLlist=True, mesh=None):
        """使用 self.data 設置權重"""
        self.mesh = mesh if mesh else self.mesh
        # 轉為列表
        if toLlist:
            self._toListF()
        # bind
        skinNodeList = thFindSkinNodeF([self.mesh])
        if not skinNodeList:
            skinNodeList = cmds.skinCluster(self.data[0], self.mesh, mi=5, omi=5, dr=4.0, tsb=True)
        # 獲得變形
        meshList = om2.MSelectionList()
        meshList.add(self.mesh)
        meshPath = meshList.getDagPath(0)
        # 獲得皮膚簇
        skinList = om2.MSelectionList()
        skinList.add(skinNodeList[0])
        skinNode = skinList.getDependNode(0)
        skinFn = omAnim2.MFnSkinCluster(skinNode)
        # 得到頂點
        vertexComp = om2.MFnSingleIndexedComponent().create(om2.MFn.kMeshVertComponent)
        # 創建影響 IntArray 以使用 setWeights() 指定
        infDags = skinFn.influenceObjects()
        infIndexes = om2.MIntArray(range(len(infDags)))
        # 還原 MDoubleArray
        weightData = om2.MDoubleArray(self.data[1])
        # 設置權重
        skinFn.setWeights(meshPath, vertexComp, infIndexes, weightData)
        # 歸一化
        cmds.skinCluster(skinNodeList[0], e=True, fnw=True)

    def getWeightDataF(self, mesh, toDict=True):
        """讀取權重"""
        self.mesh = mesh
        skinNodeList = thFindSkinNodeF([mesh])
        if not skinNodeList:
            return  # 獲得變形
        self.skinNode = skinNodeList[0]
        meshList = om2.MSelectionList()
        meshList.add(mesh)
        meshPath = meshList.getDagPath(0)
        # 獲得皮膚簇
        skinList = om2.MSelectionList()
        skinList.add(self.skinNode)
        skinNode = skinList.getDependNode(0)
        skinFn = omAnim2.MFnSkinCluster(skinNode)
        # 得到影響的骨頭
        infDags = skinFn.influenceObjects()
        jointList = [n.partialPathName() for n in infDags]
        # 得到頂點
        vertexComp = om2.MFnSingleIndexedComponent().create(om2.MFn.kMeshVertComponent)
        # 獲取所有重量值
        weightData = skinFn.getWeights(meshPath, vertexComp)[0]
        # 轉為列表
        weightDataList = list(weightData)
        self.data = [jointList, weightDataList]
        # 轉為字典
        if toDict:
            self._toDictF()

    def exportWeightFileF(self, meshList):
        """輸出權重檔"""
        # 找路徑
        if not meshList:
            cmds.error('請先選擇模型)')
            return
        # 自動產生帶時間戳的預設檔名，格式: skinWeight_20260617-130047
        timeStamp = datetime.datetime.now().strftime('%Y%m%d-%H%M%S')
        defaultName = 'skinWeight_{}.json'.format(timeStamp)
        sceneFile = cmds.file(q=True, sn=True)
        startDir = os.path.dirname(sceneFile) if sceneFile else 'D:/'
        defaultPath = os.path.join(startDir, defaultName).replace('\\', '/')
        fileList = cmds.fileDialog2(
            startingDirectory=defaultPath,
            fileFilter='Maya skin weight (*.json);;All Files (*.*)', dialogStyle=2)
        if not fileList:
            return
        # 刪除多於 shape
        ThClearChShapeNode(meshList)
        # get weight
        dataDict = {}
        for i, m in enumerate(meshList):
            self.getWeightDataF(m, False)
            if self.data:
                dataDict[m] = self.data
        #
        with open(fileList[0], 'w') as f:
            json.dump(dataDict, f)

    def importWeightFileF(
        self,
        isModifyImportData=False,
        mdlStartAdd=None, mdlEndAdd=None, mdlInpReplace=None, mdlOutReplace=None,
        jointStartAdd=None, jointEndAdd=None, jointInpReplace=None, jointOutReplace=None):
        """輸入權重檔"""
        path = cmds.file(q=True, sn=True) or 'D:/'
        fileList = cmds.fileDialog2(
            startingDirectory=path, fileFilter=('Maya skin weight (*.json)'), fm=1)
        if not fileList:
            return
        # 讀入檔案
        data = {}
        with open(fileList[0], 'r') as f:
            data = json.load(f)
        # import
        errorList = []
        for mesh, data in data.items():
            if isModifyImportData:
                mesh = f'{mdlStartAdd}{mesh}'
                mesh = f'{mesh}{mdlEndAdd}'
                mesh = mesh.replace(mdlInpReplace, mdlOutReplace)
                data[0] = [f'{jointStartAdd}{x}' for x in data[0]]
                data[0] = [f'{x}{jointEndAdd}' for x in data[0]]
                data[0] = [x.replace(jointInpReplace, jointOutReplace) for x in data[0]]
            self.mesh = mesh
            self.data = data
            if not cmds.objExists(mesh):
                continue
            skinNodeList = thFindSkinNodeF([mesh])
            if skinNodeList:
                cmds.delete(skinNodeList)
            try:
                self.setWeightDataF(False)
            except:
                errorList.append(mesh)
        if errorList:
            cmds.select(errorList, r=True)
            cmds.warning(ThLanguage.tr('部分物件匯入權重失敗!'))

    def _toDictF(self):
        """轉換為字典"""
        self.dataDict = {}
        len_ = len(self.data[0])
        for i, n in enumerate(self.data[0]):
            self.dataDict[n] = self.data[1][i::len_]

    def _toListF(self):
        """轉換為列表"""
        weightList = []
        for i in range(len(self.dataDict[self.data[0][0]])):
            for n in self.data[0]:
                weightList.append(self.dataDict[n][i])
        self.data[1] = weightList

    def roundWeightF(self, meshList, round_=3):
        """權重值四捨五入"""
        # 獲取權重
        for m in meshList:
            self.getWeightDataF(m, False)
            weightList = ThConversionMatrix.reshapeListToColumnsF(self.data[1], len(self.data[0]))
            weightList = ThConversionMatrix.transposeMatrixF(weightList)
            newWeightList = []
            for w in weightList:
                # 四捨五入
                newWeights = [Decimal(str(round(x, round_))) for x in w]
                # 操作最大值
                maxId = newWeights.index(max(newWeights))
                diffVal = Decimal('1.0') - sum(newWeights)
                newWeights[maxId] += diffVal
                #
                newWeightList.append([float(x) for x in newWeights])
            self.data[1] = ThConversionMatrix.flattenListF(newWeightList)
            self.setWeightDataF(False)

    def setMaxInfluencesF(self, meshList, value):
        """自動設定最大 influences"""
        # 獲取權重
        for m in meshList:
            self.getWeightDataF(m, False)
            weightList = ThConversionMatrix.reshapeListToColumnsF(self.data[1], len(self.data[0]))
            weightList = ThConversionMatrix.transposeMatrixF(weightList)
            newWeightList = []
            # 是否操作列表
            for w in weightList:
                if len([x for x in w if x > 0]) > value:
                    wDict = {i: x for i, x in enumerate(w)}  # 轉為字典
                    # 排序並切割出指定長度
                    sorted_ = sorted(wDict.items(), reverse=True, key=lambda item: item[1])[:value]
                    # 獲取大於指定長度的 KEY
                    sortedId = [x[0] for x in sorted_]
                    # 獲取新列表數據
                    nW = [x if i in sortedId else 0 for i, x in enumerate(w)]
                    # 計算加總為 0
                    averageData = thAverageDataF(nW)
                    newWeightList.append(averageData)
                else:
                    newWeightList.append(w)
            self.data[1] = ThConversionMatrix.flattenListF(newWeightList)
            self.setWeightDataF(False)

    def getMaxInfluencesF(self, meshList, value):
        """獲取最大 influences"""
        # 獲取權重
        rusData = {}
        for m in meshList:
            self.getWeightDataF(m, False)
            weightList = ThConversionMatrix.reshapeListToColumnsF(self.data[1], len(self.data[0]))
            weightList = ThConversionMatrix.transposeMatrixF(weightList)
            # 是否操作列表
            infData = {}
            for i, w in enumerate(weightList):
                validCount = sum(1 for x in w if x > 0)
                if validCount > value:
                    infData.setdefault(validCount, []).append(i)
            # 排序
            rusData[m] = sorted(
                infData.items(),
                reverse=False,
                key=lambda item: item[0])
        return rusData


class ThDisconnectConnect:
    def __init__(self, system='disconnectAttr_data'):
        self.system = system

    def getDataF(self, objList, disconnectAttr=False, attrList=None, typeList=None):
        conDict0 = {}
        for obj in objList:
            conDict1 = {}
            # 讀取列表
            doAttrList = attrList if attrList else cmds.listAttr(
                obj, lf=True, m=True, r=True, se=True, v=True, w=True, c=True)
            # 獲取、保存、斷開連接
            for attr in doAttrList:
                conList = None
                # 獲取連接對象
                try:  # 有些屬性無法獲取連接，若獲取失敗就跳過
                    conList = cmds.listConnections(
                        f'{obj}.{attr}', source=True, destination=False, plugs=True)
                except:
                    continue
                # 如果對象為空就跳過
                if not conList:
                    continue
                # 如果連接對象符合類別才繼續
                if typeList:
                    if not cmds.nodeType(conList[0]) in typeList:
                        continue
                # 是否斷開連接
                if disconnectAttr:
                    try:
                        cmds.disconnectAttr(conList[0], f'{obj}.{attr}')
                    except:
                        continue
                conDict1[attr] = conList[0]
            if conDict1:
                conDict0[obj] = conDict1
        return conDict0

    def transferF(self, main, objList):
        """傳遞連接"""
        data = self.getDataF([main])
        for node, conData in data.items():
            for attr, conObj in conData.items():
                for obj in objList:
                    try:
                        cmds.connectAttr(conObj, f'{obj}.{attr}')
                    except:
                        pass
        # 傳遞 lock
        ThAttrLockManager.transferF(main, objList)

    def connectF(self, data):
        """回復連接"""
        for node, conData in data.items():
            for attr, conObj in conData.items():
                try:
                    cmds.connectAttr(conObj, f'{node}.{attr}')
                except:
                    pass

    def switchF(self, doList=None, attrList=None, typeList=None):
        """斷開與回復連接"""
        if cmds.objExists(self.system):
            data = ThGrpSaveData(self.system).getF()
            self.connectF(data)
            cmds.delete(self.system)
            cmds.select([_ for _ in data.keys() if cmds.objExists(_)], r=True)
        else:
            if not doList:
                return
            data = self.getDataF(doList, True, attrList, typeList)
            gsd = ThGrpSaveData(self.system, {})
            gsd.setF(data)
            cmds.select(doList, r=True)


class ThSoftToSkin:
    def __init__(self, joint, sel, useOm2=False, scaleRange=1):
        self.joint = joint
        self.sel = sel
        self.useOm2 = useOm2
        self.scaleRange = scaleRange
        #
        self.mesh = sel[0].split('.')[0]

    def applyF(self):
        if self.useOm2:
            self.cwa = ThCopyWeightApi()
            self.cwa.getWeightDataF(self.mesh)
            try:
                self._setOm2F(self.joint)
                self.cwa.setWeightDataF()
            except RuntimeError:
                cmds.warning(ThLanguage.tr('對象與此方法不兼容!'))
        else:
            self._setF(self.joint)
        cmds.select(self.joint, r=True)

    def batchApplyF(self):
        # 找子骨骼
        jointList = cmds.listRelatives(self.joint, ad=True, type='joint')[::-1]
        # 獲取要設定的骨骼
        useJointList = [self.joint] + jointList[:-1]
        # 每根骨骼的距離
        disList = []
        for n in jointList:
            disList.append(cmds.getAttr(n + '.tx'))
        jointDisList = []
        for i, n in enumerate(useJointList):
            jointDisList.append(sum(disList[i:]))
        # 開啟 soft
        cmds.softSelect(e=True, softSelectEnabled=True)
        cmds.softSelect(e=True, softSelectCurve='0,1,0,1,0,1,0,1,1')
        # 執行
        if self.useOm2:
            self.cwa = ThCopyWeightApi()
            self.cwa.getWeightDataF(self.mesh)
            for i, n in enumerate(useJointList):
                cmds.softSelect(e=True, softSelectDistance=jointDisList[i] * self.scaleRange)
                cmds.select(self.sel, r=True)
                self._setOm2F(n)
            self.cwa.setWeightDataF()
        else:
            for i, n in enumerate(useJointList):
                cmds.softSelect(e=True, softSelectDistance=jointDisList[i] * self.scaleRange)
                cmds.select(self.sel, r=True)
                self._setF(n)
        cmds.select(self.joint, r=True)

    def _setF(self, joint):
        skinNode = thFindSkinNodeF([self.mesh])[0]
        richSel = om2.MGlobal.getRichSelection()
        richSelList = richSel.getSelection()
        path, component = richSelList.getComponent(0)
        componentFn = om2.MFnSingleIndexedComponent(component)
        # 使用進度條
        size = componentFn.getCompleteData()
        progressBar = ThUiProgressBar(1)
        progressBar.show()
        progressBar.setStratF(0, 'Vertex', size)
        # 設置權重
        for i in range(0, size):
            progressBar.setFrameF(0)
            weight = componentFn.weight(i)
            v = componentFn.element(i)
            w = weight.influence
            #
            vtx = '{}.vtx[{}]'.format(self.mesh, v)
            cmds.skinPercent(skinNode, vtx, tv=[joint, w])
        progressBar.close()

    def _setOm2F(self, joint):
        richSel = om2.MGlobal.getRichSelection()
        richSelList = richSel.getSelection()
        path, component = richSelList.getComponent(0)
        componentFn = om2.MFnSingleIndexedComponent(component)
        # 獲取值
        idList = []
        idListData = []
        size = componentFn.getCompleteData()
        for i in range(0, size):
            weight = componentFn.weight(i)
            idList.append(componentFn.element(i))
            idListData.append(weight.influence)
        # 設定權重
        self.cwa.editWeightDataF(idList, idListData, joint, findUnLockJoint=True)


class ThReconstructionParentOld:
    def __init__(self, list_=None, system='ThReconstructionParentOld_data', isSaveAttr=False):
        """重做 parent"""
        self.list_ = list_
        self.system = system
        self.isSaveAttr = isSaveAttr
        #
        self.data = {'layout': [], 'pose': []}

    def getParentF(self):
        """獲取數據"""
        if not self.list_:
            return
        # 判斷有無重複名稱
        repeatList = []
        for n in self.list_:
            if '|' in n:
                repeatList.append(n)
        if repeatList:
            cmds.select(repeatList, r=True)
            cmds.warning(
                ThLanguage.tr('程序未執行，選擇物件中包含重複名稱!'))
            return
        # 獲取 list_ 父物件
        dataList = []
        for n in self.list_:
            father = cmds.listRelatives(n, p=True, f=True)
            if father:
                dataList.append([n, father[0]])
            else:
                dataList.append([n, None])
        #
        self.data['layout'] = dataList
        #
        return dataList

    def setParentF(self, data):
        """設定數據"""
        for k, v in data:
            if v is None:
                continue
            try:
                cmds.parent(k, v)
            except:
                pass

    def applyF(self):
        # 創建數據保存
        if not cmds.objExists(self.system):
            # 獲取數據
            self.getParentF()
            # 保存當前姿勢
            if self.isSaveAttr:
                attrList = ['tx', 'ty', 'tz', 'rx', 'ry', 'rz', 'sx', 'sy', 'sz']
                soad = ThSaveObjsAttrData(objs=self.list_, attrList=attrList)
                soad.saveF()
                self.data['pose'] = soad.data
            # 保存
            gsd = ThGrpSaveData(self.system)
            gsd.setF(self.data)
            # 解除父子關係
            for k, v in self.data['layout']:
                if v:
                    cmds.parent(k, w=True)
            cmds.select(self.list_, r=True)
        else:
            self.data = ThGrpSaveData(self.system).getF()
            # 設定數據
            self.setParentF(self.data['layout'])
            # 回到保存姿勢
            if self.isSaveAttr:
                soad = ThSaveObjsAttrData(data=self.data['pose'])
                soad.redoSaveF()
            #
            cmds.delete(self.system)
            cmds.select([n[0] for n in self.data['layout']], r=True)

    def selectF(self):
        if cmds.objExists(self.system):
            self.data = ThGrpSaveData(self.system).getF()
            cmds.select([n[0] for n in self.data['layout']], r=True)


class ThReconstructionParent:
    def __init__(self, list_=None, system='ThReconstructionParent_data', isSaveAttr=False):
        """重做 parent"""
        self.list_ = list_
        self.system = system
        self.isSaveAttr = isSaveAttr
        #
        self.data = {'layout': [], 'pose': []}
        self.sysSets = self.system + '_sets'

    def getParentF(self):
        """獲取數據"""
        if not self.list_:
            return
        # 獲取 list_ 父物件
        dataList = []
        for n in self.list_:
            father = cmds.listRelatives(n, p=True, f=True)
            doSets = cmds.sets(n)
            if father:
                parentSets = cmds.sets(father)
                cmds.sets([doSets, parentSets], add=self.sysSets)
                dataList.append([doSets, parentSets])
            else:
                dataList.append([doSets, None])
        #
        self.data['layout'] = dataList
        #
        return dataList

    def setParentF(self):
        """設定數據"""
        for k, v in self.data['layout']:
            if v is None:
                continue
            #
            father = cmds.listRelatives(cmds.sets(k, q=True), p=True)  # 骨骼若做縮放會生成 grp 要刪除
            #
            cmds.parent(cmds.sets(k, q=True), cmds.sets(v, q=True)[0])
            #
            if father:
                cmds.delete(father)

    def applyF(self):
        # 創建數據保存
        if not cmds.objExists(self.system):
            #
            cmds.select(cl=True)
            self.sysSets = cmds.sets(n=self.sysSets)
            # 獲取數據
            self.getParentF()
            # 保存當前姿勢
            if self.isSaveAttr:
                attrList = ['tx', 'ty', 'tz', 'rx', 'ry', 'rz', 'sx', 'sy', 'sz']
                soad = ThSaveObjsAttrData(objs=self.list_, attrList=attrList)
                soad.saveF()
                self.data['pose'] = soad.data
            # 保存
            gsd = ThGrpSaveData(self.system)
            gsd.setF(self.data)
            # 解除父子關係
            for k, v in self.data['layout']:
                if v:
                    cmds.parent(cmds.sets(k, q=True), w=True)
            #
            cmds.select([cmds.sets(n[0], q=True)[0] for n in self.data['layout']], r=True)
        else:
            self.data = ThGrpSaveData(self.system).getF()
            # 設定數據
            self.setParentF()
            # 回到保存姿勢
            if self.isSaveAttr:
                soad = ThSaveObjsAttrData(data=self.data['pose'])
                soad.redoSaveF()
            #
            cmds.delete(self.system)
            cmds.select([cmds.sets(n[0], q=True)[0] for n in self.data['layout']], r=True)
            #
            cmds.delete(xx for x in self.data['layout'] for xx in x)
            if cmds.objExists(self.sysSets):
                cmds.delete(self.sysSets)

    def selectF(self):
        cmds.select(self.getJointListF(), r=True)

    def getJointListF(self):
        if cmds.objExists(self.system):
            self.data = ThGrpSaveData(self.system).getF()
            jointList = [cmds.sets(n[0], q=True)[0] for n in self.data['layout']]
            return jointList
        else:
            return []


class ThCtrlMirrorData:
    system = 'customCtrlMirror_data'

    def __init__(self, label):
        self.label = label
        # 創建數據保存
        if not cmds.objExists(self.system):
            cmds.group(n=self.system, em=True)
            cmds.addAttr(self.system, sn='nts', ln='notes', dt='string')
            cmds.setAttr(self.system + '.notes', '{}', type='string')
        # 添加名稱
        dataDict = eval(cmds.getAttr(self.system + '.notes'))
        if not self.label in dataDict:
            dataDict[self.label] = {'L': [], 'R': []}
            cmds.setAttr(self.system + '.notes', dataDict, type='string')

    def addListF(self, sel, direction='L'):
        dataDict = eval(cmds.getAttr(self.system + '.notes'))
        for n in sel:
            if not n in dataDict[self.label][direction]:
                dataDict[self.label][direction].append(n)
        cmds.setAttr(self.system + '.notes', dataDict, type='string')
        return len(dataDict[self.label][direction])

    def clearListF(self):
        dataDict = eval(cmds.getAttr(self.system + '.notes'))
        dataDict[self.label] = {'L': [], 'R': []}
        cmds.setAttr(self.system + '.notes', dataDict, type='string')

    def clearLabelF(self):
        dataDict = eval(cmds.getAttr(self.system + '.notes'))
        del (dataDict[self.label])
        if dataDict:
            cmds.setAttr(self.system + '.notes', dataDict, type='string')
        else:
            cmds.delete(self.system)


class ThDynamicsCtrl:
    def __init__(self, type, font=None):
        self.type = type
        self.font = font
        # add
        self.mainCtrl = 'dyn_{}_main_ctrl'.format(self.type)

    def ctrlF(self):
        if not cmds.objExists(self.mainCtrl):
            # 創建控制器
            cv = mel.eval(
                'curve -d 1 -p -1 0 -1.063394 -p 1 0 -1.063394 -p 1 0 '
                '-0.936606 -p -1 0 -0.936606 -p -1 0 -1.063394 -k 0 -k 1 -k 2 -k 3 -k 4')
            cmds.rename(cv, self.mainCtrl)
            grp = cmds.group(self.mainCtrl, n='dyn_{}_mainCtrl_grp'.format(self.type))
            # 隱藏並鎖定屬性
            thLockHiddenAttrF([self.mainCtrl], [1, 1, 1, 1])
            # 創建文字
            node = cmds.textCurves(t=self.type, ch=False, f=self.font)
            txGrp = cmds.rename(node[0], 'dyn_{}_mainCtrl_tx_grp'.format(self.type))
            children = cmds.listRelatives(txGrp, c=True, typ='transform')
            cmds.ungroup(children)
            children = cmds.listRelatives(txGrp, c=True, typ='transform')
            for c in children:
                cmds.rename(c, 'dyn_{}_mainCtrl_tx#'.format(self.type))
            cmds.move(-1, 0.08, -1, txGrp, rpr=True)
            cmds.setAttr(txGrp + '.overrideEnabled', 1)
            cmds.setAttr(txGrp + '.overrideDisplayType', 2)
            cmds.parent(txGrp, self.mainCtrl)

    def childrenCtrlF(self, quantity):
        moveData = 0
        for i in range(quantity):
            ctrl = 'dyn_{}_ch_ctrl{}'.format(self.type, i + 1)
            if not cmds.objExists(ctrl):
                cv = mel.eval(
                    'curve -d 1 -p -0.794243 0 -0.529496 '
                    '-p 0.794243 0 -0.529496 -p 0.794243 0 0.529496 '
                    '-p -0.794243 0 0.529496 -p -0.794243 0 -0.529496 '
                    '-k 0 -k 1 -k 2 -k 3 -k 4')
                cmds.rename(cv, ctrl)
                thLockHiddenAttrF([ctrl], [1, 1, 1, 1])
                grp = cmds.group(ctrl, n=ctrl + '_grp')
                cmds.parent(grp, self.mainCtrl)
                cmds.setAttr(grp + '.t', *[0, 0, moveData])
                cmds.setAttr(grp + '.r', *[0, 0, 0])
                cmds.setAttr(grp + '.s', *[1, 1, 1])
                self._addAttrF(ctrl)
            moveData += 1.2
        cmds.select('dyn_{}_mainCtrl_grp'.format(self.type), r=True)

    def _addAttrF(self, obj):
        if self.type == 'cloth':
            cmds.addAttr(obj, k=True, ln='isDynamic', at='long', min=0, max=1, dv=0)
            cmds.setAttr(obj + '.isDynamic', e=True, channelBox=True)
            cmds.addAttr(obj, k=True, ln='collisions_', at='enum', en='------:------:')
            cmds.setAttr(obj + '.collisions_', e=True, channelBox=True)
            cmds.addAttr(obj, k=True, ln='collide', at='long', min=0, max=1, dv=1)
            cmds.addAttr(obj, k=True, ln='selfCollide', at='long', min=0, max=1, dv=1)
            cmds.addAttr(obj, k=True, ln='thickness', at='double', min=0, dv=0.03)
            cmds.addAttr(obj, k=True, ln='selfCollideWidthScale', at='double', min=0, dv=1)
            cmds.addAttr(obj, k=True, ln='bounce', at='double', min=0, dv=0)
            cmds.addAttr(obj, k=True, ln='friction', at='double', min=0, dv=0.1)
            cmds.addAttr(obj, k=True, ln='stickiness', at='double', min=0, dv=0)
            cmds.addAttr(obj, k=True, ln='dynamic_', at='enum', en='------:------:')
            cmds.setAttr(obj + '.dynamic_', e=True, channelBox=True)
            cmds.addAttr(obj, k=True, ln='stretchResistance', at='double', min=0, dv=150)
            cmds.addAttr(obj, k=True, ln='compressionResistance', at='double', min=0, dv=10)
            cmds.addAttr(obj, k=True, ln='bendResistance', at='double', min=0, dv=0.1)
            cmds.addAttr(obj, k=True, ln='bendAngleDropoff', at='double', min=0, dv=.298)
            cmds.addAttr(obj, k=True, ln='shearResistance', at='double', min=0, dv=0)
            cmds.addAttr(obj, k=True, ln='restitutionAngle', at='double', min=0, dv=720)
