class ThConnDynNode:
    attrList = {
        'nCloth': [
            ['isDynamic', 'collide', 'selfCollide', 'thickness', 'selfCollideWidthScale', 'bounce',
                'friction', 'stickiness', 'stretchResistance', 'compressionResistance',
                'bendResistance', 'bendAngleDropoff', 'shearResistance', 'restitutionAngle',
                'restitutionTension', 'rigidity', 'deformResistance', 'inputMeshAttract',
                'inputAttractMethod', 'inputAttractDamp', 'inputMotionDrag', 'restLengthScale',
                'bendAngleScale', 'pointMass', 'lift', 'drag', 'tangentialDrag', 'damp',
                'stretchDamp', 'scalingRelation'], 15], 'hairSystem': [
            ['collide', 'selfCollide', 'collideWidthOffset', 'selfCollideWidthScale', 'bounce',
                'friction', 'stickiness', 'staticCling', 'stretchResistance',
                'compressionResistance', 'bendResistance', 'twistResistance', 'startCurveAttract',
                'attractionDamp', 'mass', 'drag', 'tangentialDrag', 'motionDrag', 'damp',
                'stretchDamp', 'dynamicsWeight', 'turbulenceStrength', 'turbulenceFrequency',
                'turbulenceSpeed'], 10], 'nucleus': [
            ['startFrame', 'timeScale', 'spaceScale', 'gravity', 'airDensity', 'windSpeed',
                'windDirectionX', 'windDirectionY', 'windDirectionZ', 'windNoise', 'subSteps',
                'maxCollisionIterations'], 23],
        'collider': [['isDynamic', 'collide', 'thickness', 'bounce', 'friction', 'stickiness']]}

    def __init__(self, objs):
        self.objs = objs
        # app
        ctrl = self.objs[-1]
        objList = self.objs[:-1]
        type = thTypeF([objList[0]])[0]
        # connect
        cmds.delete(objList, channels=True, hierarchy='none', controlPoints=0, shape=1)
        for obj in objList:
            for attr in self.attrList[type][0]:
                cmds.connectAttr(ctrl + '.' + attr, obj + '.' + attr, f=True)
            if type == 'hairSystem':
                cmds.setAttr(ctrl + '.enable', 0)
                cmds.setAttr(obj + '.simulationMethod', 0)
                cmds.setDrivenKeyframe(
                    obj + '.simulationMethod', cd=ctrl + '.enable', itt='linear', ott='linear')
                cmds.setAttr(ctrl + '.enable', 1)
                cmds.setAttr(obj + '.simulationMethod', 3)
                cmds.setDrivenKeyframe(
                    obj + '.simulationMethod', cd=ctrl + '.enable', itt='linear', ott='linear')
        # color
        thSetCtrlColorF([ctrl], self.attrList[type][1])
        cmds.select(ctrl, r=True)


class ThIKElasticity:
    def __init__(
        self, joints, name='obj', curve=None, mainCtrl=None, size=1.0, ctrlQuantity=3,
        color=13, useTwistAttr=True, createTwistCtrl=False, createElasticity=True,
        createFkIk=False, createScale=False, constrainObjects=True, parentCtrl=False,
        parentCtrlOther=False, hairSystem=False, jointLenIsCtrl=False):
        """Ik spline 拉伸 RIG"""
        self.joints = joints
        self.name = name
        self.curve = curve
        self.mainCtrl = mainCtrl
        self.size = size
        self.ctrlQuantity = ctrlQuantity
        self.color = color
        self.useTwistAttr = useTwistAttr
        self.createTwistCtrl = createTwistCtrl
        self.createElasticity = createElasticity
        self.createFkIk = createFkIk
        self.createScale = createScale
        self.constrainObjects = constrainObjects
        self.parentCtrl = parentCtrl
        self.parentCtrlOther = parentCtrlOther
        self.hairSystem = hairSystem
        self.jointLenIsCtrl = jointLenIsCtrl
        # add
        self.mainDefGrp = None  # 主要變形器 grp
        self.mainCtrlGrp = None  # 主要控制器 grp
        self.ikJoint = []  # IK joint
        self.ikHandle = None  # IK handle node
        self.skinCvJoint = []  # skin curve joint
        self.ikCtrl = []  # IK 控制器
        self.ikCtrlGrp = []  # IK 控制器 grp
        self.ikMainGrp = None  # IK 控制器主要 grp 名稱
        self.constrainNode = []  # constrain node list
        self.ikFk = None  # IK FK 切換控制器
        self.fkCtrl = []  # FK 控制器名稱
        self.fkMainGrp = None  # FK 控制器主要 grp 名稱
        self.iKAloneCtrl = []  # 單獨的 ik 控制器
        self.iKAloneCtrlGrp = []  # 單獨的 ik 控制器 grp

    def createF(self):
        # 創建用於 ik 的 joint
        self._createJointF()
        # 創建 ik spline system 與 ctrl
        self._createCtrlF()
        # 是否創建 parent ctrl
        if self.parentCtrl:
            self.ctrlParentF()
        # 最後一個控制器約束最後一個骨骼
        endIkCtrl = self.iKAloneCtrl[-1] if self.parentCtrlOther else self.ikCtrl[-1]
        cmds.orientConstraint([endIkCtrl, self.ikJoint[-1]], offset=[0, 0, 0], weight=1)
        # 設置 ik twist
        self._setIkAttrTwistF()
        self._setIkCtrlTwistModeF()
        # 是否創建 elasticity ik 系統
        if self.createElasticity:
            self._createElasticityIkSysF()
        # 是否創建 scale 系統
        if self.createScale:
            self._createScaleJointSysF()
        # 控制基礎物件
        if self.constrainObjects:
            self._controlObjF()
        # 是否創建 FK system
        if self.createFkIk:
            self._createFkF()
        # 是否創建 hair system
        if self.hairSystem:
            hr = ThHair(cv=self.curve, name=self.name)
            hr.appF()
        #
        cmds.select(cl=True)

    def _createJointF(self):
        """創建 IK 用的 joint"""
        # 產生主要 group
        if not cmds.objExists('def'):
            cmds.group(em=True, n='def')
        if not cmds.objExists('IK_def_grp'):
            cmds.group(em=True, n='IK_def_grp')
            cmds.parent('IK_def_grp', 'def')
        if not cmds.objExists('IK_ctrl_grp'):
            cmds.group(em=True, n='IK_ctrl_grp')
        self.mainDefGrp = cmds.group(em=True, n=self.name + '_def_grp#')
        cmds.parent(self.mainDefGrp, 'IK_def_grp')
        self.mainCtrlGrp = cmds.group(em=True, n=self.name + '_ctrl_grp#')
        cmds.parent(self.mainCtrlGrp, 'IK_ctrl_grp')
        # 如果 curve 為空就創建
        if not self.curve:
            self.curve = thObjectCurveF(self.joints)
        # freeze curve transform
        cmds.makeIdentity(self.curve, apply=True, t=True, r=True, s=True, n=False, pn=True)
        self.curve = cmds.rename(self.curve, self.name + '_IK_curve#')
        cmds.parent(self.curve, self.mainDefGrp)
        cmds.hide(self.curve)
        # create ik joint
        for j in self.joints:
            cmds.select(cl=True)
            nJ = cmds.joint(n=self.name + '_IK_joint#')
            self.ikJoint.append(nJ)
            ThAdsorptionObj([nJ], j, 'tr')
        thGrpParentF(self.ikJoint, True)
        cmds.makeIdentity(self.ikJoint, apply=True, t=True, r=True, s=True, n=False, pn=True)
        ikJointMainGrp = cmds.group(self.ikJoint[0], n=self.name + '_IK_joint_main_grp#')
        cmds.parent(ikJointMainGrp, self.mainCtrlGrp)
        cmds.hide(self.ikJoint[0])
        # 調整軸向(最後一根)
        cmds.joint(self.ikJoint[-1], e=True, oj='none', ch=False, zso=True)
        # 創建控制器用 joint
        doCtrlQuantity = len(self.ikJoint) if self.jointLenIsCtrl else self.ctrlQuantity
        cfoj = ThCreateFollowObjsJoint(self.ikJoint, doCtrlQuantity)
        cfoj.appF()
        self.skinCvJoint = thBatchRenameF(
            objs=cfoj.newJoints, name=self.name + '_skin_joint')
        cmds.hide(self.skinCvJoint)
        # 最後一根骨骼對位
        ThAdsorptionObj([self.skinCvJoint[-1]], self.joints[-1], 'tr', ifFreeze=True)

    def _createCtrlF(self):
        """創建 IK spline system 與 ctrl"""
        # 創建 ikHandle
        self.ikHandle = cmds.ikHandle(
            sol='ikSplineSolver', n=self.name + '_ikHandle#', ccv=False, scv=False, pcv=False,
            sj=self.ikJoint[0], ee=self.ikJoint[-1], c=self.curve)
        cmds.hide(self.ikHandle)
        cmds.parent(self.ikHandle[0], self.mainDefGrp)
        # skin cv joint 創建控制器
        cto = ThCtrlToObject(
            objList=self.skinCvJoint, name=self.name + '_IK', ctrlStyle='circle',
            ctrlMethod='parent', ctrlSize=self.size, ctrlColor=self.color, ctrlAxial='x')
        cto.createF()
        # 保存控制器名稱
        self.ikCtrl = cto.newCtrlList
        self.ikCtrlGrp = cto.newCtrlGrpList
        self.ikMainGrp = cto.mainGrp
        cmds.parent(cto.mainGrp, self.mainCtrlGrp)
        # skin
        ccme = ThCoordinateCreateMeshLocal(
            objList=self.skinCvJoint, maxInfluences=1, axis='z', offset=.01, loop=False)
        cmds.polySmooth(
            ccme.newMesh,
            mth=0, sdt=2, ovb=1, ofb=3, ofc=0, ost=0, ocr=1, dv=3, bnr=1,
            c=1, kb=1, ksb=1, khe=0, kt=1, kmb=1, suv=1, peh=0, sl=1,
            dpe=1, ps=0.1, ro=1, ch=1)
        dts = ThDefToSkin('ThDefToSkin_ThIKElasticity__createCtrlF')
        dts.applyF([ccme.newMesh], self.skinCvJoint, 50, True, False, False, False, 'y')
        csaw = ThCopySkinAndWeight([dts.newMeshList[0]], [self.curve])
        csaw.copySkinF()
        csaw.copyWeightF()
        cmds.delete('ThDefToSkin_ThIKElasticity__createCtrlF', ccme.newMesh)

    def _setIkAttrTwistF(self):
        """設置 IK twist"""
        # connect ik twist attr
        cmds.addAttr(self.ikCtrl[0], k=True, ln='IK_spline_attr', at='enum', en='------:------:')
        cmds.setAttr(self.ikCtrl[0] + '.IK_spline_attr', e=True, channelBox=True)
        cmds.addAttr(self.ikCtrl[0], ln='twist', at='double', dv=0, k=True)
        # 關聯 IK
        cmds.connectAttr(self.ikCtrl[0] + '.twist', self.ikHandle[0] + '.twist')

    def _setIkCtrlTwistModeF(self):
        """創建 twist ctrl mode"""
        cmds.addAttr(
            self.ikCtrl[0], ln='if_ctrl_twist', at='bool', min=0, max=1, dv=self.useTwistAttr,
            k=True)
        cmds.connectAttr(
            self.ikCtrl[0] + '.if_ctrl_twist', self.ikHandle[0] + '.dTwistControlEnable')
        # 控制模式
        if not self.createTwistCtrl:
            self._setIkCtrlTwist1F()
        else:
            self._setIkCtrlTwist2F()

    def _setIkCtrlTwist1F(self):
        """創建 twist ctrl mode1"""
        cmds.setAttr(self.ikHandle[0] + '.dWorldUpType', 4)
        # connect
        if self.parentCtrlOther:
            ikCtrl1, ikCtrl2 = (self.iKAloneCtrl[0], self.iKAloneCtrl[-1])
        else:
            ikCtrl1, ikCtrl2 = (self.ikCtrl[0], self.ikCtrl[-1])
        cmds.connectAttr(ikCtrl1 + '.worldMatrix[0]', self.ikHandle[0] + '.dWorldUpMatrix')
        cmds.connectAttr(ikCtrl2 + '.worldMatrix[0]', self.ikHandle[0] + '.dWorldUpMatrixEnd')
        # 設置向量控制 ik vector
        cmds.addAttr(self.ikCtrl[0], ln='IK_vector', at='enum', en='Y:Z:', k=True)
        #
        ikVectoryAttr = [
            'dWorldUpAxis', 'dWorldUpVectorY', 'dWorldUpVectorZ',
            'dWorldUpVectorEndY', 'dWorldUpVectorEndZ']
        ikVectoryAttr = [self.ikHandle[0] + '.' + n for n in ikVectoryAttr]
        cmds.setDrivenKeyframe(
            ikVectoryAttr, cd=self.ikCtrl[0] + '.IK_vector', itt='linear', ott='linear')
        #
        cmds.setAttr(self.ikCtrl[0] + '.IK_vector', 1)
        cmds.setAttr(self.ikHandle[0] + '.dWorldUpAxis', 3)
        cmds.setAttr(self.ikHandle[0] + '.dWorldUpVectorY', 0)
        cmds.setAttr(self.ikHandle[0] + '.dWorldUpVectorZ', 1)
        cmds.setAttr(self.ikHandle[0] + '.dWorldUpVectorEndY', 0)
        cmds.setAttr(self.ikHandle[0] + '.dWorldUpVectorEndZ', 1)
        cmds.setDrivenKeyframe(
            ikVectoryAttr, cd=self.ikCtrl[0] + '.IK_vector', itt='linear', ott='linear')

    def _setIkCtrlTwist2F(self):
        """創建 twist ctrl mode2"""
        # 用於循環創建起始與結束的控制器
        twistJointList = [self.ikCtrl[0], self.ikCtrl[-1]]
        # 用於循環創建起始與結束的新創物件命名
        newName = ['start', 'end']
        # 保存控制起始與結束的兩個物件
        controlTwistJoint = []
        # 用於歸納循環中創建的參考線
        twistTestGrp = cmds.group(em=True, n=self.name + '_twist_text_cv#')
        cmds.parent(twistTestGrp, self.mainDefGrp)
        #
        for i, n in enumerate(twistJointList):
            # create joint
            cmds.select(cl=True)
            twistJoint1 = cmds.joint(n=self.name + '_twist_joint1_' + newName[i] + '#')
            cmds.select(cl=True)
            twistJoint2 = cmds.joint(n=self.name + '_twist_joint2_' + newName[i] + '#')
            controlTwistJoint.append(twistJoint2)
            # 對位
            ThAdsorptionObj([twistJoint1, twistJoint2], n, 'tr', True)
            # create ctrl
            cto = ThCtrlToObject(
                objList=[twistJoint2], name=self.name + '_twist_' + newName[i],
                ctrlStyle='ball', ctrlMethod='parent', ctrlSize=self.size * .7, ctrlColor=4,
                grpLayout=2)
            cto.createF()
            # 設定 grp offset
            cmds.move(0, 10, 0, cto.grpLayoutList[0][1], cs=True)
            # 歸納 joint 與 控制器
            twistJointGrp = cmds.group(
                em=True, n=self.name + '_twist_joint_' + newName[i] + '_grp#')
            cmds.parent(twistJointGrp, n)
            cmds.parent([twistJoint1, cto.mainGrp], twistJointGrp)
            # 創建參考線
            testCv = thObjectCurveF([twistJoint1, twistJoint2], False)
            testCv = cmds.rename(testCv, self.name + '_twist_test_cv_' + newName[i] + '#')
            cmds.parent(testCv, twistTestGrp)
            # skin
            cmds.skinCluster([twistJoint1, twistJoint2, testCv], mi=5, dr=4.0, tsb=True)
            cmds.setAttr(testCv + '.template', 1)
        #
        cmds.setAttr(self.ikHandle[0] + '.dWorldUpType', 2)
        cmds.connectAttr(
            controlTwistJoint[0] + '.worldMatrix[0]', self.ikHandle[0] + '.dWorldUpMatrix')
        cmds.connectAttr(
            controlTwistJoint[1] + '.worldMatrix[0]', self.ikHandle[0] + '.dWorldUpMatrixEnd')

    def _createElasticityIkSysF(self):
        """創建 elasticity IK 系統"""
        # add attr
        cmds.addAttr(self.ikCtrl[0], ln='elasticity', at='double', min=0, max=1, dv=1, k=True)
        # 整體縮放器
        self.mainElasticityControl = cmds.group(
            n=self.name + '_main_elasticity_control#', em=True)
        cmds.scaleConstraint(
            [self.mainCtrlGrp, self.mainElasticityControl], offset=[1, 1, 1], weight=1)
        cmds.parent(self.mainElasticityControl, self.mainDefGrp)
        #
        elasticitySysGrp = cmds.group(n=self.name + '_IK_elasticity_curve_grp#', em=True)
        cmds.hide(elasticitySysGrp)
        cmds.parent(elasticitySysGrp, self.mainDefGrp)
        # 創建用於測量各 joint 距離之 curve
        elasticityCvList = []
        self.conditionNodes = []
        for i, n in enumerate(self.joints[:-1], 1):
            elasticityCv = thObjectCurveF([n, self.joints[i]], False, False)
            elasticityCv = cmds.rename(elasticityCv, self.name + '_IK_elasticity_curve#')
            cmds.parent(elasticityCv, elasticitySysGrp)
            elasticityCvList.append(elasticityCv)
            # 創建測量結點
            curveInfoNode = cmds.createNode('curveInfo', n=self.name + '_curve_info#')
            # 連接 curve
            self.elasticityCvShape = cmds.listRelatives(elasticityCv, s=True)[0]
            cmds.connectAttr(
                self.elasticityCvShape + '.worldSpace[0]', curveInfoNode + '.inputCurve')
            # 縮放設定
            leg_ = cmds.getAttr('{}.arcLength'.format(curveInfoNode))
            ex = '''\
if ({ctrl}.elasticity == 1){{
    {joint}.tx = {info}.arcLength * (1 / {scale}.sx);
}} else {{
    {joint}.tx = {leg_};
}}'''
            ex = ex.format(
                joint=self.ikJoint[i], info=curveInfoNode, leg_=leg_,
                scale=self.mainElasticityControl, ctrl=self.ikCtrl[0])
            cmds.expression(n='{}_ikeElasticity_EX#'.format(self.ikJoint[i]), s=ex)
        # wire
        wireNode = cmds.wire(
            elasticityCvList, gw=False, en=1.0, ce=0.0, li=0.0, n=self.name + '_wire_node#',
            w=self.curve)
        cmds.setAttr(wireNode[0] + '.dropoffDistance[0]', 5)

    def _createScaleJointSysF(self):
        """創建 scale joint 系統"""
        # 創建 distance soft locator system
        dsl = ThDistanceSoftLocator(
            objs=self.ikJoint, name=self.name, default=1, modeSoft='pipe', quantitySoft=2)
        # 連接 joint
        for i, n in enumerate(dsl.locatorList):
            cmds.connectAttr(n + '.ty', self.ikJoint[i] + '.sy')
            cmds.connectAttr(n + '.ty', self.ikJoint[i] + '.sz')
        # add attr
        cmds.addAttr(self.ikCtrl[0], k=True, ln='soft_scale', at='enum', en='------:------:')
        cmds.setAttr(self.ikCtrl[0] + '.soft_scale', e=True, channelBox=True)
        cmds.addAttr(self.ikCtrl[0], ln='follow', at='double', min=0, max=10, dv=0, k=True)
        cmds.addAttr(self.ikCtrl[0], ln='offset', at='double', min=0, max=10, dv=0, k=True)
        cmds.addAttr(self.ikCtrl[0], ln='weight', at='double', dv=1, k=True)
        cmds.connectAttr(self.ikCtrl[0] + '.follow', dsl.softNode[0][1] + '.follow')
        cmds.connectAttr(self.ikCtrl[0] + '.offset', dsl.softNode[0][1] + '.offset1')
        cmds.connectAttr(self.ikCtrl[0] + '.offset', dsl.softNode[0][1] + '.offset2')
        cmds.connectAttr(self.ikCtrl[0] + '.weight', dsl.softNode[0][1] + '.ty')
        # 創建自動縮放
        cvInfoNode = cmds.createNode('curveInfo', n=self.name + '_curveInfoScale#')
        curveShape = cmds.listRelatives(self.curve, s=True)[0]
        cmds.connectAttr(curveShape + '.worldSpace[0]', cvInfoNode + '.inputCurve')
        cmds.setAttr(dsl.softNode[1][1] + '.follow', 4.7)
        len_ = cmds.getAttr(cvInfoNode + '.arcLength')
        cmds.addAttr(self.ikCtrl[0], ln='len_scale_w', at='double', dv=.1, k=True)
        ex = '''
if (({len_} * {scale}) > {cLen}){{
    {con} = ((({len_} * {scale}) - {cLen}) / {scale}) * {weight} * 1.5;}}
else {{
    {con} = ((({len_} * {scale}) - {cLen}) / {scale}) * {weight};}}
'''
        ex = ex.format(
            cLen=cvInfoNode + '.arcLength', scale=self.mainElasticityControl + '.sx',
            len_=len_, con=dsl.softNode[1][1] + '.ty', weight=self.ikCtrl[0] + '.len_scale_w')
        cmds.expression(n='{}_ikeScale_EX#'.format(self.name), s=ex)

    def _controlObjF(self):
        """控制基礎物件"""
        if self.mainCtrl:
            cmds.parentConstraint([self.mainCtrl, self.mainCtrlGrp], mo=True, weight=1)
        for i, n in enumerate(self.ikJoint):
            self.constrainNode.append(
                cmds.parentConstraint([n, self.joints[i]], mo=True, weight=1)[0])
            cmds.connectAttr(n + '.s', self.joints[i] + '.s', f=True)

    def _createFkF(self):
        """創建 FK 系統"""
        cto = ThCtrlToObject(
            objList=self.joints, name=self.name + '_FK', ctrlStyle='circle',
            ctrlMethod='constrain', ctrlSize=self.size, ctrlColor=18, grpLayout=2,
            rigTRS=[1, 1, 0], ctrlAxial='x')
        cto.createF()
        cto.ctrlParentF()
        cmds.parent(cto.mainGrp, self.mainCtrlGrp)
        # 保存控制器名稱
        self.fkCtrl = cto.newCtrlList
        self.fkMainGrp = cto.mainGrp
        # IK FK 切換控器
        self.ikFk = thMyControllerF(
            name=self.name + '_IKFK', style='angle3', axial='x', color=6,
            lockHideAttr=[1, 1, 1, 1])
        ikFkGrp1 = cmds.group(self.ikFk, n=self.ikFk + '_grp#')
        cmds.parent(ikFkGrp1, self.mainCtrlGrp)
        # 控制器對位
        ThAdsorptionObj([ikFkGrp1], self.ikCtrl[0], 't')
        cmds.move(0, 5, 0, ikFkGrp1, cs=True, r=True)
        # 連接控制器
        cmds.addAttr(self.ikFk, ln='IKFK', at='double', min=0, max=1, dv=1, k=True)
        for i, n in enumerate(self.constrainNode):
            cmds.connectAttr(self.ikFk + '.IKFK', n + '.' + self.ikJoint[i] + 'W0')
            thReverseConnectF([n], [self.ikFk, 'IKFK'], self.fkCtrl[i] + 'W1')
        # 連接 ctrl vis
        cmds.connectAttr(self.ikFk + '.IKFK', self.ikMainGrp + '.v')
        thReverseConnectF([self.fkMainGrp], [self.ikFk, 'IKFK'], 'v')

    def ctrlParentF(self):
        """控制器 parent"""
        newCtrlList = copy.copy(self.ikCtrl)
        newCtrlGrpList = copy.copy(self.ikCtrlGrp)
        newCtrlList.reverse()
        newCtrlGrpList.reverse()
        for i, n in enumerate(newCtrlGrpList[:-1], 1):
            cmds.parent(n, newCtrlList[i])
        # 是否創建獨立控制器
        if self.parentCtrlOther:
            cto = ThCtrlToObject(
                objList=self.skinCvJoint, name=self.name + '_IK_alone', ctrlAxial='x',
                ctrlStyle='circle', ctrlMethod='parent', ctrlSize=self.size + 2, ctrlColor=21,
                ifCreateMainGrp=False)
            cto.createF()
            # 保存控制器名稱
            self.iKAloneCtrl = cto.newCtrlList
            self.iKAloneCtrlGrp = cto.newCtrlGrpList
            for i, n in enumerate(self.iKAloneCtrlGrp):
                cmds.parent(n, self.ikCtrl[i])
        cmds.select(self.ikCtrl, r=True)


class ThReelRig:
    def __init__(self):
        """卷軸綁定"""
        # add
        self.bend = []

    def appF(self, list_, axial='z', mode='two', primaryAxis='x'):
        self.list_ = list_
        self.axial = axial
        self.mode = mode
        self.primaryAxis = primaryAxis
        # add
        self.reverse = True
        # 創建主要控制器
        self.reelSys = cmds.group(em=True, n='reel_sys#')
        # 創建主要骨骼
        self.jointList = []
        for n in self.list_:
            cmds.select(cl=True)
            joint = cmds.joint(n='reel_joint#')
            self.jointList.append(joint)
            ThAdsorptionObj([joint], n, 'tr')
        thGrpParentF(self.jointList, True, 0, False)
        cmds.makeIdentity(self.jointList, apply=True, t=True, r=True, s=True, n=False, pn=True)
        cmds.parent(self.jointList[0], self.reelSys)
        # 創建骨骼 及 loc
        self._locF()
        self._cvLocF()
        self.locList1 = self.loc
        if self.mode == 'two':
            self.reverse = False
            self._locF()
            self._cvLocF()
            self.locList2 = self.loc
            # 約束列表
            ThTwoListSequential(
                list_=self.list_, conListA=self.locList2, conListB=self.locList1,
                mainCtrl=self.reelSys, ctrlMethod='key')
            cmds.connectAttr(self.reelSys + '.reverse_bend', self.reelSys + '.follow')
            cmds.setAttr(self.reelSys + '.follow', lock=True, keyable=False, channelBox=False)
        else:
            for i, n in enumerate(self.locList1):
                cmds.parentConstraint([n, self.list_[i]], mo=True, weight=1, dr=True)
        # 打開 bend
        for n in self.bend:
            cmds.setAttr(n + '.envelope', 1)
        #
        cmds.select(self.reelSys, r=True)

    def _locF(self):
        self.loc = []
        self.locGrp1 = []
        self.locGrp2 = []
        self.prefix = 'positive' if self.reverse else 'reverse'
        # create grp
        self.mainGrp = cmds.group(em=True, n=self.prefix + '_reel_grp#')
        cmds.parent(self.mainGrp, self.reelSys)
        # create loc
        for j in self.jointList:
            loc = cmds.spaceLocator(n=self.prefix + '_reel_locator#')[0]
            grp1 = cmds.group(loc, n=loc + '_grp#')
            grp2 = cmds.group(grp1, n=loc + '_grp#')
            cmds.hide(grp2)
            self.loc.append(loc)
            self.locGrp1.append(grp1)
            self.locGrp2.append(grp2)
            ThAdsorptionObj([grp2], j)
            cmds.parent(grp2, self.mainGrp)
        thGrpParentF(self.loc, self.reverse, 2, False)
        # constrain
        for i, j in enumerate(self.jointList):
            cmds.parentConstraint([j, self.locGrp2[i]], mo=True, weight=1, dr=True)
        # driven key
        doList = self.locGrp2[1:] if self.reverse else self.locGrp2[:-1]
        for grp in doList:
            for attr in ['tx', 'ty', 'tz', 'rx', 'ry', 'rz']:
                cmds.setDrivenKeyframe(
                    grp + '.' + attr, cd=self.locGrp2[0] + '.v', itt='linear', ott='linear')
        # 設置批量啟動
        cmds.addAttr(self.reelSys, k=True, ln=self.prefix, at='enum', en='------:------:')
        cmds.setAttr(self.reelSys + '.' + self.prefix, e=True, channelBox=True)
        cmds.addAttr(
            self.reelSys, ln=self.prefix + '_bend', at='double', min=0, max=10, dv=0, k=True)
        thBatchOffsetF(
            doList, 'blendParent1', '{}.{}_bend'.format(self.reelSys, self.prefix), False,
            self.reverse)
        # create connect loc
        self.conLoc = ThDuplicateWithoutChildrenCon(self.locGrp1).createConLocF()[0]
        father = thGrpParentF(self.conLoc, self.reverse, 1, False, True)
        cmds.parent(father, self.mainGrp)
        cmds.hide(father)

    def _cvLocF(self):
        vl = ThVtxLocator(
            objs=self.list_, name=self.prefix + '_reelCv', ifVl=True, vlAim='y', vlSize=1,
            controlVlMode=None, controlObj=None, rotateObj=None, ctrlStyle=None,
            ctrlAxial='y', ctrlSize=1.0, ctrlMode='not', ctrlColor=13, ctrlGrpLayer=3,
            lockNormals=False)
        vl.createVlAndFollicleF()
        # bend
        bend = cmds.nonLinear(vl.vl, type='bend', lowBound=-1, highBound=1, curvature=0)
        bend[0] = cmds.rename(bend[0], self.prefix + '_reel_bend#')
        bend[1] = cmds.rename(bend[1], self.prefix + '_reel_bendHandle#')
        self.bend.append(bend[0])
        bendGrp = thLocatorGrpF([bend[1]])[0]
        bendGrp1 = thLocatorGrpF([bendGrp])[0]
        obj = self.jointList[-1] if self.reverse else self.jointList[0]
        ThAdsorptionObj([bendGrp1], obj, 'tr', ifFreeze=False)
        cmds.parent(bendGrp1, self.mainGrp)
        cmds.hide(bendGrp1)
        setData = {
            'x': {'y': [0, 90, 90], 'z': [0, 0, 90]},
            'y': {'x': [0, 90, 180], 'z': [0, 0, 180]},
            'z': {'x': [-90, 0, 90], 'y': [-90, 0, 90]}}
        cmds.setAttr(bendGrp + '.r', *setData[self.primaryAxis][self.axial])
        lowBound = -10 if self.reverse else 0
        highBound = 0 if self.reverse else 10
        cmds.setAttr(bend[0] + '.lowBound', lowBound)
        cmds.setAttr(bend[0] + '.highBound', highBound)
        cmds.setAttr(bend[0] + '.envelope', 0)
        # 控制 blend
        cmds.addAttr(
            self.reelSys, ln=self.prefix + '_curvature', at='double', min=-180, max=180, dv=180,
            k=True)
        cmds.connectAttr(self.reelSys + '.' + self.prefix + '_curvature', bend[0] + '.curvature')
        cmds.addAttr(
            self.reelSys, ln=self.prefix + '_rotate', at='double', min=-10, max=10, dv=0, k=True)
        cmds.connectAttr(self.reelSys + '.' + self.prefix + '_rotate', bend[1] + '.rz')
        cmds.addAttr(self.reelSys, ln=self.prefix + '_scale', at='double', min=0, dv=1, k=True)
        cmds.connectAttr(self.reelSys + '.' + self.prefix + '_scale', bend[1] + '.sx')
        cmds.connectAttr(self.reelSys + '.' + self.prefix + '_scale', bend[1] + '.sy')
        cmds.connectAttr(self.reelSys + '.' + self.prefix + '_scale', bend[1] + '.sz')
        # driven key
        obj = self.jointList[0] if self.reverse else self.jointList[-1]
        xyz = cmds.xform(obj, q=True, ws=True, t=True)
        cmds.setAttr('{}.{}_bend'.format(self.reelSys, self.prefix), 0)
        key = [bendGrp + '.' + attr for attr in ['tx', 'ty', 'tz']]
        cmds.setDrivenKeyframe(
            key, cd='{}.{}_bend'.format(self.reelSys, self.prefix), itt='linear', ott='linear')
        cmds.setAttr('{}.{}_bend'.format(self.reelSys, self.prefix), 10)
        cmds.xform(bendGrp, ws=True, t=xyz)
        cmds.setDrivenKeyframe(
            key, cd='{}.{}_bend'.format(self.reelSys, self.prefix), itt='linear', ott='linear')
        cmds.setAttr('{}.{}_bend'.format(self.reelSys, self.prefix), 0)
        # constrain connect loc
        for i, l in enumerate(vl.follicleList):
            cmds.parentConstraint([l, self.conLoc[i]], mo=True, weight=1, dr=True)

    def conCtrlF(self, sys, ctrl):
        cmds.addAttr(ctrl, k=True, ln='positive', at='enum', en='------:------:')
        cmds.setAttr(ctrl + '.positive', e=True, channelBox=True)
        #
        cmds.addAttr(ctrl, ln='positive_bend', at='double', min=0, max=10, dv=0, k=True)
        cmds.connectAttr(ctrl + '.positive_bend', sys + '.positive_bend')
        cmds.addAttr(ctrl, ln='positive_curvature', at='double', min=-180, max=180, dv=180, k=True)
        cmds.connectAttr(ctrl + '.positive_curvature', sys + '.positive_curvature')
        cmds.addAttr(ctrl, ln='positive_rotate', at='double', min=-10, max=10, dv=0, k=True)
        cmds.connectAttr(ctrl + '.positive_rotate', sys + '.positive_rotate')
        cmds.addAttr(ctrl, ln='positive_scale', at='double', min=0, dv=1, k=True)
        cmds.connectAttr(ctrl + '.positive_scale', sys + '.positive_scale')
        if cmds.listAttr(sys, m=True, st='reverse'):
            cmds.addAttr(ctrl, k=True, ln='reverse', at='enum', en='------:------:')
            cmds.setAttr(ctrl + '.positive', e=True, channelBox=True)
            #
            cmds.addAttr(ctrl, ln='reverse_bend', at='double', min=0, max=10, dv=0, k=True)
            cmds.connectAttr(ctrl + '.reverse_bend', sys + '.reverse_bend')
            cmds.addAttr(
                ctrl, ln='reverse_curvature', at='double', min=-180, max=180, dv=180, k=True)
            cmds.connectAttr(ctrl + '.reverse_curvature', sys + '.reverse_curvature')
            cmds.addAttr(ctrl, ln='reverse_rotate', at='double', min=-10, max=10, dv=0, k=True)
            cmds.connectAttr(ctrl + '.reverse_rotate', sys + '.reverse_rotate')
            cmds.addAttr(ctrl, ln='reverse_scale', at='double', min=0, dv=1, k=True)
            cmds.connectAttr(ctrl + '.reverse_scale', sys + '.reverse_scale')
        cmds.select(ctrl, r=True)


class ThTwoListSequential:
    def __init__(
        self, list_, conListA, conListB, mainCtrl=None, modeSoft='zipper',
        ctrlMethod='soft'):
        """拉鍊"""
        self.list_ = list_
        self.conListA = conListA
        self.conListB = conListB
        self.mainCtrl = mainCtrl
        self.modeSoft = modeSoft
        self.ctrlMethod = ctrlMethod
        # app
        self.appF()

    def appF(self):
        if self.ctrlMethod == 'soft':
            self._softF()
        else:
            self._keyF()

    def _keyF(self):
        # add attr
        if not cmds.listAttr(self.mainCtrl, m=True, st='follow'):
            cmds.addAttr(self.mainCtrl, ln='follow', at='double', min=0, max=10, dv=0, k=True)
        # 約束
        self.conNode = []
        for i, n in enumerate(self.list_):
            node = cmds.parentConstraint(
                [self.conListA[i], self.conListB[i], n], mo=True, weight=1)[0]
            self.conNode.append(node)
        # key
        keyList = []
        for i, con in enumerate(self.conNode):
            keyList.append(f'{con}.{self.conListA[i]}W0')
            keyList.append(f'{con}.{self.conListB[i]}W1')
            #
            cmds.setAttr(f'{con}.{self.conListA[i]}W0', 0)
            cmds.setAttr(f'{con}.{self.conListB[i]}W1', 1)
            cmds.setDrivenKeyframe(
                [f'{con}.{self.conListA[i]}W0', f'{con}.{self.conListB[i]}W1'],
                cd=self.mainCtrl + '.follow', itt='linear', ott='linear')
        offset = 10.0 / len(self.conNode)
        index = 0
        for i, con in enumerate(self.conNode):
            if i < len(self.conNode) - 1:
                index += offset
            else:
                index = 10
            cmds.setAttr(self.mainCtrl + '.follow', index)
            cmds.setAttr(f'{con}.{self.conListA[i]}W0', 1)
            cmds.setAttr(f'{con}.{self.conListB[i]}W1', 0)
            cmds.setDrivenKeyframe(
                keyList, cd=self.mainCtrl + '.follow', itt='linear', ott='linear')

    def _softF(self):
        # 約束
        self.conNode = []
        formula = ''
        for i, n in enumerate(self.list_):
            node = cmds.parentConstraint(
                [self.conListA[i], self.conListB[i], n], mo=True, weight=1)[0]
            self.conNode.append(node)
            formula += '{0}.{1}W1 = 1 - {0}.{2}W0;\n'.format(
                node, self.conListB[i], self.conListA[i])
        cmds.expression(n='TwoListSequential_EX#', s=formula)
        # 創建 soft 控制器
        self.dsl = ThDistanceSoftLocator(
            objs=self.list_, name='TwoListSequential', modeSoft=self.modeSoft)
        for i, con in enumerate(self.conNode):
            cmds.connectAttr(
                self.dsl.locatorList[i] + '.ty', con + '.' + self.conListA[i] + 'W0')
        # 控制 soft
        if self.mainCtrl:
            if not cmds.listAttr(self.mainCtrl, m=True, st='follow'):
                cmds.addAttr(self.mainCtrl, ln='follow', at='double', min=0, max=10, dv=0, k=True)
            if not cmds.listAttr(self.mainCtrl, m=True, st='offset'):
                cmds.addAttr(self.mainCtrl, ln='offset', at='double', min=0, max=10, dv=0, k=True)
            cmds.connectAttr(self.mainCtrl + '.follow', self.dsl.softNode[0][1] + '.follow')
            cmds.connectAttr(self.mainCtrl + '.offset', self.dsl.softNode[0][1] + '.offset1')
            cmds.connectAttr(self.mainCtrl + '.offset', self.dsl.softNode[0][1] + '.offset2')


class ThLimitInformation:
    def __init__(self, objects, attr='tx', data=(-1, 1), en=(0, 0)):
        """限制屬性值工具"""
        self.objects = objects
        self.attr = attr
        self.data = data
        self.en = en
        # app
        appStr = 'cmds.transformLimits("{0}", {1}=self.data, e{1}=self.en)'
        for obj in self.objects:
            eval(appStr.format(obj, self.attr))


class ThDefSoftCtrl:
    def __init__(self, objects, loc, name='obj', rig=True):
        """soft 變形器控制器"""
        self.objects = objects
        self.loc = loc
        self.name = name
        self.rig = rig
        # app
        self._softF()
        self._rigF()

    def _softF(self):
        self.xyz = cmds.xform(self.loc, q=True, ws=True, t=True)
        #
        self.softNode = cmds.softMod(
            self.objects, n='soft#')
        # 設定 soft 軸心
        cmds.setAttr(
            self.softNode[1] + '.scalePivot', *self.xyz)
        cmds.setAttr(
            self.softNode[1] + '.rotatePivot', *self.xyz)
        # 設定權重軸心
        cmds.setAttr(
            self.softNode[0] + '.falloffCenter', *self.xyz)
        # 設定顯示軸心
        cmds.setAttr(
            self.softNode[1] + 'Shape.origin', *self.xyz)

    def _rigF(self):
        if self.rig:
            cto = ThCtrlToObject(
                objList=[self.softNode[1]], name=self.name + '_move', ctrlStyle='cube',
                ctrlMethod='not', ctrlSize=.7, ctrlColor=15, grpLayout=1,
                ifCreateMainGrp=False, adsorptionMode='t')
            cto.createF()
            moveCtrl = cto.newCtrlList[0]
            #
            cto = ThCtrlToObject(
                objList=[self.softNode[1]], name=self.name, ctrlStyle='ball',
                ctrlMethod='connect', ctrlSize=.5, ctrlColor=12, grpLayout=1,
                ifCreateMainGrp=False, adsorptionMode='t')
            cto.createF()
            ctrl = cto.newCtrlList[0]
            #
            cmds.parent(cto.newCtrlGrpList[-1], moveCtrl)
            #
            cmds.addAttr(ctrl, ln='falloffRadius', at='double', min=0, dv=5, k=True)
            cmds.addAttr(ctrl, ln='falloffMode', at='enum', en='volume:surface:', k=True)
            cmds.connectAttr(ctrl + '.falloffRadius', self.softNode[0] + '.falloffRadius')
            cmds.connectAttr(ctrl + '.falloffMode', self.softNode[0] + '.falloffMode')
            #
            ex = ''
            ex += '{}.falloffCenterX = {} + {}.tx;\n'.format(
                self.softNode[0], self.xyz[0], moveCtrl)
            ex += '{}.falloffCenterY = {} + {}.ty;\n'.format(
                self.softNode[0], self.xyz[1], moveCtrl)
            ex += '{}.falloffCenterZ = {} + {}.tz;'.format(
                self.softNode[0], self.xyz[2], moveCtrl)
            cmds.expression(n='{}_dynSoft_EX#'.format(self.name), s=ex)
            #
            cmds.hide(self.softNode[1])
            cmds.select(ctrl, r=True)


class ThExtrudeJoint:
    def __init__(self, joint=None, quantity=2, newJoint=None, parentToFather=False):
        """創建擠壓 joint"""
        self.joint = joint
        self.quantity = quantity
        self.newJoint = newJoint or []
        self.parentToFather = parentToFather
        # add
        self.mainJoints = [self.joint]
        self.ctrlList = []

    def _noteInitF(self):
        """初始化"""
        # 創建主要 grp
        if not cmds.objExists('extrude_data'):
            cmds.group(em=True, n='extrude_data')
            # add
            cmds.addAttr('extrude_data', sn='nts', ln='notes', dt='string')
            # set
            cmds.setAttr('extrude_data.notes', "{}", type='string')
        # 如果有讀入 newJoint quantity 依據 newJoint
        if self.newJoint:
            self.quantity = len(self.newJoint)
        # 找父骨骼
        father = cmds.listRelatives(self.joint, p=True)[0]
        if self.quantity == 2:
            self.mainJoints.append(father)
        else:
            if self.parentToFather:
                self.mainJoints[0] = father

    def createJointF(self):
        """創建 joint"""
        self._noteInitF()
        #
        if not self.newJoint:
            for i in range(self.quantity):
                cmds.select(cl=True)
                self.newJoint.append(cmds.joint(n=self.joint + '_muscle_joint#'))
                # 對位
                ThAdsorptionObj([self.newJoint[i]], self.mainJoints[i], 'tr')
            # freeze
            cmds.makeIdentity(self.newJoint, apply=True, t=True, r=True, s=True, n=False, pn=True)
            #
            cmds.select(self.newJoint, r=True)
        # in data
        dict_ = eval(cmds.getAttr('extrude_data.notes'))
        for i, n in enumerate(self.newJoint):
            dict_[n] = self.mainJoints[i]
        cmds.setAttr('extrude_data.notes', str(dict_), type='string')

    def rigF(self, ctrlSize, meshList):
        """創建控制器"""
        # parent joint
        for i, n in enumerate(self.newJoint):
            cmds.parent(n, self.mainJoints[i])
        # ctrl
        cto = ThCtrlToObject(
            objList=self.newJoint, name=self.joint + '_muscle', ctrlStyle='ball',
            ctrlMethod='constrain', ctrlColor=31, grpLayout=2, ifUseConstrainScale=True,
            ifCreateMainGrp=False, lockHideAttr=[0, 0, 0, 1], ctrlSize=ctrlSize)
        cto.createF()
        self.ctrlList = cto.newCtrlList
        #
        for i, n in enumerate(self.mainJoints):
            # 創建主要權組
            main = n + '_muscle_grp'
            if not cmds.objExists(main):
                cmds.group(em=True, n=main)
                # 對位
                ThAdsorptionObj([main], n, 'tr')
                # constrain ctrl
                cmds.parentConstraint([n, main], mo=True, weight=1)
                cmds.scaleConstraint([n, main], mo=True, weight=1)
                cmds.parent(main, 'extrude_data')
            # parent 到群組
            cmds.parent(cto.newCtrlGrpList[i], main)
            # 找 skin node
            nodeList = thFindSkinNodeF(meshList)
            # add skin
            for node in nodeList:
                cmds.skinCluster(node, e=True, ai=self.newJoint[i], wt=0)
        cmds.select(cl=True)

    def resetSysDataF(self):
        dict_ = eval(cmds.getAttr('extrude_data.notes'))
        joints = list(dict_.keys())
        for j in joints:
            if not cmds.objExists(j):
                dict_.pop(j)
        if dict_:
            cmds.setAttr('extrude_data.notes', str(dict_), type='string')
        else:
            cmds.delete('extrude_data')


class ThSelectWeightVtx:
    def __init__(self):
        """回傳 weight 不為 1 的頂點"""
        # add
        self.sel = cmds.ls(sl=True, fl=True)
        self.joint = []
        self.mesh = []
        self.vtxList = []
        # app
        self._analysisF()
        self._setF()

    def _analysisF(self):
        # 排除名稱有 '.'
        for i, s in enumerate(self.sel):
            if '.' in s:
                self.vtxList.append(s)
            else:
                type = cmds.nodeType(s)
                if type == 'joint':
                    self.joint.append(s)
                else:
                    self.mesh.append(s)
        # 尋找 skin node
        mesh = None
        if self.vtxList:
            mesh = self.vtxList[0].split('.')[0]
        else:
            mesh = self.mesh[0]
            # 判斷 mesh vertex 數量
            vertexNum = cmds.polyEvaluate(mesh, v=True)
            for i in range(vertexNum):
                self.vtxList.append('{}.vtx[{}]'.format(mesh, i))
        self.skinNode = thFindSkinNodeF([mesh])[0]

    def _setF(self):
        newVtx = []
        for vtx in self.vtxList:
            # 讀取 vetex weight
            weight = cmds.skinPercent(self.skinNode, vtx, t=self.joint[0], q=True, v=True)
            # 如果 weight 小於 1 就保存
            if 0 < weight < 1:
                newVtx.append(vtx)
        cmds.select(newVtx, r=True)


class ThTwoListTools:
    def __init__(self, mainList, operationList, mode):
        """兩列表交互操作工具"""
        self.mainList = mainList
        self.operationList = operationList
        self.mode = mode
        #
        self.appDict = {
            'parent': self._parentF,
            'skin': self._skinF,
            'skin select': self._skinSelectF,
            'blendShape': self._blendF,
            'add blendShape': self._addBlendF,
            'wire': self._wireF,
            'adsorption': self._adsorptionF,
            'data transfer': self._dataTransferF,
            'data transfer not': self._dataTransferNotF,
            'vtx transfer': self._vtxTransferF,
            'wrap': self._wrapF,
            'axis adsorption': self._axisAdsorptionF,
            'offsetConnect(inp)': self._offsetConnectInpF,
            'offsetConnect(out)': self._offsetConnectOutF,
            'setToMaterial': self._setToMaterialF,
            'copyCurveShape': self._copyCurveShapeF,
            'xform': self._xformF,
            'objectSorter': self._objectSorterF,
            'checkUVMatch': self._checkUVMatchF,
            'transferConnection': self._transferConnectionF
        }
        #
        if self.mode in self.appDict:
            self.appDict[self.mode]()

    def _transferConnectionF(self):
        for main, operation in zip(self.mainList, self.operationList):
            ThDisconnectConnect().transferF(main, [operation])

    def _checkUVMatchF(self):
        uvc = ThUVComparer(self.mainList)
        uvc.compareMeshListsF(self.operationList)

    def _objectSorterF(self):
        sorter = ThObjectSorter(self.mainList, self.operationList)
        # 執行排序並選取結果
        sorter.applySelection()

    def _xformF(self):
        for main, operation in zip(self.mainList, self.operationList):
            cmds.xform(operation, m=cmds.xform(main, q=True, m=True, ws=True), ws=True)

    def _copyCurveShapeF(self):
        for main, operation in zip(self.mainList, self.operationList):
            copyCurveShapeF(main, operation)

    def _setToMaterialF(self):
        ThSetToMaterial(self.mainList, self.operationList).setF()

    def _offsetConnectOutF(self):
        ThOffsetConnect(self.mainList, self.operationList, mode='out')

    def _offsetConnectInpF(self):
        ThOffsetConnect(self.mainList, self.operationList, mode='inp')

    def _addBlendF(self):
        for main, operation in zip(self.mainList, self.operationList):
            blendShape = thFindBlendShapeNodeF(main)
            if blendShape:
                ThEditBlendShape.addF(blendShape[0], main, [operation])

    def _vtxTransferF(self):
        for main, operation in zip(self.mainList, self.operationList):
            ThSetMeshPoint().applyF(main, operation)

    def _axisAdsorptionF(self):
        for main, operation in zip(self.mainList, self.operationList):
            thEditPivotF([main], operation)

    def _wrapF(self):
        for main, operation in zip(self.mainList, self.operationList):
            cmds.select([operation, main], r=True)
            mel.eval('doWrapArgList "7" {"1","0","1","2","0","1","0"}')

    def _parentF(self):
        for main, operation in zip(self.mainList, self.operationList):
            cmds.parent(operation, main)

    def _blendF(self):
        for main, operation in zip(self.mainList, self.operationList):
            blendNode = cmds.blendShape(main, operation, automatic=True)[0]
            cmds.setAttr(f"{blendNode}.w[0]", 1)

    def _wireF(self):
        for main, operation in zip(self.mainList, self.operationList):
            cmds.wire(operation, gw=False, en=1, ce=0, li=0, w=main)

    def _adsorptionF(self):
        for main, operation in zip(self.mainList, self.operationList):
            ThAdsorptionObj([operation], main, 'tr')

    def _dataTransferF(self):
        thDataTransferF(self.mainList, self.operationList)

    def _dataTransferNotF(self):
        thDataTransferF(self.mainList, self.operationList, False)

    def _skinSelectF(self):
        for main, operation in zip(self.mainList, self.operationList):
            cmds.skinCluster(operation, main, mi=5, dr=4.0, tsb=True)

    def _skinF(self):
        for main, operation in zip(self.mainList, self.operationList):
            cmds.skinCluster(operation, main, mi=5, dr=4.0)


class ThAdsorptionObj:
    def __init__(
        self, objs, main, mode='tr', ifFreeze=False, tangentAim=(0, 1, 0), useActing=False):
        """吸附物件"""
        self.objs = objs
        self.main = main
        self.mode = mode
        self.ifFreeze = ifFreeze
        self.tangentAim = tangentAim
        self.useActing = useActing
        # app
        if useActing:
            grp = cmds.group(em=True)
            self.applyF([grp], main)
            self.applyF(objs, grp)
            cmds.delete(grp)
        else:
            self.applyF(objs, main)

    def applyF(self, objs, main):
        modeDict = {
            't': self._tF, 'r': self._rF, 'tr': self._trF, 'tangent': self._tangentF,
            'vertex': self._vertexF}
        #
        for obj in objs:
            modeDict[self.mode](obj, main)
            cmds.delete(self.node)
        if self.ifFreeze:
            cmds.makeIdentity(objs, apply=True, t=True, r=True, s=True, n=False, pn=True)
        cmds.select(objs)

    def _tF(self, obj, main):
        self.node = cmds.pointConstraint([main, obj], weight=1)

    def _rF(self, obj, main):
        self.node = cmds.orientConstraint([main, obj], weight=1)

    def _trF(self, obj, main):
        self.node = cmds.parentConstraint([main, obj], weight=1)

    def _tangentF(self, obj, main):
        self.node = cmds.tangentConstraint(
            [main, obj], weight=1, worldUpType='vector', aimVector=[1, 0, 0],
            upVector=self.tangentAim, worldUpVector=self.tangentAim)

    def _vertexF(self, obj, main):
        cmds.select([main, obj], r=True)
        self.node = cmds.pointOnPolyConstraint(offset=[0, 0, 0], weight=1)

    def _vertexGF(self, objs, main):
        # 獲取座標
        xyz = cmds.xform(main, q=True, ws=True, t=True)
        # 獲取法線
        faceData = cmds.polyInfo(main, vf=True)[0].split(' ')
        faceData = [n for n in faceData if n]
        normal = cmds.polyInfo('{}.f[{}]'.format(main.split('.')[0], faceData[2]), fn=True)[0][
            :-1].split(' ')
        normal = [n for n in normal if n][2:]
        normal = [float(n) for n in normal]
        # 設置
        for n in objs:
            cmds.xform(n, ws=True, t=xyz)
            cmds.xform(n, ro=normal)


class ThRigCreateCtrl:
    modeAttr1 = ['tz', 'rx', 'ry', 'rz', 'sx', 'sy', 'sz', 'v']
    modeAttr2 = ['tx', 'tz', 'rx', 'ry', 'rz', 'sx', 'sy', 'sz', 'v']
    modeAttr3 = ['ty', 'tz', 'rx', 'ry', 'rz', 'sx', 'sy', 'sz', 'v']
    #
    modeDict = {
        'nine': ['''curve -d 1 -p 0 1 0 -p 1 1 0 -p 1 -1 0 -p -1 -1 0 
                -p -1 1 0 -p 0 1 0 -p 0 -1 0 -p -1 -1 0 
                -p -1 0 0 -p 1 0 0 -k 0 -k 1 -k 2 -k 3 
                -k 4 -k 5 -k 6 -k 7 -k 8 -k 9''', modeAttr1, [(-1, 1), (-1, 1)]], 'six up': ['''curve -d 1 -p 0 1 0 -p -1 1 0 -p -1 0 0 -p 0 0 0 
                -p 0 1 0 -p 1 1 0 -p 1 0 0 -p 0 0 0 
                -k 0 -k 1 -k 2 -k 3 -k 4 -k 5 -k 6 -k 7''', modeAttr1, [(-1, 1), (0, 1)]],
        'six dn': ['''curve -d 1 -p 0 0 0 -p -1 0 0 -p -1 -1 0 -p 0 -1 0 
                -p 0 0 0 -p 1 0 0 -p 1 -1 0 -p 0 -1 0 
                -k 0 -k 1 -k 2 -k 3 -k 4 -k 5 -k 6 -k 7''', modeAttr1, [(-1, 1), (-1, 0)]],
        'six left': ['''curve -d 1 -p 0 0 0 -p 0 1 0 -p -1 1 0 -p -1 0 0 
                -p 0 0 0 -p 0 -1 0 -p -1 -1 0 -p -1 0 0 
                -k 0 -k 1 -k 2 -k 3 -k 4 -k 5 -k 6 -k 7''', modeAttr1, [(-1, 0), (-1, 1)]],
        'six right': ['''curve -d 1 -p 0 0 0 -p 0 1 0 -p 1 1 0 -p 1 0 0 
                -p 0 0 0 -p 0 -1 0 -p 1 -1 0 -p 1 0 0 
                -k 0 -k 1 -k 2 -k 3 -k 4 -k 5 -k 6 -k 7''', modeAttr1, [(0, 1), (-1, 1)]],
        'up dn': ['''curve -d 1 -p -0.200587 1 0 -p 0.200587 1 0 
                -p 0.200587 0 0 -p -0.200587 0 0 -p 0.200587 0 0 
                -p 0.200587 -1 0 -p -0.200587 -1 0 
                -p -0.200587 1 0 
                -k 0 -k 1 -k 2 -k 3 -k 4 -k 5 -k 6 -k 7
            ''', modeAttr2, [(0, 0), (-1, 1)]], 'left right': ['''curve -d 1 -p -1 0.200587 0 -p -1 -0.200587 0 
                -p 0 -0.200587 0 -p 0 0.200587 0 -p 0 -0.200587 0 
                -p 1 -0.200587 0 -p 1 0.200587 0 -p -1 0.200587 0 
                -k 0 -k 1 -k 2 -k 3 -k 4 -k 5 -k 6 -k 7 ;
            ''', modeAttr3, [(-1, 1), (0, 0)]], 'up': ['''curve -d 1 -p -0.200587 1 0 -p -0.200587 0 0 
                -p 0.200587 0 0 -p 0.200587 1 0 -p -0.200587 1 0 
                -k 0 -k 1 -k 2 -k 3 -k 4''', modeAttr2, [(0, 0), (0, 1)]], 'dn': ['''curve -d 1 -p -0.200587 0 0 -p -0.200587 -1 0 
                -p 0.200587 -1 0 -p 0.200587 0 0 -p -0.200587 0 0 
                -k 0 -k 1 -k 2 -k 3 -k 4''', modeAttr2, [(0, 0), (-1, 0)]], 'left': ['''curve -d 1 -p 0 0.200587 0 -p -1 0.200587 0 
                -p -1 -0.200587 0 -p 0 -0.200587 0 -p 0 0.200587 0 
                -k 0 -k 1 -k 2 -k 3 -k 4''', modeAttr3, [(-1, 0), (0, 0)]], 'right': ['''curve -d 1 -p 0 0.200587 0 -p 1 0.200587 0 
                -p 1 -0.200587 0 -p 0 -0.200587 0 -p 0 0.200587 0 
                -k 0 -k 1 -k 2 -k 3 -k 4''', modeAttr3, [(0, 1), (0, 0)]]}
    #
    mainGrp = None
    txtGrp = None
    ctrlName = None
    ctrlNameGrp = None

    def __init__(self, name, mode, rotateList=(0, 0, 0), scale=2):
        """創建拉霸控制器.
        :type mode: str
            'nine' |
            'six_up' | 'six_dn' | 'six_left' | 'six_right' |
            'up_dn' | 'left_right' |
            'up' | 'dn' | 'left' | 'right'
        """
        self.name = name
        self.mode = mode
        self.rotateList = rotateList
        self.scale = scale
        # app
        self.appF()

    def appF(self):
        # 是否增加數字序列號
        addNum = '#' if cmds.objExists(f'{self.name}_ctrl_main_grp') else ''
        # create group
        self.mainGrp = cmds.group(em=True, n=f'{self.name}_ctrl_main_grp{addNum}')
        self.txtGrp = cmds.group(em=True, n=f'{self.name}_ctrl_txt_grp{addNum}')
        cmds.setAttr(f'{self.txtGrp}.template', 1)
        cmds.parent(self.txtGrp, self.mainGrp)
        # create ctrl
        self.ctrlName = cmds.circle(
            n=f'{self.name}_ctrl{addNum}',
            c=(0, 0, 0), nr=(0, 0, 1), sw=360, r=0.2, d=3, ut=False, tol=0.01, s=8, ch=False)[0]
        self.ctrlNameGrp = cmds.group(self.ctrlName, n=f'{self.ctrlName}_grp{addNum}')
        cmds.parent(self.ctrlNameGrp, self.mainGrp)
        # color
        thSetCtrlColorF([self.ctrlName], 22)
        # 鎖定屬性
        for attr in self.modeDict[self.mode][1]:
            cmds.setAttr(f'{self.ctrlName}.{attr}', lock=True)
            cmds.setAttr(f'{self.ctrlName}.{attr}', keyable=True)
            cmds.setAttr(f'{self.ctrlName}.{attr}', keyable=False, channelBox=False)
        # 限制
        cmds.transformLimits(
            self.ctrlName, tx=self.modeDict[self.mode][2][0], ty=self.modeDict[self.mode][2][1])
        cmds.transformLimits(self.ctrlName, etx=(True, True), ety=(True, True))
        # 參考現
        tx1Name = mel.eval(self.modeDict[self.mode][0])
        tx1Name = cmds.rename(tx1Name, f'{self.name}_txt{addNum}')
        cmds.parent(tx1Name, self.txtGrp)
        #
        cmds.rotate(self.rotateList[0], self.rotateList[1], self.rotateList[2], self.mainGrp)
        cmds.scale(self.scale, self.scale, self.scale, self.mainGrp)
        cmds.select(self.mainGrp, r=True)


class ThLockJointWeight:
    def __init__(self, objects, mode):
        """鎖定骨骼權重編輯.
        :type mode: str
            'lock' | 'nulock'
        """
        self.objects = objects
        self.mode = mode
        #
        self._analysisF()
        self._addJointF()
        self._setF()
        # 選擇物件中，有 vtx 就選擇
        if self.ifVtx:
            cmds.select(objects, r=True)
        else:
            cmds.select(self.meshList, r=True)

    def _analysisF(self):
        """分析選擇物件"""
        self.meshList = []
        self.jointList = []
        # 如果選擇的物件中有 vtx
        # 就只採用前中一個 mesh
        mesh = None
        self.ifVtx = False  # 選擇物件中，有無 vtx
        for obj in self.objects:
            if '.' in obj:
                mesh = obj.split('.')[0]
                self.ifVtx = True
                break
        if mesh:
            self.meshList.append(mesh)
        else:
            typeList = thTypeF(self.objects)
            for i, type in enumerate(typeList):
                if type == 'mesh':
                    self.meshList.append(self.objects[i])
                elif type == 'joint':
                    self.jointList.append(self.objects[i])

    def _addJointF(self):
        self.skinJoints = []
        for m in self.meshList:
            # 找 joints
            skinJoints = thFindSkinJointF([m])
            self.skinJoints.extend(skinJoints)
            # 如果 joint 不在列表 就添加
            for j in self.jointList:
                if not j in skinJoints:
                    cmds.skinCluster(m, e=True, wt=0, ai=j)
                    self.skinJoints.append(j)

    def _setF(self):
        # 找 skin node
        skinList = thFindSkinNodeF(self.meshList)
        # 規格化權重
        for j in self.skinJoints:
            cmds.setAttr(j + '.liw', 0)
        for i, skin in enumerate(skinList):
            if cmds.getAttr(skin + '.normalizeWeights') != 1:
                cmds.setAttr(skin + '.normalizeWeights', 1)
                cmds.skinPercent(skin, self.meshList[i], normalize=True)
        # 產生設定資料
        app = True if self.mode == 'lock' else False
        appDict = {}
        for j in self.skinJoints:
            appDict[j] = app
        for j in self.jointList:
            appDict[j] = False if appDict[j] else True
        # set
        for j in self.skinJoints:
            try:
                cmds.setAttr(j + '.liw', appDict[j])
            except RuntimeError:
                pass


class ThRigMouth:
    """拉鍊嘴型"""

    def __init__(
        self, upLeft, upRight, downLeft, downRight, head, jaw, jawCtrl, ctrlMode,
        mouthCorner=None, isGrp=True, isCtrl=True, ctrlStyle='hexagon', ctrlAxial='z',
        centerRefLoc=None, replaceStr='_joint', combineCtrlLocList1=None,
        combineCtrlLocList2_1=None, combineCtrlLocList2_2=None, precludeUpList=None,
        precludeDnList=None):
        self.mouthCorner = mouthCorner
        self.upLeft = upLeft
        self.upRight = upRight
        self.downLeft = downLeft
        self.downRight = downRight
        self.head = head
        self.jaw = jaw
        self.jawCtrl = jawCtrl
        self.ctrlMode = ctrlMode
        self.isGrp = isGrp
        self.isCtrl = isCtrl
        self.ctrlStyle = ctrlStyle
        self.ctrlAxial = ctrlAxial
        self.centerRefLoc = centerRefLoc
        self.replaceStr = replaceStr
        self.combineCtrlLocList1 = combineCtrlLocList1
        self.combineCtrlLocList2_1 = combineCtrlLocList2_1
        self.combineCtrlLocList2_2 = combineCtrlLocList2_2
        self.precludeUpList = precludeUpList
        self.precludeDnList = precludeDnList
        # 獲取執行列表
        self.doUpRight = self.upRight
        self.doUpLeft = self._getDoLeftListF(self.upLeft, self.upRight)
        self.doDnRight = self.downRight
        self.doDnLeft = self._getDoLeftListF(self.downLeft, self.downRight)
        self.doList = self.doUpLeft[0] + self.doUpRight + self.doDnLeft[0] + self.doDnRight
        self.precludeAllUpId = []
        self.precludeAllDnId = []
        # 獲取排除物件 id
        self.precludeAllUpId = [i for i, n in enumerate(self.doList) if n in self.precludeUpList]
        self.precludeAllDnId = [i for i, n in enumerate(self.doList) if n in self.precludeDnList]
        self.precludeUpId = \
            [i for i, n in enumerate(self.doUpLeft[0] + self.doUpRight) if n in self.precludeUpList]
        self.precludeDnId = \
            [i for i, n in enumerate(self.doDnLeft[0] + self.doDnRight) if n in self.precludeDnList]
        # apply
        self.applyF()

    def applyF(self):
        # 創建主要 locator
        self._inLocF()
        # 創建控制器
        if self.isCtrl:
            self._ctrlF()
        # 創建層級 locator
        if self.isGrp:
            self._locGrpF()
        # 創建控制器
        self._rigF()
        # 創建權重控制器1
        if self.combineCtrlLocList1:
            self._mainCtrlF(
                list_=self.combineCtrlLocList1, doCtrlList=self.doCtrlList,
                precludeId=self.precludeAllUpId + self.precludeAllDnId, p2=self.sysGrp)
        # 創建權重控制器2
        if self.combineCtrlLocList2_1:
            self._mainCtrlF(
                self.combineCtrlLocList2_1, self.doUpCtrlList, self.precludeUpId,
                'triangle', 6, self.sysGrp)
        if self.combineCtrlLocList2_2:
            self._mainCtrlF(
                self.combineCtrlLocList2_2, self.doDnCtrlList, self.precludeDnId,
                'triangle', 6, self.jawCtrl)
        cmds.select(self.jawCtrl, r=True)

    def _mainCtrlF(
        self, list_, doCtrlList, precludeId, ctrlStyle='hexagon', ctrlColor=22, p2=None):
        if doCtrlList:
            # 創建控制器
            self.cto = ThCtrlToObject(
                objList=list_, ctrlColor=ctrlColor, ctrlMethod='None', ifUseObjName=True,
                replaceStr=self.replaceStr, ctrlAxial=self.ctrlAxial, ifParent=False,
                ifCreateMainGrp=False, ctrlStyle=ctrlStyle)
            self.cto.createF()
            newCtrlList = self.cto.newCtrlList
            newCtrlGrpList = self.cto.newCtrlGrpList
            ctrlGrp = cmds.group(newCtrlGrpList, n='main_mouth_ctrl_grp#')
            # 少數控制多數
            doCtrlList = [n for i, n in enumerate(doCtrlList) if i not in precludeId]
            locList = ThDuplicateWithoutChildrenCon(thLocatorGrpF(doCtrlList)).createConLocF()
            locGrp = cmds.group(locList[1], n='mouth_main_loc_grp#')
            cmds.hide(locGrp)
            jointList = thWeightToCtrlF(newCtrlList, locList[0])
            # parent
            mainGrp = cmds.group(em=True, n='main_mouth_sys_grp#')
            cmds.parent(mainGrp, p2)
            cmds.parent([ctrlGrp, locGrp], mainGrp)
            # 創建 lo poly
            ThCoordinateCreateMeshLocal(objList=jointList, axis='y', offset=.1, loop=False)

    def _getDoLeftListF(self, lList, rList):
        """回傳左邊列表"""
        if rList[-1] in lList:
            isSplit = True
            doLeftList = lList[:-1]
        else:
            isSplit = False
            doLeftList = lList
        return [doLeftList, isSplit]

    def _inLocF(self):
        # 創建 locator
        lo = cmds.spaceLocator(n='in_jaw_locator#')[0]
        loGrp = cmds.group(lo, n='in_jaw_locator_grp#')
        head = cmds.spaceLocator(n='head_locator#')[0]
        headGrp = cmds.group(head, n='head_locator_grp#')
        jaw = cmds.spaceLocator(n='jaw_locator#')[0]
        jawGrp = cmds.group(jaw, n='jaw_locator_grp#')
        self.locMainGrp = cmds.group([loGrp, headGrp, jawGrp], n='mouthZipperLocator_grp#')
        cmds.hide(self.locMainGrp)
        # 對位
        ThAdsorptionObj([loGrp], self.jaw, 't')
        ThAdsorptionObj([headGrp], self.head, 't')
        ThAdsorptionObj([jawGrp], self.jaw, 't')
        # constrain
        cmds.parentConstraint([self.jaw, lo], mo=True, weight=1)
        cmds.parentConstraint([self.head, head], mo=True, weight=1)
        cmds.parentConstraint([self.jaw, jaw], mo=True, weight=1)
        # key
        keyAttr = ['tx', 'ty', 'tz', 'rx', 'ry', 'rz']
        jawKeyAttr = [lo + '.' + n for n in keyAttr]
        cmds.setDrivenKeyframe(jawKeyAttr, cd=lo + '.v', itt='linear', ott='linear')
        # set attr
        cmds.setAttr(lo + '.blendParent1', .5)
        self.inJaw = [lo, head, jaw]

    def _doCtrlF(self, color, list_):
        # 先操作右邊
        self.cto.objList = list_
        self.cto.ctrlColor = color
        self.cto.createF()
        ctrl = self.cto.newCtrlList
        ctrlGrp = self.cto.newCtrlGrpList
        return [ctrl, ctrlGrp]

    def _ctrlF(self):
        # 實例化控制器模組
        self.cto = ThCtrlToObject(
            objList=[], ifUseObjName=True, replaceStr=self.replaceStr,
            ctrlStyle=self.ctrlStyle, ctrlAxial=self.ctrlAxial, ifParent=False,
            ifCreateMainGrp=False)
        # 創建控制器
        self.doUpLeft[0], doUpLeftGrp = self._doCtrlF(14, self.doUpLeft[0])
        self.doUpRight, doUpRightGrp = self._doCtrlF(14, self.doUpRight)
        self.doDnLeft[0], doDnLeftGrp = self._doCtrlF(14, self.doDnLeft[0])
        self.doDnRight, doDnRightGrp = self._doCtrlF(14, self.doDnRight)
        self.doUpCtrlList = self.doUpLeft[0] + self.doUpRight
        self.doDnCtrlList = self.doDnLeft[0] + self.doDnRight
        self.doCtrlList = self.doUpLeft[0] + self.doUpRight + self.doDnLeft[
            0] + self.doDnRight
        self.doCtrlListGrp = doUpLeftGrp + doUpRightGrp + doDnLeftGrp + doDnRightGrp
        # 主要控制器群組列表
        ctrlMainGrp = doUpRightGrp + doUpLeftGrp + doDnRightGrp + doDnLeftGrp
        # 創建嘴角控制器
        if self.mouthCorner:
            self.cto.objList = self.mouthCorner
            self.cto.ctrlColor = 6
            self.cto.createF()
            self.mouthCorner = self.cto.newCtrlList
            ctrlMainGrp.extend(self.cto.newCtrlGrpList)
        # 創建次要控制器群組
        self.ctrlMainGrp = cmds.group(ctrlMainGrp, n='mouthZipperCtrl_grp#')
        cmds.xform(self.ctrlMainGrp, cp=True)
        # 創建主要控制器
        self.cto = ThCtrlToObject(
            objList=[self.centerRefLoc if self.centerRefLoc else self.ctrlMainGrp],
            ifUseObjName=False, name='mouth_main', ctrlStyle='hexagon',
            ctrlAxial=self.ctrlAxial, ifParent=False, ifCreateMainGrp=False, ctrlColor=13,
            ctrlMethod='constrain' if self.centerRefLoc else 'not')
        self.cto.createF()
        self.mainRotateCtrl = self.cto.newCtrlList[0]
        self.mainRotateCtrlGrp = self.cto.newCtrlGrpList[0]
        # 與子控制器建立 parent
        cmds.parent(self.ctrlMainGrp, self.mainRotateCtrl)
        # 創建下顎控制器
        self.cto = ThCtrlToObject(
            objList=[self.jaw], ifUseObjName=True, replaceStr=self.replaceStr, ctrlColor=13,
            ctrlStyle='triangle', ctrlAxial=self.ctrlAxial, ifParent=False,
            ifCreateMainGrp=False)
        self.cto.createF()
        self.jawCtrl = self.cto.newCtrlList[0]
        self.jawCtrlGrp = self.cto.newCtrlGrpList[0]
        # 創建主要群組
        self.sysGrp = cmds.group(
            [self.locMainGrp, self.mainRotateCtrlGrp, self.jawCtrlGrp],
            n='mouthZipperSystem_grp#')
        # 設定主要嘴唇控制排除臉頰控制器
        if self.precludeUpList and self.precludeDnList:
            grp = cmds.group(em=True, n='cheek_main_ctrl_grp#')
            cmds.parent(grp, self.mainRotateCtrlGrp)
            pUpCtrlGrp = \
                [n for i, n in enumerate(self.doCtrlListGrp) if i in self.precludeAllUpId]
            pDnCtrlGrp = \
                [n for i, n in enumerate(self.doCtrlListGrp) if i in self.precludeAllDnId]
            cmds.parent(pUpCtrlGrp + pDnCtrlGrp, grp)

    def _locGrpF(self):
        self.doUpLeft[0], upLeftLocGrp = ThDuplicateWithoutChildrenCon(
            thLocatorGrpF(self.doUpLeft[0])).createConLocF()
        self.doUpRight, upRightLocGrp = ThDuplicateWithoutChildrenCon(
            thLocatorGrpF(self.doUpRight)).createConLocF()
        self.doDnLeft[0], downLeftLocGrp = ThDuplicateWithoutChildrenCon(
            thLocatorGrpF(self.doDnLeft[0])).createConLocF()
        self.doDnRight, downRightLocGrp = ThDuplicateWithoutChildrenCon(
            thLocatorGrpF(self.doDnRight)).createConLocF()
        # 創建 grp
        locGrpList = upLeftLocGrp + upRightLocGrp + downLeftLocGrp + downRightLocGrp
        locMainGrp = cmds.group(locGrpList, n='mouthConZipperLocator_grp#')
        cmds.parent(locMainGrp, self.locMainGrp)
        cmds.hide(locMainGrp)
        # 設定排除
        if self.precludeUpList and self.precludeDnList:
            grp = cmds.group(em=True, n='cheek_main_loc_grp#')
            cmds.parent(grp, self.mainRotateCtrlGrp)
            cmds.hide(grp)
            pUpLocGrp = [n for i, n in enumerate(locGrpList) if i in self.precludeAllUpId]
            pDnLocGrp = [n for i, n in enumerate(locGrpList) if i in self.precludeAllDnId]
            cmds.parent(pUpLocGrp + pDnLocGrp, grp)

    def _rigF(self):
        # 控制中間物件
        if not cmds.listAttr(self.jawCtrl, m=True, st='up_down'):
            cmds.addAttr(self.jawCtrl, ln='up_down', at='double', min=0, max=1, dv=.5, k=True)
        cmds.connectAttr(self.jawCtrl + '.up_down', self.inJaw[0] + '.blendParent1')
        # 約束嘴角
        if self.mouthCorner:
            for corner in self.mouthCorner:
                cmds.parentConstraint([self.inJaw[0], corner], mo=True, w=1)
        # up left
        ThTwoObjCtrl(
            self.inJaw[0], self.inJaw[1],
            self.doUpLeft[0] + [self.doUpRight[-1]] if self.doUpLeft[1] else self.doUpLeft[0],
            self.jawCtrl, self.ctrlMode, self.doUpLeft[1], 'L_follow', 'L_offset')
        # up right
        ThTwoObjCtrl(
            self.inJaw[0], self.inJaw[1], self.doUpRight, self.jawCtrl, self.ctrlMode, False,
            'R_follow', 'R_offset')
        # down left
        ThTwoObjCtrl(
            self.inJaw[0], self.inJaw[2],
            self.doDnLeft[0] + [self.doDnRight[-1]] if self.doDnLeft[1] else self.doDnLeft[0],
            self.jawCtrl, self.ctrlMode, self.doDnLeft[1], 'L_follow', 'L_offset')
        # down left
        ThTwoObjCtrl(
            self.inJaw[0], self.inJaw[2], self.doDnRight, self.jawCtrl, self.ctrlMode, False,
            'R_follow', 'R_offset')
        # 設定排除
        if self.precludeUpList and self.precludeDnList:
            locList = self.doUpLeft[0] + self.doUpRight + self.doDnLeft[0] + self.doDnRight
            pUpLoc = [n for i, n in enumerate(locList) if i in self.precludeAllUpId]
            pDnLoc = [n for i, n in enumerate(locList) if i in self.precludeAllDnId]
            pAllLoc = pUpLoc + pDnLoc
            keyList = [f'{n}.{nn}' for n in pAllLoc for nn in ['tx', 'ty', 'tz', 'rx', 'ry', 'rz']]
            cmds.setDrivenKeyframe(
                keyList, cd='{}.v'.format(self.sysGrp), itt='linear', ott='linear')
            # add attr
            cmds.addAttr(self.jawCtrl, ln='cheek_weight', at='double', min=0, max=1, dv=1, k=True)
            for n in pAllLoc:
                cmds.connectAttr(
                    '{}.cheek_weight'.format(self.jawCtrl), '{}.blendParent1'.format(n))


class ThTwoObjWeightBlend:
    def __init__(
        self, mainObjList, refObj, mainJointList, refJointList=None, om2=False,
        doPruneWeightsArgList=False):
        """拆分權重值"""
        self.refObj = refObj
        self.mainObjList = mainObjList
        self.refJointList = refJointList if refJointList else thFindSkinJointF([refObj])
        self.mainJointList = mainJointList
        self.om2 = om2
        self.doPruneWeightsArgList = doPruneWeightsArgList
        # app
        self.applyF()

    def applyF(self):
        # 使用進度條
        progressBar = ThUiProgressBar(1)
        progressBar.show()
        progressBar.setStratF(0, '', len(self.mainObjList))
        #
        for mainObj in self.mainObjList:
            progressBar.setFrameF(0, mainObj)
            # 讀取 skin node
            self.mainSkin = thFindSkinNodeF([mainObj])[0]
            # 歸一化
            cmds.skinCluster(self.mainSkin, e=True, fnw=True, normalizeWeights=1)
            cmds.setAttr(self.mainSkin + '.maintainMaxInfluences', 0)
            # 添加 joint
            self._addJointF(mainObj)
            # 解開 joint lock
            ThLockJointWeight([mainObj], 'nulock')
            # 設定權重
            self._copyRefF(mainObj)
            if self.om2:
                self._setWeightOm2F(mainObj)
            else:
                self._setWeightMelF()
            cmds.delete(self.refObjCopy)
        cmds.select(self.mainObjList, r=True)
        # 減去最小權重
        if self.doPruneWeightsArgList:
            ThCopyWeightApi().clearMinF(self.mainObjList)
        progressBar.close()

    def _setWeightMelF(self):
        for mainJoint in self.mainJointList:
            self._getF(mainJoint)
            self._setF(mainJoint)

    def _setWeightOm2F(self, mainObj):
        # 獲取主要型權重
        mainCwa = ThCopyWeightApi()
        mainCwa.getWeightDataF(mainObj)
        # 獲取新模型權重
        refCwa = ThCopyWeightApi()
        refCwa.getWeightDataF(self.refObjCopy)
        # 循環主要骨骼
        for mainJoint in self.mainJointList:
            # 主要 joint 的 weight 範圍
            cmds.select(cl=True)
            cmds.skinCluster(self.mainSkin, e=True, siv=mainJoint)
            self.mainVtxList = cmds.ls(sl=True, fl=True)
            if not '.' in ''.join(self.mainVtxList):
                continue
            # 取得編輯頂點序列號
            idList = [int(n.split('.')[1][4:-1]) for n in self.mainVtxList]
            # 拷貝數據避免被修改
            baseDataDict = copy.deepcopy(mainCwa.dataDict)
            # 是否轉移剩下權重
            refJointList = []
            ifMoveFinallyWeight = None
            if mainJoint in self.refJointList:
                refJointList = [n for n in self.refJointList if n != mainJoint]
                ifMoveFinallyWeight = False
            else:
                refJointList = self.refJointList[:-1]
                ifMoveFinallyWeight = True
            # 循環 ref 骨骼
            for refJoint in refJointList:
                # 循環頂點
                idListData = []
                for id in idList:
                    # 取得骨骼權重值
                    idListData.append(refCwa.dataDict[refJoint][id] * baseDataDict[mainJoint][id])
                # 轉移權重
                mainCwa.editWeightDataF(
                    idList=idList, idListData=idListData, joint=refJoint,
                    otherJointList=[mainJoint])
            if ifMoveFinallyWeight:
                # 轉移剩下的權重
                mainCwa.editWeightDataF(
                    idList=idList, idListData=[0] * len(idList), joint=mainJoint,
                    otherJointList=[self.refJointList[-1]])
            # 設定權重
            mainCwa.setWeightDataF()

    def _addJointF(self, mainObj):
        """添加 joint"""
        mainJointList = thFindSkinJointF([mainObj])
        for joint in self.refJointList:
            if not joint in mainJointList:
                cmds.skinCluster(self.mainSkin, e=True, lw=True, wt=0, ai=joint)

    def _copyRefF(self, mainObj):
        """複製新權重模型"""
        self.refObjCopy = cmds.duplicate(mainObj, rr=True, rc=True)[0]
        # copy weight
        refObjSize = cmds.polyEvaluate(self.refObj, v=True)
        refObjCopySize = cmds.polyEvaluate(self.refObjCopy, v=True)
        if self.om2 and refObjSize == refObjCopySize:
            ThCopyWeightApi().copyWeightF(self.refObj, self.refObjCopy)
        else:
            tcsaw = ThCopySkinAndWeight([self.refObj], [self.refObjCopy])
            tcsaw.copySkinF()
            tcsaw.copyWeightF()
            tcsaw.setMaxInfluencesF()
        # 讀取 skin node
        self.copyMainSkin = thFindSkinNodeF([self.refObjCopy])[0]

    def _getF(self, mainJoint):
        # 主要 joint 的 weight 範圍
        cmds.select(cl=True)
        cmds.skinCluster(self.mainSkin, e=True, siv=mainJoint)
        self.mainVtxList = cmds.ls(sl=True, fl=True)
        # get main weighr
        self.mainWeightList = []
        for i, vtx in enumerate(self.mainVtxList):
            self.mainWeightList.append(
                cmds.skinPercent(self.mainSkin, vtx, t=mainJoint, q=True, v=True))

    def _setF(self, mainJoint):
        # 產生新頂點列表數據
        refVtxList = []
        for n in self.mainVtxList:
            refVtxList.append('{}.{}'.format(self.refObjCopy, n.split('.')[1]))
        # 讀取 ref weight，確認循環次數, 到達最後 1 次, 直接轉移剩下 weight
        refList0 = []  # [vtx[joint,weight]]
        for vtx in refVtxList:
            refList1 = []
            for joint in self.refJointList:
                # 讀取 ref weight 多少
                refWeight = cmds.skinPercent(self.copyMainSkin, vtx, t=joint, q=True, v=True)
                # 排除權重為 0 的 joint
                if refWeight:
                    refList1.append([joint, refWeight])
            refList0.append(refList1)
        # 轉移 weight
        # 使用進度條
        for i, vtx in enumerate(refVtxList):
            for ii, jointWeight in enumerate(refList0[i], 1):
                # 讀取現在 weight 剩多少
                mainWeight = cmds.skinPercent(
                    self.mainSkin, self.mainVtxList[i], t=mainJoint, q=True, v=True)
                mainWeightR = cmds.skinPercent(
                    self.mainSkin, self.mainVtxList[i], t=jointWeight[0], q=True, v=True)
                # 到達最後 1 次, 直接轉移剩下 weight
                jointData = None
                mainJointData = None
                if len(refList0[i]) != ii:
                    jointData = self.mainWeightList[i] * jointWeight[1]
                    mainJointData = mainWeight - jointData
                    jointData += mainWeightR
                else:
                    jointData = mainWeight + mainWeightR
                    mainJointData = 0
                #
                cmds.skinPercent(
                    self.mainSkin, self.mainVtxList[i],
                    tv=[(jointWeight[0], jointData), (mainJoint, mainJointData)])


class ThAffectSystemList:
    ui = 'th_affectSystemList_{}_ui'

    def __init__(self):
        # add
        self.sysDict = None
        # app
        self.createF()

    def createF(self):
        if cmds.objExists('affectSystem_data'):
            if cmds.window(self.ui.format('main'), ex=True):
                cmds.deleteUI(self.ui.format('main'))
            cmds.window(self.ui.format('main'), title='list')
            cmds.formLayout(self.ui.format('form'), w=400)
            cmds.textScrollList(
                self.ui.format('list'), h=150, ams=True, sc=lambda *args: self._selectListObjF(),
                dcc=lambda *args: self._labelToUiF())
            cmds.button(self.ui.format('del'), h=20, l='delete', c=lambda *args: self._delF())
            cmds.button(
                self.ui.format('start'), h=20, l='to start pose',
                c=lambda *args: self._toPoseF('start'))
            cmds.button(
                self.ui.format('end'), h=20, l='to end pose', c=lambda *args: self._toPoseF('end'))
            cmds.textScrollList(
                self.ui.format('objs'), h=150, ams=True,
                sc=lambda *args: self._selectListObj2F('objs'))
            cmds.textScrollList(
                self.ui.format('ctrl'), h=150, ams=True,
                sc=lambda *args: self._selectListObj2F('ctrl'))
            # show ui
            cmds.showWindow(self.ui.format('main'))
            # edit form layout
            self._setMainFormEuiF()
            # 寫入列表
            self._inputF()

    def _setMainFormEuiF(self):
        ac_ = []
        an_ = []
        af_ = []
        ap_ = []
        #
        af_.append([self.ui.format('list'), 'top', 2])
        ac_.append([self.ui.format('list'), 'bottom', 5, self.ui.format('del')])
        af_.append([self.ui.format('list'), 'left', 2])
        ap_.append([self.ui.format('list'), 'right', 2, 40])
        #
        an_.append([self.ui.format('del'), 'top'])
        ac_.append([self.ui.format('del'), 'bottom', 5, self.ui.format('start')])
        af_.append([self.ui.format('del'), 'left', 2])
        ap_.append([self.ui.format('del'), 'right', 2, 40])
        #
        an_.append([self.ui.format('start'), 'top'])
        af_.append([self.ui.format('start'), 'bottom', 2])
        af_.append([self.ui.format('start'), 'left', 2])
        ap_.append([self.ui.format('start'), 'right', 2, 20])
        #
        an_.append([self.ui.format('end'), 'top'])
        af_.append([self.ui.format('end'), 'bottom', 2])
        ap_.append([self.ui.format('end'), 'left', 2, 20])
        ap_.append([self.ui.format('end'), 'right', 2, 40])
        #
        af_.append([self.ui.format('objs'), 'top', 2])
        ap_.append([self.ui.format('objs'), 'bottom', 2, 50])
        ap_.append([self.ui.format('objs'), 'left', 2, 40])
        af_.append([self.ui.format('objs'), 'right', 2])
        #
        ap_.append([self.ui.format('ctrl'), 'top', 2, 50])
        af_.append([self.ui.format('ctrl'), 'bottom', 2])
        ap_.append([self.ui.format('ctrl'), 'left', 2, 40])
        af_.append([self.ui.format('ctrl'), 'right', 2])
        #
        cmds.formLayout(self.ui.format('form'), e=True, af=af_, ac=ac_, an=an_, ap=ap_)

    def _inputF(self):
        """寫入列表"""
        # get system
        if cmds.objExists('affectSystem_data'):
            sysStr = cmds.getAttr('affectSystem_data.notes')
            self.sysDict = eval(sysStr)
            #
            cmds.textScrollList(self.ui.format('list'), e=True, ra=True)
            cmds.textScrollList(self.ui.format('objs'), e=True, ra=True)
            cmds.textScrollList(self.ui.format('ctrl'), e=True, ra=True)
            #
            label = list(self.sysDict['label'].keys())
            label.sort()
            for n in label:
                cmds.textScrollList(self.ui.format('list'), e=True, a=n)
        else:
            cmds.deleteUI(self.ui.format('main'))

    def _selectListObjF(self):
        """選擇列表物件"""
        # 選擇的列表
        labelList = cmds.textScrollList(
            self.ui.format('list'), q=True, si=True)
        label = labelList[0]
        # 選擇到 ctrl
        ctrlList = []
        for n in labelList:
            ctrlList.extend(self.sysDict['label'][n]['ctrl'])
        ctrlList = list(set(ctrlList))
        cmds.select(ctrlList, r=True)
        # 資料寫入 list2
        cmds.textScrollList(self.ui.format('objs'), e=True, ra=True)
        for n in self.sysDict['label'][label]['objs']:
            cmds.textScrollList(self.ui.format('objs'), e=True, a=n)
        # 資料寫入 list2 grp
        cmds.textScrollList(self.ui.format('ctrl'), e=True, ra=True)
        for n in self.sysDict['label'][label]['ctrl']:
            cmds.textScrollList(self.ui.format('ctrl'), e=True, a=n)

    def _selectListObj2F(self, ui):
        """選擇列表物件"""
        # 選擇的列表
        selList = cmds.textScrollList(
            self.ui.format(ui), q=True, si=True)
        cmds.select(selList, r=True)

    def _delF(self):
        """刪除指定物件"""
        # 選擇的列表
        label = cmds.textScrollList(
            self.ui.format('list'), q=True, si=True)
        ThAffectSystem().deleteAttrF(label)
        # 刷新列表
        self._inputF()

    def _toPoseF(self, mode):
        # 選擇的列表
        label = cmds.textScrollList(
            self.ui.format('list'), q=True, si=True)
        ThAffectSystem().setCtrlF(mode, label)

    def _labelToUiF(self):
        label = cmds.textScrollList(
            self.ui.format('list'), q=True, si=True)[0]
        ui = 'th_rig_affectSystem_{}_ui'
        cmds.textField(ui.format('labelName'), e=True, tx=label)


class ThDrivenKeySystem:
    sys = 'drivenKeySystem_data'

    def __init__(self, ctrlAttr=None, objects=None, attrList=None, isGrp=True, isPrefix=True):
        """Driven key system"""
        self.ctrlAttr = ctrlAttr
        self.objects = objects
        self.attrList = attrList
        self.isGrp = isGrp
        self.isPrefix = isPrefix

    def appF(self):
        # 創建紀錄用 grp
        self._sysF()
        # 創建 group
        self._grpF()
        # 設置 key
        self._keyF()
        # select
        cmds.select(self.selectObj, r=True)

    def reDataF(self):
        """刷新數據"""
        data = eval(cmds.getAttr(self.sys + '.notes'))
        for k, v in data.items():
            # 移除失效 grp
            objList = copy.copy(v['obj'])
            grpList = copy.copy(v['grp'])
            for g in v['grp']:
                if not cmds.objExists(g):
                    objList.pop(grpList.index(g))
                    grpList.remove(g)
            data[k]['obj'] = objList
            data[k]['grp'] = grpList
        cmds.setAttr(self.sys + '.notes', str(data), type='string')
        sys.stdout.write(ThLanguage.tr('更新完成!'))

    def _sysF(self):
        """創建紀錄用 grp"""
        if not cmds.objExists(self.sys):
            cmds.group(em=True, n=self.sys)
            cmds.addAttr(self.sys, sn='nts', ln='notes', dt='string')
            cmds.setAttr(self.sys + '.notes', '{}', type='string')
        self.sysDict = eval(cmds.getAttr(self.sys + '.notes'))

    def _grpF(self):
        """創建 group"""
        newObj = self.objects  # 未執行的 物件
        newGrp = self.objects  # 未執行的 grp
        sysObj = []  # 已執行的 物件
        sysGrp = []  # 已執行的 grp
        # 如果標籤存在字典，就從執行物件中，篩選出未執行過的物件
        if self.ctrlAttr in self.sysDict:
            newObj = []
            newGrp = []
            # 系統紀錄的 objs
            sysObj = self.sysDict[self.ctrlAttr]['obj']
            sysGrp = self.sysDict[self.ctrlAttr]['grp']
            for obj in self.objects:
                if not obj in sysObj:
                    newObj.append(obj)
                    newGrp.append(obj)
        # 判斷是否增加 grp 與 是否增加前綴
        if self.isPrefix and self.ctrlAttr:
            self.prefix = '{}__'.format(self.ctrlAttr.replace('.', '_'))
        if self.isGrp:
            newGrp = thLocatorGrpF(newGrp)
            # 判斷是否增加前綴
            if self.isPrefix:
                newGrp = [cmds.rename(n, self.prefix + n) for n in newGrp]
        # 保存物件列表
        if self.ctrlAttr in self.sysDict:
            self.sysDict[self.ctrlAttr]['obj'] = sysObj + newObj
            self.sysDict[self.ctrlAttr]['grp'] = sysGrp + newGrp
        else:
            self.sysDict[self.ctrlAttr] = {'obj': sysObj + newObj, 'grp': sysGrp + newGrp}
        cmds.setAttr(self.sys + '.notes', self.sysDict, type='string')

    def _keyF(self):
        """設置 key"""
        self.selectObj = []
        for obj in self.objects:
            index = self.sysDict[self.ctrlAttr]['obj'].index(obj)
            grp = self.sysDict[self.ctrlAttr]['grp'][index]
            self.selectObj.append(grp)
            for attr in self.attrList:
                try:
                    cmds.setDrivenKeyframe(
                        grp + '.' + attr, cd=self.ctrlAttr, itt='linear', ott='linear')
                except:
                    pass
        # 保存物件列表
        valueList = self.sysDict[self.ctrlAttr].get('value') or []
        keyValue = cmds.getAttr(self.ctrlAttr)
        if not keyValue in valueList:
            valueList.append(keyValue)
            self.sysDict[self.ctrlAttr]['value'] = valueList
            cmds.setAttr(self.sys + '.notes', self.sysDict, type='string')

    def deleteF(self, ctrlAttrs, objs=None):
        # 讀取系統資料
        self._sysF()
        if objs:
            # 移除字典
            for ctrlAttr in ctrlAttrs:
                for obj in objs:
                    if obj in self.sysDict[ctrlAttr]['obj']:
                        # 找 index
                        index = self.sysDict[ctrlAttr]['obj'].index(obj)
                        # 刪除 grp
                        try:
                            cmds.ungroup(self.sysDict[ctrlAttr]['grp'][index])
                        except:
                            thDeleteDrivenKeyF([self.sysDict[ctrlAttr]['grp'][index]])
                        # 移出列表
                        self.sysDict[ctrlAttr]['obj'].pop(index)
                        self.sysDict[ctrlAttr]['grp'].pop(index)
                # 如果標籤字典為空 就刪除字典
                if not self.sysDict[ctrlAttr]['obj']:
                    del (self.sysDict[ctrlAttr])
        else:
            for ctrlAttr in ctrlAttrs:
                # 如果刪除 grp 沒報出錯誤
                try:
                    cmds.ungroup(self.sysDict[ctrlAttr]['grp'])
                # 否則刪除 driven key
                except:
                    thDeleteDrivenKeyF(self.sysDict[ctrlAttr]['grp'])
                # 刪除字典
                del (self.sysDict[ctrlAttr])
        # 如果字典為空 就刪除 system data
        if not self.sysDict:
            cmds.delete(self.sys)
        # 否則寫入資料
        else:
            sysStr = str(self.sysDict)
            cmds.setAttr(self.sys + '.notes', sysStr, type='string')

    def delNotKeyF(self):
        if not cmds.objExists(self.sys):
            return
        groupList = []
        data = eval(cmds.getAttr(self.sys + '.notes'))
        valueList = data.values()
        for objGrp in valueList:
            groupList.extend(objGrp['grp'])
        cmds.delete(groupList, sc=True, uac=True)

    @staticmethod
    def getDrivenKeyAttributesF(obj):
        """
        獲取給定物件上所有有 driven key 設置的屬性
        :param obj: 物件名稱 (str)
        """
        drivenKeyData = {}
        # 獲取物件所有的 keyframe 動畫曲線
        connections = cmds.listConnections(obj, type='animCurve', source=True, destination=False) or []
        #
        for animCurve in connections:
            # 檢查動畫曲線是否是 driven key（即是否通過 setDrivenKeyframe 創建）
            if cmds.attributeQuery('input', node=animCurve, exists=True):
                # 獲取控制的屬性 (驅動值)
                driverAttr = cmds.listConnections(animCurve + '.input', source=True, destination=False, plugs=True)
                if not driverAttr:
                    continue
                driverAttr = driverAttr[0]  # 取第一個
                # 獲取動畫曲線的輸出屬性（被驅動的屬性）
                drivenAttrs = cmds.listConnections(
                    animCurve + '.output', source=False, destination=True, plugs=True) or []
                drivenAttrName = drivenAttrs[0].split('.')[-1]
                # 獲取設置的值
                keyTimes = cmds.keyframe(animCurve, query=True, floatChange=True) or []
                keyValues = cmds.keyframe(animCurve, query=True, valueChange=True) or []
                #
                if not keyTimes:
                    continue
                #
                for time, value in zip(keyTimes, keyValues):
                    if not drivenAttrName in drivenKeyData:
                        drivenKeyData[drivenAttrName] = {}
                    drivenKeyData[drivenAttrName][time] = value
        #
        return drivenKeyData

    @staticmethod
    def getDrivenKeyDataF():
        if not cmds.objExists(__class__.sys):
            return
        #
        sysDict = eval(cmds.getAttr(__class__.sys + '.notes'))
        #
        data = {}
        for ctrlAttr, _data in sysDict.items():
            data1 = {}
            for _obj, _grp in zip(_data['obj'], _data['grp']):
                grpData = __class__.getDrivenKeyAttributesF(_grp)
                data1[_obj] = grpData
            #
            data[ctrlAttr] = data1
        #
        return data

    @staticmethod
    def setDrivenKeyDataF(data):
        upData = {}
        otherData = {}
        #
        for _k, _v in data.items():
            if '.tx' in _k:
                upData[_k] = _v
            else:
                otherData[_k] = _v
        #
        ThDrivenKeySystem._setDrivenKeyDataF(upData)
        ThDrivenKeySystem._setDrivenKeyDataF(otherData)

    @staticmethod
    def _setDrivenKeyDataF(data):
        for ctrlAttr, objData in data.items():
            ctrl = ctrlAttr.split('.')[0]
            if not cmds.objExists(ctrl):
                print(f'not found ctrl: {ctrl}')
                continue
            #
            try:
                ctrlAttrValue = cmds.getAttr(ctrlAttr)
            except:
                print(f'unable set: {ctrlAttrValue}')
                continue
            #
            for obj, attrData in objData.items():
                if not cmds.objExists(obj):
                    print(f'not found obj: {obj}')
                    continue
                #
                for attr, valueData in attrData.items():
                    cls = __class__(ctrlAttr=ctrlAttr, objects=[obj], attrList=[attr], isGrp=True, isPrefix=True)
                    # 創建紀錄用 grp
                    cls._sysF()
                    # 創建 group
                    cls._grpF()
                    #
                    for time, value in valueData.items():
                        try:
                            cmds.setAttr(ctrlAttr, float(time))
                        except:
                            print(f'unable set: {ctrlAttr} = {time}')
                            continue
                        #
                        grp = cls.sysDict[ctrlAttr]['grp'][cls.sysDict[ctrlAttr]['obj'].index(obj)]
                        cmds.setAttr(grp + '.' + attr, value)
                        # 設置 key
                        cls._keyF()
            #
            try:
                cmds.setAttr(ctrlAttr, ctrlAttrValue)
            except:
                pass


class ThAffectSystem:
    typeList = ['X', 'Y', 'Z']
    typeAttr = ['tx', 'ty', 'tz']
    ctrlAttr = ['rx', 'ry', 'rz']

    def __init__(self, objs=None, name=None, aim='x', rotate_='object', offset=1, ctrl=None):
        """牽動系統.
        關於名稱
        - 把主要的 obj 名稱作為 dict 包存於 note
        - 再依據 obj 名稱產生其他分之名稱
        """
        self.objs = objs
        self.name = name
        self.aim = aim
        self.rotate_ = rotate_
        self.offset = offset
        self.ctrl = ctrl if ctrl else objs  # 控制器列表
        #
        self.objSrNode = []  # 依據物件產生結點列表名稱，用於創建與編輯模式
        self.locator = []  # 用於 save to note
        self.allNode = []  # 用於 delete data
        self.startData = []  # 當前位置數據 [obj[data],...]
        self.endData = []  # 結束位置數據 [obj[data],...]
        self.ctrlStartData = []  # ctrl 開始位置數據 [obj[data],...]
        self.ctrlEndData = []  # ctrl 結束位置數據 [obj[data],...]
        # 是否以編輯模式進行(預設為創建模式，True 為編輯模式)
        self.isEdit = False

    def createF(self):
        # 創建 sys
        self._noteInitF()
        # 讀取系統
        self._getSysDataF()
        # 創建控制器
        self._locatorF()
        # 創建節點
        self._createNodeF()
        # 保存節點到 notes
        self._noteSaveF()
        cmds.select('affectSystem_data', r=True)

    def _noteInitF(self):
        """初始化"""
        # 創建主要 grp
        if not cmds.objExists('affectSystem_data'):
            cmds.group(em=True, n='affectSystem_data')
            # 鎖定並隱藏屬性
            thLockHiddenAttrF(['affectSystem_data'], [1, 1, 1, 1], 1)
            # add
            cmds.addAttr('affectSystem_data', sn='nts', ln='notes', dt='string')
            # set
            cmds.setAttr('affectSystem_data.notes', "{'label': {}, 'locator': {}}", type='string')

    def _getSysDataF(self):
        """讀取系統"""
        # 以標籤存在與否，判斷是否採用編輯模式
        if cmds.listAttr('affectSystem_data', m=True, st=self.name):
            str_ = cmds.getAttr('affectSystem_data.notes')
            dict_ = eval(str_)
            # 回復物件列表數據
            self.objs = dict_['label'][self.name]['objs']
            self.ctrl = dict_['label'][self.name]['ctrl']
            # 回復開始與結束數據
            try:
                self.startData = dict_['label'][self.name]['pose']['start']
                self.endData = dict_['label'][self.name]['pose']['end']
                self.ctrlStartData = dict_['label'][self.name]['ctrl pose']['start']
                self.ctrlEndData = dict_['label'][self.name]['ctrl pose']['end']
            except:
                pass
            #
            self.isEdit = True
        else:
            self.isEdit = False

    def _locatorF(self):
        """創建定位器"""
        # 創建模式才執行
        if not self.isEdit:
            # 循環物件
            for obj in self.objs:
                # 命名
                offset = '1' if self.offset > 0 else '0'
                name = '{}_{}{}_affectSystem_'.format(
                    obj, self.rotate_, offset)
                # 如果場景中沒有該系統就創建
                if not cmds.objExists(name + 'LO'):
                    # 創建定義旋轉控制的 grp
                    grp1 = cmds.group(em=True, n=name + 'RO_grp1')
                    grp2 = cmds.group(grp1, n=name + 'RO_grp2')
                    grp = cmds.group(grp2, n=name + 'LO_main_grp')
                    cmds.parent(grp, 'affectSystem_data')
                    # 創建 locator
                    lo = cmds.spaceLocator(n=name + 'LO')[0]
                    cmds.hide(lo)
                    loGrp = cmds.group(lo, n=name + 'LO_grp')
                    cmds.parent(loGrp, grp)
                    # 對位
                    ro = 't' if self.rotate_ == 'world' else 'tr'
                    ThAdsorptionObj([grp], obj, ro)
                    # move
                    cmds.setAttr('{}.t{}'.format(grp1, self.aim), self.offset)
                    cmds.setAttr('{}.t{}'.format(loGrp, self.aim), self.offset)
                    # constrain main
                    cmds.orientConstraint([obj, grp2], mo=True, weight=1)
                    cmds.pointConstraint([grp1, lo], mo=True, weight=1)
                    father = cmds.listRelatives(obj, p=True)
                    if father:
                        cmds.parentConstraint([father[0], grp], mo=True, weight=1)
        # 產生 LO 名稱列表
        offset = '1' if self.offset > 0 else '0'
        for obj in self.objs:
            self.locator.append('{}_{}{}_affectSystem_LO'.format(obj, self.rotate_, offset))

    def _createNodeF(self):
        """創建節點"""
        # 創建模式才執行
        if not self.isEdit:
            # 添加控制屬性
            cmds.addAttr('affectSystem_data', ln=self.name, at='double', k=True)
            cmds.addAttr(
                'affectSystem_data', ln=self.name + '_switch', at='double', min=0, max=1, dv=1,
                k=True)
            # 每個數據一個節點
            allSrNode = []
            for i, obj in enumerate(self.objs):
                node = cmds.createNode('setRange', n='{}_{}_affectSystem_SR'.format(self.name, obj))
                # 連接屬性
                cmds.connectAttr(self.locator[i] + '.t', node + '.value')
                # 保存節點名稱
                allSrNode.append(node)
                self.allNode.append(node)
            # 數據相乘
            formula = ''
            index = 1
            for n in allSrNode:
                for type in self.typeList:
                    formula += '{}.outValue{} * '.format(n, type)
            formula += 'affectSystem_data.{};'.format(self.name + '_switch')
            formula = 'affectSystem_data.{} = {}'.format(self.name, formula)
            #
            self.allNode.append(
                cmds.expression(n='{}_affectSystem_EX'.format(self.name), s=formula))
        # 產生 SR 節點名稱列表
        for obj in self.objs:
            self.objSrNode.append('{}_{}_affectSystem_SR'.format(self.name, obj))

    def _noteSaveF(self):
        """保存數據 to notes"""
        str_ = cmds.getAttr('affectSystem_data.notes')
        dict_ = eval(str_)
        # 如果是創建模式就寫入數據
        if not self.isEdit:
            dict_['label'][self.name] = {}
            dict_['label'][self.name]['objs'] = self.objs
            dict_['label'][self.name]['ctrl'] = self.ctrl
            dict_['label'][self.name]['del'] = self.allNode
            # locator 與 name 對應
            for lo in self.locator:
                dict_['locator'].setdefault(lo, [])
                if not self.name in dict_['locator'][lo]:
                    dict_['locator'][lo].append(self.name)
            #
            cmds.setAttr('affectSystem_data.notes', dict_, type='string')

    def savePoseF(self, mode):
        """保存位置.
        :type mode: str
            'start' | 'end'
        """
        # 保存模式與清空保存數據
        saveData0 = None
        ctrlSaveData0 = None
        if mode == 'start':
            saveData0 = self.startData = []
            ctrlSaveData0 = self.ctrlStartData = []
        elif mode == 'end':
            saveData0 = self.endData = []
            ctrlSaveData0 = self.ctrlEndData = []
        # 讀取數據
        for i, obj in enumerate(self.objs):
            saveData1 = []
            ctrlSaveData1 = []
            for ii, type in enumerate(self.typeList):
                data = cmds.getAttr('{}.{}'.format(self.locator[i], self.typeAttr[ii]))
                ctrlData = cmds.getAttr('{}.{}'.format(self.ctrl[i], self.ctrlAttr[ii]))
                # 四捨五入，確保數值不要太小
                saveData1.append(round(data, 3))
                ctrlSaveData1.append(ctrlData)
            saveData0.append(saveData1)
            ctrlSaveData0.append(ctrlSaveData1)

    def setDataF(self, useValue=1):
        """設定數據"""
        # 格式化數據
        rawDict0 = {}  # 原始數據 {obj: {XYZ: {attr: data}}}
        appDict0 = {}  # 格式化數據 {obj: {XYZ: {attr: data}}}
        maxDict0 = {}  # 每個屬性最大值 {obj: {XYZ: data}}
        #
        for i, obj in enumerate(self.objs):
            rawDict1 = {}
            appDict1 = {}
            maxDict1 = {}
            for ii, type in enumerate(self.typeList):
                min_ = max_ = oldMin = oldMax = None
                # 起始數值與結束數值相等 就保持輸出數值為 1
                if self.startData[i][ii] != self.endData[i][ii]:
                    # 判斷設定屬性的最大最小值如何正確輸入
                    min_, max_ = 0, 1
                    oldMin, oldMax = self.startData[i][ii], self.endData[i][ii]
                    if oldMin > oldMax:
                        min_, max_ = 1, 0
                        oldMin, oldMax = oldMax, oldMin
                else:
                    min_ = max_ = oldMax = 1
                    oldMin = 0
                # 保存用於判斷屬性最大值
                # abs(oldMin - oldMax) - (min_ * max_)
                maxDict1[type] = abs(oldMin - oldMax) - (min_ * max_)
                # 保存最終數據
                attrList = ['min', 'max', 'oldMin', 'oldMax']
                rawDataList = [1, 1, 0, 1]
                appDataList = [min_, max_, oldMin, oldMax]
                #
                rawDict2 = {}
                appDict2 = {}
                for iii, attr in enumerate(attrList):
                    rawDict2[attr] = rawDataList[iii]
                    appDict2[attr] = appDataList[iii]
                rawDict1[type] = rawDict2
                appDict1[type] = appDict2
            rawDict0[self.objSrNode[i]] = rawDict1
            appDict0[self.objSrNode[i]] = appDict1
            maxDict0[self.objSrNode[i]] = maxDict1
        # 是否排除小數據
        if useValue != 3:
            for node in maxDict0:
                # 由大到小排序字典
                sort = sorted(maxDict0[node].items(), reverse=True, key=lambda item: item[1])
                # 修改原始數據
                for type in sort[:useValue]:
                    rawDict0[node][type[0]] = appDict0[node][type[0]]
            appDict0 = rawDict0
        # 設置數據
        for node in appDict0:
            for type in appDict0[node]:
                for attr in appDict0[node][type]:
                    cmds.setAttr(node + '.' + attr + type, appDict0[node][type][attr])
        # 保存起始與結束數據到 nots
        self._noteSavePoseF()

    def _noteSavePoseF(self):
        """保存起始與結束位置"""
        str_ = cmds.getAttr('affectSystem_data.notes')
        dict_ = eval(str_)
        # locator
        dict_['label'][self.name]['pose'] = {'start': self.startData, 'end': self.endData}
        # ctrl
        dict_['label'][self.name]['ctrl pose'] = {
            'start': self.ctrlStartData, 'end': self.ctrlEndData}
        cmds.setAttr('affectSystem_data.notes', dict_, type='string')

    def setCtrlF(self, mode, nameList):
        """設定控制器起始與結束位置.
        :type mode: str
            'start' | 'end'
        """
        # 讀取系統
        str_ = cmds.getAttr('affectSystem_data.notes')
        dict_ = eval(str_)
        #
        for name in nameList:
            appData = {
                'start': "dict_['label'][name]['ctrl pose']['start']",
                'end': "dict_['label'][name]['ctrl pose']['end']"}
            #
            for i, n in enumerate(dict_['label'][name]['ctrl']):
                for ii, attr in enumerate(['rx', 'ry', 'rz']):
                    cmds.setAttr(n + '.' + attr, eval(appData[mode])[i][ii])

    def checkLocRrotateF(self):
        """確認 locator 座標與軸向"""
        str_ = cmds.getAttr('affectSystem_data.notes')
        dict_ = eval(str_)
        transform = list(dict_['locator'].keys())
        if not cmds.getAttr(transform[0] + '.v'):
            cmds.showHidden(transform)
            for lo in transform:
                cmds.setAttr(lo + '.displayLocalAxis', 1)
        else:
            cmds.hide(transform)
            for lo in transform:
                cmds.setAttr(lo + '.displayLocalAxis', 0)

    def deleteAttrF(self, attrList):
        """刪除屬性, EX, SR"""
        str_ = cmds.getAttr('affectSystem_data.notes')
        dict_ = eval(str_)
        for attr in attrList:
            # 刪除節點
            cmds.delete(dict_['label'][attr]['del'])
            # 刪除屬性
            cmds.deleteAttr('affectSystem_data', at=attr + '_switch')
            cmds.deleteAttr('affectSystem_data', at=attr)
            # 清理字典
            del (dict_['label'][attr])
            # 清理無作用 loc
            loList = copy.copy(dict_['locator'])
            for lo in loList:
                if attr in dict_['locator'][lo]:
                    dict_['locator'][lo].remove(attr)
                # 如果 LO 字典等於空 就刪除場景中 loc grp 並清除字典
                if not dict_['locator'][lo]:
                    cmds.delete(lo + '_main_grp')
                    del (dict_['locator'][lo])
            # 清除無作用 system
            if not dict_['locator']:
                cmds.delete('affectSystem_data')
            else:
                cmds.setAttr('affectSystem_data.notes', dict_, type='string')


class ThMoveSkinWeightOm2:
    def __init__(self, objs, oldJointList, newJointList, opacity=1, ifRemoveInfluence=False):
        """移動 skin weight"""
        self.objs = objs
        self.oldJointList = oldJointList
        self.newJointList = newJointList
        self.opacity = 1 - opacity
        self.ifRemoveInfluence = ifRemoveInfluence
        #
        self.idList = []
        # 判斷添加 joint
        self._addJointF()
        # 移動 weight
        try:
            self._moveF()
        except RuntimeError:
            sys.stdout.write(ThLanguage.tr('對象與此方法不兼容!'))

    def _addJointF(self):
        """判斷添加 joint"""
        self.meshs = self.objs
        if '.' in self.objs[0]:
            # 轉為頂點
            self.objs = cmds.polyListComponentConversion(self.objs, tv=True)
            # 排序
            self.objs = cmds.ls(self.objs, fl=True)
            # 擷取出 mesh name
            self.meshs = [self.objs[0].split('.')[0]]
        addJointList = self.oldJointList + self.newJointList
        for m in self.meshs:
            # 找 joints
            skinJointList = thFindSkinJointF([m]) or []
            # 如果 joint 不在列表 就添加
            for j in addJointList:
                if not j in skinJointList:
                    cmds.skinCluster(m, e=True, wt=0, ai=j)

    def _moveF(self):
        """移動 weight"""
        # 如果數量不是成對的
        # 判定為很多舊 joint weight 要移動到 1 個新的 joint 上的情況
        if len(self.newJointList) < len(self.oldJointList):
            # 新的 joint list 數量與 old joint list 批配
            appJointList = [self.newJointList[0]] * len(self.oldJointList)
        else:
            appJointList = self.newJointList
        #
        for m in self.meshs:
            cwa = ThCopyWeightApi()
            cwa.getWeightDataF(m)
            skinNode = thFindSkinNodeF([m])[0]
            for i, oldJoint in enumerate(self.oldJointList):
                # 如果 self.objs[0] 是包含頂點
                # 表示 mesh 只循環一次
                # 且不用自動搜尋 vtx
                if '.' in self.objs[0]:
                    self.idList = [int(n.split('.')[1][4:-1]) for n in self.objs]
                else:
                    cmds.select(cl=True)
                    cmds.skinCluster(skinNode, e=True, siv=oldJoint)
                    vtxList = cmds.ls(sl=True, fl=True)
                    if not '.' in vtxList[0]:
                        continue
                    self.idList = [int(n.split('.')[1][4:-1]) for n in vtxList]
                # 設定權重
                cwa.editWeightDataF(
                    idList=self.idList,
                    idListData=[cwa.dataDict[oldJoint][x] * self.opacity for x in self.idList],
                    joint=oldJoint, otherJointList=[appJointList[i]])
            cwa.setWeightDataF()
            # 移除骨骼
            if self.ifRemoveInfluence:
                cmds.skinCluster(skinNode, e=True, ri=oldJoint)


class ThMoveSkinWeight:
    def __init__(self, objs, oldJointList, newJointList, opacity=1):
        """移動 skin weight"""
        self.objs = objs
        self.oldJointList = oldJointList
        self.newJointList = newJointList
        self.opacity = opacity
        # add
        self.skinNodes = []
        self.isRange = True  # 是否自動尋找 vertex 範圍
        self.appF()

    def appF(self):
        # 找 skin node
        self._findSkinF()
        # 　歸一化 並 關閉 maintainMaxInfluences
        for n in self.skinNodes:
            cmds.skinCluster(n, e=True, fnw=True, normalizeWeights=1)
            cmds.setAttr(n + '.maintainMaxInfluences', 0)
        # 判斷添加 joint
        self._addJointF()
        # 移動 weight
        self._moveF()

    def _findSkinF(self):
        """判斷是否為 vtx 與 find skin node"""
        meshs = self.objs
        # 如果選擇的物件是 vertex
        if '.' in self.objs[0]:
            # 轉為頂點
            self.objs = cmds.polyListComponentConversion(self.objs, tv=True)
            # 擷取出 mesh name
            meshs = [n.split('.')[0] for n in self.objs]
            meshs = list(set(meshs))
            #
            self.isRange = False
        # 找 skin node
        self.skinNodes = thFindSkinNodeF(meshs)

    def _addJointF(self):
        """判斷添加 joint"""
        jointList = self.oldJointList + self.newJointList
        for m in self.objs:
            # 找 joints
            skinJoints = thFindSkinJointF([m])
            # 如果 joint 不在列表 就添加
            for j in jointList:
                if not j in skinJoints:
                    cmds.skinCluster(m, e=True, wt=0, ai=j)

    def _moveF(self):
        """移動 weight"""
        # 鎖定 joint lock
        mesh = self.objs[0].split('.')[0] if self.isRange else self.objs[0]
        jointList = thFindSkinJointF([mesh])
        for j in jointList:
            cmds.setAttr(j + '.liw', 1)
        # 如果數量不是成對的
        # 判定為很多舊 joint weight 要移動到 1 個新的 joint 上的情況
        appList = self.newJointList
        if len(self.newJointList) < len(self.oldJointList):
            # 新的 joint list 數量與 old joint list 批配
            appList = [self.newJointList[0]] * len(self.oldJointList)
        # 使用進度條
        progressBar = ThUiProgressBar(3)
        progressBar.show()
        progressBar.setStratF(0, 'Joint', len(self.oldJointList))
        #
        vtxList = self.objs
        for i, j in enumerate(self.oldJointList):
            progressBar.setFrameF(0)
            if not self.skinNodes:
                continue
            # 解開要編輯的 joint
            cmds.setAttr(appList[i] + '.liw', 0)
            progressBar.setStratF(1, 'Skin node', len(self.skinNodes))
            for s in self.skinNodes:
                progressBar.setFrameF(1)
                # 如果 ref joint 有 skin node 連接就執行
                inJoints = cmds.skinCluster(s, q=True, wi=True)
                if j in inJoints:
                    # 是否自動尋找 weight vertex
                    if self.isRange:
                        cmds.select(cl=True)
                        cmds.skinCluster(s, e=True, siv=j)
                        vtxList = cmds.ls(sl=True, fl=True)
                else:
                    continue
                # 設定權重
                progressBar.setStratF(2, 'Vertex', len(vtxList))
                for vtx in vtxList:
                    progressBar.setFrameF(2)
                    # 讀取舊頂點權重值
                    oldWeight = cmds.skinPercent(s, vtx, t=j, q=True)
                    if oldWeight > 0:
                        setWeight = oldWeight * self.opacity  # 獲取要傳遞的值
                        cmds.skinPercent(s, vtx, tv=[j, oldWeight - setWeight])
            # 鎖定 joint
            cmds.setAttr(appList[i] + '.liw', 1)
        progressBar.close()


class ThHair:
    def __init__(self, cv, name, solver=None, follicleMode='base', createMode='ik'):
        """create hair rig
        :type follicleMode: str
            'base' | 'tip' | 'both ends'
        """
        self.cv = cv
        self.name = name
        self.follicleMode = follicleMode
        self.createMode = createMode
        # add
        self.hair = None
        self.hairShape = None
        self.nucleus = None
        self.follicle = None
        self.follicleShape = None
        self.startCv = None
        self.startCvGrp = None
        self.dynCv = None
        self.dynCvShape = None
        self.dynCvGrp = None

    def appF(self):
        # 是否創建
        isApp = True
        #
        if isApp:
            # create hair system
            self._createF()
            # rename
            self._renameF()
            # 整理 outliner
            self._outlinerF()
            # rig ik spline
            self._rigIkF()
            # hide
            cmds.hide([self.startCvGrp, self.dynCvGrp])

    def _createF(self):
        """create hair system"""
        # 要創建為 hain 的 curve
        self.startCv = self.cv
        # 如果是 ik 模式就複製一條 cv
        if self.createMode == 'ik':
            self.startCv = cmds.duplicate(self.cv, rr=True, rc=True)[0]
        # 檢查 cv 是否為頂級物件
        if cmds.listRelatives(self.startCv, p=True):
            cmds.parent(self.startCv, w=True)
        # 創建 hair system
        cmds.select(self.startCv, r=True)
        stratTopNodes = cmds.ls(assemblies=True, long=False)
        mel.eval('makeCurvesDynamic 2 {"1","0","1","1","0"}')  # 創建後場景頂級物件
        endTopNodes = cmds.ls(assemblies=True, long=False)
        addObjList = set(endTopNodes) - set(stratTopNodes)
        #
        self.hair = [x for x in addObjList if thTypeF([x])[0] == 'hairSystem'][0]
        self.follicleGrp = [x for x in addObjList if 'Follicles' in x][0]
        self.curvesGrp = [x for x in addObjList if 'OutputCurves' in x][0]
        self.nucleus = [x for x in addObjList if 'nucleus' in x]

    def _renameF(self):
        """rename"""
        self.hair = cmds.rename(self.hair, f'{self.name}_hairSystem#')
        self.hairShape = cmds.listRelatives(self.hair, s=True)[0]
        #
        self.follicle = cmds.listRelatives(self.follicleGrp, c=True)[0]
        self.follicle = cmds.rename(self.follicle, f'{self.name}_follicle#')
        self.follicleShape = cmds.listRelatives(self.follicle, s=True)[0]
        #
        self.startCv = cmds.rename(self.startCv, f'{self.name}_hairCv#')
        self.startCvGrp = cmds.rename(self.follicleGrp, f'{self.name}_hairSystem1Follicles#')
        #
        self.dynCv = cmds.listRelatives(self.curvesGrp, c=True)[0]
        self.dynCv = cmds.rename(self.dynCv, f'{self.name}_hairDynCv#')
        self.dynCvShape = cmds.listRelatives(self.dynCv, s=True)[0]
        self.dynCvGrp = cmds.rename(self.curvesGrp, f'{self.name}_hairSystem1OutputCurves#')
        #
        if self.nucleus:
            self.nucleus = cmds.rename(self.nucleus[0], f'{self.name}_nucleus#')

    def _outlinerF(self):
        """整理 outliner"""
        if not cmds.objExists('dyn'):
            cmds.group(em=True, n='dyn')
        if not cmds.objExists(self.name + '_dyn_grp'):
            cmds.group(em=True, n=self.name + '_dyn_grp')
            cmds.parent(self.name + '_dyn_grp', 'dyn')
        cmds.parent(self.hair, self.name + '_dyn_grp')
        if self.nucleus:
            if not cmds.objExists(self.name + '_dyn_nucleus_grp'):
                cmds.group(em=True, n=self.name + '_dyn_nucleus_grp')
                cmds.parent(self.name + '_dyn_nucleus_grp', self.name + '_dyn_grp')
            cmds.parent(self.nucleus, self.name + '_dyn_nucleus_grp')
        cmds.parent(self.startCvGrp, self.name + '_dyn_grp')
        cmds.parent(self.dynCvGrp, self.name + '_dyn_grp')

    def _rigIkF(self):
        """rig ik spline"""
        # 設定 follicle
        folliclePointLock = {'base': 1, 'tip': 2, 'both ends': 3}
        cmds.setAttr(self.follicleShape + '.pointLock', folliclePointLock[self.follicleMode])
        # 力學曲線 blend to ik cv
        blend = cmds.blendShape(
            [self.dynCv, self.cv], n=self.name + '_hairSystem_blend_node#', frontOfChain=True)[0]
        cmds.setAttr(blend + '.w[0]', 1)
        # skin
        skinObjs = thFindSkinJointF([self.cv])
        skinObjs.append(self.startCv)
        cmds.skinCluster(skinObjs, n=self.name + '_hairSystem_skin_node#', mi=5, dr=4.0, tsb=True)
        # 設置 blend 開關
        skin = thFindSkinNodeF([self.cv])[0]
        cmds.expression(
            n=self.name + '_hairSystem_blend_EX#',
            s='{}.envelope = 1 - {}.envelope;'.format(blend, skin))
        # 設置 hairSystem 開關
        cmds.setAttr(self.hairShape + '.simulationMethod', 0)
        cmds.setAttr(skin + '.envelope', 1)
        cmds.setDrivenKeyframe(
            skin + '.envelope', cd=self.hairShape + '.simulationMethod', itt='linear',
            ott='linear')
        cmds.setAttr(self.hairShape + '.simulationMethod', 3)
        cmds.setAttr(skin + '.envelope', 0)
        cmds.setDrivenKeyframe(
            skin + '.envelope', cd=self.hairShape + '.simulationMethod', itt='linear',
            ott='linear')


class ThObjOffsetObjs:
    def __init__(self, list_, obj):
        """物件座標在物件列表上偏移
        :type list_: list
        :type obj: str
        """
        self.list_ = list_
        self.obj = obj
        # add
        self.conNode = None
        self.sys = None

    def appF(self):
        # 約束
        self._constrainF()
        # 控制器
        self._ctrlF()
        # key 批次啟動
        self._keyF()

    def _constrainF(self):
        """約束"""
        con = self.list_ + [self.obj]
        self.conNode = cmds.parentConstraint(con, weight=1)[0]

    def _ctrlF(self):
        """創建控制器"""
        self.sys = cmds.group(em=True, n='objOffsetSystem')
        cmds.addAttr(self.sys, ln='offset', at='double', min=0, max=10, dv=0, k=True)

    def _keyF(self):
        """key 批次啟動"""
        # 產生 key attr list
        keyList = []
        for i, n in enumerate(self.list_):
            keyList.append('{}.{}W{}'.format(self.conNode, n, i))
        # key
        set_ = 0
        add = 10.0 / (len(keyList) - 1)
        for i, n in enumerate(keyList):
            cmds.setAttr(self.sys + '.offset', set_)
            for nn in keyList:
                cmds.setAttr(nn, 0)
            cmds.setAttr(n, 1)
            cmds.setDrivenKeyframe(keyList, cd=self.sys + '.offset', itt='linear', ott='linear')
            #
            if i < len(keyList) - 1:
                set_ += add
                if set_ > 10:
                    set_ = 10

    def deleteF(self):
        cmds.delete(self.conNode)
        cmds.delete(self.sys)


class ThCreateFollowObjsJoint:
    def __init__(self, list_, quantity):
        """創建跟隨物件"""
        self.list_ = list_
        self.quantity = quantity
        # add
        self.joint = None
        self.newJoints = []

    def appF(self):
        # create joint
        cmds.select(cl=True)
        self.joint = cmds.joint()
        # create offset system
        ooo = ThObjOffsetObjs(self.list_, self.joint)
        ooo.appF()
        # create new joint
        set_ = 0
        add = 10.0 / (self.quantity - 1)
        for i in range(self.quantity):
            cmds.setAttr(ooo.sys + '.offset', set_)
            cmds.select(cl=True)
            joint = cmds.joint()
            ThAdsorptionObj([joint], self.joint, 'tr')
            self.newJoints.append(joint)
            #
            if i < self.quantity - 1:
                set_ += add
                if set_ > 10:
                    set_ = 10
        # freeze
        cmds.makeIdentity(self.newJoints, apply=True, t=True, r=True, s=True, n=False, pn=True)
        # delete
        ooo.deleteF()
        cmds.delete(self.joint)


class ThWheelRig:
    def __init__(self, meshList, name='wheel', axial='x', axisObjList=None, ifConAxisObjList=True):
        """輪子 RIG"""
        self.meshList = meshList
        self.name = name
        self.axial = axial
        self.axisObjList = axisObjList or []
        self.ifConAxisObjList = ifConAxisObjList
        # add
        self.mainGrp = None  # 主要的 grp
        self.axisList = []  # 軸心物件z
        self.ctrlList = []  # 控制器
        #
        if len(self.meshList) != len(self.axisObjList):
            self.axisObjList = self.meshList
        # 創建 grp
        if not cmds.objExists('def_wheel_main_grp'):
            cmds.group(em=True, n='def_wheel_main_grp')
        if not cmds.objExists('rig_wheel_main_grp'):
            cmds.group(em=True, n='rig_wheel_main_grp')
        self.mainGrp = cmds.group(em=True, n='{}_wheel_main_grp'.format(self.name))
        cmds.parent([self.mainGrp, 'def_wheel_main_grp'])
        cmds.hide(self.mainGrp)
        for i, mesh in enumerate(self.meshList):
            self.newName = '{}{}'.format(self.name, i + 1)
            # 輪子大小測量
            self._disF(mesh)
            # 創建控制器
            ctrlRus = self._ctrlF(self.axisObjList[i] if self.axisObjList else None)
            # ex
            self._exF()
            # 約束
            if self.ifConAxisObjList:
                cmds.parentConstraint([self.axis, self.axisObjList[i]], mo=True, weight=1)
        cmds.select(self.ctrlList, r=True)

    def _disF(self, mesh):
        """輪子大小測量"""
        # 測量輪子大小
        self.tfvmd = ThFindVtxMaxDis([mesh])
        # 創建 loc
        self.loc1 = cmds.spaceLocator(n='{}_wheel_loc1'.format(self.newName))[0]
        cmds.move(
            self.tfvmd.hexagon[2][0], self.tfvmd.hexagon[2][1], self.tfvmd.hexagon[2][2], self.loc1)
        self.loc2 = cmds.spaceLocator(n='{}_wheel_loc2'.format(self.newName))[0]
        cmds.move(
            self.tfvmd.hexagon[3][0], self.tfvmd.hexagon[3][1], self.tfvmd.hexagon[3][2], self.loc2)
        self.locGrp = cmds.group(em=True, n='{}_wheel_loc_grp'.format(self.newName))
        cmds.parent([self.loc1, self.loc2, self.locGrp])
        cmds.parent([self.locGrp, self.mainGrp])
        # 創建 distanceBetween
        self.dis = cmds.createNode('distanceBetween', n='{}_wheel_loc_dis'.format(self.newName))
        cmds.connectAttr(self.loc1 + '.t', self.dis + '.point1')
        cmds.connectAttr(self.loc2 + '.t', self.dis + '.point2')

    def _ctrlF(self, axisObj):
        """創建控制器"""
        # 創建中心物件
        self.axis = cmds.spaceLocator(n='{}_wheel_axis'.format(self.newName))[0]
        self.axisList.append(self.axis)
        if axisObj:
            ThAdsorptionObj([self.axis], axisObj, 'tr')
        else:
            cmds.move(self.tfvmd.center[0], self.tfvmd.center[1], self.tfvmd.center[2], self.axis)
        # 創建中心物件控制器
        thcto = ThCtrlToObject(
            [self.axis], name='{}_wheel'.format(self.newName), ctrlStyle='hexagon',
            ctrlAxial=self.axial, ctrlMethod='parent', ctrlColor=18, grpLayout=2,
            ifCreateMainGrp=False, ctrlSize=2)
        thcto.createF()
        self.ctrlList.append(thcto.newCtrlList[0])
        # 保存名稱
        self.ctrl = thcto.newCtrlList[0]
        ctrlGrpEnd = thcto.newCtrlGrpList[-1]
        # 添加屬性
        cmds.addAttr(self.ctrl, ln='auto', at='bool', k=True, dv=1)
        # constrain 輪子大小測量
        cmds.parentConstraint([self.ctrl, self.loc1], mo=True, skipRotate=['x', 'y', 'z'], weight=1)
        cmds.parentConstraint([self.ctrl, self.loc2], mo=True, skipRotate=['x', 'y', 'z'], weight=1)
        # p
        cmds.parent([ctrlGrpEnd, 'rig_wheel_main_grp'])

    def _exF(self):
        """expression"""
        app = {'x': 'z', 'z': 'x'}
        #
        moveLoc = cmds.spaceLocator(n='{}_wheel_move_loc'.format(self.newName))[0]
        moveLocGrp = cmds.group(moveLoc, n='{}_wheel_move_loc_grp'.format(self.newName))
        # constrain
        cmds.pointConstraint([self.ctrl, moveLoc], mo=True, weight=1)
        cmds.orientConstraint([self.ctrl, moveLocGrp], mo=True, weight=1)
        # add attt
        cmds.addAttr(self.ctrl, ln='anim', at='double', dv=0, k=True)
        # ex
        ex = '''
if ({ctrl}.auto == 1){{
    {axis}.rx = (({moveLoc}.t{axial} + {ctrlAttr}) * 360) / ({dis}.distance * 3.14159);
}} else {{
    {axis}.rx = ({ctrlAttr} * 360) / ({dis}.distance * 3.14159);
}}
'''
        ctrlAttr = '{}.anim'.format(self.ctrl)
        ex = ex.format(
            ctrl=self.ctrl, axis=self.axis, moveLoc=moveLoc, axial=app[self.axial],
            ctrlAttr=ctrlAttr, dis=self.dis)
        cmds.expression(n='{}_wheel_EX'.format(self.newName), s=ex)
        # p
        cmds.parent([moveLocGrp, self.mainGrp])


class ThFindVtxMaxDis:
    def __init__(self, list_):
        """判斷頂點最大最小距離"""
        self.list_ = list_
        # add
        self.xyzList = []
        self.vtxList = []
        self.hexagon = []  # 六角座標
        self.anise = []  # 八角座標
        self.center = []  # 中心座標
        # 分析列表
        if '.' in list_[0]:
            self.vtxList = list_
        else:
            for n in list_:
                # 頂點數量
                size = cmds.polyEvaluate(n, v=True)
                for i in range(size):
                    self.vtxList.append('{}.vtx[{}]'.format(n, i))
        # app
        # 讀取當前 vertex 座標
        for n in self.vtxList:
            self.xyzList.append(cmds.xform(n, q=True, ws=True, t=True))
        # 邊界
        xDir = sorted([i[0] for i in self.xyzList])
        yDir = sorted([i[1] for i in self.xyzList])
        zDir = sorted([i[2] for i in self.xyzList])
        # 邊界(xyz 大中小排序)
        xList = [xDir[0], ((xDir[0] - xDir[-1]) / 2) + xDir[-1], xDir[-1]]
        yList = [yDir[0], ((yDir[0] - yDir[-1]) / 2) + yDir[-1], yDir[-1]]
        zList = [zDir[0], ((zDir[0] - zDir[-1]) / 2) + zDir[-1], zDir[-1]]
        # 六角座標
        self.hexagon = [[xList[0], yList[1], zList[1]], [xList[2], yList[1], zList[1]],
            [xList[1], yList[0], zList[1]], [xList[1], yList[2], zList[1]],
            [xList[1], yList[1], zList[0]], [xList[1], yList[1], zList[2]]]
        # 八角座標
        self.anise = [[xList[0], yList[0], zList[2]], [xList[0], yList[0], zList[0]],
            [xList[0], yList[2], zList[2]], [xList[0], yList[2], zList[0]],
            [xList[2], yList[0], zList[2]], [xList[2], yList[0], zList[0]],
            [xList[2], yList[2], zList[2]], [xList[2], yList[2], zList[0]]]
        # 中心座標
        self.center = [xList[1], yList[1], zList[1]]

    def createF(self, mode='hexagon'):
        """
        :type mode: str
            'anise' | 'hexagon'
        """
        app = {'hexagon': self.hexagon, 'anise': self.anise}
        new = []
        for i in app[mode]:
            cmds.select(cl=True)
            new.append(cmds.joint(p=i))
        cmds.select(new, r=True)


class ThEditCvShape:
    def __init__(self, ctrl):
        """控制器移動, 旋轉, 縮放"""
        self.ctrl = ctrl
        # add
        self.cvList = []
        # app
        if '.' in ctrl[0]:
            set_ = set([n.split('.')[0] for n in ctrl])
            self.ctrl = list(set_)
        # find cv list
        for n in self.ctrl:
            shape = cmds.listRelatives(n, f=True, s=True)[0]
            # 回傳控制器 cv list
            cvSize = int(cmds.getAttr(shape + '.maxValue'))
            # 判斷 smooth
            cvDegree = int(cmds.getAttr(shape + '.degree'))
            # 判斷是否為閉合曲線
            open = cmds.getAttr(shape + '.form')
            # 如果是封閉曲線，頂點數量 -1
            if open:
                cvSize -= 1
            else:
                if cvDegree == 2:
                    cvSize += 1
                elif cvDegree == 3:
                    cvSize += 2
            self.cvList.append(
                '{}.cv[{}:{}]'.format(n, 0, cvSize))

    def moveF(self, axial, offset):
        """旋轉控制器造型.
        :type axial: str
            'x' | 'y' | 'z'
        :rotate offset: float
        """
        xData, yData, zData = 0, 0, 0
        if axial == 'x':
            xData, yData, zData = offset, 0, 0
        elif axial == 'y':
            xData, yData, zData = 0, offset, 0
        elif axial == 'z':
            xData, yData, zData = 0, 0, offset
        #
        cmds.move(xData, yData, zData, self.cvList, r=True, os=True, wd=True)

    def rotateF(self, rotate):
        """旋轉控制器造型.
        :rotate size: list
            [int, int, int]
        """
        cmds.rotate(rotate[0], rotate[1], rotate[2], self.cvList, r=True)

    def scaleF(self, size):
        """縮放控制器造型大小.
        :type size: float
        """
        cmds.scale(size, size, size, self.cvList, r=True)


class ThRandSelect:
    def __init__(self, objs, quantity):
        """隨機選擇"""
        listLen = len(objs)
        if listLen < quantity:
            return
        # add
        self.newList = copy.copy(objs)
        self.oldList = []
        #
        range_ = listLen - quantity
        for i in range(range_):
            index = random.randint(0, listLen - (i + 1))
            self.oldList.append(self.newList.pop(index))
        cmds.select(self.newList, r=True)


class ThCopySkinAndWeight:
    def __init__(self, refList, objList):
        """複製 skin 與 weight"""
        self.refList = refList
        self.objList = objList
        #
        self.refSize = len(self.refList)
        self.objSize = len(self.objList)

    def copySkinF(self):
        """複製 skin"""
        # 如果不是兩個列表要做對應的話
        # 直接找 refList 的 joints skin objList
        if self.refSize > 1 and self.objSize == 1 or self.refSize == 1 and self.objSize > 1:
            # 找 ref 的 joint
            joints = thFindSkinJointF(self.refList)
            for i, obj in enumerate(self.objList):
                # 找 obj 的 skin node
                skinNode = thFindSkinNodeF([obj])
                if joints and not skinNode:
                    # skin obj
                    skinNode = cmds.skinCluster(joints, obj, mi=5, dr=4.0, tsb=True)
        elif self.refSize == self.objSize:
            for i, ref in enumerate(self.refList):
                joints = thFindSkinJointF([ref])
                skinNode = thFindSkinNodeF([self.objList[i]])
                if joints and not skinNode:
                    skinNode = cmds.skinCluster(joints, self.objList[i], mi=5, dr=4.0, tsb=True)
        return skinNode[0]

    def copyWeightF(self, mode='closestJoint'):
        """複製 weight"""
        # 如果使用 uv 模式
        if mode == 'uv':
            refUv = cmds.polyUVSet(self.refList, q=True, cuv=True)
            objUv = cmds.polyUVSet(self.objList, q=True, cuv=True)
            if self.refSize > 1 and self.objSize == 1:
                sys.stdout.write(ThLanguage.tr('無法使用此模式!'))
                return
            elif self.refSize == self.objSize:
                for i, obj in enumerate(self.objList):
                    cmds.copySkinWeights(
                        self.refList[i], obj, uv=[refUv[i], objUv[i]], nm=True,
                        sa='closestPoint', ia='closestJoint')
            elif self.refSize == 1 and self.objSize > 1:
                for i, obj in enumerate(self.objList):
                    cmds.copySkinWeights(
                        self.refList[0], obj, uv=[refUv[0], objUv[i]], nm=True,
                        sa='closestPoint', ia='closestJoint')
        elif mode == 'closestJoint':
            if self.refSize > 1 and self.objSize == 1:
                cmds.copySkinWeights(
                    self.refList, self.objList[0], nm=True, sa='closestPoint', ia='closestJoint')
            elif self.refSize == self.objSize:
                for i, obj in enumerate(self.objList):
                    cmds.copySkinWeights(
                        self.refList[i], obj, nm=True, sa='closestPoint', ia='closestJoint')
            elif self.refSize == 1 and self.objSize > 1:
                for obj in self.objList:
                    cmds.copySkinWeights(
                        self.refList[0], obj, nm=True, sa='closestPoint', ia='closestJoint')
        elif mode == 'oneToOne':
            if self.refSize > 1 and self.objSize == 1:
                cmds.copySkinWeights(
                    self.refList, self.objList[0], nm=True, sa='closestPoint', ia='oneToOne')
            elif self.refSize == self.objSize:
                for i, obj in enumerate(self.objList):
                    cmds.copySkinWeights(
                        self.refList[i], obj, nm=True, sa='closestPoint', ia='oneToOne')
            elif self.refSize == 1 and self.objSize > 1:
                for obj in self.objList:
                    cmds.copySkinWeights(
                        self.refList[0], obj, nm=True, sa='closestPoint', ia='oneToOne')
        elif mode == 'name':
            if self.refSize > 1 and self.objSize == 1:
                cmds.copySkinWeights(
                    self.refList, self.objList[0], nm=True, sa='closestPoint', ia='name')
            elif self.refSize == self.objSize:
                for i, obj in enumerate(self.objList):
                    cmds.copySkinWeights(
                        self.refList[i], obj, nm=True, sa='closestPoint', ia='name')
            elif self.refSize == 1 and self.objSize > 1:
                for obj in self.objList:
                    cmds.copySkinWeights(
                        self.refList[0], obj, nm=True, sa='closestPoint', ia='name')

    def setMaxInfluencesF(self):
        # set ref max influences
        skinNode = thFindSkinNodeF([self.refList[0]])[0]
        inf = cmds.getAttr(skinNode + '.maxInfluences')
        for obj in self.objList:
            objSkinNode = thFindSkinNodeF([obj])[0]
            cmds.setAttr(objSkinNode + '.maxInfluences', inf)


class ThSelectPointIndex:
    def __init__(self, list_):
        """保存與選擇 index"""
        self.list_ = list_
        #
        self.index = []

    def saveF(self):
        for i in self.list_:
            self.index.append(i.split('.')[1])

    def doSelectF(self, objs):
        objsList = []
        for obj in objs:
            objsList.extend([obj + '.' + i for i in self.index])
        cmds.select(objsList, r=True)


class ThTwoObjCtrl:
    def __init__(
        self, obj1, obj2, objList, mainCtrl, mode, excludeEnd=False,
        addFollowName='follow', addOffsetName='offset', attrCtrl=None):
        """兩個物件約束批量物件並創建批次啟動控制器.
        :type obj2: str
        :type obj1: str
        :type objList: list
        :type mainCtrl: str
        :type mode: str ('connect', 'soft')
        :type excludeEnd: bool 是否排除列表最後一個物件
        :rtype: list
        """
        self.obj1 = obj1
        self.obj2 = obj2
        self.objList = objList
        self.mainCtrl = mainCtrl
        self.mode = mode
        self.excludeEnd = excludeEnd
        self.addFollowName = addFollowName
        self.addOffsetName = addOffsetName
        self.attrCtrl = attrCtrl
        # add
        self.constrainList = []  # save constrain name
        # app
        self.createF()

    def createF(self):
        # constrain
        conList = self.objList[:-1] if self.excludeEnd else self.objList
        for i, n in enumerate(conList):
            self.constrainList.append(
                cmds.parentConstraint([self.obj2, self.obj1, n], mo=True, w=1)[0])
        # add attr
        self.doAttrCtrl = self.attrCtrl if self.attrCtrl else self.mainCtrl
        if not cmds.listAttr(self.doAttrCtrl, m=True, st=self.addFollowName):
            cmds.addAttr(
                self.doAttrCtrl, ln=self.addFollowName, at='double', min=0, max=10, dv=0,
                k=True)
        if not cmds.listAttr(self.doAttrCtrl, m=True, st=self.addOffsetName):
            cmds.addAttr(
                self.doAttrCtrl, ln=self.addOffsetName, at='double', min=0, max=10, dv=0,
                k=True)
        # 控制模式
        appDict = {'connect': self._modeConnectF, 'soft': self._modeSoftF}
        appDict[self.mode]()
        cmds.select(self.doAttrCtrl)

    def _modeConnectF(self):
        """connect 控制模式"""
        # 創建控制器連接
        for n in self.constrainList:
            # constrain 第一個屬性 = 1 - constrain 第二個屬性
            thReverseConnectF([n], [n, self.obj1 + 'W1'], self.obj2 + 'W0')
        # 設置批量啟動
        thBatchEnableF(
            f'{self.doAttrCtrl}.{self.addFollowName}',
            f'{self.doAttrCtrl}.{self.addOffsetName}',
            self.constrainList,
            self.obj1 + 'W1',
            len(self.objList))

    def _modeSoftF(self):
        """soft 控制模式"""
        # 創建 DSL system
        dsl = ThDistanceSoftLocator(objs=self.objList, excludeEnd=self.excludeEnd)
        # 連接 constrain node
        for i, con in enumerate(self.constrainList):
            thReverseConnectF([con], [con, self.obj1 + 'W1'], self.obj2 + 'W0')
            cmds.connectAttr(f'{dsl.locatorList[i]}.ty', f'{con}.{self.obj1}W1')
        # 連接控制器
        cmds.connectAttr(
            f'{self.doAttrCtrl}.{self.addFollowName}', f'{dsl.softNode[0][1]}.follow')
        cmds.connectAttr(
            f'{self.doAttrCtrl}.{self.addOffsetName}', f'{dsl.softNode[0][1]}.offset1')
        cmds.connectAttr(
            f'{self.doAttrCtrl}.{self.addOffsetName}', f'{dsl.softNode[0][1]}.offset2')


class ThRemoveDuplicateNames:
    def __init__(self, objs=None, findShape=True):
        """重命名重複名稱物件"""
        self.objs = objs if objs else cmds.ls(typ='transform')
        self.findShape = findShape
        #
        self.newObjs = []
        self.newObjsShape = []

    def findShapeF(self, objs=None):
        doObjs = objs if objs else self.objs
        shapeList = []
        if self.findShape:
            shapeList = cmds.listRelatives(doObjs, f=True, s=True)
            shapeList = cmds.ls(shapeList)
        return shapeList

    def doRenameF(self):
        self.newObjs = self.renameF(self.objs)
        shapeList = self.findShapeF(self.newObjs)
        if shapeList:
            self.newObjsShape = self.renameF(shapeList)

    def renameF(self, objs=None):
        doObjs = objs if objs else self.objs
        if not doObjs:
            return
        objsLen = len(doObjs)
        longName = cmds.ls(doObjs, l=True)  # 長名稱
        longNameDict = {i: x for i, x in enumerate(longName)}  # 轉為字典標註順序
        sort = sorted(longNameDict.items(), reverse=True, key=lambda item: len(item[1]))
        longNameDict = {}
        for i, n in sort:
            obj = cmds.ls(n[1:], l=False)[0]
            if '|' in obj:
                reObjClear = obj.split('|')[-1]  # 分割字符
                reObjClear = thRemoveStrNumF(reObjClear, False)[0]  # 去掉尾數字
                longNameDict[i] = cmds.rename(n, f'{reObjClear}#')
            else:
                longNameDict[i] = obj
        newObjs = [longNameDict[i] for i in range(objsLen)]  # 還原列表
        return newObjs

    def printMenuF(self, select=True):
        """打印與選擇重複名稱物件"""
        # 重複名稱的物件
        shapeList = self.findShapeF()
        reObjs = [x for x in self.objs + shapeList if '|' in x]
        if select:
            cmds.select(reObjs, r=True)
        sys.stdout.write(
            ThLanguage.tr('重複名稱的物件共有: {}').format(len(reObjs)))


class ThVtxLocator:
    """依據選擇物件創建 follow ctrl"""

    def __init__(
        self, objs=None, name='obj', ifVl=False, vlAim='y', vlSize=1, controlVlMode=None,
        controlObj=None, rotateObj=None, ctrlStyle=None, ctrlAxial='y', ctrlSize=1.0,
        ctrlMode='not', ctrlColor=13, ctrlGrpLayer=3, lockNormals=False, isScaleCluster=True):
        self.objs = objs
        self.name = name
        self.ifVl = ifVl
        self.vlAim = vlAim
        self.vlSize = vlSize
        self.controlVlMode = controlVlMode
        self.controlObj = controlObj
        self.rotateObj = rotateObj
        self.ctrlStyle = ctrlStyle
        self.ctrlAxial = ctrlAxial
        self.ctrlSize = ctrlSize
        self.ctrlMode = ctrlMode
        self.ctrlColor = ctrlColor
        self.ctrlGrpLayer = ctrlGrpLayer
        self.lockNormals = lockNormals
        self.isScaleCluster = isScaleCluster
        #
        self.vl = None  # 定位器名稱
        self.vlVtxList = []  # 使用的頂點名稱
        self.follicleList = []  # follicle 列表
        self.follicleListGrp = ''  # follicle grp
        self.newCtrlList = []  # 新控制器列表

    def _vlScaleClusterF(self, meshName, vertexList):
        """
        在模型指定頂點 ID 上創建 cluster
        :type meshName: str
        :type vertexList: list[list[str], ...]
        """
        clusterList = []
        # 獲取模型目前的變形器歷史，用於後續排序
        allDeformers = cmds.listHistory(meshName, pruneDagObjects=True, interestLevel=1) or []
        # 遍歷頂點 ID 列表
        for ids in vertexList:
            # 將整數 ID 轉換為完整的頂點路徑字串清單
            vtxPaths = [f"{meshName}.vtx[{i}]" for i in ids]
            # 創建 cluster 並取得其名稱 (cmds.cluster 回傳 [node, handle])
            res = cmds.cluster(vtxPaths, n=f"{meshName}_vlCluster")
            clusterNode = res[1]
            # 將生成的 cluster 加入結果清單
            clusterList.append(clusterNode)
            # 如果模型已有其他變形器，將新 cluster 移至最底層
            if allDeformers:
                # 使用 reorderDeformers 將其置於變形鏈的最前端 (靠近原始 Shape)
                cmds.reorderDeformers(allDeformers[-1], clusterNode, meshName)
            #
        return clusterList

    def doVlScaleClusterF(self, vl, follicleList):
        vlVtxSetsIdList = self._returnVeryexSetsIdListF(vl)
        clusterList = self._vlScaleClusterF(vl, vlVtxSetsIdList)
        scaleClusterGrp = cmds.group(clusterList, n=f'{vl}_scaleCluster_grp')
        cmds.parent(scaleClusterGrp, 'vl_grp')
        # 編輯軸心
        for f, c in zip(follicleList, clusterList):
            thEditPivotF([c], f)
        # scale
        cmds.addAttr(scaleClusterGrp, k=True, ln='scaleCluster', at='double', dv=100)
        for c in clusterList:
            for a in ['sx', 'sy', 'sz']:
                cmds.connectAttr(f'{scaleClusterGrp}.scaleCluster', f'{c}.{a}', f=True)

    def createVlAndFollicleF(self):
        if not self.objs:
            return
        # 是否創建 vl
        smoothNode = None
        if self.ifVl:
            # 依據物件創建 vl
            self._vlForSelF()
            smoothNode = cmds.polySmooth(self.vl)[0]
            smoothVtxSize = cmds.polyEvaluate(self.vl, v=True)
            range_ = (range(smoothVtxSize - len(self.objs), smoothVtxSize))
            self.vlVtxList = ['{}.vtx[{}]'.format(self.vl, i) for i in range_]
        else:
            # 作用頂點名稱等於選擇頂點名稱
            self.vlVtxList = self.objs
        # 如果作用物件是 vtx 就創建 follicle
        if '.' in self.vlVtxList[0]:
            vf = ThVertexFollicle(
                self.vlVtxList, self.name, self.rotateObj)
            self.follicleList = vf.applyF()
            self.follicleListGrp = vf.mainGrp
        else:
            self.follicleList = self.vlVtxList
        # 創建控制器 模式
        if self.ctrlMode == 'ctrl' or self.ctrlMode == 'ctrl follow':
            self._ctrlModeF()
            cmds.select(self.newCtrlList, r=True)
        #
        if smoothNode:
            cmds.delete(smoothNode)
            # 是否受控制
            self._controlVtxF()
            cmds.select(self.follicleList, r=True)
        # 創建 scale cluster
        if self.isScaleCluster:
            self.doVlScaleClusterF(self.vl, self.follicleList)

    def createVlF(self):
        """創建定位用 polygons 三角形定位器"""
        # 創建三角平面
        poly = cmds.polyCreateFacet(
            ch=False, tx=1, s=1, n=self.name + '_vl#',
            p=[[0, 0.037021, 0.111063], [0, 0.037021, -0.111063], [0, -0.074042, 0]])[0]
        # 拆解 UV
        cmds.polyProjection(poly, ch=False, type='Planar', ibd=True, kir=True, md='y')
        # 選轉
        polyVtx = f'{poly}.vtx[0:2]'
        if self.vlAim == 'x':
            cmds.rotate(90, -90, 0, polyVtx, r=True)
        elif self.vlAim == 'z':
            cmds.rotate(90, 0, 0, polyVtx, r=True)
        # scale
        if self.vlSize != 1:
            cmds.scale(self.vlSize, self.vlSize, self.vlSize, polyVtx, r=True)
        # 是否鎖定法線
        if self.lockNormals:
            cmds.polyNormalPerVertex(poly, fn=True)
        #
        return poly

    def testCreateVlF(self):
        vlSysName = 'thTestVlScale'
        #
        if cmds.objExists(vlSysName):
            sData = cmds.getAttr(f'{vlSysName}.sx')
            cmds.delete(vlSysName)
            return sData
        else:
            selectList = cmds.ls(sl=True)
            #
            vl = self.createVlF()
            vlSysName = cmds.rename(vl, vlSysName)
            #
            if selectList:
                ThAdsorptionObj([vlSysName], selectList[0], 'tr')

    def _vlForSelF(self):
        """依據物件創建 vl"""
        # 創建 group
        if not cmds.objExists('def'):
            cmds.group(em=True, n='def')
        if not cmds.objExists('vl_grp'):
            cmds.group(em=True, n='vl_grp')
            cmds.parent('vl_grp', 'def')
        # 判斷物件類型用於選擇對位功能
        adsorptionType = None
        if '.' in self.objs[0]:
            adsorptionType = 'vertex'
        else:
            adsorptionType = 'tr'
        #
        vlList = []
        for n in self.objs:
            # 創建
            vl = self.createVlF()
            vlList.append(vl)
            # 對位
            ThAdsorptionObj([vl], n, adsorptionType)
        # 如果 vtx locator 數量 > 1 才執行模型合併
        if len(self.objs) > 1:
            # 合併模型
            self.vl = cmds.polyUnite(vlList, ch=False, mergeUVSets=1)
            # 重命名
            self.vl = cmds.rename(self.vl, self.name + '_vl#')
            # 排佈 UV
            cmds.polyMultiLayoutUV(
                self.vl, lm=1, sc=1, rbf=1, fr=1, ps=1, l=2, psc=0, su=1, sv=1, ou=0, ov=0)
            if self.lockNormals:
                cmds.polyNormalPerVertex(self.vl, fn=True)
        else:
            self.vl = vl
        #
        cmds.parent(self.vl, 'vl_grp')

    def _returnVeryexSetsIdListF(self, vl):
        """
        回傳頂點集 id 列表
        :type vl: str
        """
        vertexSize = cmds.polyEvaluate(vl, v=True)
        # 保存分組
        vlVtxSetsIdList = []
        list_ = []
        for i in range(vertexSize):
            list_.append(i)
            if len(list_) == 3:
                vlVtxSetsIdList.append(list_)
                list_ = []
        #
        return vlVtxSetsIdList

    def _returnVeryexSetsListF(self, vl):
        """
        回傳頂點集列表
        :type vl: str
        """
        vertexSize = cmds.polyEvaluate(vl, v=True)
        # 保存分組
        vlVtxSetsList = []
        list_ = []
        for i in range(vertexSize):
            list_.append('{}.vtx[{}]'.format(vl, i))
            if len(list_) == 3:
                vlVtxSetsList.append(list_)
                list_ = []
        #
        return vlVtxSetsList

    def _returnVeryexListF(self, vl):
        """
        回傳頂點列表
        :type vl: str
        """
        vertexSize = cmds.polyEvaluate(vl, v=True)
        # 保存作用頂點
        list_ = []
        for i in range(2, vertexSize, 3):
            list_.append('{}.vtx[{}]'.format(vl, i))
        #
        return list_

    def _controlVtxF(self):
        """控制 vtx locator"""
        if not self.controlObj:
            return
        if self.controlVlMode == 'skin':
            # skin
            thObjForObjSkinF(self.controlObj, self.vl)
            # copy weight
            cmds.copySkinWeights(
                self.controlObj, self.vl, nm=True, sa='closestPoint', ia='closestJoint')
            # 統一權重
            self.uniteWightF([self.vl])
        elif self.controlVlMode == 'wrap':
            cmds.select([self.vl, self.controlObj], r=True)
            mel.eval('doWrapArgList "7" {"1","0","1","2","0","1","0"}')
        elif self.controlVlMode == 'proximityWrap':
            thCreateProximityWrapF([self.controlObj], [self.vl])

    def uniteWightF(self, vlList):
        """統一權重.
        :type vl: str
        """
        # 取得作用頂點集名稱
        for vl in vlList:
            vlVtxSetsList = self._returnVeryexSetsListF(vl)
            for n in vlVtxSetsList:
                cmds.select(n[2], r=True)
                mel.eval('artAttrSkinWeightCopy')
                cmds.GrowPolygonSelectionRegion()
                mel.eval('artAttrSkinWeightPaste')
        cmds.select(cl=True)

    def _ctrlModeF(self):
        """創建控制器 模式"""
        locatorList = self.follicleList if '.' in self.objs[0] else self.objs
        cto = ThCtrlToObject(
            objList=locatorList, name=self.name + '_follow', ctrlStyle=self.ctrlStyle,
            ctrlAxial=self.ctrlAxial, ctrlMethod='not', lockHideAttr=[0, 0, 0, 1],
            ctrlSize=self.ctrlSize, ctrlColor=self.ctrlColor, grpLayout=self.ctrlGrpLayer,
            ifCreateMainGrp=True)
        cto.createF()
        self.newCtrlList = cto.newCtrlList
        # 獲取要約束的物件
        conObjList = \
            self.newCtrlList if self.ctrlGrpLayer == 0 else [n[0] for n in cto.grpLayoutList]
        for i, follicle in enumerate(self.follicleList):
            # 約束
            cmds.parentConstraint([follicle, conObjList[i]], mo=True, weight=1)
        if self.ctrlMode == 'ctrl follow':
            for i, follicle in enumerate(self.follicleList):
                md = cmds.createNode('multiplyDivide', n=self.name + '_follow_MD#')
                cmds.connectAttr(self.newCtrlList[i] + '.t', md + '.input1')
                cmds.setAttr(md + '.input2', -1, -1, -1)
                cmds.connectAttr(md + '.output', cto.grpLayoutList[i][2] + '.t')

    def resetUvPosF(self, follicleList, vl):
        vertexList = self._returnVeryexListF(vl)
        uvPosList = thGetPolyUvPosF(vertexList)[1]
        if len(vertexList) != len(follicleList):
            cmds.warning(
                ThLanguage.tr(
                    '程序未執行: 頂點與 follicle 數量不一致!'))
            return
        for i, follicle in enumerate(follicleList):
            follicleShape = cmds.listRelatives(follicle, f=True, s=True)[0]
            cmds.setAttr(follicleShape + '.parameterU', uvPosList[i][0])
            cmds.setAttr(follicleShape + '.parameterV', uvPosList[i][1])


class ThAimCtrl:
    def __init__(self, locator, father=None, name='eye', ctrlAim='z', ctrlOffset=5, ctrlSize=1):
        """創建 eye 控制器.
        :type locator: str
        :type father: str
        """
        self.locator = locator
        self.father = father
        self.name = name
        self.ctrlAim = ctrlAim
        self.ctrlOffset = ctrlOffset
        self.ctrlSize = ctrlSize
        #
        self.defMainGrp = None  # 主要並行器 grp
        self.ctrlMainGrp = None  # 主要控制器 grp
        self.aimMainGrp = None
        self.aimMainConGrp = None  # 受父物件約束的 grp
        self.ikJoint = []
        self.ik = None
        self.ctrl = None
        self.fkCtrl = None

    def createF(self):
        # 創建 group
        self._createGrpF()
        # 創建 joint
        self._createJointF()
        # 創建 IK
        self.ik = cmds.ikHandle(
            n=self.name + '_aimSys_ik#', sj=self.ikJoint[0], ee=self.ikJoint[1], sol='ikSCsolver')
        cmds.hide(self.ik[0])
        # 創建控制器
        self._createCtrlF()
        # 創件參考線
        self._createTextCvF()
        # 是否受父物件約束
        self._isConstrainF()
        #
        cmds.select(self.ctrl)

    def _createGrpF(self):
        """創建 grp"""
        if not cmds.objExists('def'):
            cmds.group(em=True, n='def')
        #
        if not cmds.objExists('def_aimSys_grp'):
            cmds.group(em=True, n='def_aimSys_grp')
            cmds.parent('def_aimSys_grp', 'def')
        self.defMainGrp = cmds.group(em=True, n=self.name + '_def_aimSys_grp#')
        cmds.parent(self.defMainGrp, 'def_aimSys_grp')
        #
        if not cmds.objExists('aimSys_ctrl_grp'):
            cmds.group(em=True, n='aimSys_ctrl_grp')
        self.ctrlMainGrp = cmds.group(em=True, n=self.name + '_aimSys_ctrl_grp#')
        cmds.parent(self.ctrlMainGrp, 'aimSys_ctrl_grp')

    def _createJointF(self):
        """創建 joint"""
        cmds.select(cl=True)
        self.ikJoint.append(cmds.joint(n=self.name + '_aimSys_ik_joint1_#'))
        self.ikJoint.append(cmds.joint(n=self.name + '_aimSys_ik_joint2_#'))
        # 對位
        ThAdsorptionObj([self.ikJoint[0]], self.locator, ifFreeze=True)
        # 設定第二根 joint 位移
        data = cmds.getAttr(self.ikJoint[1] + '.t' + self.ctrlAim)
        cmds.setAttr(self.ikJoint[1] + '.t' + self.ctrlAim, data + self.ctrlOffset)

    def _createCtrlF(self):
        """創建控制器"""
        cto = ThCtrlToObject(
            objList=[self.ik[0]], name=self.name + '_aim', ctrlStyle='ball', ctrlMethod='parent',
            ctrlSize=self.ctrlSize / 2, ctrlColor=22, grpLayout=3, ifCreateMainGrp=False,
            lockHideAttr=[0, 0, 1, 1])
        cto.createF()
        # 保存控制器名稱
        self.ctrl = cto.newCtrlList[0]
        # 保存 main grp 名稱
        self.aimMainGrp = cto.newCtrlGrpList
        # 保存手約束的 grp 名稱
        self.aimMainConGrp = cto.grpLayoutList[0][1]
        # parent joint
        cmds.parent(self.aimMainGrp, self.ctrlMainGrp)
        #
        # 創建 fk 控制器
        cto = ThCtrlToObject(
            objList=[self.ikJoint[0]], name=self.name + '_fk', ctrlStyle='circle',
            ctrlMethod='not', ctrlSize=self.ctrlSize, ctrlColor=18, grpLayout=2,
            ifCreateMainGrp=False, ctrlAxial=self.ctrlAim, lockHideAttr=[0, 1, 0, 1])
        cto.createF()
        # 保存控制器名稱
        self.fkCtrl = cto.newCtrlList[0]
        # 形狀偏移
        ThEditCvShape([self.fkCtrl]).moveF(self.ctrlAim, self.ctrlOffset / 3)
        # parent 到主要 grp 中
        cmds.parent(self.ikJoint[0], self.fkCtrl)
        cmds.parent(cto.newCtrlGrpList[0], self.ctrlMainGrp)
        # 如果有父物件就約束
        if self.father:
            cmds.parentConstraint([self.father, cto.grpLayoutList[0][1]], mo=True, w=1)

    def _createTextCvF(self):
        """創建參考線"""
        testCv = thObjectCurveF(self.ikJoint, False)
        testCv = cmds.rename(testCv, self.name + '_aimSys_test_cv#')
        cmds.parent(testCv, self.defMainGrp)
        # - skin
        # 創建 joint
        cmds.select(cl=True)
        joint1 = cmds.joint(n=self.name + '_aimSys_test_joint1_#')
        cmds.select(cl=True)
        joint2 = cmds.joint(n=self.name + '_aimSys_test_joint2_#')
        cmds.hide([joint1, joint2])
        # 對位
        ThAdsorptionObj([joint1], self.ikJoint[0])
        ThAdsorptionObj([joint2], self.ikJoint[1])
        cmds.parent(joint1, self.fkCtrl)
        cmds.parent(joint2, self.ctrl)
        cmds.skinCluster([joint1, joint2, testCv], mi=1, dr=2, tsb=True)
        cmds.setAttr(testCv + '.template', 1)

    def _isConstrainF(self):
        """是否受父物件約束"""
        if self.father:
            # attr func
            attrs = ['tx', 'ty', 'tz', 'rx', 'ry', 'rz']
            conAttr = []
            for attr in attrs:
                conAttr.append('{}.{}'.format(self.aimMainConGrp, attr))
            # constrain
            cmds.parentConstraint(
                [self.father, self.aimMainConGrp], mo=True, w=1)
            cmds.setDrivenKeyframe(
                conAttr, cd=self.aimMainConGrp + '.v', itt='linear', ott='linear')
            # add attr
            cmds.addAttr(self.ctrl, k=True, ln='add_attr', at='enum', en='------:------:')
            cmds.setAttr(self.ctrl + '.add_attr', e=True, channelBox=True)
            cmds.addAttr(self.ctrl, min=0, max=1, dv=1, ln='follow', at='double', k=True)
            # connect attr
            cmds.connectAttr(self.ctrl + '.follow', self.aimMainConGrp + '.blendParent1')

    def combineCtrlF(self, objs, name, father):
        """合併控制器
        :type objs: list
        :type name: str
        :type father: str
        """
        # 獲取選擇物件的父群組
        objsFather = cmds.listRelatives(objs, p=True)
        # 創建控制器
        ctrl = thMyControllerF(
            name=name + '_ctrl', style='x', axial=self.ctrlAim, scale=self.ctrlSize, color=13,
            lockHideAttr=[0, 1, 1, 1])
        ctrlGrp1 = cmds.group(ctrl, n=ctrl + '_grp#')
        ctrlGrp2 = cmds.group(ctrl, n=ctrl + '_grp#')
        # 對位
        conObj = copy.copy(objs)
        conObj.append(ctrlGrp1)
        constrain_ = cmds.parentConstraint(conObj, w=1)
        cmds.delete(constrain_)
        # 新控制器 連接 選擇物件 grp
        for obj in objsFather:
            cmds.connectAttr(ctrl + '.t', obj + '.t')
        # 回傳有 follow 屬性的控制器列表
        ifFollowAttrCtrl = []
        for obj in objs:
            if cmds.listAttr(obj, m=True, st='follow'):
                ifFollowAttrCtrl.append(obj)
        # 如果有父物件 或 控制器有 follow 屬性
        # 就在主要控制器上添加 follow 屬性
        if ifFollowAttrCtrl or father:
            cmds.addAttr(ctrl, k=True, ln='add_attr', at='enum', en='------:------:')
            cmds.setAttr(ctrl + '.add_attr', e=True, channelBox=True)
            cmds.addAttr(ctrl, min=0, max=1, dv=1, ln='follow', at='double', k=True)
        # 主要控制器 連接 選擇物件 follow 屬性
        for followAttrCtrl in ifFollowAttrCtrl:
            cmds.connectAttr(ctrl + '.follow', followAttrCtrl + '.follow')
            # 隱藏選擇物件 follow 屬性
            cmds.setAttr(followAttrCtrl + '.add_attr', lock=True, keyable=False, channelBox=False)
            cmds.setAttr(followAttrCtrl + '.follow', lock=True, keyable=False, channelBox=False)
        # 如果有父物件就控制
        if father:
            # attr func
            attrs = ['tx', 'ty', 'tz', 'rx', 'ry', 'rz']
            conAttr = []
            for attr in attrs:
                conAttr.append('{}.{}'.format(ctrlGrp2, attr))
            #
            cmds.parentConstraint([father, ctrlGrp2], mo=True, w=1)
            cmds.setDrivenKeyframe(
                conAttr, cd=ctrlGrp2 + '.v', itt='linear', ott='linear')
            # connect attr
            cmds.connectAttr(ctrl + '.follow', ctrlGrp2 + '.blendParent1')
        cmds.parent(ctrlGrp1, 'aimSys_ctrl_grp')
        cmds.select(ctrl)


class ThCtrlToObject:
    def __init__(
        self, objList=None, name='obj', ctrlStyle='circle', ctrlAxial='y',
        ctrlMethod='constrain', rigTRS=(1, 1, 1), ifUseConstrainScale=False,
        lockHideAttr=(0, 0, 0, 1), ctrlSize=1.0, ctrlColor=18, grpLayout=2,
        ifCreateMainGrp=True, adsorptionMode='tr', ifParent=False, ifUseObjName=False,
        replaceStr=None, suffix='_ctrl', ifWeight=False):
        """依據選擇物件創建控制器.
        :type ctrlAxial: str
            'x' | 'y' | 'z'
        :type ctrlMethod: str
            'None' | 'parent' | 'constrain' | 'connect'
        :type rigTRS: list
            [bool, bool, bool]
        :type lockHideAttr: list
            [bool, bool, bool, bool]
        :type adsorptionMode: str
            'tr' | 't' | 'r'
        """
        self.objList = objList
        self.name = name
        self.ctrlStyle = ctrlStyle
        self.ctrlAxial = ctrlAxial
        self.ctrlMethod = ctrlMethod
        self.rigTRS = rigTRS
        self.ifUseConstrainScale = ifUseConstrainScale
        self.lockHideAttr = lockHideAttr
        self.ctrlSize = ctrlSize
        self.ctrlColor = ctrlColor
        self.grpLayout = grpLayout
        self.ifCreateMainGrp = ifCreateMainGrp
        self.adsorptionMode = adsorptionMode
        self.ifParent = ifParent
        self.ifUseObjName = ifUseObjName
        self.replaceStr = replaceStr
        self.suffix = suffix
        self.ifWeight = ifWeight
        #
        self.newName = None  # 新物件名稱
        self.newCtrlList = []  # 控制器名稱列表
        self.newCtrlGrpList = []  # 控制器 grp 名稱列表
        self.mainGrp = None  # 主要 grp 名稱(如果有創建)
        self.grpLayoutList = []  # grp 的層級層級，用於 parent，型態 [[object[goup],...],...]

    def createF(self, objList=None):
        if not objList is None:
            self.objList = objList
        # 產生命名列表
        self._nameF()
        # 創建控制器
        self._ctrlF()
        # 控制物件
        self._controlF()
        # 創建主要 grp
        self._mainGrpF()
        # 是否將控制器 parent
        if self.ifParent:
            self.ctrlParentF()
        return [self.newCtrlList, self.newCtrlGrpList]

    @staticmethod
    def batchCreateF(
        doObjList, isExcludeLastBone=False, **kwargs):
        #
        for obj in doObjList:
            childList = cmds.listRelatives(obj, ad=True, type='joint')
            childList = childList[1:] if isExcludeLastBone else childList
            childList.append(obj)
            childList = childList[::-1]
            #
            kwargs['objList'] = childList
            cto = __class__(**kwargs)
            cto.createF()

    def _nameF(self):
        """產生命名列表"""
        self.newName = []
        # 是否依據物件名稱來命名
        if self.ifUseObjName:
            # 是否去除指定名稱
            if self.replaceStr:
                for n in self.objList:
                    # 如果找不到替換名稱，就直接加上 suffix
                    newName = n.replace(self.replaceStr, self.suffix)
                    newName = n + self.suffix if newName == n else newName
                    self.newName.append(newName)
            # 無指定名稱就以物件名加上 suffix
            else:
                for n in self.objList:
                    self.newName.append(n + self.suffix)
        # 自訂名稱
        else:
            for i, n in enumerate(self.objList, 1):
                self.newName.append('{}{}{}'.format(self.name, self.suffix, i))

    def _ctrlF(self):
        self.newCtrlList = []
        self.newCtrlGrpList = []
        self.grpLayoutList = []
        #
        for i, n in enumerate(self.objList):
            # 創建控制器
            ctrl = thMyControllerF(
                name=self.newName[i],
                style=self.ctrlStyle,
                axial=self.ctrlAxial,
                scale=self.ctrlSize,
                color=self.ctrlColor)
            # 自身 grp
            newGrpList = []
            if self.grpLayout:
                for i in range(self.grpLayout):
                    newGrpList.append(thLocatorGrpF([ctrl])[0])
                ctrlGrp1 = newGrpList[0]
            else:
                newGrpList.append(ctrl)
                ctrlGrp1 = ctrl
            # 保存名稱
            self.newCtrlList.append(ctrl)
            self.newCtrlGrpList.append(ctrlGrp1)
            self.grpLayoutList.append(newGrpList)
            # 讀取物件 axial 並設置控制器
            cmds.setAttr(f'{ctrl}.rotateOrder', cmds.getAttr(f'{n}.rotateOrder'))
            # 與物件對位
            ThAdsorptionObj([ctrlGrp1], n, self.adsorptionMode)
        # 隱藏並鎖定屬性
        thLockHiddenAttrF(self.newCtrlList, self.lockHideAttr)

    def _controlF(self):
        """控制物件"""
        tmc = ThMultipleControl(self.newCtrlList, self.objList)
        if self.ctrlMethod == 'parent':
            tmc.appParentF()
        elif self.ctrlMethod == 'connect':
            tmc.appConnectF(self.rigTRS)
        elif self.ctrlMethod == 'constrain':
            tmc.appConstrainF(self.rigTRS, self.ifUseConstrainScale)
            #
            if self.ifWeight:
                cmds.addAttr(
                    self.newCtrlList[0],
                    ln='conWeight', k=True, at='double',
                    min=0, max=1, dv=1)
                #
                if self.rigTRS[0] and self.rigTRS[1]:
                    keyAttrList = ['tx', 'ty', 'tz', 'rx', 'ry', 'rz']
                    connectAttr = 'blendParent1'
                elif self.rigTRS[0]:
                    keyAttrList = ['tx', 'ty', 'tz']
                    connectAttr = 'blendPoint1'
                elif self.rigTRS[1]:
                    keyAttrList = ['rx', 'ry', 'rz']
                    connectAttr = 'blendOrient1'
                #
                cmds.setDrivenKeyframe(
                    [f'{x}.{xx}' for x in self.objList for xx in keyAttrList],
                    cd=f'{self.newCtrlList[0]}.conWeight',
                    itt='linear', ott='linear')
                #
                for n in self.objList:
                    cmds.connectAttr(
                        f'{self.newCtrlList[0]}.conWeight',
                        f'{n}.{connectAttr}')

    def _mainGrpF(self):
        """創件主要 grp"""
        # 創建主要 group
        if self.ifCreateMainGrp:
            # 去除子尾數字
            name = thRemoveStrNumF(self.newName[0])[0]
            self.mainGrp = cmds.group(n=name + '_main_grp#', em=True)
            #
            cmds.parent(self.newCtrlGrpList, self.mainGrp)

    def ctrlParentF(self):
        thGrpParentF(self.newCtrlList, True, self.grpLayout, isFreeParent=True)


class ThMultipleControl:
    def __init__(self, ctrlList, objs):
        """多個控制多個.
        :type ctrlList: list
        :type objs: list
        """
        self.ctrlList = ctrlList
        self.objs = objs

    def appParentF(self):
        """parent"""
        for i, ctrl in enumerate(self.ctrlList):
            cmds.parent(self.objs[i], ctrl)

    def appConnectF(self, useTrsBool):
        """connect.
        :type useTrsBool: list
            [bool, bool, bool]
        """
        attrList = []
        for i, attr in enumerate(['t', 'r', 's']):
            if useTrsBool[i]:
                attrList.append(attr)
        #
        for i, ctrl in enumerate(self.ctrlList):
            for attr in attrList:
                cmds.connectAttr(f'{ctrl}.{attr}', f'{self.objs[i]}.{attr}')

    def appConstrainF(self, useTrsBool, isConnScale=False):
        """constrain.
        :type useTrsBool: list
            [bool, bool, bool]
        """
        for obj, ctrl in zip(self.objs, self.ctrlList):
            if useTrsBool[0] and useTrsBool[1]:
                cmds.parentConstraint([ctrl, obj], mo=True, weight=1)
            elif useTrsBool[0]:
                cmds.pointConstraint([ctrl, obj], mo=True, weight=1)
            elif useTrsBool[1]:
                cmds.orientConstraint([ctrl, obj], offset=[0, 0, 0], weight=1)
            #
            if useTrsBool[2]:
                if isConnScale:
                    cmds.connectAttr(f'{ctrl}.s', f'{obj}.s', f=True)
                else:
                    cmds.scaleConstraint([ctrl, obj], offset=[1, 1, 1], weight=1)


class ThAnimKeyChangeType:
    def __init__(self, objs, mainCtrlAttr, keyAttrs, startTime, endTime):
        """動畫轉 driven key.
        :type objs: list
        :type mainCtrlAttr: str
        :type keyAttrs: list
        :type startTime: int
        :type endTime: int
        """
        self.objs = objs
        self.mainCtrlAttr = mainCtrlAttr
        self.keyAttrs = keyAttrs
        self.startTime = startTime
        self.endTime = endTime
        #
        self.totalTimr = None  # 時間總長
        self.inKeyAttrDict = {}  # 有 key 的 attr
        self.frameDataDict = {}  # 保存每個時間上的物件屬性數據

    def toDrivenKeyF(self):
        # 清理 key
        cmds.delete(self.objs, sc=True, uac=False, hi=False, cp=False, s=False)
        # 時間總長
        self.totalTimr = int(self.endTime - self.startTime)
        # 篩選有 key 的屬性
        animNodeList = self._getKeyAttrsF()
        # 保存數據
        self._saveFrameDataF()
        # 刪除所有 key
        cmds.delete(animNodeList)
        # 設置 key
        self._setKeyF()
        #
        cmds.select(self.mainCtrlAttr.split('.')[0])

    def _getKeyAttrsF(self):
        """找每個物件中有設置 key 的 attr
            {obj: [attr,...],...}
        """
        animNodeList = []
        for obj in self.objs:
            # 如果沒有輸入要轉 key 的屬性
            # 就搜尋該物件屬性列表
            attrList = []
            if self.keyAttrs:
                attrList = self.keyAttrs
            else:
                attrList = cmds.listAttr(obj, k=True, u=True, m=True)
            # 篩選有 key 的屬性
            attr_ = []
            for attr in attrList:
                keyNode = cmds.listConnections(obj + '.' + attr, c=False)
                if keyNode:
                    type = cmds.nodeType(keyNode[0])
                    if type == 'animCurveTA' or type == 'animCurveTL' or type == 'animCurveTU':
                        attr_.append(attr)
                        animNodeList.append(keyNode[0])
            if attr_:
                self.inKeyAttrDict[obj] = attr_
        return animNodeList

    def _saveFrameDataF(self):
        """保存每個時間上的物件屬性數據.
            {frame: {obj: {attr: data, ...}, ...}, ...}
        """
        for frame in range(self.totalTimr):
            # 設置 frame
            offset = self.startTime + frame
            cmds.currentTime(offset)
            # 保存數據
            objAttrData = {}
            for obj in self.inKeyAttrDict:
                attrData = {}
                for attr in self.inKeyAttrDict[obj]:
                    attrData[attr] = cmds.getAttr(obj + '.' + attr)
                objAttrData[obj] = attrData
            self.frameDataDict[offset] = objAttrData

    def _setKeyF(self):
        """設定 DrivenKey"""
        # key attr list
        keyAttrList = []
        for obj in self.inKeyAttrDict:
            for attr in self.inKeyAttrDict[obj]:
                keyAttrList.append(obj + '.' + attr)
        #
        for frame in self.frameDataDict:
            # 設定控制參數
            cmds.setAttr(self.mainCtrlAttr, frame)
            # 設定物件參數
            for obj in self.frameDataDict[frame]:
                for attr in self.frameDataDict[frame][obj]:
                    cmds.setAttr(obj + '.' + attr, self.frameDataDict[frame][obj][attr])
            #
            cmds.setDrivenKeyframe(
                keyAttrList, cd=self.mainCtrlAttr, itt='linear', ott='linear')


class ThSaveObjsAttrData:
    def __init__(self, objs=None, attrList=None, data=None):
        """保存物件屬性及數據"""
        self.objs = objs
        self.attrList = attrList if attrList else []
        self.data = data if data else []
        # 如果輸入的 data 是 dict 就轉為 list
        if type(data) is dict:
            dataList = []
            for key, values in data.items():
                dataValue = []
                for attr, value in values.items():
                    dataValue.append([attr, value])
                dataList.append([key, dataValue])
            self.data = dataList

    def saveF(self):
        for obj in self.objs:
            # 讀取物件屬性列表
            if not self.attrList:
                doAttrList = cmds.listAttr(
                    obj, m=True, k=True, r=True, se=True, v=True, w=True, c=True, u=True)
            else:
                doAttrList = self.attrList
            # 如果屬性列表為空就跳過循環
            if not doAttrList:
                continue
            # 循環屬性列表
            dataAttr = []
            for attr in doAttrList:
                # 某些屬性無法 getAttr
                try:
                    value = cmds.getAttr('{}.{}'.format(obj, attr))
                    dataAttr.append([attr, value])
                except:
                    continue
            dataAttr = dataAttr if dataAttr else None
            self.data.append([obj, dataAttr])

    def redoSaveF(self):
        """回到保存數據"""
        for obj, attrValue in self.data:
            if attrValue is None:
                continue
            for attr, value in attrValue:
                try:
                    cmds.setAttr('{}.{}'.format(obj, attr), value)
                except RuntimeError:
                    continue


class ThDistanceSoftLocator:
    def __init__(
        self, objs, name='th', createSoft=True, quantitySoft=1, modeSoft='zipper', default=0,
        connAttr=None, excludeEnd=False):
        """依據距離創建 soft locator.
        :type objs: list
        :type name: str
        :type createSoft: bool
        :type quantitySoft: int
        :type modeSoft: str  'zipper' | 'pipe'
        :type default: int
        :type connAttr: list  [attr] | None
        :type excludeEnd: bool  是否排除列表最後一個物件
        """
        self.objs = objs  # 選擇物件列表
        self.name = name  # 命名
        self.createSoft = createSoft  # 是否創建 soft
        self.quantitySoft = quantitySoft  # 創建 soft 數量
        self.modeSoft = modeSoft  # 創建模式
        self.default = default  # 初始值
        self.connAttr = connAttr  # 與物件連接
        self.excludeEnd = excludeEnd
        self.ifGetDis = True if len(objs) > 1 else False
        # app
        self.createF()

    def createF(self):
        # 創建主要 group
        self._createGrpF()
        # 讀取距離
        self._getDistanceF()
        # 創建 curve
        self._createCurveF()
        # 創建 locator
        self._creatrLocatorF()
        # 創建 soft
        if self.createSoft:
            self._createSoftF()
        # 是否連接控制器
        if self.connAttr:
            self._connectF()
        # 設置初始值
        cmds.setAttr(self.curve + '.ty', self.default)

    def _getDistanceF(self):
        """測量每個物件之間的距離."""
        self.lenList = []
        if self.ifGetDis:
            # 創建距離測量結點
            dds = cmds.createNode('distanceDimShape')
            ddsTr = cmds.listRelatives(dds, p=True, f=True)
            xyz = cmds.xform(self.objs[0], q=True, ws=True, t=True)
            cmds.setAttr(dds + '.startPoint', xyz[0], xyz[1], xyz[2])
            # 讀取距離
            for i in range(1, len(self.objs)):
                xyz = cmds.xform(self.objs[i], q=True, ws=True, t=True)
                if i % 2:
                    cmds.setAttr(dds + '.endPoint', xyz[0], xyz[1], xyz[2])
                else:
                    cmds.setAttr(dds + '.startPoint', xyz[0], xyz[1], xyz[2])
                #
                distance = cmds.getAttr(dds + '.distance')
                self.lenList.append(distance)
            cmds.delete(ddsTr)

    def _createGrpF(self):
        """創建主要 group"""
        if not cmds.objExists('def'):
            cmds.group(em=True, n='def')
        if not cmds.objExists('DSL_system_grp'):
            cmds.group(em=True, n='DSL_system_grp')
            cmds.parent('DSL_system_grp', 'def')
            cmds.hide('DSL_system_grp')
        self.mainGrp = cmds.group(n=self.name + '_DSL_grp#', em=True)
        cmds.parent(self.mainGrp, 'DSL_system_grp')

    def _createCurveF(self):
        """創建 curve"""
        # 計算總長度
        max = sum(self.lenList)
        # 加上總長度
        allLenList = copy.copy(self.lenList)
        if self.ifGetDis:
            allLenList.insert(0, max)
            allLenList.append(max)
        else:
            allLenList = [1, 1]
        # 轉換疊加長度
        addAllLenList = []
        add = 0
        for n in allLenList:
            add += n
            addAllLenList.append(add)
        # 產生座標列表
        move_ = [[n, 0, 0] for n in addAllLenList]
        # 增加初始座標
        move_.insert(0, [0, 0, 0])
        # create curve
        self.curve = cmds.curve(d=1, p=move_, n=self.name + '_DSL_curve#')
        self.curveShape = cmds.listRelatives(self.curve, ad=True)[0]
        #
        cmds.parent(self.curve, self.mainGrp)
        # 計算總長度
        self.maxAll = max * 3 if self.ifGetDis else 2

    def _creatrLocatorF(self):
        """創建 locator"""
        loGrp = cmds.group(n=self.name + '_DSL_locator_grp#', em=True)
        cmds.parent(loGrp, self.mainGrp)
        # 是否排除列表最後一個物件
        appLen = len(self.objs) if self.excludeEnd else len(self.objs) + 1
        self.locatorList = []
        for i in range(1, appLen):
            # 創建曲線測量結點
            poci = cmds.createNode(
                'pointOnCurveInfo', n='{0}_pointOnCurveInfo{1}_#'.format(self.name, i))
            # 設置位置
            cmds.setAttr(poci + '.parameter', i)
            # 關聯 curve
            cmds.connectAttr(self.curveShape + '.worldSpace[0]', poci + '.inputCurve')
            # 創建 locator
            lo = cmds.spaceLocator(n='{0}_DSL_locator{1}_#'.format(self.name, i))[0]
            self.locatorList.append(lo)
            # 關聯 locator
            cmds.connectAttr(poci + '.position', lo + '.translate')
            #
            cmds.parent(lo, loGrp)

    def _createSoftF(self):
        """創建 soft"""
        self.softNode = []
        for i in range(self.quantitySoft):
            self.softNode.append(cmds.softMod(self.curve, n=self.name + '_DSL_soft#'))
            cmds.parent(self.softNode[i][1], self.mainGrp)
            # 設定 soft 軸心
            cmds.setAttr(self.softNode[i][1] + '.scalePivot', 0, 0, 0)
            cmds.setAttr(self.softNode[i][1] + '.rotatePivot', 0, 0, 0)
            # 設定權重軸心
            cmds.setAttr(self.softNode[i][0] + '.falloffCenter', 0, 0, 0)
            # 設定顯示軸心
            cmds.setAttr(self.softNode[i][1] + 'Shape.origin', 0, 0, 0)
            # 設置最大影響範圍
            cmds.setAttr(self.softNode[i][0] + '.falloffRadius', self.maxAll)
        #
        for i in range(self.quantitySoft):
            # 添加屬性
            cmds.addAttr(self.softNode[i][1], ln='follow', at='double', min=0, max=10, dv=0, k=True)
            cmds.addAttr(
                self.softNode[i][1], ln='offset1', at='double', min=0, max=10, dv=0, k=True)
            cmds.addAttr(
                self.softNode[i][1], ln='offset2', at='double', min=0, max=10, dv=0, k=True)
            cmds.addAttr(
                self.softNode[i][1], ln='floatValue1', at='double', min=0, max=1, dv=1, k=True)
            cmds.addAttr(
                self.softNode[i][1], ln='floatValue2', at='double', min=0, max=1, dv=0, k=True)
            moveDataStart = 0.6667 if self.ifGetDis else .5
            moveDataEnd = 0.16665 if self.ifGetDis else .25
            ex = '''\
{node}.falloffCurve[0].falloffCurve_Position = clamp(0, 1, ((({ctrl}.follow / 10) * {start}) + {end}) - ({end} * (1 - ({ctrl}.offset1 / 10.2))));
{node}.falloffCurve[1].falloffCurve_Position = clamp(0, 1, ((({ctrl}.follow / 10) * {start}) + {end}) + ({end} * (1 - ({ctrl}.offset2 / 10.2))));
'''
            ex = ex.format(
                node=self.softNode[i][0], ctrl=self.softNode[i][1], start=moveDataStart,
                end=moveDataEnd)
            cmds.expression(s=ex, n=self.name + '_DSL_EX#')
            #
            cmds.connectAttr(
                self.softNode[i][1] + '.floatValue1',
                self.softNode[i][0] + '.falloffCurve[0].falloffCurve_FloatValue')
            cmds.connectAttr(
                self.softNode[i][1] + '.floatValue2',
                self.softNode[i][0] + '.falloffCurve[1].falloffCurve_FloatValue')
            # 設定 soft ty follow
            cmds.setAttr(self.softNode[i][1] + '.ty', 1)
            if self.modeSoft == 'pipe':
                ex = '{} = ({}/2)+({}/2)'.format(
                    self.softNode[i][0] + '.falloffCurve[2].falloffCurve_Position',
                    self.softNode[i][0] + '.falloffCurve[0].falloffCurve_Position',
                    self.softNode[i][0] + '.falloffCurve[1].falloffCurve_Position')
                cmds.expression(s=ex, n=self.name + '_DSL_EX#')
                #
                cmds.setAttr(self.softNode[i][0] + '.falloffCurve[2].falloffCurve_Interp', 2)
                cmds.setAttr(self.softNode[i][0] + '.falloffCurve[2].falloffCurve_FloatValue', 1)
                #
                cmds.setAttr(self.softNode[i][1] + '.floatValue1', 0)
        cmds.select([n[1] for n in self.softNode], r=True)

    def _connectF(self):
        """與控制器連接"""
        for i, lo in enumerate(self.locatorList):
            for attr in self.connAttr:
                cmds.connectAttr(lo + '.ty', f'{self.objs[i]}.{attr}')


class ThCurveCreateJoint:
    def __init__(
        self, curve, quantity, name='new', isAdsorption=False, isParent=True,
        tangentAim=(0, 1, 0)):
        """依據 curve create joint.
        :type curve: list
        :type name: str
        :type quantity: int
        :type isAdsorption: bool
        :type isParent: bool
        :rtype: list
        """
        self.curve = curve
        self.quantity = quantity
        self.name = name
        self.isAdsorption = isAdsorption
        self.isParent = isParent
        self.tangentAim = tangentAim
        #
        self.jointListAll = []
        #
        self.createF()

    def createF(self):
        for n in self.curve:
            self.jointListAll.extend(self._ikhF(n))
        cmds.select(self.jointListAll, r=True)
        return self.jointListAll

    def _ikhF(self, curve):
        # 創建 ikh
        cmds.select(cl=True)
        ikhJoint1 = cmds.joint()
        ikhJoint2 = cmds.joint(p=[.5, 0, 0])
        cmds.ikHandle(
            sol='ikSplineSolver', ccv=False, pcv=False, n="cc_ikSplineSolver", sj=ikhJoint1,
            ee=ikhJoint2, c=curve)
        # 判斷是否為閉合曲線
        open = cmds.getAttr(curve + '.form')
        openClose = 0 if open else 1
        # 查找最大值
        maxVertex = cmds.getAttr(curve + '.maxValue')
        addTime = maxVertex / (self.quantity - openClose)
        # 複製 joint
        time = 0
        jointList = []
        for i in range(self.quantity):
            # 設置 offset
            cmds.setAttr('cc_ikSplineSolver.offset', time)
            # 讀取位置
            xyz = cmds.xform(ikhJoint1, q=True, ws=True, t=True)
            # 創建 joint
            cmds.select(cl=True)
            newJoint = cmds.joint(n=self.name + '_joint#', p=xyz)
            time += addTime
            jointList.append(newJoint)
        # 是否 吸附曲線
        if self.isAdsorption:
            ThAdsorptionObj(
                objs=jointList, main=curve, mode='tangent', ifFreeze=True,
                tangentAim=self.tangentAim)
        # 是否 parent
        if self.isParent:
            thGrpParentF(jointList, False)
        # 刪除 ikh
        cmds.delete(ikhJoint1)
        return jointList


