class ThUiTreeWidget(QtWidgets.QTreeWidget):
    """
    GUI TreeWidget 類別。
    """

    def __init__(self):
        super().__init__()

    def wheelEvent(self, event):
        delta = event.angleDelta().y()
        vBar = self.verticalScrollBar()
        if vBar and vBar.maximum() > 0:
            step = vBar.singleStep() * 3
            if delta > 0:
                vBar.setValue(vBar.value() - step)
            elif delta < 0:
                vBar.setValue(vBar.value() + step)
        # 阻止滾動事件傳遞給父級 (Scroll Propagation)
        event.accept()


