class ThUiFlowLayout(QtWidgets.QLayout):
    """自動縮排的 layout"""

    def __init__(self, parent=None, margin=0, spacing=-1):
        super().__init__(parent)
        self._items = []
        self.setSpacing(spacing)
        self.setContentsMargins(margin, margin, margin, margin)

    def addItem(self, item):
        self._items.append(item)

    def count(self):
        return len(self._items)

    def itemAt(self, index):
        return self._items[index] if 0 <= index < len(self._items) else None

    def takeAt(self, index):
        return self._items.pop(index) if 0 <= index < len(self._items) else None

    def expandingDirections(self):
        return QtCore.Qt.Orientations(QtCore.Qt.Orientation(0))

    def hasHeightForWidth(self):
        return True

    def heightForWidth(self, width):
        return self._doLayout(QtCore.QRect(0, 0, width, 0), True)

    def setGeometry(self, rect):
        super().setGeometry(rect)
        self._doLayout(rect, False)

    def sizeHint(self):
        return self.minimumSize()

    def minimumSize(self):
        size = QtCore.QSize()
        for item in self._items:
            size = size.expandedTo(item.minimumSize())
        size += QtCore.QSize(2 * self.contentsMargins().top(), 2 * self.contentsMargins().top())
        return size

    def _doLayout(self, rect, testOnly):
        x = rect.x()
        y = rect.y()
        lineHeight = 0
        #
        for item in self._items:
            spaceX = self.spacing()
            spaceY = self.spacing()
            nextX = x + item.sizeHint().width() + spaceX
            if nextX - spaceX > rect.right() and lineHeight > 0:
                x = rect.x()
                y = y + lineHeight + spaceY
                nextX = x + item.sizeHint().width() + spaceX
                lineHeight = 0
            if not testOnly:
                item.setGeometry(QtCore.QRect(QtCore.QPoint(x, y), item.sizeHint()))
            x = nextX
            lineHeight = max(lineHeight, item.sizeHint().height())
        return y + lineHeight - rect.y()


class ThUiSelectFolders(QtWidgets.QFileDialog):
    """應用開檔，可選擇複數資料夾"""

    def __init__(self, parent=None, title="選擇資料夾", startDir="C:/"):
        super().__init__(parent, title)
        #
        self.setParent(None)  # 防止繼承 QSS
        #
        self.setFileMode(QtWidgets.QFileDialog.Directory)
        self.setOption(QtWidgets.QFileDialog.ShowDirsOnly, True)
        self.setOption(QtWidgets.QFileDialog.DontUseNativeDialog, True)
        self.setStyleSheet("")
        # 處理路徑，安全設定起始目錄
        startDir = self.normalizePathF(startDir)
        if startDir.startswith("\\\\"):
            try:
                url = QtCore.QUrl.fromLocalFile(startDir)
                self.setDirectoryUrl(url)
            except Exception as e:
                print(f"設定網路路徑失敗: {e}")
        else:
            if os.path.exists(startDir):
                self.setDirectory(startDir)
            else:
                print(f"警告: 起始路徑不存在: {startDir}")
        # 防止拖拽錯誤
        view = self.findChild(QtWidgets.QListView)
        if view:
            view.setSelectionMode(QtWidgets.QAbstractItemView.ExtendedSelection)
            view.setDragEnabled(False)
            view.setAcceptDrops(False)
            view.setDragDropMode(QtWidgets.QAbstractItemView.NoDragDrop)
            view.setStyleSheet("")
        #
        treeView = self.findChild(QtWidgets.QTreeView)
        if treeView:
            treeView.setSelectionMode(QtWidgets.QAbstractItemView.ExtendedSelection)
            treeView.setDragEnabled(False)
            treeView.setAcceptDrops(False)
            treeView.setDragDropMode(QtWidgets.QAbstractItemView.NoDragDrop)
            treeView.setStyleSheet("")

    def selectFoldersF(self):
        if self.exec_():
            folderPaths = self.selectedFiles()
            folderPaths = [x.replace('/', '\\') for x in folderPaths]
            return folderPaths
        else:
            return []

    def normalizePathF(self, path):
        """
        清理路徑，去除多餘的斜線，避免錯誤
        """
        if not path:
            return ""
        path = path.rstrip("\\/")
        return path


class ThUiScrollAreaWithAnimation(QtWidgets.QScrollArea):
    """滾動條，支援右鍵拖拉 (pyside2與6通用版本)"""

    def __init__(self, parent=None):
        super().__init__(parent)
        self.setWidgetResizable(True)
        self.setCursor(QtCore.Qt.ArrowCursor)
        self.isRightDragging = False
        self.lastPos = QtCore.QPoint()
        self.lastDelta = QtCore.QPoint()
        # 安裝 event filter 到 viewport
        self.viewport().installEventFilter(self)
        # 遞迴安裝 event filter 到所有子控件
        QtCore.QTimer.singleShot(0, self._installEventFiltersF)

    def _installEventFiltersF(self):
        def recursiveInstallF(widget):
            widget.installEventFilter(self)
            for child in widget.findChildren(QtWidgets.QWidget):
                recursiveInstallF(child)
        #
        if self.widget():
            recursiveInstallF(self.widget())

    def eventFilter(self, obj, event):
        # 特定控件不攔截左鍵行為
        if isinstance(obj, (QtWidgets.QLineEdit, QtWidgets.QSpinBox, QtWidgets.QDoubleSpinBox)):
            if event.type() in [QtCore.QEvent.MouseButtonPress, QtCore.QEvent.MouseButtonRelease]:
                if event.button() != QtCore.Qt.RightButton:
                    return False
        # 右鍵按下開始拖動
        if event.type() == QtCore.QEvent.MouseButtonPress and event.button() == QtCore.Qt.RightButton:
            self.isRightDragging = True
            # 兼容 PySide6 (globalPosition) 與 PySide2 (globalPos) 的寫法
            if hasattr(event, "globalPosition"):
                globalMousePos = event.globalPosition().toPoint()
            else:
                globalMousePos = event.globalPos()
            #
            self.lastPos = self.viewport().mapFromGlobal(globalMousePos)
            self.setCursor(QtCore.Qt.ClosedHandCursor)
            self.viewport().grabMouse()
            return True
        # 拖動中
        elif event.type() == QtCore.QEvent.MouseMove and self.isRightDragging:
            # 兼容 PySide6 (globalPosition) 與 PySide2 (globalPos) 的寫法
            if hasattr(event, "globalPosition"):
                globalMousePos = event.globalPosition().toPoint()
            else:
                globalMousePos = event.globalPos()
            #
            currentPos = self.viewport().mapFromGlobal(globalMousePos)
            delta = currentPos - self.lastPos
            self.lastPos = currentPos
            self.lastDelta = delta
            dragFactor = 3.0
            hScroll = self.horizontalScrollBar()
            vScroll = self.verticalScrollBar()
            hScroll.setValue(hScroll.value() - delta.x() * dragFactor)
            vScroll.setValue(vScroll.value() - delta.y() * dragFactor)
            return True
        # 放開右鍵，停止拖動
        elif event.type() == QtCore.QEvent.MouseButtonRelease and event.button() == QtCore.Qt.RightButton:
            self.isRightDragging = False
            self.setCursor(QtCore.Qt.ArrowCursor)
            self.viewport().grabMouse() if hasattr(self.viewport(), "grabMouse") else None
            self.viewport().releaseMouse()
            return True
        # 動態安裝新加入的子 widget 的 event filter
        if event.type() == QtCore.QEvent.ChildAdded:
            child = event.child()
            if isinstance(child, QtWidgets.QWidget):
                child.installEventFilter(self)
        #
        return QtWidgets.QScrollArea.eventFilter(self, obj, event)

    def wheelEvent(self, event):
        scrollBar = self.verticalScrollBar()
        delta = event.angleDelta().y()
        if delta == 0:
            return
        scrollStep = 200
        duration = 200
        easing = QtCore.QEasingCurve.OutQuad
        currentValue = scrollBar.value()
        targetValue = currentValue - (delta / 120) * scrollStep
        targetValue = max(scrollBar.minimum(), min(scrollBar.maximum(), targetValue))
        if hasattr(self, "wheelAnim") and self.wheelAnim.state() == QtCore.QAbstractAnimation.Running:
            self.wheelAnim.stop()
        self.wheelAnim = QtCore.QPropertyAnimation(scrollBar, b"value")
        self.wheelAnim.setDuration(duration)
        self.wheelAnim.setEasingCurve(easing)
        self.wheelAnim.setStartValue(currentValue)
        self.wheelAnim.setEndValue(targetValue)
        self.wheelAnim.start()
        # 阻止滾動事件傳遞給父級 (Scroll Propagation)
        event.accept()


