class ThUiAppPushButton(QtWidgets.QPushButton):
    """按下有顏色漸變按鈕"""

    def __init__(self, text='', pxSize=ThUiConfig.pxSize):
        super().__init__(text)
        ThUiConfig.pxSize = pxSize
        self.setObjectName('appBtn')
        self.setSizePolicy(
            QtWidgets.QSizePolicy(QtWidgets.QSizePolicy.Minimum, QtWidgets.QSizePolicy.Minimum))
        #
        self.pRgb = [180, 80, 80]
        self.hpRgb = [80, 125, 135]
        self.defaultColor = QtGui.QColor(95, 95, 95)
        self.pressedColor = QtGui.QColor(*self.pRgb)
        self.duration = 1000  # in milliseconds
        self.durationAnim = 0
        #
        self.setStyleSheet(self.generateQss(self.defaultColor))
        #
        self.clicked.connect(self.animateReset)

    def generateQss(self, bgColor):
        # 將顏色組成 qss 字串
        r, g, b = bgColor.red(), bgColor.green(), bgColor.blue()
        hr = self.hpRgb[0] - ((self.hpRgb[0] - self.pRgb[0]) * self.durationAnim)
        hg = self.hpRgb[1] - ((self.hpRgb[1] - self.pRgb[1]) * self.durationAnim)
        hb = self.hpRgb[2] - ((self.hpRgb[2] - self.pRgb[2]) * self.durationAnim)
        return """
QPushButton {{
    background: rgb({r},{g},{b});
    border-radius: {radius}px;
    padding: {padding}px;
}}
QPushButton:hover {{
    color: rgb(222,222,222);
    background: rgb({hr},{hg},{hb});
}}
        """.format(
            r=r, g=g, b=b,
            hr=hr, hg=hg, hb=hb,
            radius=4 * ThUiConfig.pxSize,
            padding=3 * ThUiConfig.pxSize,
            border=1 * ThUiConfig.pxSize)

    def animateReset(self):
        self.startTime = QtCore.QTime.currentTime()
        self.animation = QtCore.QVariantAnimation(
            startValue=self.pressedColor,
            endValue=self.defaultColor,
            duration=self.duration
        )
        self.animation.valueChanged.connect(self.updateBackground)
        self.animation.start()

    def updateBackground(self, color):
        self.setStyleSheet(self.generateQss(color))
        elapsed = self.startTime.msecsTo(QtCore.QTime.currentTime())
        self.durationAnim = max(0, (self.duration - elapsed) / 1000.0)


