class ThUiProgressBar(QtWidgets.QDialog):
    """進度條"""

    def __init__(self, size, parent=None):
        self.mainProgressBar = getattr(ThUiMain.instanceCls, 'progressBar', None)
        self._updateMainProgress(0)
        # 處理動態父級視窗
        if parent is None:
            parent = thGetParentMainWindowF()
        #
        super().__init__(parent)
        #
        self.setWindowTitle('Progress')
        #
        width = 15
        for i in range(size):
            width += 20
        self.resize(500, width)
        #
        self.layout1 = QtWidgets.QVBoxLayout()
        self.layout1.setContentsMargins(10, 10, 10, 10)
        self.layout1.setSpacing(2 * ThUiConfig.pxSize)
        self.setLayout(self.layout1)
        #
        self.progressList = []
        self.addProgressF(size)
        #
        self.setStyleSheet(ThUiConfig.getQss())
        #
        QtWidgets.QApplication.processEvents()

    def show(self):
        if not getattr(ThUiMain.instanceCls, 'progressBar', None):
            super().show()

    def _updateMainProgress(self, val):
        if self.mainProgressBar:
            try:
                self.mainProgressBar.setValue(int(val))
            except Exception:
                self.mainProgressBar = None

    def addProgressF(self, size):
        fIndex = -1
        layout2 = ThUiFormLayout()
        layout2.setContentsMargins(0, 0, 0, 0)
        layout2.setSpacing(6)
        self.layout1.addLayout(layout2)
        #
        for i in range(size):
            fIndex += 1
            label = QtWidgets.QLabel()
            layout2.setWidget(fIndex, QtWidgets.QFormLayout.LabelRole, label)
            #
            progressBar = QtWidgets.QProgressBar()
            progressBar.setValue(0)
            layout2.setWidget(fIndex, QtWidgets.QFormLayout.FieldRole, progressBar)
            #
            self.progressList.append([label, progressBar])

    def setStratF(self, index, label, max):
        if label:
            self.progressList[index][0].setText('{}: '.format(label))
        self.progressList[index][1].setMaximum(max)
        self.progressList[index][1].setValue(0)
        if index == 0:
            self._updateMainProgress(0)
        QtWidgets.QApplication.processEvents()

    def setFrameF(self, index, label=None):
        if label:
            self.progressList[index][0].setText('{}: '.format(label))
        value = self.progressList[index][1].value() + 1
        self.progressList[index][1].setValue(value)
        maximum = self.progressList[index][1].maximum()
        if value > maximum:
            if index != 0:
                self.progressList[index][1].setValue(1)

        if maximum > 0:
            totalStages = len(self.progressList)
            if totalStages == 1:
                pct = int((value / maximum) * 100)
            else:
                stageProgress = value / maximum
                pct = int(((index + stageProgress) / totalStages) * 100)
            self._updateMainProgress(min(pct, 100))
        QtWidgets.QApplication.processEvents()

    def close(self):
        if self.mainProgressBar:
            self._updateMainProgress(100)
            QtCore.QTimer.singleShot(600, lambda: self._updateMainProgress(0))
        super().close()

    def closeEvent(self, event):
        if self.mainProgressBar:
            self._updateMainProgress(100)
            QtCore.QTimer.singleShot(600, lambda: self._updateMainProgress(0))
        time.sleep(.2)  # 這行會執行
        super().closeEvent(event)


