class ThUiComboBox(QtWidgets.QComboBox):
    """菜單欄"""

    def __init__(self, maxVisibleItems=30):
        super().__init__()
        self.setMaxVisibleItems(maxVisibleItems)
        self.setView(QtWidgets.QListView())
        self.setObjectName('thQComboBox')

    def setInputMaxWidthF(self, padding=40):
        fontMetrics = QtGui.QFontMetrics(self.font())
        maxTextWidth = 0
        for i in range(self.count()):
            width = fontMetrics.horizontalAdvance(self.itemText(i))
            maxTextWidth = max(maxTextWidth, width)
        # 預設寬度（當 QProxyStyle 被刪除時的備用方案，字型寬度 + 額外寬度預留給下拉箭頭）
        popupWidth = maxTextWidth + padding + 30 
        try:
            # 獲取樣式內邊距
            styleOpt = QtWidgets.QStyleOptionComboBox()
            self.initStyleOption(styleOpt)
            styleHint = self.style().sizeFromContents(
                QtWidgets.QStyle.CT_ComboBox,
                styleOpt,
                QtCore.QSize(maxTextWidth, 0),
                self)
            popupWidth = styleHint.width() + padding
        except RuntimeError:
            # 當 PySide2.QtWidgets.QProxyStyle 已被刪除時，忽略錯誤，使用估算的寬度
            pass
        #
        self.view().setMinimumWidth(popupWidth)

    def wheelEvent(self, event):
        event.ignore()


class ThUiSlider(QtWidgets.QSlider):
    """拉霸 (pyside2與6通用版本)"""

    def setDpiHeightF(self):
        app = QtWidgets.QApplication.instance()
        screen = app.primaryScreen()
        screenHeight = screen.geometry().height()
        self.setMaximum(screenHeight)

    def wheelEvent(self, event):
        event.ignore()

    def mousePressEvent(self, event):
        if event.button() == QtCore.Qt.LeftButton:
            # 兼容 PySide6 (position) 與 PySide2 (pos) 的寫法
            if hasattr(event, "position"):
                mousePos = event.position()
            else:
                mousePos = event.pos()
            #
            if self.orientation() == QtCore.Qt.Horizontal:
                sliderLength = self.width()
                clickPos = mousePos.x()
            else:
                sliderLength = self.height()
                clickPos = self.height() - mousePos.y()
            #
            minValue = self.minimum()
            maxValue = self.maximum()
            #
            ratio = clickPos / float(sliderLength)
            newValue = minValue + (maxValue - minValue) * ratio
            #
            self.setValue(int(newValue))
        #
        super().mousePressEvent(event)


