class ThUiToolBoxTopBtn(QtWidgets.QPushButton):
    """應用於 ThUiToolBox 的整合多功能按鈕"""

    def __init__(self, *args, **kwargs):
        super().__init__(*args, **kwargs)
        self.setObjectName('toolButton')
        #
        layout1 = QtWidgets.QHBoxLayout()
        layout1.setContentsMargins(0, 0, 0, 0)
        layout1.setSpacing(2 * ThUiConfig.pxSize)
        self.setLayout(layout1)
        #
        spacerItem = QtWidgets.QSpacerItem(
            0, 0, QtWidgets.QSizePolicy.Expanding, QtWidgets.QSizePolicy.Minimum)
        layout1.addItem(spacerItem)
        #
        self.copyWidgetButton = ThUiPushButton('+')
        self.copyWidgetButton.setObjectName('copyButton')
        layout1.addWidget(self.copyWidgetButton)
        #
        self.helpCheck = False
        self.helpWidgetList = []
        self.help = ThUiPushButton('...')
        self.help.setObjectName('helpButton')
        self.help.setProperty('check', False)
        self.help.clicked.connect(self.setHiddenHelpTextF)
        layout1.addWidget(self.help)
        #
        self.demo = ThUiPushButton('?')
        self.demo.setObjectName('demoButton')
        self.demo.setProperty('check', False)
        layout1.addWidget(self.demo)

    def showOtherWinF(self, func, ifSpacerItem=True):
        """顯示 copy 視窗"""
        self.otherWin = ThUiOther(func, ifSpacerItem, parent=self)
        self.otherWin.show()

    def connShowOtherWinF(self, func, ifSpacerItem=True):
        self.copyWidgetButton.clicked.connect(lambda: self.showOtherWinF(func, ifSpacerItem))

    def addDemoF(self, http):
        self.demo.setProperty('check', True)
        self.demo.clicked.connect(lambda: self.openPathOrUrlF(http))

    def openPathOrUrlF(self, target):
        """
        根據輸入是網址或本機檔案路徑，自動選擇開啟方式。
        - 若為以 http 開頭的網址 → 使用瀏覽器開啟
        - 若為本機檔案路徑 → 使用系統預設程式開啟
        """
        if isinstance(target, str) and target.lower().startswith(('http://', 'https://')):
            webbrowser.open(target)
        elif os.path.exists(target):
            os.startfile(target)  # Windows 專用
        else:
            print(f"無法開啟：找不到檔案或網址格式錯誤\n➡️ 輸入內容：{target}")

    def addHelpTextF(self, text):
        self.help.setProperty('check', True)
        self.helpWidgetList.append(text)
        text.hide()

    def setHiddenHelpTextF(self):
        if not self.helpWidgetList:
            return
        if self.helpCheck:
            for widget in self.helpWidgetList:
                widget.hide()
            self.helpCheck = False
        else:
            for widget in self.helpWidgetList:
                widget.show()
            self.helpCheck = True


class ThUiToolBox(QtWidgets.QWidget):
    """Tool box"""
    requestResize = QtCore.Signal()

    def __init__(self, label='', check=False):
        super().__init__()
        self.check = check
        #
        self.layout = None
        #
        layoutMain = QtWidgets.QVBoxLayout()
        layoutMain.setContentsMargins(0, 0, 0, 0)
        layoutMain.setSpacing(0)
        self.setLayout(layoutMain)
        #
        layout1 = QtWidgets.QHBoxLayout()
        layout1.setContentsMargins(0, 0, 0, 0)
        layout1.setSpacing(0)
        layoutMain.addLayout(layout1)
        #
        self.topBotton = ThUiToolBoxTopBtn(label)
        self.topBotton.setProperty('check', self.check)
        self.topBotton.clicked.connect(lambda: self.switchWidgetF())
        layout1.addWidget(self.topBotton)
        #
        self.widget = QtWidgets.QWidget()
        layoutMain.addWidget(self.widget)
        #
        self.layout = QtWidgets.QVBoxLayout()
        self.layout.setContentsMargins(2, 6, 2, 6)
        self.layout.setSpacing(6)
        self.widget.setLayout(self.layout)
        #
        if not self.check:
            self.widget.hide()

    def switchWidgetF(self, check=None):
        """切換控件收合狀態"""
        check = not check if not check is None else self.check
        if check:
            self.widget.hide()
            self.check = False
        else:
            self.widget.show()
            self.check = True


class ThUiModifyClassData(ThUiToolBox):
    """編輯 json 控件"""

    def __init__(
        self, parent=None, check=False, inCls=None, outCls=None, clsAttr=None,
        label='', helpText=''):
        super().__init__(label=label, check=check)
        self.inCls = inCls
        self.outCls = outCls
        self.clsAttr = clsAttr
        #
        parent.addWidget(self)
        #
        grpBox = ThUiFrameGrp()
        self.layout.addWidget(grpBox)
        #
        layout1 = QtWidgets.QVBoxLayout()
        layout1.setContentsMargins(
            4 * ThUiConfig.pxSize,
            4 * ThUiConfig.pxSize,
            4 * ThUiConfig.pxSize,
            4 * ThUiConfig.pxSize)
        layout1.setSpacing(2 * ThUiConfig.pxSize)
        grpBox.setLayout(layout1)
        #
        if helpText:
            label = ThUiLabelAnnotation(helpText)
            self.topBotton.addHelpTextF(label)
            layout1.addWidget(label)
        #
        self.textWidget = ThUiPlainTextEdit()
        self.textWidget.setReadOnly(False)
        layout1.addWidget(self.textWidget)
        #
        layout2 = QtWidgets.QHBoxLayout()
        layout2.setContentsMargins(0, 0, 0, 0)
        layout2.setSpacing(2 * ThUiConfig.pxSize)
        layout1.addLayout(layout2)
        #
        button = ThUiAppPushButton(ThLanguage.tr('回復到預設'))
        button.clicked.connect(self.resetF)
        layout2.addWidget(button)
        #
        button = ThUiAppPushButton(ThLanguage.tr('回復到最後編輯'))
        button.clicked.connect(self.reNowF)
        layout2.addWidget(button)
        #
        button = ThUiAppPushButton(ThLanguage.tr('讀檔'))
        button.clicked.connect(self.openF)
        layout2.addWidget(button)
        #
        button = ThUiAppPushButton(ThLanguage.tr('存檔'))
        button.clicked.connect(self.saveF)
        layout2.addWidget(button)
        #
        self.buttonApp = ThUiAppPushButton(ThLanguage.tr('執行'))
        self.buttonApp.clicked.connect(self.applyF)
        layout2.addWidget(self.buttonApp)
        #
        self.reNowF()

    def reNowF(self):
        try:
            text = getattr(self.outCls, self.clsAttr)
            self.textWidget.setPlainText(pprint.pformat(text))
        except:
            print(ThLanguage.tr('獲取資料發生錯誤!'))

    def openF(self):
        global TH_TOOLS_FILE_PATH
        startDir = os.path.normpath(
            f'{TH_TOOLS_FILE_PATH}/files/json/')
        #
        filePath, _ = QtWidgets.QFileDialog.getOpenFileName(
            self,
            u'選擇 JSON 檔案',
            startDir,
            u'JSON (*.json)')
        if not filePath:
            return
        with open(filePath, 'r') as file:
            data = json.load(file)
        self.textWidget.setPlainText(pprint.pformat(data))
        sys.stdout.write(
            ThLanguage.tr('讀取完成，確認資料無誤，再執行應用!'))

    def saveF(self):
        data = self._getDataF()
        if data is None:
            return
        startDir = os.path.normpath(
            f'{TH_TOOLS_FILE_PATH}/files/json/')
        #
        filePath, selectedFilter = QtWidgets.QFileDialog.getSaveFileName(
            self,
            u'儲存檔案',
            startDir,
            u'json (*.json);;All Files (*.*)'
        )
        if not filePath:
            return
        with open(filePath, 'w') as file:
            json.dump(data, file, indent=4)
        sys.stdout.write(ThLanguage.tr('存檔完成!'))

    def _getDataF(self):
        try:
            data = self.textWidget.toPlainText()
            data = json.loads(data.replace("'", '"'))
            return data
        except:
            print(ThLanguage.tr('語法錯誤!'))
            return None

    def applyF(self):
        data = self._getDataF()
        if data is None:
            return
        setattr(self.outCls, self.clsAttr, data)
        sys.stdout.write(ThLanguage.tr('執行完成!'))

    def resetF(self):
        try:
            text = getattr(self.inCls, self.clsAttr)
            self.textWidget.setPlainText(pprint.pformat(text))
        except:
            print(ThLanguage.tr('獲取資料發生錯誤!'))


class ThUiOther(QtWidgets.QMainWindow):
    """顯示獨立小部件"""

    def __init__(self, toolBox, ifSpacerItem=True, doWidth=None, doHeight=None, parent=None):
        self.doWidth = doWidth
        self.doHeight = doHeight
        # 處理動態父級視窗
        if parent is None:
            parent = thGetParentMainWindowF()
        #
        super().__init__(parent)
        #
        self.setWindowTitle('Window')
        self.setObjectName('mainWindow')
        self.setMinimumSize(300 * ThUiConfig.pxSize, 30 * ThUiConfig.pxSize)
        # 主窗體
