    def progressBarF(self):
        """進度條"""
        self.progressBar = QtWidgets.QProgressBar()
        self.progressBar.setTextVisible(False)
        h = 6 * ThUiConfig.pxSize
        radius = int(3 * ThUiConfig.pxSize)
        marginV = 2 * ThUiConfig.pxSize
        marginH = 3 * ThUiConfig.pxSize
        chunkRadius = int(1 * ThUiConfig.pxSize)
        self.progressBar.setFixedHeight(h)
        self.progressBar.setValue(0)
