class ThUiLogoShow(QtWidgets.QDialog):
    """顯示 LOGO 動畫"""

    instanceCls = None

    def __init__(self):
        super().__init__()
        global TH_TOOLS_FILE_PATH
        #
        self.setAttribute(QtCore.Qt.WA_TranslucentBackground, True)
        self.setWindowFlags(QtCore.Qt.FramelessWindowHint | QtCore.Qt.WindowStaysOnTopHint)
        #
        layout1 = QtWidgets.QVBoxLayout()
        layout1.setContentsMargins(2, 2, 2, 2)
        layout1.setSpacing(2)
        self.setLayout(layout1)
        #
        movie = QtGui.QMovie(f'{TH_TOOLS_FILE_PATH}/files/icons/logoShow.gif')
        label = QtWidgets.QLabel(self)
        label.setMovie(movie)
        movie.start()
        layout1.addWidget(label)
        #
        QtWidgets.QApplication.processEvents()
        #
        self.timer = QtCore.QTimer(self)
        self.timer.start(2500)
        self.timer.timeout.connect(self.timeDeleteUiF)

    def show(self):
        if __class__.instanceCls:
            __class__.instanceCls.close()
            __class__.instanceCls.deleteLater()
        __class__.instanceCls = self
        #
        super().show()

    def timeDeleteUiF(self):
        self.close()
        self.deleteLater()


