class ThUiLineBox(QtWidgets.QWidget):
    """物件部件"""

    def __init__(self, ifShowHideButton=True, ifEnabled=False, ifShowSelectButton=True):
        super().__init__()
        layout1 = QtWidgets.QHBoxLayout()
        layout1.setContentsMargins(0, 0, 0, 0)
        layout1.setSpacing(2 * ThUiConfig.pxSize)
        self.setLayout(layout1)
        #
        self.dataList = []
        self.lineEdit = QtWidgets.QLineEdit()
        self.lineEdit.setEnabled(ifEnabled)
        layout1.addWidget(self.lineEdit)
        #
        if ifShowHideButton:
            line = ThUiSeparationLine('V')
            layout1.addWidget(line)
            #
            button = ThUiAppPushButton('H')
            button.setObjectName('sizeBtn_20')
            button.clicked.connect(self.hideObjectF)
            layout1.addWidget(button)
            button = ThUiAppPushButton('S')
            button.setObjectName('sizeBtn_20')
            button.clicked.connect(self.showObjectF)
            layout1.addWidget(button)
        #
        if ifShowSelectButton:
            line = ThUiSeparationLine('V')
            layout1.addWidget(line)
            #
            button = ThUiAppPushButton(ThLanguage.tr('選'))
            button.setObjectName('sizeBtn_20')
            button.clicked.connect(self.selectF)
            layout1.addWidget(button)
        #
        line = ThUiSeparationLine('V')
        layout1.addWidget(line)
        #
        self.inputButton = ThUiAppPushButton('<')
        self.inputButton.setObjectName('sizeBtn_20')
        self.inputButton.clicked.connect(lambda: self.setDataF())
        layout1.addWidget(self.inputButton)

    def setDataF(self, data=None):
        if data is None:
            selectList = cmds.ls(sl=True, fl=True)
            data = selectList[0] if selectList else ''
        if '|' in data:
            result = QtWidgets.QMessageBox.question(
                self, 'Check',
                ThLanguage.tr('所選對象包含重複名稱，\n是否要執行重命名?'),
                QtWidgets.QMessageBox.Yes | QtWidgets.QMessageBox.No, QtWidgets.QMessageBox.No)
            if result == QtWidgets.QMessageBox.Yes:
                trdnCls = ThRemoveDuplicateNames([data])
                trdnCls.doRenameF()
                data = trdnCls.newObjs[0]
            else:
                self.lineEdit.setText('')
                return
        self.lineEdit.setText(data)

    def getDataF(self):
        return self.lineEdit.text()

    def selectF(self):
        cmds.select(self.lineEdit.text(), r=True)

    def showObjectF(self):
        cmds.showHidden(self.lineEdit.text())

    def hideObjectF(self):
        cmds.hide(self.lineEdit.text())


class ThUiLineBoxList(ThUiLineBox):
    """列表部件"""

    def __init__(
        self, ifShowHideButton=True, ifEnabled=False, ifShowSelectButton=True, flatten=False):
        super().__init__(
            ifShowHideButton, ifEnabled, ifShowSelectButton)
        self.flatten = flatten
        self.inputButton.setText('<<')

    @thDoUndoF
    def setDataF(self, data=None):
        appLs = {True: 'cmds.ls(sl=True, fl=True)', False: 'cmds.ls(sl=True)'}
        dataList = eval(appLs[self.flatten]) if data is None else data
        isRename = False
        for n in dataList:
            # 判斷重複名稱
            if '|' in n:
                isRename = True
                break
        # 重命名重複名稱
        if isRename:
            result = QtWidgets.QMessageBox.question(
                self, 'Check',
                ThLanguage.tr('所選對象包含重複名稱，\n是否要執行重命名?'),
                QtWidgets.QMessageBox.Yes | QtWidgets.QMessageBox.No, QtWidgets.QMessageBox.No)
            if result == QtWidgets.QMessageBox.Yes:
                trdnCls = ThRemoveDuplicateNames(dataList)
                trdnCls.doRenameF()
                dataList = trdnCls.newObjs
            else:
                cmds.select(dataList, r=True)
                self.lineEdit.setText('')
                return
        # 設定 UI
        self.dataList = dataList
        self.lineEdit.setText(str(len(dataList)))

    def getDataF(self):
        return self.dataList

    def selectF(self):
        doList = []
        errorList = []
        for n in self.dataList:
            if cmds.objExists(n):
                doList.append(n)
            else:
                errorList.append(n)
        cmds.select(doList, r=True)
        if errorList:
            cmds.warning(ThLanguage.tr('找不到: {}').format(errorList))

    def showObjectF(self):
        cmds.showHidden(self.dataList)

    def hideObjectF(self):
        cmds.hide(self.dataList)


