class ThUiLineBoxObjAttr(ThUiLineBox):
    """控制器與屬性"""

    def __init__(self, ifEnabled=False):
        super().__init__(
            ifShowHideButton=False, ifEnabled=ifEnabled)
        self.inputButton.setText('<:')

    def setDataF(self, data=None):
        if data:
            self.data = data
        else:
            selectList = cmds.ls(sl=True)
            if selectList:
                if '|' in selectList[0]:
                    result = QtWidgets.QMessageBox.question(
                        self, 'Check',
                        ThLanguage.tr(
                            '所選對象包含重複名稱，\n是否要執行重命名?'),
                        QtWidgets.QMessageBox.Yes | QtWidgets.QMessageBox.No, QtWidgets.QMessageBox.No)
                    if result == QtWidgets.QMessageBox.Yes:
                        trdnCls = ThRemoveDuplicateNames([selectList[0]])
                        trdnCls.doRenameF()
                        obj = trdnCls.newObjs[0]
                    else:
                        cmds.select(selectList, r=True)
                        self.lineEdit.setText('')
                        return
                else:
                    obj = selectList[0]
            else:
                self.lineEdit.setText('')
                return
            #
            attrs = thGetMainChannelBoxF()
            if attrs:
                self.data = f'{obj}.{attrs[0]}'
            else:
                self.data = ''
        self.lineEdit.setText(self.data)

    def selectF(self):
        if self.data:
            cmds.select(self.data.split('.')[0], r=True)


