class ThUiBsFunc:
    def sbsInBsNodeF(self, ui, ifSelectNode=False):
        selectList = cmds.ls(sl=True)
        if not selectList:
            return
        nodeList = thFindBlendShapeNodeF(selectList[0])
        if not nodeList:
            return
        ui.setDataF(nodeList[0])
        if ifSelectNode:
            cmds.select(nodeList[0], r=True)


