def thGetParentMainWindowF():
    """獲取主要框架名稱"""
    pointer = omui.MQtUtil.mainWindow()
    return wrapInstance(int(pointer), QtWidgets.QMainWindow)


class ThInitUi:
    preferences = {}  # 給預設值，避免未定義

    @staticmethod
    def highDpF():
        # 這些屬性建議在 QApplication 建立前設定
        # 雖然 Qt6 預設開啟 (AA_UseHighDpiPixmaps 已被棄用且預設為 True)，
        # 但手動指定 PassThrough 政策仍是好的做法
        if hasattr(QtCore.Qt, 'HighDpiScaleFactorRoundingPolicy'):
            QtWidgets.QApplication.setHighDpiScaleFactorRoundingPolicy(
                QtCore.Qt.HighDpiScaleFactorRoundingPolicy.PassThrough)

    @classmethod
    def _loadPreferencesF(cls):
        path = thGetResourcePathF('files', 'json', 'preferences.json')
        if os.path.isfile(path):
            with open(path, 'r', encoding='utf-8') as file:
                cls.preferences = json.load(file)
        else:
            # 處理找不到檔案的情況，例如給預設值
            cls.preferences = {'UI Size': 1, 'Lang': 'zh_TW'}

    @classmethod
    def initDataF(cls):
        # 加載字形
        QtGui.QFontDatabase.addApplicationFont(
            thGetResourcePathF('files', 'font', 'NotoSansTC-VF.ttf'))
        # 加載偏好設定
        cls._loadPreferencesF()
        # 設定 UI 大小
        ThUiConfig.setPxSizeF(cls.preferences['UI Size'])
        # 設定語言
        ThLanguage.setLanguageF(cls.preferences['Lang'])


