    if hasattr(cmds, "thMainUiInstance"):
        try:
            cmds.thMainUiInstance.close()
            cmds.thMainUiInstance.deleteLater()
        except:
            pass
    # 顯示 UI
    ThInitUi.initDataF()
    # 將視窗實例動態註冊到 cmds 模組中，等同於 Blender 的 bpy.types 作法
    cmds.thMainUiInstance = ThUiMain()
    cmds.thMainUiInstance.show()